function a11y.load_text_assets()
    if not a11y.use_text_assets or not a11y.sider_dir then
        return false
    end
    local loaded = false
    for _, language in ipairs({"pt", "en"}) do
        local path = a11y.sider_dir .. "\\livecpk\\FlAccessReader\\text\\" ..
            language .. ".tsv"
        local file = io.open(path, "rt")
        if file then
            local roles = {}
            local templates = {}
            local count = 0
            for line in file:lines() do
                if line:sub(1, 1) ~= "#" then
                    local role, text = line:match("^([^\t]+)\t(.+)$")
                    if role and text and roles[text] == nil then
                        roles[text] = role
                        count = count + 1
                        if (role == "dialog" or role == "instruction")
                                and text:find("%%%d*%$?s") then
                            local pieces = {}
                            local position = 1
                            local first_prefix = ""
                            while true do
                                local first, last = text:find(
                                    "%%%d*%$?s", position)
                                if not first then break end
                                local literal = text:sub(position, first - 1)
                                if #pieces == 0 then first_prefix = literal end
                                pieces[#pieces + 1] = literal:gsub(
                                    "([%(%)%.%%%+%-%*%?%[%]%^%$])", "%%%1")
                                position = last + 1
                            end
                            local suffix = text:sub(position)
                            pieces[#pieces + 1] = suffix:gsub(
                                "([%(%)%.%%%+%-%*%?%[%]%^%$])", "%%%1")
                            if #first_prefix + #suffix >= 15 then
                                templates[#templates + 1] = {
                                    role=role,
                                    prefix=first_prefix,
                                    suffix=suffix,
                                    pattern="^" .. table.concat(pieces, ".+") .. "$",
                                }
                            end
                        end
                    end
                end
            end
            file:close()
            a11y.text_asset_roles[language] = roles
            a11y.text_asset_templates[language] = templates
            a11y.text_asset_counts[language] = count
            loaded = true
            log(string.format(
                "[FLAccess] text-assets-loaded language=%s count=%d path=%q",
                language, count, path))
        else
            log(string.format(
                "[FLAccess] text-assets-missing language=%s path=%q",
                language, path))
        end
    end
    return loaded
end

function a11y.text_asset_role(text)
    if not a11y.use_text_assets or not text or text == "" then
        return nil
    end
    local roles = a11y.text_asset_roles[a11y.ui_language]
    local role = roles and roles[text] or nil
    if role or #text < 60 then return role end
    for _, template in ipairs(a11y.text_asset_templates[a11y.ui_language]) do
        if text:sub(1, #template.prefix) == template.prefix
                and (#template.suffix == 0
                    or text:sub(-#template.suffix) == template.suffix)
                and text:match(template.pattern) then
            return template.role
        end
    end
    return nil
end

function a11y.load_config()
    local file = a11y.config_path and io.open(a11y.config_path, "rt") or nil
    if not file then
        return false
    end
    for line in file:lines() do
        local name, value = line:match("^%s*([%w_]+)%s*=%s*([%w_%-]+)")
        if name == "read_tooltips" then
            value = value:lower()
            a11y.read_tooltips = value ~= "false" and value ~= "no" and value ~= "0"
        elseif name == "use_text_assets" then
            value = value:lower()
            a11y.use_text_assets = value ~= "false" and value ~= "no" and value ~= "0"
        end
    end
    file:close()
    return true
end

function a11y.save_config()
    if not a11y.config_path then
        return
    end
    local file = io.open(a11y.config_path, "wt")
    if not file then
        log(string.format(
            "[FLAccess] config-write-failed path=%q",
            a11y.config_path))
        return
    end
    file:write("# FLAccess settings\n")
    file:write("read_tooltips = ", a11y.read_tooltips and "true" or "false", "\n")
    file:write("use_text_assets = ", a11y.use_text_assets and "true" or "false", "\n")
    file:close()
end

function a11y.diagnostic_text(text)
    return tostring(text or "")
        :gsub("[\r\n\t]+", " ")
        :gsub("[%z\1-\31]", "")
end

function a11y.diagnostic_hex(value)
    if value == nil then
        return "nil"
    end
    return memory.hex(value)
end

function a11y.diagnostic_write(lines)
    if not a11y.diagnostic_mode or not a11y.diagnostic_path then
        return false
    end
    local file = io.open(a11y.diagnostic_path, "at")
    if not file then
        log(string.format(
            "[FLAccess] diagnostic-write-failed path=%q",
            a11y.diagnostic_path))
        return false
    end
    if type(lines) == "table" then
        file:write(table.concat(lines, "\n"), "\n")
    else
        file:write(tostring(lines), "\n")
    end
    file:close()
    return true
end

function a11y.start_diagnostic(reason)
    if not a11y.diagnostic_path then
        return false
    end
    local file = io.open(a11y.diagnostic_path, "wt")
    if not file then
        log(string.format(
            "[FLAccess] diagnostic-start-failed path=%q",
            a11y.diagnostic_path))
        return false
    end
    a11y.diagnostic_sequence = 0
    a11y.diagnostic_candidate_key = nil
    a11y.diagnostic_candidate_since = 0
    a11y.diagnostic_last_key = nil
    a11y.diagnostic_slider_values = {}
    a11y.diagnostic_class_ids = {}
    a11y.diagnostic_class_count = 0
    a11y.diagnostic_last_snapshot_frame = -10000
    a11y.diagnostic_input_sequence = 0
    a11y.diagnostic_last_input_action = nil
    a11y.diagnostic_last_input_source = nil
    a11y.diagnostic_last_input_frame = -10000
    a11y.diagnostic_keyboard_state = {}
    a11y.diagnostic_gamepad_state = {}
    a11y.diagnostic_left_stick_direction = nil
    a11y.diagnostic_selected_heading = nil
    a11y.diagnostic_selected_heading_frame = -10000
    a11y.diagnostic_selected_heading_widget = nil
    a11y.diagnostic_selection_sequence = 0
    a11y.diagnostic_player_visits = {}
    file:write("FLAccess diagnostic\n")
    file:write("version=", VERSION, "\nbuild=", tostring(a11y.build), "\n")
    file:write("started=", os.date("!%Y-%m-%dT%H:%M:%SZ"), "\n")
    file:write("reason=", a11y.diagnostic_text(reason), "\n")
    file:write("policy=stable focus changes, bounded snapshots, and correlated Game Plan input/selection events; no continuous memory dump\n\n")
    file:close()
    return true
end

function a11y.set_diagnostic(enabled, reason)
    if enabled then
        a11y.diagnostic_mode = true
        if not a11y.start_diagnostic(reason or "enabled from Sider") then
            a11y.diagnostic_mode = false
            return false
        end
    else
        if a11y.diagnostic_mode then
            a11y.diagnostic_write({
                "END frame=" .. tostring(frame),
                "ended=" .. os.date("!%Y-%m-%dT%H:%M:%SZ"),
            })
        end
        a11y.diagnostic_mode = false
        a11y.diagnostic_candidate_key = nil
        a11y.diagnostic_last_key = nil
    end
    return true
end

function a11y.record_slider(kind, key, value, row, minimum, maximum)
    if not a11y.diagnostic_mode then
        return
    end
    local value_key = tostring(key) .. ":" .. tostring(value)
    if kind == "set" and a11y.diagnostic_slider_values[key] == value_key then
        return
    end
    a11y.diagnostic_slider_values[key] = value_key
    a11y.diagnostic_sequence = a11y.diagnostic_sequence + 1
    a11y.diagnostic_write({
        string.format(
            "EVENT %d frame=%d kind=slider-%s object=%s value=%s min=%s max=%s",
            a11y.diagnostic_sequence,
            frame,
            tostring(kind),
            tostring(key),
            tostring(value),
            tostring(minimum or (row and row.minimum) or "unknown"),
            tostring(maximum or (row and row.maximum) or "unknown")),
        string.format(
            "control label=%q type=%q mapped=%s",
            a11y.diagnostic_text(row and row.label or ""),
            a11y.diagnostic_text(row and row.role or "slider"),
            row and "true" or "false"),
        "",
    })
end

function a11y.clear_pending_tooltips()
    a11y.main_menu_tooltip_choice=nil
    pending_controller_tooltip = nil
    pending_controller_tooltip_label = nil
    controller_tooltip_due_ms = nil
    main_menu_tooltip = nil
    main_menu_tooltip_due_ms = nil
    latest_generic_tooltip = nil
    latest_generic_tooltip_widget = nil
    latest_generic_tooltip_ms = 0
end

local function is_plain_text(text)
    return text:match("^Carregando") ~= nil
        or text:match("^Salvando") ~= nil
        or text:match("^Aguarde") ~= nil
end

local function is_splash_text(text)
    local lower = text:lower()
    return lower:find("smokepatch", 1, true) ~= nil
        or lower:find("smoke patch", 1, true) ~= nil
        or lower:find("edit file", 1, true) ~= nil
end

local function is_noninteractive_text(text)
    local lower = text:lower()
    return lower:find("conectar ao servidor", 1, true) ~= nil
        or lower:find("conecte ao servidor", 1, true) ~= nil
        or lower:find("connect to the server", 1, true) ~= nil
        or text:find("Dados de atualiz.", 1, true) ~= nil
        or text:find("Pont. unif.", 1, true) ~= nil
        or text == "Pontos da temporada"
        or text == "Progresso"
        or text == "Dados do sistema"
        or text == "Carregando a bola"
        or text == "FOR" or text == "STR"
        or text == "DRI" or text == "PAS"
        or text == "VEL" or text == "SPD"
        or text == "DEF" or text == "CHU" or text == "SHO"
        or (#text == 2 and text:match("^%u%u$") ~= nil
            and text ~= "OK" and text ~= "PN")
end

local function control_label_from_tooltip(text)
    if text:find("volume de uma variedade de efeitos sonoros", 1, true) then
        return "Efeitos sonoros do menu"
    elseif text:find("volume da música de fundo", 1, true) then
        return "Volume da música de fundo"
    elseif text:find("volume da narração e dos comentários", 1, true) then
        return "Volume dos comentários"
    elseif text:find("sons e cantos da torcida", 1, true) then
        return "Em jogo: Barulho da torcida"
    elseif text:find("anúncios do sistema de som", 1, true) then
        return "Em jogo: Anúncios do estádio"
    elseif text:find("músicas do jogo tocadas nos estádios", 1, true) then
        return "Em jogo: Músicas do estádio"
    elseif text:find("sons do campo", 1, true) then
        return "Em jogo: Sons do campo"
    elseif text:find("número de usuários participantes", 1, true) then
        return "Número de usuários"
    elseif text:find("nível de dificuldade das partidas", 1, true) then
        return "Nível da partida"
    elseif text:find("duração da partida", 1, true) then
        return "Duração da partida"
    elseif text:find("jogadores sofrem lesões", 1, true) then
        return "Lesões"
    elseif text:find("configurações de câmera que serão usadas", 1, true) then
        return "Configurações de câmera"
    end
    return nil
end

local function looks_like_message(text, widget)
    if a11y.is_structural_answer(text, widget and memory.hex(widget)) then return false end
    if is_noninteractive_text(text) or is_splash_text(text) then
        return false
    end
    local role = a11y.text_asset_role(text)
    if role == "dialog" or role == "instruction" or role == "status"
            or role == "tooltip-or-description" then
        return true
    elseif role == "control" or role == "dialog-button"
            or role == "menu-item-or-title" or role == "label-or-name" then
        return false
    end
    local name = widget and a11y.widget_internal_name(widget)
    if name and (name:match("_item$") or name:match("_value$")) then
        return false
    end
    return (#text >= 55
        or (#text >= 28 and text:match("[%.%!%?]$") ~= nil)
    )
end

local function is_cup_group_message(text)
    local lower = text:lower()
    return lower:find("agrupamentos da fase de grupos", 1, true) ~= nil
        or lower:find("group stage groups", 1, true) ~= nil
        or lower:find("groupings for the group stage", 1, true) ~= nil
end

function a11y.activate_cup_group_table(reset_cells)
    if a11y.cup_group_table_active and not reset_cells then return end
    a11y.cup_group_table_active = true
    a11y.cup_group_cell_by_widget = {}
    a11y.cup_group_current_cell = nil
    a11y.cup_group_last_announced = nil
    a11y.cup_group_last_navigation_frame = -10000
    a11y.reset_focus_reuse_state()
end

function a11y.is_cup_group_header(widget, text)
    return text and (text:match("^Grupo [A-H]$")
        or text:match("^Group [A-H]$"))
        and a11y.widget_internal_name(widget) == "groupName" or false
end

function a11y.is_instruction_message(text)
    if a11y.text_asset_role(text) == "instruction" then
        return true
    end
    local lower = text:lower()
    return lower:find("enquanto segura", 1, true) ~= nil
        or lower:find("mantendo pressionado", 1, true) ~= nil
        or lower:find("use escalação/editar posição", 1, true) ~= nil
        or lower:find("while holding", 1, true) ~= nil
        or lower:find("hold the", 1, true) ~= nil
        or lower:find("use team sheet/edit position", 1, true) ~= nil
end

local function is_modal_button(text)
    return text == "Concordo." or text == "I agree."
        or a11y.text_asset_role(text) == "dialog-button"
        or text == "Sim" or text == "Não" or text == "OK"
end

local function is_data_notice(text)
    local lower = text:lower()
    return lower:find("dados edit", 1, true) ~= nil
        or lower:find("dados de edi", 1, true) ~= nil
end

local function register_dialog_option(text, widget, widget_key)
    if text ~= "Sim" and text ~= "Não" then
        return
    end
    local previous_option = dialog_options[text]
    if previous_option and frame - previous_option.last_seen > 30 then
        dialog_signature = nil
        dialog_preferred_offset = nil
        dialog_focus_candidate = nil
        dialog_focus_candidate_since = 0
        last_dialog_announcement = nil
    end
    dialog_options[text] = {
        address = widget,
        key = widget_key,
        last_seen = frame,
        native_owner = a11y.native_owner_token(),
    }
    local yes = dialog_options["Sim"]
    local no = dialog_options["Não"]
    if yes and no and yes.key ~= no.key
            and math.abs(yes.last_seen - no.last_seen) <= 3 then
        local signature = no.key .. ":" .. yes.key
        if signature ~= dialog_signature then
            dialog_signature = signature
            dialog_preferred_offset = nil
            dialog_focus_candidate = nil
            dialog_focus_candidate_since = 0
            last_dialog_announcement = nil
            a11y.dialog_button_queued_for_message = false
        end
    end
end

local queue_recent_message

local function add_recent_heading_to_message()
    if recent_heading_text and frame - recent_heading_frame <= 12
            and not recent_message_text:find(recent_heading_text, 1, true) then
        recent_message_text = recent_heading_text .. ". " .. recent_message_text
    end
end

local function remember_message_text(text, widget_key)
    local node=widget_key and a11y.ui_model and a11y.ui_model.nodes[widget_key]
    if a11y.is_menu_description(node) then return end
    if a11y.is_match_ready_notice(text) and a11y.native_pause_context() then return end
    if not a11y.native_key_allowed(widget_key) then return end
    local observed=widget_key and a11y.ui_model and a11y.ui_model.nodes[widget_key]
    if observed and a11y.capture_reading_panel(observed) then return end
    if observed and not a11y.native_presentation_ready(observed.address) then
        a11y.defer_bound_guidance(observed.address,text)
        return
    end
    local message_role = a11y.text_asset_role(text)
    if a11y.dashboard_review and not a11y.read_context_state().structural_question
            and not a11y.read_context_state().structural_event then
        -- Loaded flow metadata must not silence a bound, current dialog.
        -- Keep ambient panel content in review; require an observed object.
        local node = a11y.ui_model and a11y.ui_model.nodes[widget_key]
        if message_role ~= "dialog" or not node or node.text ~= text then return end
    end
    if a11y.is_structural_answer(text,widget_key) then return end
    if is_modal_button(text) or is_noninteractive_text(text) then
        return
    end
    if control_label_from_tooltip(text) or a11y.is_control_help(text) then
        -- Focus help belongs after its label/type/value, not in the modal
        -- paragraph queue. The UI text hook schedules it as a tooltip.
        return
    end
    if message_role == "dialog" or message_role == "instruction" then
        a11y.transition_old_focus_texts = nil
        a11y.transition_guard_until_ms = 0
    end
    if a11y.pre_match_active and a11y.pre_match_notice_text == text then
        -- The ready notice is redrawn in the background of pre-match
        -- submenus. Re-queuing it on each draw can mute real navigation.
        return
    end
    local lower = text:lower()
    local cup_group_message = is_cup_group_message(text)
    if cup_group_message then
        -- Cup group assignment is a focusable table, but unlike the league and
        -- club carousels it does not pass through either native list renderer.
        -- Reset the cell map after its introduction, including when the
        -- structural group headers enabled the table earlier.
        a11y.activate_cup_group_table(true)
    end
    if lower:find("quer usar a configuração básica", 1, true)
            or lower:find("use basic settings", 1, true) then
        -- The prompt's Usar/Não usar widgets remain allocated after the
        -- dialog closes and can later regain a stale focus bit. Track the
        -- real prompt lifetime so those recycled controls cannot interrupt
        -- player names in Edit Position.
        a11y.game_plan_basic_prompt_active = true
    end
    if text:find("A partida começará quando os dois times", 1, true)
            or lower:find("match will begin when both teams", 1, true) then
        if not a11y.pre_match_active then
            a11y.pre_match_entry_pending = true
            a11y.pre_match_entry_guard_until_frame = frame + 120
            a11y.pre_match_last_action = nil
        end
        a11y.pre_match_active = true
        a11y.leave_game_plan()
        a11y.stadium_active = false
        a11y.pre_match_notice_text = text
    elseif text:find("Se você voltar à tela anterior", 1, true)
            or lower:find("if you return to the previous screen", 1, true) then
        -- Only enable the specialized dialog reader for this real, current
        -- confirmation. The former always-on reader retained stale Sim/Não
        -- widgets after dialogs closed.
        a11y.confirmation_dialog_until_frame = frame + 900
    end
    if recent_message_text
            and a11y.is_instruction_message(recent_message_text)
            and recent_message_text ~= text then
        queue_recent_message()
        -- A paged tutorial can replace the same text buffer without closing
        -- the dialog. Finish the previous page, then allow the new page to
        -- become the current candidate instead of discarding it.
        recent_message_text = nil
        recent_message_widget_key = nil
        recent_message_frame = -10000
    end
    -- Main-menu help is reconstructed from localization IDs below. The
    -- rendered copy contains control bytes and must not interrupt the title.
    if current_main_menu_title and frame < main_menu_focus_guard_until then
        return
    end
    if recent_message_text
            and frame - recent_message_frame <= 4
            and widget_key == recent_message_widget_key
            and not is_data_notice(recent_message_text)
            and not recent_message_text:match("[%.%!%?]$")
            and recent_message_text ~= text
            and not recent_message_text:find(text, 1, true)
            and #text <= 120 then
        recent_message_text = recent_message_text .. " " .. text
        recent_message_frame = frame
        log(string.format(
            "[FLAccess] message-append text=%q",
            recent_message_text))
        if (pending_message_text
                and a11y.pending_message_widget_key == recent_message_widget_key
                and recent_message_text:sub(1, #pending_message_text)
                    == pending_message_text)
                or is_data_notice(recent_message_text)
                or frame - last_modal_button_frame <= 120 then
            queue_recent_message()
        elseif a11y.is_instruction_message(recent_message_text) then
            instruction_message_locked = true
            add_recent_heading_to_message()
            queue_recent_message()
        elseif #recent_message_text >= 100
                and not instruction_message_locked then
            instruction_message_locked = true
            add_recent_heading_to_message()
            queue_recent_message()
        end
        return
    end
    local observed = a11y.ui_model and a11y.ui_model.nodes[widget_key]
    if looks_like_message(text, observed and observed.address)
            or a11y.is_instruction_message(text) or is_data_notice(text) then
        recent_message_text = text
        recent_message_widget_key = widget_key
        recent_message_frame = frame
        log(string.format(
            "[FLAccess] message-candidate text=%q",
            recent_message_text))
        if message_role == "dialog" or (text:match("%?$"))
                or cup_group_message
                or text:find("A partida começará quando os dois times", 1, true)
                or is_data_notice(recent_message_text)
                or frame - last_modal_button_frame <= 120 then
            queue_recent_message()
        elseif a11y.is_instruction_message(recent_message_text) then
            instruction_message_locked = true
            add_recent_heading_to_message()
            queue_recent_message()
        elseif #recent_message_text >= 100
                and not instruction_message_locked then
            instruction_message_locked = true
            add_recent_heading_to_message()
            queue_recent_message()
        end
    end
end

function a11y.poll_direct_message_update()
    if not recent_message_widget_key
            or not recent_message_text
            or not a11y.is_instruction_message(recent_message_text)
            or frame - recent_message_frame > 3600 then return end
    -- Setter arguments frequently point into a caller's temporary stack.
    -- Only copied observations may survive the callback; never poll that pointer.
    local node=a11y.ui_model and a11y.ui_model.nodes[recent_message_widget_key]
    if not node or not a11y.native_widget_allowed(node.address)
            or not a11y.ui_node_matches_live(node) then return end
    local text=node.text
    if not text or text == ""
            or text == ui_text_by_widget[recent_message_widget_key] then return end
    ui_text_by_widget[recent_message_widget_key] = text
    log(string.format(
        "[FLAccess] direct-message-update widget=%s text=%q",
        recent_message_widget_key, text))
    remember_message_text(text, recent_message_widget_key)
end

queue_recent_message = function()
    if not recent_message_text
            or frame - recent_message_frame > 120 then
        return
    end
    local key = (recent_message_widget_key or "") .. "\0" ..
        recent_message_text
    local now_ms = tonumber(ffi.C.GetTickCount64())
    if key == last_announced_message_key then
        return
    end
    if pending_message_text then
        if pending_message_key == key then return end
        if a11y.pending_message_widget_key == recent_message_widget_key
                and recent_message_text:sub(1, #pending_message_text)
                    == pending_message_text then
            -- A dialog sentence can arrive in two UI text writes. Replace
            -- the pending prefix instead of speaking prefix and full copy.
            pending_message_text = recent_message_text
            pending_message_key = key
            pending_message_due_ms = now_ms + 40
            a11y.open_read_dialog(recent_message_text, recent_message_widget_key)
            return
        end
        for _, entry in ipairs(a11y.modal_message_backlog) do
            if entry.key == key then return end
        end
        a11y.modal_message_backlog[#a11y.modal_message_backlog + 1] = {
            text=recent_message_text,
            key=key,
        }
        return
    end
    pending_message_text = recent_message_text
    pending_message_key = key
    a11y.pending_message_widget_key = recent_message_widget_key
    a11y.pending_message_owner=a11y.native_owner_token()
    pending_message_due_ms = now_ms
        + (recent_message_text:match("[%.%!%?]$") and 40 or 160)
    -- Any fresh message may own a paired Sim/Não confirmation. Require its
    -- buttons to be rendered with this message before using their focus bits.
    a11y.modal_dialog_start_frame = frame
    a11y.confirmation_dialog_until_frame = frame + 900
    a11y.open_read_dialog(recent_message_text, recent_message_widget_key)
    a11y.modal_navigation_last_ms = nil
    -- A newly detected dialog owns the next output. Drop focus announcements
    -- captured earlier in this render slice before the text hook arrived.
    local pending_title
    if last_screen_title_key and frame - a11y.last_screen_title_frame <= 120 then
        for index = a11y.native_speech_first,
                a11y.native_speech_last do
            local entry = a11y.native_speech_queue[index]
            if entry and entry.text == last_screen_title_key then
                pending_title = entry
                break
            end
        end
    end
    a11y.clear_speech_queue(pending_title)
    a11y.deferred_modal_announcement = nil
    a11y.pending_modal_button_text = nil
    pending_controller_tooltip = nil
    pending_controller_tooltip_label = nil
    controller_tooltip_due_ms = nil
    dynamic_text_candidate = nil
    dynamic_text_due_ms = nil
    main_menu_tooltip = nil
    main_menu_tooltip_due_ms = nil
end

speak = function(text, interrupt, modal, identity, origin_widget)
    if not text or text == "" or text == "No String" or text == "/" or a11y.unresolved_format(text) then
        return
    end
    local source_node=origin_widget and a11y.ui_model and a11y.ui_model.nodes[memory.hex(origin_widget)]
    if source_node and (a11y.is_media_caption(source_node) or (a11y.is_menu_description(source_node)
            and not (identity and identity:sub(1,8)=="tooltip:"))) then return end
    if a11y.selected_message_packet and a11y.selected_message_packet()
            and not overlay_visible and not sider_overlay_visible
            and not (identity and (identity:sub(1,17)=="selected-message:" or identity:sub(1,7)=="review:"
                or identity:sub(1,8)=="loading:")) then return end
    local information=a11y.native_information_context()
    if information and not overlay_visible and not sider_overlay_visible
            and a11y.read_context_state().kind~="dialog"
            and not (identity and (identity:sub(1,14)=="visualization:" or identity:sub(1,19)=="information-header:")) then return end
    if a11y.native_pause_context() and a11y.is_match_ready_notice(text) then
        a11y.poll_native_pause();return
    end
    if a11y.cup_group_table_active
            and (text == "OK, item selecionado"
                or text == "OK, botão selecionado") then
        return
    end
    if a11y.game_plan_active then
        local inside = text:match("%((.-)%)")
        local effective = inside and inside:gsub("%s+", "") or nil
        if effective and effective:match("^%d[%d%-]+$") then
            local default_suffix = (text:find("Padrão", 1, true)
                    or text:find("Default", 1, true))
                and (a11y.ui_language == "pt" and ", padrão" or ", default")
                or ""
            text = effective .. default_suffix .. (a11y.ui_language == "pt"
                    and ", selecionada" or ", selected")
        end
    end
    if not game_is_foreground() then
        return
    end
    local now_ms = tonumber(ffi.C.GetTickCount64())
    if (text == "OK, item selecionado"
            or text == "OK, botão selecionado")
            and not modal and (pending_message_text
                or (modal_message_spoken_frame > 0
                    and now_ms < modal_focus_hold_until_ms + 1000)) then
        return
    end
    if text == last_spoken_text and now_ms - last_spoken_ms < 40
            and (not identity or identity == a11y.last_spoken_identity) then
        return
    end
    if pending_message_text and not modal then
        a11y.defer_speech(text,identity,origin_widget)
        return
    end
    -- Prism has no completion callback. While a modal paragraph is expected
    -- to be spoken, send later announcements to its non-interrupting queue.
    if now_ms < modal_focus_hold_until_ms then
        if interrupt ~= false and not modal then
            -- Rapid focus changes during a paragraph should not leave every
            -- obsolete item queued in Prism. Keep only the latest announcement.
            a11y.defer_speech(text,identity,origin_widget)
            return
        end
        interrupt = false
    elseif interrupt ~= false then
        a11y.deferred_modal_announcement = nil
        a11y.deferred_speech=nil
    end
    if a11y.title_pending_first_item then
        if now_ms <= a11y.title_pending_first_item_until_ms
                and text ~= a11y.title_pending_first_item then
            -- The automatically focused first row must not interrupt the
            -- title that was just submitted to the screen reader.
            interrupt = false
        end
        a11y.title_pending_first_item = nil
    end
    speech_sequence = speech_sequence + 1
    local mode = interrupt == false and "queue" or "interrupt"
    last_spoken_text = text
    a11y.last_spoken_identity = identity
    last_spoken_ms = now_ms
    a11y.native_speech_last = a11y.native_speech_last + 1
    a11y.native_speech_queue[a11y.native_speech_last] = {
        sequence=speech_sequence,
        text=text,
        interrupt=interrupt ~= false,
        mode=mode,
        identity=identity,
        presentation_owner=a11y.native_owner_token(),
        origin=origin_widget and a11y.capture_speech_origin(origin_widget) or nil,
    }
    if origin_widget then
        log("[FLAccess] speech-origin sequence=" .. tostring(speech_sequence) .. " widget=" .. memory.hex(origin_widget)
            .. " owner=" .. tostring(a11y.native_owner_token()))
    else
        log("[FLAccess] speech-origin sequence=" .. tostring(speech_sequence) .. " source=legacy-or-system")
    end
end

-- All queue replacement goes through this function, including modal takeover.
-- One publication lifecycle for every producer. Validation and delivery are
-- separate: queuing a sentence is not evidence that Prism accepted it.
function a11y.update_speech_state(entry,outcome,now_ms,error_code,fragmented)
    if not entry then return end
    local group=entry.fragment_group
    if group then
        if group.finished then return end
        if outcome=="delivered" and entry.suppress_delivery_state then return end
        group.finished=true
    elseif entry.suppress_delivery_state then return end
    local status=outcome=="delivered" and "delivered" or "pending"
    if outcome=="failed" and error_code==13 then status=fragmented and "fragmenting" or "failed-content" end
    for _,tag in ipairs({"selected_message","structured_record"}) do
        local origin=entry[tag]
        if origin and origin.state then
            origin.state.status=status
            if outcome=="failed" then origin.state.retry_after=(now_ms or 0)+750 end
        end
    end
    if entry.loading_state then entry.loading_state.announced=outcome=="delivered" or status=="fragmenting" end
    if entry.common_tooltip then
        entry.common_tooltip.status=status
        if status=="pending" then a11y.tooltip_dirty=true end
    end
    if entry.native_list and entry.native_list.state then
        local item=entry.native_list.state
        item.speech_status=status
        if status=="pending" or status=="failed-content" then item.committed=nil end
    end
    if entry.selection_result then
        entry.selection_result.status=outcome=="delivered" and "delivered" or outcome=="failed" and "failed" or "discarded"
    end
    if entry.menu_choice then entry.menu_choice.status=status end
    if outcome=="delivered" then
        a11y.remember_roster_navigation(entry.selection_result)
        if entry.page_context then a11y.last_page_delivery=entry.page_context.identity end
        if entry.assignment_change then
            local change=entry.assignment_change
            a11y.assignment_delivered=a11y.assignment_delivered or {}
            a11y.assignment_delivered[change.key]={signature=change.signature}
        end
    end
end

function a11y.clear_speech_queue(preserved_entry)
    for index=a11y.native_speech_first,a11y.native_speech_last do
        local entry=a11y.native_speech_queue[index]
        if entry~=preserved_entry then a11y.update_speech_state(entry,"discarded") end
    end
    a11y.native_speech_queue = preserved_entry and {preserved_entry} or {}
    a11y.native_speech_first = 1
    a11y.native_speech_last = preserved_entry and 1 or 0
end

function a11y.speech_entry_allowed(entry)
    return entry ~= nil
        and not entry.superseded
        and (not entry.fragment_group or not entry.fragment_group.finished)
        and (not entry.content_review or a11y.content_review_allowed(entry.content_review))
        and (not entry.common_tooltip or a11y.common_tooltip_allowed(entry.common_tooltip))
        and (not entry.selected_message or a11y.selected_message_allowed(entry.selected_message))
        and (not entry.structured_record or a11y.structured_record_allowed(entry.structured_record))
        and (not entry.loading_state or (a11y.loading_notice==entry.loading_state and a11y.loading_context()==entry.loading_state.address))
        and (not entry.menu_choice or (a11y.main_menu_choice_active(entry.menu_choice)
            and entry.menu_choice_attempt==entry.menu_choice.attempt))
        and (not entry.menu_tooltip or (a11y.main_menu_choice_active(entry.menu_tooltip) and entry.menu_tooltip.status=="delivered"))
        and (not entry.presentation_owner or entry.presentation_owner == a11y.native_owner_token())
        and (not entry.origin or a11y.speech_origin_allowed(entry.origin))
        and (not entry.engine_focus or a11y.engine_focus_delivery_allowed(entry.engine_focus))
        and (not entry.native_list or a11y.native_list_delivery_allowed(entry.native_list))
        and (not entry.reading_selection or a11y.reading_selection_delivery_allowed(entry.reading_selection))
        and (not entry.page_context or a11y.page_delivery_allowed(entry.page_context))
        and (not entry.selection_result or a11y.selection_result_allowed(entry.selection_result))
        and (not entry.roster_review or a11y.roster_review_allowed(entry.roster_review))
        and (not entry.player_details or a11y.player_details_allowed(entry.player_details))
        and (not entry.visualization or a11y.visualization_allowed(entry.visualization))
        and (not entry.static_presentation or a11y.read_native_rendered_text(entry.static_presentation.address)==entry.static_presentation.text)
        and (not entry.information_header or (a11y.native_information_context() or {}).identity==entry.information_header)
        and (not entry.pause_header or (a11y.native_pause_context() or {}).identity==entry.pause_header)
        and (not entry.assignment_change or a11y.assignment_change_allowed(entry.assignment_change))
        and (not entry.language_header or ((a11y.native_language_context() or {}).identity==entry.language_header
            and entry.language_generation==a11y.language_generation))
end

function a11y.queue_speech_fragments(entry)
    if entry.fragmented then return false end
    local characters=a11y.utf8_characters(entry.text)
    if table.concat(characters)~=entry.text then return false end
    local limit=math.max(24,math.min(160,math.floor(#entry.text/2)))
    local parts,current={},""
    for word in entry.text:gmatch("%S+%s*") do
        if #current>0 and #current+#word>limit then parts[#parts+1]=current;current="" end
        current=current .. word
    end
    if #current>0 then parts[#parts+1]=current end
    if #parts<2 then return false end
    local at=a11y.native_speech_first
    for index=a11y.native_speech_last,at+1,-1 do
        a11y.native_speech_queue[index+#parts]=a11y.native_speech_queue[index]
    end
    local group={}
    for index,part in ipairs(parts) do
        local clone={}
        for key,value in pairs(entry) do clone[key]=value end
        clone.text,clone.fragmented,clone.interrupt=part,true,index==1 and entry.interrupt or false
        clone.suppress_delivery_state=index<#parts
        clone.fragment_group=group
        clone.mode=clone.interrupt and "interrupt" or "queue"
        a11y.native_speech_queue[at+index]=clone
    end
    a11y.native_speech_last=a11y.native_speech_last+#parts
    log("[FLAccess] speech-fragments count=" .. #parts .. " reason=backend-content-conversion")
    return true
end

function a11y.flush_native_speech(now_ms)
    if a11y.native_speech_first > a11y.native_speech_last then return end
    a11y.render_read_work=nil -- no memory snapshot may cross Prism IPC
    if not a11y.initialize_native_prism() or not a11y.refresh_native_prism(now_ms) then
        if a11y.prism_failed then a11y.clear_speech_queue() end
        if a11y.render_metric then a11y.render_read_work={} end
        return
    end
    while a11y.native_speech_first <= a11y.native_speech_last do
        local entry=a11y.native_speech_queue[a11y.native_speech_first]
        local allowed=a11y.speech_entry_allowed(entry)
        local metric=a11y.render_metric
        -- Invalidated items cost no IPC budget. Valid text continues next frame
        -- after two attempts, so a paragraph cannot monopolize this callback.
        if allowed and metric and (metric.speech_calls or 0)>=2 then
            a11y.render_read_work={}
            return
        end
        if not allowed then
            a11y.update_speech_state(entry,"discarded")
            log("[FLAccess] speech-discard reason=origin-or-focus-changed sequence=" .. tostring(entry and entry.sequence))
        else
            local spoken=entry.origin and entry.origin.text==entry.text and entry.text or a11y.output_speech_text(entry.text)
            spoken=a11y.roster_navigation_speech(entry.selection_result,spoken)
            local native_text=a11y.to_c_string(spoken)
            local started=metric and tonumber(ffi.C.GetTickCount64())
            if metric then metric.speech_calls=(metric.speech_calls or 0)+1 end
            local error_code=a11y.prism_functions.backend_speak(a11y.prism_backend,native_text,entry.interrupt)
            if error_code~=0 and error_code~=13 and now_ms>=(a11y.prism_recovery_after or 0)
                    and (not metric or metric.speech_calls<2) then
                a11y.prism_recovery_after=now_ms+750
                local failed_name=a11y.prism_backend_name
                if a11y.select_prism_backend(failed_name) then
                    if metric then metric.speech_calls=metric.speech_calls+1 end
                    error_code=a11y.prism_functions.backend_speak(a11y.prism_backend,native_text,entry.interrupt)
                end
            end
            if metric then metric.speech_ms=(metric.speech_ms or 0)+tonumber(ffi.C.GetTickCount64())-started end
            if error_code==0 then
                a11y.update_speech_state(entry,"delivered",now_ms)
                log(string.format("[FLAccess] speech sequence=%d backend=%q mode=%s text=%q",
                    entry.sequence,a11y.prism_backend_name,entry.mode,spoken))
            else
                local fragmented=error_code==13 and a11y.queue_speech_fragments(entry)
                a11y.update_speech_state(entry,"failed",now_ms,error_code,fragmented)
                log(string.format("[FLAccess] native-prism-speak-failed backend=%q error=%d text=%q",
                    a11y.prism_backend_name or "none",error_code,spoken))
            end
        end
        a11y.native_speech_queue[a11y.native_speech_first]=nil
        a11y.native_speech_first=a11y.native_speech_first+1
    end
    a11y.clear_speech_queue()
    if a11y.render_metric then a11y.render_read_work={} end
end

function a11y.stop_nvda_if_requested()
    if not a11y.nvda_stop_requested then return end
    a11y.nvda_stop_requested = false
    if a11y.prism_backend_name == "NVDA" and a11y.prism_backend
            and a11y.prism_functions
            and a11y.prism_functions.backend_stop then
        local result = a11y.prism_functions.backend_stop(
            a11y.prism_backend)
        if result ~= 0 then
            log(string.format("[FLAccess] nvda-stop-failed error=%d", result))
        end
    end
end

local function is_screen_title(text, widget)
    local role = a11y.text_asset_role(text)
    local widget_name = widget and a11y.widget_internal_name(widget) or nil
    if (widget_name == "title" or widget_name == "text_title")
            and #text <= 80 and not text:find("%", 1, true)
            and role ~= "control" and role ~= "dialog-button"
            and role ~= "status" and role ~= "technical"
            and not looks_like_message(text) then
        return true
    end
    return (role == "menu-item-or-title" and #text <= 55
            and not text:match("[%.%!%?]$")
            and (text:match("^Escolha ") or text:match("^Escolher ")
                or text:match("^Selecionar ")
                or text:match("^Choose ") or text:match("^Select ")))
        or text == "Selecionar time"
        or text == "Selecionar Time"
        or text == "Selecionar time."
        or text == "Select Team"
        or text == "Escolha seu time"
        or text == "Escolher seu time"
        or text == "Escolha o seu time"
end

local function announce_screen_title(text, widget_key, widget)
    local source=widget and a11y.ui_model and a11y.ui_model.nodes[memory.hex(widget)]
    if source and a11y.is_media_caption(source) then return end
    local language=a11y.native_language_context()
    if language and a11y.native_language_heading(widget)==language.label then
        a11y.poll_native_language();return
    end
    text=a11y.native_language_heading(widget) or text
    if not is_screen_title(text, widget) then
        return
    end
    local panel=a11y.read_context_state()
    if panel.native_reading_panel and panel.title==text and a11y.reading_panel_is_current() then return end
    if widget and not a11y.native_presentation_ready(widget) then
        a11y.defer_bound_guidance(widget,text)
        return
    end
    local title_name = widget and a11y.widget_internal_name(widget)
    local title_role = a11y.text_asset_role(text)
    if (title_name == "title" or title_name == "text_title")
            and (not title_role or title_role == "label-or-name") then
        -- An unknown overlay caption must not reset a working menu. Keep it
        -- pending only after an independently recognized context boundary.
        local member=a11y.native_windows and a11y.native_windows.members and a11y.native_windows.members[tonumber(widget)]
        if a11y.read_context_state().kind == "unknown" and member and (member.active or member.presented) then
            a11y.read_context.pending_title = text
        end
        return
    end
    if title_name == "title" or title_name == "text_title" then
        -- A caption is presentation, not proof of a new native scene. A late
        -- title must never erase controls already observed in that scene.
        if a11y.ui_model then a11y.ui_model.surface = text end
        -- A real submenu title ends the horizontal pre-match action reader.
        -- Its background System Settings caption may still be rendered.
        a11y.pre_match_active = false
        a11y.pre_match_entry_pending = false
    end
    a11y.transition_old_focus_texts = nil
    a11y.transition_guard_until_ms = 0
    -- Returning from group assignment to team selection ends the table mode.
    a11y.cup_group_table_active = false
    a11y.set_read_title(text)
    a11y.screen_title_hold_until_ms =
        tonumber(ffi.C.GetTickCount64()) + 500
    local key = text
    if key ~= last_screen_title_key
            or frame - a11y.last_screen_title_frame > 120 then
        last_screen_title_key = key
        a11y.last_screen_title_frame = frame
        a11y.title_pending_first_item = nil
        speak(text,not a11y.read_context_state().native_reading_panel,nil,nil,widget)
        a11y.title_pending_first_item = text
        a11y.title_pending_first_item_until_ms =
            tonumber(ffi.C.GetTickCount64()) + 2000
    end
end

function a11y.announce_skip_hint(text, node)
    if not text or frame - a11y.skip_hint_last_frame < 300
            or not a11y.game_is_foreground() then
        return false
    end
    local lower = text:lower()
    if node and (text == "Pular" or text == "Skip") then
        if not a11y.pending_skip_hint or a11y.pending_skip_hint.key ~= node.key then
            a11y.pending_skip_hint = {owner=node.owner_link,key=node.key,started=frame,
                text=text,native_owner=a11y.native_owner_token()}
        end
        return true
    end
    local skip_marker = text:find("<Pular>", 1, true)
        or text:find("<Skip>", 1, true)
        or text:match("[Pp]ressione%s+.+%s+para pular")
        or text:match("[Pp]ress%s+.+%s+to skip")
        or (lower:find("options", 1, true)
            and (lower:find("pular", 1, true)
                or lower:find("skip", 1, true)))
    if not skip_marker then return false end
    if text:find("%%s") then return false end
    a11y.skip_hint_last_frame = frame
    -- Preserve the game's wording rather than inventing an instruction.
    local spoken=text:gsub("<Pular>","Pular"):gsub("<Skip>","Skip")
    speak(spoken,nil,nil,nil,node and node.address)
    return true
end

function a11y.spoken_control_icon(text)
    return text and (text:find("botão",1,true) or text:find("button",1,true)
        or text:find("tecla ",1,true) or text:find("key ",1,true)
        or text=="Options" or text=="Start" or text=="Menu" or text=="Esc" or text=="Enter")
end

function a11y.command_icon_for_node(source)
    local snapshot=a11y.native_windows
    -- GuideBar pairs follow the indexed nodes used by its presentation
    -- routine. They need not be sibling UI nodes.
    local bound_button
    for _,pair in ipairs(snapshot and snapshot.command_bar and snapshot.command_bar.pairs or {}) do
        if source and pair.caption==tonumber(source.address)
                and a11y.native_widget_allowed(pair.icon) and a11y.native_widget_allowed(pair.caption) then
            local caption=a11y.read_native_rendered_text(pair.caption)
            local icon=a11y.read_native_rendered_text(pair.icon)
            if caption==source.text and a11y.spoken_control_icon(icon) then
                if bound_button and bound_button~=icon then return nil end
                bound_button=icon
            end
        end
    end
    if bound_button then return bound_button end
    local member=source and snapshot and snapshot.members[tonumber(source.address)]
    if not member or not member.active then return nil end
    local nodes=a11y.presented_nodes()
    for _,owner in ipairs(member.owners or {}) do
        local parents=owner.parents
        local ancestor=parents and parents[tonumber(source.address)]
        local visited={}
        for _=1,8 do
            if not owner.enabled or not ancestor or ancestor==owner.root or visited[ancestor] then break end
            visited[ancestor]=true
            local captions,icons,button=0,0,nil
            for _,node in ipairs(nodes) do
                local at,seen=tonumber(node.address),{}
                for _=1,10 do
                    if not at or seen[at] then break end
                    seen[at]=true
                    if at==ancestor then
                        if node.name=="padIcon" then
                            icons=icons+1
                            if a11y.spoken_control_icon(node.text) then button=node.text end
                        elseif node.text and node.text~="" then captions=captions+1 end
                        break
                    end
                    at=parents[at]
                end
            end
            if captions>1 then break end
            if captions==1 and icons==1 and button then return button end
            ancestor=parents[ancestor]
        end
    end
end

function a11y.poll_skip_hint()
    local hint = a11y.pending_skip_hint
    if not hint then return end
    if hint.native_owner and hint.native_owner ~= a11y.native_owner_token() then
        a11y.pending_skip_hint=nil
        return
    end
    if not a11y.native_key_allowed(hint.key) then a11y.pending_skip_hint=nil; return end
    local button,ambiguous
    local source=a11y.ui_model and a11y.ui_model.nodes[hint.key]
    for _, node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        local peers=source and a11y.component_peers(source.address,node.address)
        if (peers==true or (peers==nil and hint.owner and node.owner_link==hint.owner))
                and node.name == "padIcon" and a11y.ui_node_matches_live(node)
                and a11y.native_widget_allowed(node.address)
                and a11y.spoken_control_icon(node.text) then
            if button and button ~= node.text then ambiguous=true end
            button=node.text
        end
    end
    if ambiguous then button=nil end
    if not button and not ambiguous then button=a11y.command_icon_for_node(source) end
    if not button then
        if frame-hint.started < 12 then return end
        if not hint.label_spoken then
            hint.label_spoken=true
            local source=a11y.ui_model and a11y.ui_model.nodes[hint.key]
            speak(hint.text or (source and source.text),nil,nil,nil,source and source.address)
            a11y.component_evidence(source,"skip-button-unresolved")
            local parts={}
            for _,node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
                if node.name=="padIcon" and #parts<8 and a11y.native_widget_allowed(node.address) then
                    local _,native_raw,native_font=a11y.read_native_rendered_text(node.address)
                    parts[#parts+1]=string.format("%s raw=%q font=%s",node.key,
                        native_raw or node.raw_text or node.text or "",tostring(native_font or node.native_font))
                end
            end
            log("[FLAccess] skip-icon-unresolved widget=" .. hint.key .. " ambiguous=" .. tostring(ambiguous)
                .. " font-family=" .. tostring(a11y.control_font_family) .. " icons=" .. table.concat(parts," | "))
        end
        if frame-hint.started>120 then a11y.pending_skip_hint=nil end
        return
    end
    a11y.pending_skip_hint = nil
    if frame - a11y.skip_hint_last_frame < 300 then return end
    a11y.skip_hint_last_frame = frame
    local source=a11y.ui_model and a11y.ui_model.nodes[hint.key]
    speak((hint.text or (source and source.text) or "") .. ", " .. button,
        nil,nil,nil,source and source.address)
end

local function enqueue_startup_speech(text, duration_ms)
    if not text or text == "" or startup_speech.seen[text] then
        return
    end
    startup_speech.seen[text] = true
    startup_speech.last = startup_speech.last + 1
    startup_speech.queue[startup_speech.last] = {
        text = text,
        duration_ms = duration_ms or 1000,
    }
end

local function queue_startup_text(text, now_ms)
    local lower = text:lower()
    if lower:find("edit file", 1, true) then
        startup_speech.version = text
        startup_speech.version_due_ms = now_ms + 5000
        return true
    end
    if lower:find("smokepatch", 1, true)
            or lower:find("smoke patch", 1, true) then
        if startup_speech.version and not startup_speech.version_queued then
            enqueue_startup_speech(startup_speech.version, 1500)
            startup_speech.version_queued = true
        end
        return true
    end
    if is_plain_text(text) and not startup_complete then
        if startup_speech.version and not startup_speech.version_queued then
            enqueue_startup_speech(startup_speech.version, 1500)
            startup_speech.version_queued = true
        end
        enqueue_startup_speech(text, 900)
        return true
    end
    return false
end

local function process_startup_speech(now_ms)
    if startup_speech.version and not startup_speech.version_queued
            and startup_speech.version_due_ms
            and now_ms >= startup_speech.version_due_ms then
        enqueue_startup_speech(startup_speech.version, 1500)
        startup_speech.version_queued = true
    end
    if now_ms < startup_speech.next_ms then
        return true
    end
    local item = startup_speech.queue[startup_speech.first]
    if item then
        startup_speech.queue[startup_speech.first] = nil
        startup_speech.first = startup_speech.first + 1
        speak(item.text)
        startup_speech.next_ms = now_ms + item.duration_ms
        return true
    end
    return false
end

local function selector_role(label)
    if label == "Nome do treinador" or label == "Manager Name" or label == "Coach Name" then
        return "ativar para editar"
    end
    if label == "Nome dos ajustes" then
        return "campo de texto"
    end
    return "seletor"
end

local function control_speech(row)
    local spoken = row.label .. ", " .. (row.role or selector_role(row.label))
    if row.value and row.value ~= "" then
        spoken = spoken .. ", " .. row.value
    end
    return spoken
end

function a11y.track_control_focus(key)
    local row = a11y.control_for_widget(key)
    local owner = row or key
    if a11y.control_focus_owner ~= owner then
        a11y.control_focus_owner = owner
        last_controller_announcement, last_announced_control_row = nil, nil
        last_announced_selector_label = nil
    end
end

function a11y.secondary_focus_is_current(key, index)
    local model = a11y.ui_model
    local edge = ui_focus_activated[key] and ui_focus_activated[key][index] or -1
    return not model or not model.last_primary_edge or edge >= model.last_primary_edge
end

-- Investigation only: bounded observations, never used as visibility or focus authority.
function a11y.capture_focus_trace(stage)
    if not a11y.diagnostic_mode then return end
    local trace = a11y.focus_trace
    if not trace or not a11y.sider_dir or (trace.bytes or 0) >= 2097152 then return end
    local lines = {string.format("TRACE input=%d frame=%d stage=%s action=%s generation=%s reason=%s",
        trace.sequence, frame, stage, tostring(trace.action),
        tostring(a11y.ui_model and a11y.ui_model.generation),
        tostring(a11y.ui_model and a11y.ui_model.focus_reason))}
    local generation = a11y.ui_model and a11y.ui_model.generation
    if trace.sample_generation ~= generation then
        trace.samples, trace.owner_samples, trace.sample_generation = {}, {}, generation
    end
    trace.samples = trace.samples or {}
    local nodes = {}
    for _, node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do nodes[#nodes + 1] = node end
    table.sort(nodes, function(left, right) return left.sequence > right.sequence end)
    for position, node in ipairs(nodes) do
        if position > 80 then break end
        if readable(node.address, 0x180) then
            local bytes = memory.read(node.address, 0x180)
            if bytes and #bytes == 0x180 then
                local previous = trace.samples[node.identity]
                local fields = {}
                for offset = 0, 0x17c, 4 do
                    local relative = offset
                    local value = memory.unpack("u32", bytes:sub(relative + 1, relative + 4))
                    local old = previous and memory.unpack("u32", previous.bytes:sub(relative + 1, relative + 4))
                    if (not previous and value ~= 0) or (previous and value ~= old) then
                        fields[#fields + 1] = string.format("%x=%x", offset, value)
                    end
                end
                trace.samples[node.identity] = {bytes=bytes, text=node.text}
                local row = a11y.control_for_widget(node.key)
                if not previous or #fields > 0 or previous.text ~= node.text then
                lines[#lines + 1] = string.format("node=%s identity=%s name=%q text=%q age=%d control=%s fields={%s}",
                    node.key, node.identity, node.name or "", node.text or "", frame-node.last_seen,
                    row and control_speech(row) or "none", table.concat(fields, ","))
                end
            end
        end
    end
    local owners, owner_count = {}, 0
    trace.owner_samples = trace.owner_samples or {}
    for _, node in ipairs(nodes) do
        local owner = node.owner_link
        if owner and not owners[owner] and owner_count < 16 then
            owners[owner], owner_count = true, owner_count + 1
            if readable(owner, 0x100) then
                local bytes = memory.read(owner, 0x100)
                if bytes and #bytes == 0x100 then
                    local previous, fields = trace.owner_samples[owner], {}
                    for offset = 0, 0xfc, 4 do
                        local value = memory.unpack("u32",bytes:sub(offset+1,offset+4))
                        local old = previous and memory.unpack("u32",previous:sub(offset+1,offset+4))
                        if (not previous and value ~= 0) or (previous and value ~= old) then
                            fields[#fields+1] = string.format("%x=%x",offset,value)
                        end
                    end
                    trace.owner_samples[owner] = bytes
                    if #fields > 0 then
                        lines[#lines+1] = "owner-candidate=" .. tostring(owner) .. " fields={" .. table.concat(fields,",") .. "}"
                    end
                end
            end
        end
    end
    local output = table.concat(lines, "\n") .. "\n\n"
    local file = io.open(a11y.sider_dir .. "\\FLAccess-focus-trace.log", trace.started and "at" or "wt")
    if not file then return end
    file:write(output); file:close()
    trace.started, trace.bytes = true, (trace.bytes or 0) + #output
end

function a11y.begin_focus_trace(action)
    if not a11y.diagnostic_mode then return end
    local trace = a11y.focus_trace or {sequence=0, bytes=0}
    if trace.sequence >= 120 or trace.bytes >= 2097152 then return end
    trace.sequence, trace.action, trace.input_frame = trace.sequence + 1, action, frame
    trace.followups = {frame + 4, frame + 12}
    a11y.focus_trace = trace
    a11y.capture_focus_trace("input")
end

function a11y.poll_focus_trace()
    if not a11y.diagnostic_mode then a11y.focus_trace=nil;return end
    local trace = a11y.focus_trace
    if not trace or not trace.followups then return end
    while trace.followups[1] and frame >= trace.followups[1] do
        local due = table.remove(trace.followups, 1)
        a11y.capture_focus_trace("after-" .. tostring(due - trace.input_frame))
    end
end

-- Structured, opt-in evidence. These records never grant speech authority.
-- Capture changes throughout a session, not only its first 120 inputs.
function a11y.start_component_capture(path)
    local file=path and io.open(path,"wt")
    if not file then return false end
    file:write("FLACCESS_COMPONENTS format=1 build=",tostring(a11y.build),
        " started=",os.date("!%Y-%m-%dT%H:%M:%SZ"),"\n")
    file:close()
    a11y.component_capture={active=true,path=path,bytes=0,sequence=0,nodes={},parents={}}
    return true
end

function a11y.start_armed_component_capture()
    if not a11y.sider_dir then return false end
    local marker=a11y.sider_dir .. "\\FLAccess-components.capture"
    local file=io.open(marker,"rt")
    if not file then return false end
    local armed=file:read("*l")=="armed"
    file:close()
    if not armed or not a11y.start_component_capture(a11y.sider_dir .. "\\FLAccess-components.log") then return false end
    file=io.open(marker,"wt")
    if not file then a11y.component_capture.active=false; return false end
    file:write("consumed\n");file:close()
    log("[FLAccess] component-capture=started policy=changes-only one-session")
    return true
end

function a11y.component_capture_lines(capture)
    local snapshot=a11y.native_windows
    local owner=a11y.native_owner_token() or ""
    local lines,ordered,parents={}, {}, {}
    local generation=a11y.ui_model and a11y.ui_model.generation
    if capture.owner~=owner or capture.generation~=generation then
        capture.owner,capture.generation,capture.nodes,capture.parents=owner,generation,{},{}
    end
    lines[#lines+1]=string.format("SNAP sequence=%d frame=%d owner=%q generation=%s reason=%q action=%q keyboard=%s font=%s base=%s",
        capture.sequence,frame,owner,tostring(a11y.ui_model and a11y.ui_model.generation),
        a11y.ui_model and a11y.ui_model.focus_reason or "",a11y.diagnostic_last_input_action or "",
        tostring(a11y.keyboard_window),tostring(a11y.control_font_family),tostring(tonumber(process_base_u64)))
    for _,window in ipairs(snapshot and snapshot.windows or {}) do
        local d=window.cursor_detail or {}
        lines[#lines+1]=string.format("WINDOW address=%s root=%s input=%s selected=%s group=%s index=%s status=%q owned_roots=%q type=%s impl=%s presentation=%s task_parent=%s task_child=%s",
            tostring(window.address),tostring(window.root),tostring(window.enabled),tostring(d.selected),
            tostring(d.group),tostring(d.item_index),d.status or "no-cursor",table.concat(window.owned_roots or {},","),
            tostring(a11y.menu_read(window.address,"u64")),tostring(window.impl),
            tostring(window.impl and a11y.menu_read(window.impl+0x90,"u64")),
            tostring(a11y.menu_read(window.address+0x38,"u64")),
            tostring(a11y.menu_read(window.address+0x40,"u64")))
        for _,item in ipairs(window.tree_evidence and window.tree_evidence.frontier or {}) do
            lines[#lines+1]="FRONTIER window=" .. tostring(window.address) .. " address=" .. tostring(item.address)
                .. " rva=" .. tostring(item.rva) .. " fields=" .. a11y.native_node_summary(item.address)
        end
    end
    for _,line in ipairs(a11y.component_link_capture_lines(snapshot)) do lines[#lines+1]=line end
    local list=a11y.native_list_selection
    if list then
        lines[#lines+1]=string.format("LIST widget=%s identity=%q text=%q observed=%s committed=%s",
            tostring(list.widget),list.identity or "",a11y.diagnostic_text(list.text),tostring(list.observed),tostring(list.committed))
    end
    for key,node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        local address=tonumber(node.address)
        if address then
            local member=snapshot and snapshot.members and snapshot.members[address]
            local selected=snapshot and snapshot.selected_members and snapshot.selected_members[address]
            ordered[#ordered+1]={key=key,node=node,member=member,selected=selected==true,
                rank=selected and 0 or member and member.active and 1 or not member and 2 or 3}
        end
    end
    table.sort(ordered,function(a,b)
        if a.rank~=b.rank then return a.rank<b.rank end
        if (a.node.last_seen or 0)~=(b.node.last_seen or 0) then return (a.node.last_seen or 0)>(b.node.last_seen or 0) end
        return a.key<b.key
    end)
    local live={}
    for index,item in ipairs(ordered) do
        if index>128 then break end
        local node,member=item.node,item.member
        local address=tonumber(node.address)
        local bound=a11y.control_for_widget(item.key)
        local provisional=control_rows_by_label_widget[item.key]
        local event=a11y.engine_focus and a11y.engine_focus.nodes and a11y.engine_focus.nodes[item.key]
        local text,raw,font=a11y.read_native_rendered_text(address)
        local path={}
        for _,entry in ipairs(member and member.owners or {}) do
            if entry.parents then
                local at,visited=address,{}
                for _=1,8 do
                    if not at or visited[at] then break end
                    visited[at]=true
                    path[#path+1]=tostring(at)
                    parents[at]=true
                    if at==entry.root then break end
                    at=entry.parents[at]
                end
                break
            end
        end
        -- membership=unknown is intentionally not reported as visible.
        local raw_hex=((raw or node.raw_text or ""):sub(1,128):gsub(".",function(byte) return string.format("%02x",byte:byte()) end))
        local line=string.format("NODE key=%q identity=%q type=%s flags=%s focus104=%s event_edge=%s name=%q text=%q rendered=%q rendered_read=%s raw=%q raw_hex=%q font=%s member=%q selected=%s label=%q value=%q relation=%q provisional=%q link38=%s link40=%s link50=%s path=%q",
            item.key,tostring(node.identity),tostring(a11y.menu_read(address,"u64")),
            tostring(a11y.menu_read(address+0xc,"u32")),tostring(a11y.menu_read(address+0x104,"u32")),
            tostring(event and event.edge),node.name or "",a11y.diagnostic_text(node.text),
            a11y.diagnostic_text(text),tostring(text~=nil),a11y.diagnostic_text(raw or node.raw_text),raw_hex,tostring(font or node.native_font),
            member and (member.active and "input-owner" or member.presented and "context-owner" or "inactive-owner") or "unknown",
            tostring(item.selected),bound and a11y.diagnostic_text(bound.label) or "",
            bound and a11y.diagnostic_text(bound.value) or "",
            bound and (bound.native_field and "native-field" or bound.structural and "named-pair" or "provisional") or "none",
            provisional and a11y.diagnostic_text(provisional.label) or "",
            tostring(node.owner_link),tostring(a11y.menu_read(address+0x40,"u64")),
            tostring(a11y.menu_read(address+0x50,"u64")),table.concat(path,">"))
        live[item.key]=true
        if capture.nodes[item.key]~=line then lines[#lines+1]=line;capture.nodes[item.key]=line end
    end
    local removed={}
    for key in pairs(capture.nodes) do if not live[key] then removed[#removed+1]=key end end
    table.sort(removed)
    for _,key in ipairs(removed) do
        lines[#lines+1]=string.format("DROP key=%q reason=outside-sampled-model",key)
        capture.nodes[key]=nil
    end
    local addresses={}
    for at in pairs(parents) do addresses[#addresses+1]=at end
    table.sort(addresses)
    for index,at in ipairs(addresses) do
        if index>64 then break end
        local line="PARENT address=" .. tostring(at) .. " name=" .. string.format("%q",a11y.widget_internal_name(at) or "")
            .. " flags=" .. tostring(a11y.menu_read(at+0xc,"u32"))
            .. " focus104=" .. tostring(a11y.menu_read(at+0x104,"u32"))
            .. " fields=" .. a11y.native_node_summary(at)
        if capture.parents[at]~=line then lines[#lines+1]=line;capture.parents[at]=line end
    end
    lines[#lines+1]="END sampled=" .. tostring(math.min(#ordered,128)) .. " total=" .. tostring(#ordered)
    return lines
end

function a11y.poll_component_capture()
    local capture=a11y.component_capture
    if not capture or not capture.active or frame-(capture.last_poll or -10000)<12 then return end
    capture.last_poll=frame
    local signature=(a11y.native_owner_token() or "") .. ":" .. tostring(a11y.component_capture_dirty_frame)
        .. ":" .. tostring(a11y.diagnostic_last_input_frame)
        .. ":" .. tostring(a11y.native_cursor_identity)
        .. ":" .. tostring(a11y.ui_model and a11y.ui_model.generation)
    if signature==capture.signature then
        if not capture.followup_due or frame<capture.followup_due then return end
        capture.followup_due=nil
    else
        capture.signature=signature
        capture.followup_due=frame+36
    end
    capture.sequence=capture.sequence+1
    local output=table.concat(a11y.component_capture_lines(capture),"\n") .. "\n"
    -- On reaching a limit, preserve the entire file and report it explicitly.
    if capture.bytes+#output>33554432 or capture.sequence>20000 then
        capture.active=false
        log("[FLAccess] component-capture=limit-reached bytes=" .. tostring(capture.bytes))
        return
    end
    local file=io.open(capture.path,"at")
    if not file then capture.active=false;log("[FLAccess] component-capture=write-failed");return end
    file:write(output);file:close();capture.bytes=capture.bytes+#output
end

local function announce_control(row)
    if a11y.keyboard_window then return end
    if not row or not row.label then
        return
    end
    if row.label_widget and not a11y.native_presentation_ready(row.label_widget) then return end
    if a11y.read_context_state().kind == "dialog" then return end
    local spoken = control_speech(row)
    local result=a11y.selection_result({row=row,source="control",
        identity=row.identity or row.label_widget_key or row.label})
    if not result then return end
    local page=result.page
    if spoken ~= last_controller_announcement or (page and page.identity~=a11y.last_page_announcement)
            or last_announced_control_row ~= row
            or not a11y.read_context_state().selection_result
            or a11y.read_context_state().selection_result.status=="discarded"
            or a11y.read_context_state().selection_result.status=="failed"
            or a11y.read_context_state().selection_result.signature~=result.signature then
        if active_control_row ~= row then
            last_spoken_controller_tooltip_key = nil
            pending_controller_tooltip = nil
            pending_controller_tooltip_label = nil
            controller_tooltip_due_ms = nil
        end
        last_controller_announcement = spoken
        last_announced_control_row = row
        last_announced_selector_label = row.label_widget_key or row.label
        active_control_row = row
        active_controller_label = row.label
        active_control_focused_ms = tonumber(ffi.C.GetTickCount64())
        if a11y.read_tooltips and latest_generic_tooltip
                and latest_generic_tooltip_widget ~= row.label_widget
                and active_control_focused_ms - latest_generic_tooltip_ms <= 1000 then
            pending_controller_tooltip = latest_generic_tooltip
            pending_controller_tooltip_label = row.label
            controller_tooltip_due_ms = active_control_focused_ms
        end
        if not a11y.deliver_selection_result(result) then
            -- A temporary modal hold is not a delivered control announcement.
            last_controller_announcement,last_announced_control_row=nil,nil
        end
    end
end

local function announce_control_value(row, value)
    if not row or not value or value == "" then
        return
    end
    if a11y.read_context_state().kind == "dialog" then return end
    row.value = value
    if a11y.keyboard_window then return end
    local full = control_speech(row)
    if row.label_widget and not a11y.native_widget_allowed(row.label_widget) then return end
    local result=a11y.selection_result({row=row,source="control",
        identity=row.identity or row.label_widget_key or row.label})
    if not result then return end
    if full == last_controller_announcement
            and last_announced_control_row == row then
        return
    end
    last_controller_announcement = full
    last_announced_control_row = row
    local row_key = row.label_widget_key or row.label
    if active_control_row == row and last_announced_selector_label == row_key then
        a11y.deliver_selection_result(result,{value_only=true})
    else
        active_control_row = row
        last_announced_selector_label = row_key
        a11y.deliver_selection_result(result)
    end
end

local function reset_stadium_screen()
    a11y.stadium_value_index_by_widget = {}
    a11y.stadium_rows = {}
    a11y.stadium_started_frame = frame
end

local function stadium_value_category(text)
    if text == "Dia" or text == "Noite"
            or text == "Day" or text == "Night" then
        return 2
    end
    if text == "Verão" or text == "Inverno" or text == "Primavera"
            or text == "Outono" or text == "Ensolarado"
            or text == "Chuva" or text == "Neve"
            or text == "Summer" or text == "Winter" or text == "Spring"
            or text == "Autumn" or text == "Fine" or text == "Rain"
            or text == "Snow" then
        return 3
    end
    if text == "Curta" or text == "Longa"
            or text == "Short" or text == "Long" then
        return 4
    end
    if text == "Seco" or text == "Molhado" or text == "Encharcado"
            or text == "Dry" or text == "Wet" or text == "Waterlogged" then
        return 5
    end
    return nil
end

local function stadium_control_for_entry(widget_key, entry)
    if not a11y.stadium_active or not widget_key or not entry then
        return nil
    end
    local index = a11y.stadium_value_index_by_widget[widget_key]
    if not index then
        index = stadium_value_category(entry.text)
        if index and a11y.stadium_rows[index]
                and a11y.stadium_rows[index].value_widget_key ~= widget_key then
            index = nil
        end
    end
    if not index and not a11y.stadium_rows[1] then
        -- The first focused value after opening this screen is the stadium.
        -- Unlike the remaining values, its text is an arbitrary stadium name.
        index = 1
    end
    if not index then
        -- "Aleatório" and "Normal" are shared by several rows. Assign a new
        -- value widget by the screen's verified top-to-bottom order and keep
        -- that ownership while its text changes laterally.
        for candidate = 2, 5 do
            if not a11y.stadium_rows[candidate] then
                index = candidate
                break
            end
        end
    end
    if not index then
        return nil
    end
    a11y.stadium_value_index_by_widget[widget_key] = index
    local labels = stadium_labels[a11y.ui_language] or stadium_labels.en
    local row = a11y.stadium_rows[index]
    if not row then
        row = {
            label = labels[index],
            role = "seletor",
            label_widget_key = "stadium:" .. tostring(index),
            value_widget_key = widget_key,
            is_control = true,
        }
        a11y.stadium_rows[index] = row
    end
    row.value_widget_key = widget_key
    row.value = entry.text
    return row
end

local function announce_controller_row(label, value)
    if not label then
        return
    end
    local row = controller_rows[label]
    if not row then
        row = {label = label, role = selector_role(label)}
        controller_rows[label] = row
    end
    if value and value ~= "" then
        row.value = value
    end
    row.is_control = true
    announce_control(row)
end

function a11y.read_msvc_string(object,raw)
    object=tonumber(object)
    if not object or object<0x10000 then return nil end
    local work=a11y.render_read_work
    local key=tostring(object) .. ":" .. tostring(raw)
    if work and work.strings and work.strings[key]~=nil then return work.strings[key] or nil end
    local length=tonumber(read_u64(a11y.safe_memory_read(object+0x10,8)))
    local capacity=tonumber(read_u64(a11y.safe_memory_read(object+0x18,8)))
    if not length or not capacity or length>4096 or capacity<length or capacity>65536 then return nil end
    if length==0 then return "" end
    local source=capacity>=16 and read_u64(a11y.safe_memory_read(object,8)) or object
    local text=source and a11y.safe_memory_read(source,length)
    if not text then return nil end
    local result=raw and text or clean_text(text)
    if work then work.strings=work.strings or {};work.strings[key]=result end
    return result
end

function a11y.widget_internal_name(widget)
    -- The UI text widget contains another MSVC string at +0x18. In captured
    -- FL26 objects this is a stable engine-side name (teamName, btnH_str,
    -- ok_text, setName), not the localized caption. Read it only for
    -- structural field pairs; a name alone does not prove visibility or focus.
    if not widget or widget < 0x10000 then return nil end
    local name = a11y.read_msvc_string(widget + 0x18)
    if name and #name <= 64 and name:match("^[%w_%.%-]+$") then
        return name
    end
    return nil
end

-- Bounded observations, independent of translated captions and render order.
-- +0x38 is deliberately not used: its ownership semantics remain unproven.
function a11y.reset_read_context(reason)
    a11y.last_roster_navigation=nil
    if reason == "transition" then a11y.answer_chain = nil end
    local old = a11y.read_context
    a11y.deferred_modal_announcement,a11y.deferred_speech=nil,nil
    a11y.read_context = {
        generation=(old and old.generation or 0) + 1,
        kind="unknown", reason=reason, started_frame=frame,
        cursor=1,
        title=nil, question=nil, selection=nil, help=nil,
    }
    if reason == "dialog-input" and old and (old.structural_question or old.structural_event) then
        a11y.read_context.kind = "dialog"
        a11y.read_context.structural_question = old.structural_question
        a11y.read_context.structural_event = old.structural_event
        a11y.read_context.owner_link = old.owner_link
        a11y.read_context.baseline, a11y.read_context.answer_owners = {},{}
        a11y.read_context.expires_frame = frame + 3600
    end
end

function a11y.is_structural_answer(text, key)
    local context = a11y.read_context
    if not context or not (context.structural_question or context.structural_event) or not context.owner_link then return false end
    local model = a11y.ui_model
    for node_key, node in pairs(model and model.nodes or {}) do
        if (not key or node_key == key) and node.text == text and node.name == "text"
                and node.owner_link == context.owner_link then return true end
    end
    return false
end

function a11y.capture_question_panel(node)
    if not a11y.native_presentation_ready(node.address) then
        a11y.defer_bound_guidance(node.address,node.text)
        return false
    end
    if (node.name ~= "question" and node.name ~= "eventMsg") or not node.owner_link or not node.text or node.text == "" then return false end
    a11y.dashboard_review = false
    local context = a11y.read_context_state()
    if (context.structural_question or context.structural_event) and context.message_key == node.key and context.question == node.text then
        return true
    end
    a11y.open_read_dialog(node.text, node.key)
    context = a11y.read_context_state()
    context.kind, context.owner_link = "dialog", node.owner_link
    context.structural_question, context.structural_event = node.name == "question", node.name == "eventMsg"
    for key, other in pairs(a11y.ui_model.nodes) do
        if context.structural_question and other.name == "text" and other.owner_link == node.owner_link then
            context.answer_owners[key] = other.identity
            if #other.text >= 2 and #other.text <= 512 and not ui_focus_widgets[key] then
                ui_focus_widgets[key] = {address=other.address,text=other.text,last_seen=other.last_seen,identity=other.identity}
                ui_focus_widget_count = ui_focus_widget_count + 1
            end
        end
    end
    -- The localization resolver may have queued options before their widgets
    -- revealed the question layout. Replace that batch with the actual prompt.
    a11y.native_speech_queue, a11y.native_speech_first, a11y.native_speech_last = {},1,0
    a11y.modal_message_backlog = {}
    a11y.pending_modal_button_text, a11y.deferred_modal_announcement = nil,nil
    recent_message_text, recent_message_widget_key, recent_message_frame = node.text,node.key,frame
    pending_message_text, pending_message_key = node.text,node.key .. "\0" .. node.text
    a11y.pending_message_widget_key = node.key
    a11y.pending_message_owner=a11y.native_owner_token()
    pending_message_due_ms = tonumber(ffi.C.GetTickCount64()) + 40
    a11y.clear_pending_tooltips()
    a11y.transition_old_focus_texts, a11y.transition_old_focus_nodes = nil,nil
    log(string.format("[FLAccess] question-panel owner=%s widget=%s",tostring(node.owner_link),node.key))
    return true
end

function a11y.read_context_state()
    if not a11y.read_context then a11y.reset_read_context("initial") end
    return a11y.read_context
end

function a11y.open_read_dialog(text, key)
    local context = a11y.read_context_state()
    if context.question == text and context.message_key == key then return end
    if context.message_key == key and context.question
            and text:sub(1, #context.question) == context.question then
        context.question = text
        if a11y.text_asset_role(text) == "dialog" or text:match("%?$") then
            context.kind = "dialog"
        end
        return
    end
    local owners = context.message_key == key and context.answer_owners or nil
    local chain = a11y.answer_chain
    if not owners and chain and chain.message_key == key
            and frame - chain.frame <= 120 and a11y.ui_model
            and chain.model_generation == a11y.ui_model.generation then
        owners = chain.owners
    end
    a11y.answer_chain = nil
    local baseline = {}
    for widget_key, entry in pairs(ui_focus_widgets) do
        baseline[widget_key] = {text=entry.text, seen=entry.last_seen}
    end
    a11y.reset_read_context("dialog")
    context = a11y.read_context
    context.kind = (a11y.text_asset_role(text) == "dialog" or text:match("%?$"))
        and "dialog" or "notice"
    context.question, context.message_key = text, key
    local native_owner=a11y.native_owner_token()
    context.native_owner=native_owner ~= "" and native_owner or nil
    context.baseline = baseline
    context.answer_owners = owners or {}
    context.answer_queued = false
    context.expires_frame = frame + 3600
    log(string.format("[FLAccess] reading-context kind=%s generation=%d", context.kind, context.generation))
end

function a11y.set_read_title(text)
    a11y.answer_chain = nil
    local context = a11y.read_context_state()
    if context.native_reading_panel and a11y.reading_panel_is_current() then
        context.title=text
        return
    end
    if context.question or context.structural_question or context.structural_event then a11y.reset_read_context("title") end
    context = a11y.read_context_state()
    context.title, context.kind, context.pending_title = text, "menu", nil
end

function a11y.set_read_help(text, label)
    local context = a11y.read_context_state()
    if context.kind ~= "dialog" then
        context.help = {text=text, label=label, frame=frame}
    end
end

function a11y.commit_read_selection(text, identity, source, label, widget)
    local context = a11y.read_context_state()
    if context.native_reading_panel and not a11y.reading_panel_is_current() then
        a11y.reset_read_context("reading-panel-selection-changed")
        context=a11y.read_context_state()
    end
    if context.kind == "dialog" and source ~= "dialog-answer" then return false end
    if not text or text == "" or is_noninteractive_text(text)
            or text == "No String" then return false end
    if context.pending_title then
        local title = context.pending_title
        a11y.set_read_title(title)
        context = a11y.read_context_state()
        speak(title)
        a11y.title_pending_first_item = title
        a11y.title_pending_first_item_until_ms = tonumber(ffi.C.GetTickCount64()) + 2000
    end
    if context.selection and context.selection.identity ~= identity then
        context.selection_result=nil
        if context.help and context.help.label ~= label then context.help = nil end
        context.cursor = 1
    end
    context.selection = {text=text, identity=identity, source=source, label=label, frame=frame,
        origin=widget and a11y.capture_speech_origin(widget) or nil}
    if context.kind == "unknown" then context.kind = "menu" end
    return true
end

-- Producers supply observations; this boundary owns composition, review,
-- deduplication and delivery validity. Missing context is not a blank value.
function a11y.selection_result(request)
    local address=request.widget or (request.row and request.row.label_widget)
    if address and not a11y.native_presentation_ready(address) then return nil end
    local context=a11y.read_context_state()
    if context.kind=="dialog" and request.source~="dialog-answer" then return nil end
    local key=address and memory.hex(address)
    local node=request.node or (key and a11y.ui_model and a11y.ui_model.nodes[key])
    if node and (a11y.is_media_caption(node) or a11y.is_menu_description(node)) then return nil end
    local row=request.row or (key and a11y.control_for_widget(key))
    if row and not row.is_control and not request.row then row=nil end
    if request.text and not request.row then row=nil end
    local label=request.text or (row and row.label) or (node and node.text)
    if not label or a11y.empty_selection_caption(label) or a11y.unresolved_format(label) then return nil end
    local value=row and row.value
    local music=a11y.native_music_packet(node)
    local text=music and music.text or (row and control_speech(row) or a11y.engine_focus_speech(label,node))
    if request.text and not request.row then text=a11y.engine_focus_speech(request.text,node) end
    if request.source=="dialog-answer" then
        text=label .. (a11y.ui_language=="pt" and ", opção selecionada" or ", selected option")
    end
    if request.presentation then text=request.presentation end
    local assignment=a11y.native_assignment_context(address)
    if assignment then text=a11y.output_speech_text(text) .. ", " .. assignment.text end
    local spoken,page=a11y.page_focus_speech(text,address)
    local owner=a11y.native_owner_token()
    local identity=request.identity or (key and node and a11y.engine_selection_identity(key,node)) or label
    local result={widget=address,key=key,node=node,row=row,label=label,value=value,
        text=text,spoken=spoken,page=page,assignment=assignment,music=music,owner=owner,generation=context.generation,
        source=request.source or "component",identity=identity,
        origin=address and a11y.capture_speech_origin(address),
        value_origin=row and row.value_widget and a11y.capture_speech_origin(row.value_widget),
        missing={}}
    result.roster=a11y.native_player_roster_context(node)
    result.player_section=node and node.name and node.name:lower():find("playername",1,true)
        and ((result.roster and result.roster.section) or a11y.player_component_section(node)) or nil
    result.caption_binding=address and a11y.native_caption_selection_identity(address)
    if row and value==nil then result.missing[#result.missing+1]="value" end
    result.player_parts={}
    for _,part in ipairs(a11y.player_row_details(node)) do
        result.player_parts[#result.player_parts+1]=a11y.capture_speech_origin(part.address)
    end
    result.signature=a11y.selection_result_signature(result)
    return result
end

function a11y.selection_result_signature(result)
    return tostring(result.owner) .. ":" .. tostring(result.generation) .. ":"
        .. result.identity .. ":" .. result.text .. ":" .. (result.page and result.page.identity or "")
        .. ":" .. (result.assignment and result.assignment.identity or "")
        .. ":" .. (result.roster and result.roster.identity or "")
        .. ":" .. (result.caption_binding or "")
end

function a11y.roster_navigation_speech(result,text)
    local previous=a11y.last_roster_navigation
    if not result or not result.player_section or not previous
            or previous.owner~=result.owner or previous.generation~=result.generation
            or previous.section~=result.player_section then return text end
    local prefixes=a11y.ui_language=="pt"
        and {starter="Titular. ",reserve="Reserva. ",unselected="Não relacionado. "}
        or {starter="Starter. ",reserve="Substitute. ",unselected="Not selected. "}
    local prefix=prefixes[result.player_section]
    local page=result.page and result.page.text .. ". " or ""
    if prefix and text:sub(1,#page+#prefix)==page .. prefix then
        return page .. text:sub(#page+#prefix+1)
    end
    return text
end

function a11y.remember_roster_navigation(result)
    if not result then return end
    a11y.last_roster_navigation=result and result.player_section and {
        owner=result.owner,generation=result.generation,section=result.player_section} or nil
end

function a11y.selection_result_allowed(result)
    local context=a11y.read_context_state()
    if context.generation~=result.generation or a11y.native_owner_token()~=result.owner then return false end
    if not context.selection or context.selection.identity~=result.identity then return false end
    if context.selection_result and context.selection_result.signature~=result.signature then return false end
    if result.origin and not a11y.speech_origin_allowed(result.origin) then return false end
    if result.value_origin and not a11y.speech_origin_allowed(result.value_origin) then return false end
    for _,origin in ipairs(result.player_parts or {}) do
        if not a11y.speech_origin_allowed(origin)
                or a11y.read_native_rendered_text(origin.address)~=origin.text then return false end
    end
    for _,origin in ipairs({result.origin or false,result.value_origin or false}) do
        if origin and origin.text then
            local current=a11y.read_native_rendered_text(origin.address)
            if current~=nil and current~=origin.text then return false end
        end
    end
    if result.row and (result.row.label~=result.label or result.row.value~=result.value) then return false end
    local current_page=a11y.native_page_context(result.widget)
    if (result.page and result.page.identity or nil)~=(current_page and current_page.identity or nil) then return false end
    local music=a11y.native_music_packet(result.node)
    if (result.music and result.music.signature or nil)~=(music and music.signature or nil) then return false end
    local assignment=a11y.native_assignment_context(result.widget)
    if (result.assignment and result.assignment.identity or nil)~=(assignment and assignment.identity or nil) then return false end
    local roster=a11y.native_player_roster_context(result.node)
    if (result.roster and result.roster.identity or nil)~=(roster and roster.identity or nil) then return false end
    if result.player_section and ((roster and roster.section) or a11y.player_component_section(result.node))~=result.player_section then return false end
    if result.caption_binding~=(result.widget and a11y.native_caption_selection_identity(result.widget)) then return false end
    if result.node and result.key and result.source=="engine-focus"
            and a11y.engine_selection_identity(result.key,result.node)~=result.identity then return false end
    return true
end

function a11y.deliver_selection_result(result,options)
    if not result or a11y.keyboard_window then return false end
    options=options or {}
    local context=a11y.read_context_state()
    local previous=context.selection_result
    if previous and previous.signature==result.signature
            and (previous.status=="queued" or previous.status=="delivered") and context.selection
            and context.selection.identity==result.identity then return true end
    if not a11y.commit_read_selection(result.text,result.identity,result.source,result.label,result.widget) then return false end
    -- commit may open a pending title; bind to the resulting context generation.
    context=a11y.read_context_state()
    result.generation=context.generation
    result.signature=a11y.selection_result_signature(result)
    local before=a11y.native_speech_last
    local spoken=options.value_only and result.value or result.spoken
    if not result.page and options.interrupt~=false then
        for index=a11y.native_speech_first,a11y.native_speech_last do
            local pending=a11y.native_speech_queue[index]
            if pending and pending.page_context and not pending.selection_result
                    and a11y.page_delivery_allowed(pending.page_context) then
                options.interrupt=false;break
            end
        end
    end
    result.attempt=previous and previous.signature==result.signature and (previous.attempt or 0)+1 or 1
    speak(spoken,options.interrupt,options.modal,result.signature .. ":attempt=" .. tostring(result.attempt),result.widget)
    if a11y.native_speech_last==before then
        local deferred=a11y.deferred_speech
        if deferred and deferred.text==spoken and a11y.deferred_modal_announcement==spoken then
            deferred.selection_result=result
            deferred.options={interrupt=false,value_only=options.value_only,modal=options.modal}
            context.selection_result=result
            result.status="deferred"
        end
        return false
    end
    context.selection_result=result
    result.status="queued"
    if result.page then a11y.last_page_announcement=result.page.identity end
    if result.page then
        for index=a11y.native_speech_first,before do
            local pending=a11y.native_speech_queue[index]
            if pending and pending.page_context and not pending.selection_result
                    and pending.page_context.identity==result.page.identity then pending.superseded=true end
        end
    end
    for index=before+1,a11y.native_speech_last do
        local entry=a11y.native_speech_queue[index]
        entry.selection_result=result
        entry.page_context=result.page
    end
    log(string.format("[FLAccess] selection-result source=%s widget=%s label=%q value=%q missing=%q",
        result.source,tostring(result.widget),result.label,result.value or "",table.concat(result.missing,",")))
    return true
end

-- Deferral is still speech work: retain the same ownership/content evidence
-- rather than converting a composed selection into an unbound literal string.
function a11y.defer_speech(text,identity,address)
    local context=a11y.read_context_state()
    a11y.deferred_modal_announcement=text
    a11y.deferred_speech={text=text,identity=identity,owner=a11y.native_owner_token(),
        generation=context.generation,selection_identity=context.selection and context.selection.identity,
        origin=address and a11y.capture_speech_origin(address)}
end

function a11y.drain_deferred_speech()
    local now=tonumber(ffi.C.GetTickCount64())
    if pending_message_text or now<modal_focus_hold_until_ms or now<(a11y.screen_title_hold_until_ms or 0) then return false end
    local text,deferred=a11y.deferred_modal_announcement,a11y.deferred_speech
    a11y.deferred_modal_announcement,a11y.deferred_speech=nil,nil
    if not text then return false end
    local context=a11y.read_context_state()
    local valid=deferred and deferred.text==text and deferred.owner==a11y.native_owner_token()
        and deferred.generation==context.generation
        and (not deferred.selection_identity or (context.selection and context.selection.identity==deferred.selection_identity))
        and (not deferred.origin or a11y.speech_origin_allowed(deferred.origin))
    if valid and deferred.origin and deferred.origin.text then
        local current=a11y.read_native_rendered_text(deferred.origin.address)
        if current~=nil and current~=deferred.origin.text then valid=false end
    end
    if valid and deferred.selection_result then valid=a11y.selection_result_allowed(deferred.selection_result) end
    if not valid then
        if deferred and deferred.selection_result then deferred.selection_result.status="discarded" end
        log("[FLAccess] deferred-speech-discard reason=context-or-content-changed")
        return false
    end
    if deferred.selection_result then return a11y.deliver_selection_result(deferred.selection_result,deferred.options) end
    speak(text,false,nil,deferred.identity,deferred.origin and deferred.origin.address)
    return true
end

-- Compatibility producers retain their established extraction. They submit
-- data here instead of bypassing the common validity and delivery decision.
function a11y.offer_adapter_selection(text,identity,address,interrupt)
    return a11y.deliver_selection_result(a11y.selection_result({widget=address,
        text=text,presentation=text,identity=identity,source="adapter-focus"}),{interrupt=interrupt})
end

function a11y.dialog_answer_candidate(key, entry, offset, activity)
    local context = a11y.read_context_state()
    if context.kind ~= "dialog" or frame > context.expires_frame
            or not entry or offset ~= 0x104
            or pending_message_text or #a11y.modal_message_backlog > 0 then return false end
    local role = a11y.text_asset_role(entry.text)
    local scoped_node = a11y.ui_model and a11y.ui_model.nodes[key]
    if context.structural_event then
        local snapshot=a11y.native_windows
        return scoped_node and scoped_node.key~=context.message_key and is_modal_button(entry.text)
            and snapshot and snapshot.selected_members and snapshot.selected_members[tonumber(scoped_node.address)]
            and a11y.native_presentation_ready(scoped_node.address)
            and scoped_node.owner_link==context.owner_link
    end
    if context.structural_question then
        return scoped_node and scoped_node.owner_link == context.owner_link and scoped_node.name == "text"
            and not is_noninteractive_text(entry.text) and role ~= "technical" and role ~= "status"
            and (entry.last_seen >= context.started_frame or context.answer_owners[key] == scoped_node.identity)
    end
    if key == context.message_key or entry.text == context.question
            or role == "dialog" or role == "instruction" or role == "tooltip-or-description"
            or is_noninteractive_text(entry.text) or is_splash_text(entry.text) then return false end
    local previous = context.baseline[key]
    local changed = previous and previous.text ~= entry.text
    local introduced = not previous
    local fresh_edge = activity and activity >= context.started_frame
    local node = a11y.ui_model and a11y.ui_model.nodes[key]
    local owned = node and context.answer_owners[key] == node.identity
    local engine=a11y.engine_focus
    local live_event=engine and engine.nodes[key]
    local native_focus=node and context.native_owner and engine
        and engine.owner==context.native_owner and a11y.native_owner_token()==context.native_owner
        and live_event and live_event.edge>=context.started_frame
        and live_event.edge==activity and a11y.native_widget_allowed(node.address)
    -- A background row may redraw with the dialog. Redraw alone is not an
    -- answer; require the primary selection edge or a newly introduced row.
    if not introduced and not changed and not fresh_edge and not owned then return false end
    if entry.last_seen < context.started_frame and not owned and not native_focus then return false end
    if role == "technical" or role == "status" then return false end
    return true
end

function a11y.announce_read_answer(key, entry, offset, activity)
    if not a11y.dialog_answer_candidate(key, entry, offset, activity) then return false end
    local context = a11y.read_context
    local identity = tostring(context.generation) .. ":" .. a11y.ui_focus_identity(key, entry.text)
    local text = entry.text .. (a11y.ui_language == "pt" and ", opção selecionada" or ", selected option")
    a11y.commit_read_selection(text, identity, "dialog-answer")
    context.selection.widget_key = key
    local node = a11y.ui_model and a11y.ui_model.nodes[key]
    if node then context.answer_owners[key] = node.identity end
    if context.structural_question and (a11y.navigation_frame or -1) < context.started_frame then return true end
    if context.last_answer ~= identity then
        local queue = not context.answer_queued and tonumber(ffi.C.GetTickCount64()) < modal_focus_hold_until_ms
        local before=a11y.native_speech_last
        a11y.deliver_selection_result(a11y.selection_result({text=entry.text,widget=node and node.address,
            identity=identity,source="dialog-answer"}),{interrupt=not queue,modal=true})
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].reading_selection={generation=context.generation,identity=identity}
        end
        if a11y.native_speech_last>before then
            context.last_answer, context.answer_queued = identity, true
        end
    end
    return true
end

function a11y.reading_panel_is_current()
    local context=a11y.read_context
    local snapshot=a11y.native_windows
    local node=context and context.message_key and a11y.ui_model and a11y.ui_model.nodes[context.message_key]
    return context and context.native_reading_panel and context.native_owner==a11y.native_owner_token()
        and node and snapshot and snapshot.members and snapshot.members[tonumber(node.address)]
        and snapshot.members[tonumber(node.address)].presented~=false
        and context.native_reading_panel==context.native_owner .. ":" .. node.identity .. ":" .. node.text
        and a11y.native_presentation_ready(node.address) and a11y.ui_node_matches_live(node)
end

function a11y.capture_reading_panel(node)
    local snapshot=a11y.native_windows
    local address=node and tonumber(node.address)
    if not node or node.name~="text_contents" or not node.text or node.text==""
            or a11y.unresolved_format(node.text) or not snapshot or not snapshot.selected_members or not snapshot.selected_members[address]
            or not a11y.native_presentation_ready(address) or not a11y.ui_node_matches_live(node) then return false end
    local count=0
    for selected in pairs(snapshot.selected_members) do
        local other=a11y.ui_model.nodes[memory.hex(selected)]
        if other and other.name=="text_contents" and a11y.native_presentation_ready(selected) then count=count+1 end
    end
    if count~=1 then return false end
    local context=a11y.read_context_state()
    if context.structural_question or context.structural_event then return false end
    local owner=a11y.native_owner_token()
    if not owner or owner=="" then return false end
    local identity=owner .. ":" .. node.identity .. ":" .. node.text
    if context.native_reading_panel==identity then return true end
    local changing=context.native_reading_panel~=nil
    local title=context.title
    reset_message_state()
    a11y.reset_read_context("native-reading-panel")
    context=a11y.read_context_state()
    context.kind,context.question,context.message_key="notice",node.text,node.key
    context.native_owner,context.native_reading_panel,context.title=owner,identity,title
    modal_focus_hold_until_ms=0
    a11y.clear_pending_tooltips()
    speak(node.text,changing,true,identity,node.address)
    return true
end

function a11y.poll_notice_actions()
    local context=a11y.read_context_state()
    local node=context.message_key and a11y.ui_model and a11y.ui_model.nodes[context.message_key]
    local snapshot=a11y.native_windows
    local bar=snapshot and snapshot.command_bar
    local message=node and snapshot and snapshot.members[tonumber(node.address)]
    if not context.question or not message or not bar then a11y.notice_actions=nil;return end
    local identity=tostring(context.generation) .. ":" .. tostring(context.question) .. ":" .. tostring(a11y.native_owner_token())
    if a11y.notice_actions==identity then return end
    local count=0
    for _,pair in ipairs(bar.pairs or {}) do
        local member=snapshot.members[pair.caption]
        local same=false
        for _,owner in ipairs(member and member.owners or {}) do
            for _,other in ipairs(message.owners or {}) do
                if owner.enabled and other.enabled and owner.address==other.address and owner.root==other.root then same=true end
            end
        end
        local text=same and a11y.read_native_rendered_text(pair.caption)
        if text and text~="" and not a11y.unresolved_format(text) and a11y.native_presentation_ready(pair.caption) then
            speak(text,false,true,"notice-action:" .. identity .. ":" .. pair.caption,pair.caption)
            count=count+1
            if count>=4 then break end
        end
    end
    if count>0 then a11y.notice_actions=identity end
end

function a11y.process_read_dialog_focus(candidates)
    local context = a11y.read_context_state()
    if context.kind ~= "dialog" then return false end
    if not context.structural_question and not context.structural_event
            and a11y.native_control_help(context.question) then
        local help=context.question
        reset_message_state()
        a11y.reset_read_context("native-field-help")
        a11y.set_read_help(help)
        modal_focus_hold_until_ms=0
        return false
    end
    if frame > context.expires_frame then
        a11y.reset_read_context("dialog-expired")
        return false
    end
    local selected, reason = a11y.resolve_primary_focus(candidates)
    local entry = selected and (ui_focus_widgets[selected.key]
        or (a11y.ui_model and a11y.ui_model.nodes[selected.key]))
    if not selected or not a11y.dialog_answer_candidate(selected.key, entry, 0x104, selected.edge) then
        context.candidate = nil
        local unresolved = pending_message_text and "message-pending"
            or (selected and "context-ownership-unproven" or reason)
        if unresolved ~= context.unresolved_reason then
            context.unresolved_reason = unresolved
            log(string.format("[FLAccess] dialog-selection-unresolved reason=%s candidates=%d", unresolved, #candidates))
        end
        return true
    end
    local identity = a11y.ui_focus_identity(selected.key, entry.text)
    if identity ~= context.candidate then
        context.candidate, context.candidate_frame = identity, frame
    elseif frame - context.candidate_frame >= 4 then
        a11y.announce_read_answer(selected.key, entry, 0x104, selected.edge)
    end
    if a11y.ui_model then a11y.ui_model.focus_reason = "dialog:" .. reason end
    return true
end

function a11y.entity_review_entries(nodes)
    local item=a11y.native_list_selection
    local snapshot=a11y.native_windows
    local owner=a11y.native_owner_token()
    if a11y.keyboard_window or a11y.read_context_state().kind=="dialog" then return nil end
    local selection=a11y.read_context_state().selection
    if selection and selection.origin and item and selection.origin.address~=item.widget then return nil end
    if not item or not owner or item.committed~=owner .. ":" .. item.identity .. ":" .. item.text
            or a11y.widget_internal_name(item.widget)~="teamName"
            or a11y.read_native_rendered_text(item.widget)~=item.text then return nil end
    local selected=snapshot and snapshot.members and snapshot.members[item.widget]
    if not selected or not selected.active then return nil end
    local anchor=a11y.ui_model.nodes[memory.hex(item.widget)]
    local review={nodes={anchor},anchor=anchor,identity=item.committed,list_identity=item.committed}
    local windows={}
    for _,entry in ipairs(selected.owners or {}) do if entry.enabled then windows[entry.address]=true end end
    local players,roots={},{}
    local function belongs(node,root)
        local member=snapshot.members[tonumber(node.address)]
        for _,entry in ipairs(member and member.owners or {}) do
            if entry.enabled and windows[entry.address] and (not root or entry.root==root) then return entry.root end
        end
    end
    for _,node in ipairs(nodes) do
        if node.name and (node.name=="playerName" or node.name:match("^playerName_")) then
            local root=belongs(node)
            if root then roots[root]=true;players[#players+1]=node end
        end
    end
    if #players==0 then return {item.text},review end
    local root
    for value in pairs(roots) do if root then return {item.text},review end;root=value end
    local heading
    for _,node in ipairs(nodes) do
        if (node.name=="text_title" or node.name=="title" or node.name=="listHeader" or node.name=="header")
                and belongs(node,root) then
            if heading and heading.text~=node.text then heading=false;break end
            heading=node
        end
    end
    local result,seen={item.text},{[item.text]=true}
    if heading and not seen[heading.text] then
        result[#result+1],seen[heading.text]=heading.text,true
        review.nodes[#result]=heading
    end
    for _,node in ipairs(players) do
        if not a11y.empty_selection_caption(node.text) then
            result[#result+1]=node.text
            review.nodes[#result]=node
        end
    end
    return result,review
end

-- Review a player list through the same indexed rows as its native cursor.
-- Repeated names stay separate; a detail panel or a second team cannot join it.
function a11y.player_list_review_entries(nodes)
    local snapshot=a11y.native_windows
    if not snapshot or a11y.keyboard_window or a11y.read_context_state().kind=="dialog" then return nil end
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local d=window.cursor_detail
        if window.enabled and d and d.group and d.selected then
            local rows,anchor={},nil
            for index=0,255 do
                local row=a11y.menu_child(d.group,index)
                if not row or row<0x10000 then break end
                rows[row]=index
            end
            local entries,has_rows={},false
            for _,node in ipairs(nodes) do
                if node.name=="playerName" and not a11y.empty_selection_caption(node.text) then
                    local member=snapshot.members[tonumber(node.address)]
                    local index,ambiguous
                    for _,owner in ipairs(member and member.owners or {}) do
                        if owner.enabled and owner.address==window.address and owner.root==window.root then
                            local at,seen=tonumber(node.address),{}
                            for _=1,12 do
                                at=owner.parents and owner.parents[at]
                                if not at or seen[at] then break end
                                seen[at]=true
                                if rows[at]~=nil then
                                    if index and index~=rows[at] then ambiguous=true end
                                    index=rows[at]
                                    if at==d.selected then anchor=node end
                                    break
                                end
                            end
                        end
                    end
                    if index and not ambiguous then
                        if entries[index] and entries[index]~=node then return nil end
                        entries[index]=node
                        has_rows=true
                    end
                end
            end
            if anchor then
                if found then return nil end
                local texts,ordered={},{}
                texts[1]=anchor.text
                ordered[1]=anchor
                for _,detail in ipairs(a11y.player_row_details(anchor)) do
                    texts[#texts+1]=detail.name=="allOver" and ((a11y.ui_language=="pt" and "Força geral: " or "Overall rating: ") .. detail.text) or detail.text
                    ordered[#ordered+1]=anchor
                end
                found={texts=texts,nodes=ordered,anchor=anchor,
                    selection={window=window.address,root=window.root,group=d.group,selected=d.selected},
                    identity=tostring(window.address) .. ":" .. tostring(d.group) .. ":" .. anchor.identity .. ":" .. anchor.text}
            elseif has_rows or a11y.widget_internal_name(d.group)=="p_list" then
                -- A recognized player list with an unavailable selected record
                -- must not leak other rows or the surrounding detail table.
                return {},{identity="player-unresolved:" .. window.address .. ":" .. d.group .. ":" .. d.selected,nodes={}}
            end
        end
    end
    if found then return found.texts,found end
end

function a11y.roster_review_allowed(review)
    if review.generation~=a11y.read_context_state().generation then return false end
    if review.selection then
        local found=false
        for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
            local d=window.cursor_detail
            if window.enabled and window.address==review.selection.window and window.root==review.selection.root
                    and d and d.group==review.selection.group and d.selected==review.selection.selected then found=true end
        end
        if not found then return false end
    end
    for _,origin in ipairs({review.origin,review.anchor}) do
        if not a11y.speech_origin_allowed(origin)
                or a11y.read_native_rendered_text(origin.address)~=origin.text then return false end
    end
    local node=a11y.ui_model.nodes[memory.hex(review.origin.address)]
    if not node or a11y.engine_selection_identity(node.key,node)~=review.identity then return false end
    for _,origin in ipairs(review.parts) do
        if not a11y.speech_origin_allowed(origin)
                or a11y.read_native_rendered_text(origin.address)~=origin.text then return false end
    end
    if review.list_identity then
        local item=a11y.native_list_selection
        if not item or item.committed~=review.list_identity then return false end
    end
    return true
end

function a11y.review_chrome(text,node)
    if not text or a11y.empty_selection_caption(text) or a11y.unresolved_format(text) then return true end
    local commands={ajuda=true,voltar=true,sair=true,["opções"]=true,confirmar=true,cancelar=true,
        ["avançar"]=true,["próximo"]=true,pular=true,help=true,back=true,exit=true,options=true,
        confirm=true,cancel=true,next=true,skip=true,ok=true}
    if commands[text:lower():gsub('^%s+',''):gsub('%s+$','')] then return true end
    if not node then return false end
    local name=(node.name or ''):lower()
    if name=='padicon' or name=='itemname' or name=='ok_text' or name:find('help',1,true) or name:find('guide',1,true)
            or name:find('tooltip',1,true) or name:match('^btn') or name:match('_button$')
            or name:match('_text$') and (name:find('back',1,true) or name:find('cancel',1,true))
            or a11y.is_media_caption(node) or a11y.is_menu_description(node) then return true end
    local bar=a11y.native_windows and a11y.native_windows.command_bar
    for _,pair in ipairs(bar and bar.pairs or {}) do
        if tonumber(node.address)==pair.caption or tonumber(node.address)==pair.icon then return true end
    end
    return a11y.is_control_help(text)
end

function a11y.content_review_allowed(origin)
    local node=a11y.ui_model and a11y.ui_model.nodes[origin.key]
    return node and node.identity==origin.identity and node.text==origin.text
        and origin.owner==a11y.native_owner_token() and a11y.native_presentation_ready(node.address)
        and a11y.ui_node_matches_live(node) and a11y.read_native_rendered_text(node.address)==origin.text
end

-- Selected-record packet, independent of the generic screen-text bag. The
-- native mailbox indexes 0x90 records; b44520 renders +8 title and +50 body.
function a11y.selected_message_packet()
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    local context=a11y.read_context_state()
    if not snapshot or not base or context.structural_question or context.structural_event then return nil end
    local work=a11y.render_read_work
    if work and work.mailbox~=nil then return work.mailbox or nil end
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        if window.enabled and (window.vtable or a11y.menu_read(window.address,"u64"))==base+0x26a1120
                and a11y.menu_read(window.address,"u64")==base+0x26a1120
                and a11y.menu_read(base+0x26a1120+0x148,"u64")==base+0xb43ad0 then
            local index=a11y.native_window_selected_index(window,base)
            local first,last=a11y.menu_read(window.address+0x90,"u64"),a11y.menu_read(window.address+0x98,"u64")
            local packet={identity="message:" .. window.address .. ":" .. tostring(window.root),entries={},nodes={}}
            if index and first and first>=0x10000 and last and last>=first and (last-first)%0x90==0
                    and last-first<=4096*0x90 and index<(last-first)/0x90 then
                local record=first+index*0x90
                local title=a11y.read_msvc_string(record+8)
                local mode=a11y.menu_read(record+0x48,"u32")
                local body=(mode==0 or mode==1) and a11y.read_msvc_string(record+0x50)
                if mode==1 then
                    local head,tail=a11y.menu_read(record+0x70,"u64"),a11y.menu_read(record+0x78,"u64")
                    if head and head>=0x10000 and tail and tail>=head and (tail-head)%0x28==0 and tail-head<=256*0x28 then
                        local parts={body or ""}
                        for at=head,tail-0x28,0x28 do
                            local part=a11y.read_msvc_string(at+8)
                            if part and part~="" and not a11y.unresolved_format(part) then parts[#parts+1]=part end
                        end
                        body=table.concat(parts,". ")
                    end
                end
                if title and title~="" then
                    packet.identity=packet.identity .. ":" .. record .. ":" .. title
                    packet.entries[1]=title
                    if body and body~="" and not a11y.unresolved_format(body) then packet.entries[2]=body end
                    packet.signature=packet.identity .. ":" .. (packet.entries[2] or "")
                end
            end
            if found then return {identity="message:ambiguous",entries={},nodes={}} end
            found=packet -- an unresolved record never falls through to all table rows
        end
    end
    if work then work.mailbox=found or false end
    return found
end

function a11y.selected_message_allowed(stamp)
    local packet=a11y.selected_message_packet()
    return packet and packet.signature==stamp.signature and a11y.native_owner_token()==stamp.owner
end

function a11y.poll_selected_message()
    local packet=a11y.selected_message_packet()
    if not packet or not packet.signature then a11y.selected_message_announced=nil;return end
    local previous=a11y.selected_message_announced
    if previous and previous.signature==packet.signature and previous.status~="pending" then return end
    if previous and previous.signature==packet.signature and previous.retry_after
            and tonumber(ffi.C.GetTickCount64())<previous.retry_after then return end
    local state={signature=packet.signature,status="pending",attempt=(previous and previous.attempt or 0)+1};a11y.selected_message_announced=state
    local before=a11y.native_speech_last
    speak(table.concat(packet.entries,". "),true,true,"selected-message:" .. packet.signature .. ":attempt=" .. state.attempt)
    for index=before+1,a11y.native_speech_last do
        a11y.native_speech_queue[index].selected_message={signature=packet.signature,owner=a11y.native_owner_token(),state=state}
        state.status="queued"
    end
end

-- Column names describe reusable native records, not translated screen paths.
a11y.record_columns={
    {"teamNameText","Time","Team"},
    {"leagueRank_teamName","Time","Team"},{"teamName","Time","Team"},
    {"leagueRank_rank","Posição","Position"},{"ranking","Posição","Position"},
    {"leagueRank_point","Pontos","Points"},{"point","Pontos","Points"},
    {"match","Jogos","Played"},{"winText","Vit\195\179rias","Wins"},
    {"drawText","Empates","Draws"},{"loseText","Derrotas","Losses"},
    {"ptsText","Pontos","Points"},{"goalsText","Gols marcados","Goals for"},
    {"goalsAgainstText","Gols sofridos","Goals against"},{"goalDifferenceText","Saldo de gols","Goal difference"},
    {"date","Dia","Day"},{"event","Evento","Event"},
    {"teamName_home","Time da casa","Home team"},{"teamName_away","Time visitante","Away team"},
}

function a11y.record_contains(node,window,row)
    local member=a11y.native_windows and a11y.native_windows.members[tonumber(node.address)]
    for _,owner in ipairs(member and member.owners or {}) do
        if owner.enabled and owner.address==window.address and owner.root==window.root then
            local at,seen=tonumber(node.address),{}
            for _=1,16 do
                if at==row then return true end
                if not at or seen[at] then break end
                seen[at]=true;at=owner.parents and owner.parents[at]
            end
        end
    end
    return false
end

function a11y.structured_record_packet()
    local context=a11y.read_context_state()
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    if not base or not snapshot or a11y.keyboard_window or context.structural_question or context.structural_event then return nil end
    local names=a11y.ui_model and a11y.ui_model.names or {}
    local work=a11y.render_read_work
    if work and work.structured~=nil then return work.structured or nil end
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local detail=window.enabled and window.cursor_detail
        if detail and detail.selected then
            local row=detail.selected
            -- NodeChoice can select an internal scrolling row while the outer
            -- window cursor stays on the whole table (calendar/news dashboard).
            local anchors=0
            for _,name in ipairs({"teamNameText","teamName","leagueRank_teamName","date"}) do
                for _,node in pairs(names[name] or {}) do
                    if a11y.record_contains(node,window,row) and a11y.native_presentation_ready(node.address) then anchors=anchors+1 end
                end
            end
            -- A choice can already BE one record. Its selector does not always
            -- index rows: descending blindly also selected individual columns.
            if anchors~=1 and a11y.menu_read(row,"u64")==base+0x27cb508 then
                local selectors=a11y.holder_kind_nodes(row+0x98,0x10)
                if selectors and #selectors==1 then
                    local vt=a11y.menu_read(selectors[1],"u64")
                    if vt==base+0x27b84d0 or vt==base+0x27be998 then
                        local index=a11y.menu_read(selectors[1]+0xbc,"u32")
                        row=index and a11y.menu_child(row,index)
                    else row=nil end
                elseif selectors and #selectors>1 then row=nil end
            end
            if row then
                local fields,nodes,keys,encountered={}, {}, {}, {}
                local function add(name,label)
                    local candidate
                    for _,node in pairs(names[name] or {}) do
                        if a11y.record_contains(node,window,row) and a11y.native_presentation_ready(node.address) then
                            encountered[name]=true
                            if candidate then return end
                            candidate=node
                        end
                    end
                    if candidate then
                        local text=a11y.read_native_rendered_text(candidate.address)
                        if text and not a11y.empty_selection_caption(text) and not a11y.unresolved_format(text) then
                            fields[#fields+1]=label .. ": " .. text;nodes[#nodes+1]=candidate;keys[name]=true
                        end
                    end
                end
                for _,column in ipairs(a11y.record_columns) do add(column[1],column[a11y.ui_language=="pt" and 2 or 3]) end
                -- Additional columns require an actual native label/value pair.
                -- Their numeric meanings are never guessed from column order.
                local column_names={}
                for name in pairs(names) do if name:match("_value$") then column_names[#column_names+1]=name end end
                table.sort(column_names)
                for _,name in ipairs(column_names) do
                    local stem=name:match("^(.-)_value$")
                    if stem then
                        local label
                        for _,node in pairs(names[stem .. "_item"] or {}) do
                            if a11y.record_contains(node,window,window.root) and a11y.native_presentation_ready(node.address) then
                                if label then label=false;break end
                                label=a11y.read_native_rendered_text(node.address)
                            end
                        end
                        if label and not a11y.review_chrome(label) then add(name,label) end
                    end
                end
                local calendar=keys.date and encountered.event
                local standings=(keys.teamNameText and keys.ptsText) or (keys.leagueRank_teamName and (keys.leagueRank_point or keys.leagueRank_rank))
                    or (keys.teamName and (keys.point or keys.ranking))
                local unresolved=(encountered.date and encountered.event and not calendar)
                    or (encountered.leagueRank_teamName and encountered.leagueRank_point and not standings)
                if unresolved then fields,nodes={},{} end
                if calendar or standings or unresolved then
                    if found then return nil end
                    local identity="record:" .. window.address .. ":" .. window.root .. ":" .. row .. ":" .. (fields[1] or "unresolved")
                    found={entries=fields,nodes=nodes,identity=identity,window=window.address,row=row,
                        signature=identity .. ":" .. table.concat(fields,"; "),
                        label=(standings or unresolved) and encountered.leagueRank_teamName and (a11y.ui_language=="pt" and "Classificação" or "Standings")
                            or unresolved and (a11y.ui_language=="pt" and "Calendário" or "Calendar") or nil}
                end
            end
        end
    end
    if work then work.structured=found or false end
    return found
end

function a11y.structured_record_allowed(stamp)
    local packet=a11y.structured_record_packet()
    return packet and packet.signature==stamp.signature and a11y.native_owner_token()==stamp.owner
end

function a11y.poll_structured_record(blocked)
    local packet=a11y.structured_record_packet()
    if not packet then a11y.structured_record_announced=nil;return false end
    if blocked then
        local context=a11y.read_context_state()
        if (a11y.navigation_frame or -10000)<(context.started_frame or 0)
                or frame-(a11y.navigation_frame or -10000)>2 then return true end
        modal_focus_hold_until_ms=0
    end
    local previous=a11y.structured_record_announced
    if previous and previous.signature==packet.signature and previous.status~="pending" then return true end
    local state={signature=packet.signature,status="pending",attempt=(previous and previous.attempt or 0)+1}
    a11y.structured_record_announced=state
    local before=a11y.native_speech_last
    local text=(packet.label and packet.label .. ". " or "") .. table.concat(packet.entries,"; ")
    speak(text,true,true,"structured-record:" .. packet.signature .. ":" .. state.attempt)
    for index=before+1,a11y.native_speech_last do
        a11y.native_speech_queue[index].structured_record={signature=packet.signature,owner=a11y.native_owner_token(),state=state}
        state.status="queued"
    end
    return true
end

function a11y.buffer_entries()
    -- A review request reads the current rendered panel, including companion
    -- lists, rather than the previous entity's cached captions.
    a11y.poll_native_texts(true)
    local nodes=a11y.presented_nodes()
    local context = a11y.read_context_state()
    local message=a11y.selected_message_packet()
    if message then return message.entries,{identity=message.identity,content=true,nodes={},message=message.signature} end
    local country=a11y.native_list_selection
    if country and country.country and country.native_only then
        local current=a11y.native_country_selection()
        if current and current.identity==country.identity and current.text==country.text then
            return {current.text},{identity=current.identity,nodes={},country={identity=current.identity,text=current.text,owner=a11y.native_owner_token()}}
        end
    end
    local bodies,body_nodes={},{}
    for _,node in ipairs(nodes) do
        if node.name=="text_contents" or node.name=="messageBody" or node.name=="bodyText" then
            bodies[#bodies+1]=node.text;body_nodes[#body_nodes+1]=node
        end
    end
    if #bodies>0 and context.kind~="dialog" then
        return bodies,{identity="body:" .. tostring(a11y.native_owner_token()) .. ":" .. context.generation,content=true,nodes=body_nodes}
    end
    if context.kind~="dialog" then
        local entity,entity_review=a11y.entity_review_entries(nodes)
        if entity then return entity,entity_review end
        local record=a11y.structured_record_packet()
        if record then return record.entries,{identity=record.identity,nodes={},record=record.signature,content=true} end
        local players,review=a11y.player_list_review_entries(nodes)
        if players then return players,review end
    end
    local result, seen = {}, {}
    local review={content=true,identity="content:" .. tostring(a11y.native_owner_token()) .. ":" .. context.generation,nodes={}}
    local function add(text,node,force)
        if text and text ~= "" and not seen[text] and (force or not a11y.review_chrome(text,node)) then
            result[#result + 1], seen[text] = text, true
            review.nodes[#result]=node
        end
    end
    -- A dialog's body owns review. Background players and command captions do
    -- not become additional entries; answering remains native game navigation.
    if context.kind=="dialog" and context.question then
        add(context.question,nil,true)
        return result,review
    end
    add(context.title)
    add(context.question,nil,true)
    local selection=context.selection
    if selection and (not selection.origin or a11y.speech_origin_allowed(selection.origin)) then
        local committed=context.selection_result
        local current=committed and a11y.selection_result({row=committed.row,widget=committed.widget,
            identity=selection.identity,source=committed.source})
        local selected=selection.origin and a11y.ui_model and a11y.ui_model.nodes[memory.hex(selection.origin.address)]
        add(current and current.text or selection.text,selected)
    end
    for _, item in ipairs(a11y.dashboard_texts or {}) do
        local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(item.address)]
        if #result < 80 and a11y.native_widget_allowed(item.address)
                and (not item.owner or item.owner==a11y.native_owner_token())
                and (not item.identity or (node and node.identity==item.identity and node.text==item.text)) then add(item.text,node) end
    end
    if context.kind ~= "dialog" then
        table.sort(nodes,function(a,b)
            local function heading(node)
                local name=(node.name or ""):lower()
                return (name:find("title",1,true) or name:find("headline",1,true) or name:find("subject",1,true)) and 0 or 1
            end
            local ar,br=heading(a),heading(b)
            if ar~=br then return ar<br end
            return (a.sequence or 0)<(b.sequence or 0)
        end)
        for _,node in ipairs(nodes) do
            if #result>=80 then break end
            local role=a11y.text_asset_role(node.text)
            if node.name~="padIcon" and not a11y.is_media_caption(node) and role~="technical" and role~="status"
                    and not is_noninteractive_text(node.text) then add(node.text,node) end
        end
    end
    return result,review
end

function a11y.is_menu_description(node)
    return node and node.name=="description_offline"
end

-- Read-only equivalent of Window::get_select_index (e3d140). A mapped
-- scrolling list uses its typed kind-16 selector; flat menus use Impl+d8.
function a11y.native_window_selected_index(window,base)
    local impl=window.impl or a11y.menu_read(window.address+0x88,"u64")
    if not impl or impl<0x10000 then return nil end
    local group_index=a11y.menu_read(impl+0xa0,"u32")
    local first,last=a11y.menu_read(impl+0xa8,"u64"),a11y.menu_read(impl+0xb0,"u64")
    if not group_index or not first or not last or last<first or (first~=last and first<0x10000) or (last-first)%0x18~=0
            or last-first>0x18*64 then return nil end
    for at=first,last-0x18,0x18 do
        if a11y.menu_read(at,"u32")==group_index then
            local group=a11y.menu_child(window.root,group_index)
            local selectors=group and a11y.holder_kind_nodes(group+0x98,0x10)
            if not selectors or #selectors~=1 then return nil end
            return a11y.menu_read(selectors[1]+0xbc,"u32")
        end
    end
    return a11y.menu_read(impl+0xd8,"u32")
end

function a11y.native_music_state(node)
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    local member=snapshot and snapshot.members[tonumber(node.address)]
    local found
    for _,owner in ipairs(member and member.owners or {}) do
        local vt=owner.enabled and base and a11y.menu_read(owner.address,"u64")
        if vt and a11y.menu_read(vt+0x270,"u64")==base+0xcb8310
                and a11y.menu_read(vt+0x280,"u64")==base+0xcb8520 then
            for _,window in ipairs(snapshot.windows or {}) do
                if window.enabled and window.address==owner.address then
                    local index=a11y.native_window_selected_index(window,base)
                    local first,last=a11y.menu_read(window.address+0xf0,"u64"),a11y.menu_read(window.address+0xf8,"u64")
                    local category=a11y.menu_read(window.address+0xbc,"u32")
                    local cfirst,clast=a11y.menu_read(window.address+0xc0,"u64"),a11y.menu_read(window.address+0xc8,"u64")
                    if index and first and last and first>=0x10000 and last>=first and (last-first)%0x50==0
                            and last-first<=0x50*4096 and index<(last-first)/0x50
                            and category and cfirst and clast and cfirst>=0x10000 and clast>=cfirst and (clast-cfirst)%32==0
                            and clast-cfirst<=32*64 and category<(clast-cfirst)/32
                            and a11y.menu_read(first+index*0x50+0x41,"u8")==0 then
                        local pointer=a11y.menu_read(first+index*0x50+8,"u64")
                        local state=pointer and pointer>=0x10000 and a11y.menu_read(pointer+category,"u8")
                        -- b25c94 reads the category byte; b25cb6..cff renders
                        -- only 1 checked, 0/2 unchecked. Other values unknown.
                        if state==0 or state==1 or state==2 then
                            local current={window=window.address,index=index,category=category,state=state,
                                identity=table.concat({window.address,index,category,state},":")}
                            if found and found.identity~=current.identity then return nil end
                            found=current
                        end
                    end
                end
            end
        end
    end
    return found
end

function a11y.native_music_packet(node)
    if not node or node.name~="music" or not node.text or node.text=="" then return nil end
    local snapshot=a11y.native_windows
    if not snapshot or not snapshot.selected_members or not snapshot.selected_members[tonumber(node.address)] then return nil end
    local artist
    for _,other in pairs(a11y.ui_model and a11y.ui_model.names.artist or {}) do
        if other.text and other.text~="" and a11y.native_presentation_ready(other.address)
                and a11y.component_peers(node.address,other.address)==true then
            if artist and artist~=other then return nil end
            artist=other
        end
    end
    local state=a11y.native_music_state(node)
    local text=node.text .. (artist and ", " .. artist.text or "")
    if state then
        text=text .. ", " .. (state.state==1 and (a11y.ui_language=="pt" and "ativada" or "enabled")
            or (a11y.ui_language=="pt" and "desativada" or "disabled"))
    end
    return {text=text,artist=artist,state=state,signature=text .. ":" .. (state and state.identity or "unknown")}
end

function a11y.is_media_caption(node)
    if not node or (node.name~="music" and node.name~="artist") then return false end
    -- A passive music banner can inherit cursor membership from a whole panel.
    -- Only the typed soundtrack selector proves explicit track navigation.
    return not a11y.native_music_state(node)
end

function a11y.is_match_ready_notice(text)
    return text and (text:find("A partida começará quando os dois times",1,true)
        or text:lower():find("match will begin when both teams",1,true))~=nil
end

function a11y.native_pause_context()
    if a11y.native_information_context() then return nil end
    local base=tonumber(process_base_u64)
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        local vt=base and window.enabled and window.root and window.root>=0x10000
            and a11y.menu_read(window.address,"u64")
        local flags=vt and a11y.menu_read(window.root+0xc,"u32")
        if flags and flags%8==7 and math.floor(flags/256)%2==1
                and a11y.menu_read(vt+0x18,"u64")==base+0x4d7540
                and a11y.menu_read(vt+0x100,"u64")==base+0x4d7610 then
            return {window=window.address,root=window.root,identity=tostring(window.address) .. ":" .. tostring(window.root)}
        end
    end
end

function a11y.poll_native_pause()
    local pause=a11y.native_pause_context()
    if not pause then a11y.pause_announced=nil;return end
    a11y.pre_match_active,a11y.pre_match_entry_pending,a11y.pre_match_notice_text=false,false,nil
    if a11y.is_match_ready_notice(pending_message_text) then
        pending_message_text,pending_message_key,pending_message_due_ms=nil,nil,nil
        modal_focus_hold_until_ms=0
    end
    local context=a11y.read_context_state()
    if a11y.is_match_ready_notice(context.question) then a11y.reset_read_context("pause-presentation");modal_focus_hold_until_ms=0 end
    if a11y.read_context_state().kind=="dialog" or a11y.pause_announced==pause.identity then return end
    local title=a11y.ui_language=="pt" and "Menu de pausa" or "Pause menu"
    local before=a11y.native_speech_last
    a11y.set_read_title(title)
    speak(title,true,nil,"pause-header:" .. pause.identity)
    if a11y.native_speech_last>before then
        a11y.pause_announced=pause.identity
        a11y.title_pending_first_item=title
        a11y.title_pending_first_item_until_ms=tonumber(ffi.C.GetTickCount64())+2000
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].pause_header=pause.identity end
    end
end

function a11y.native_information_context()
    local base=tonumber(process_base_u64)
    local found
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        local vt=base and window.enabled and window.root and window.root>=0x10000 and a11y.menu_read(window.address,"u64")
        -- ParameterDetail's lifecycle and presentation updater, independent
        -- of translated headings and of whether its page has a text cursor.
        local flags=vt and a11y.menu_read(window.root+0xc,"u32")
        if flags and flags%8==7 and math.floor(flags/256)%2==1
                and a11y.menu_read(vt+0x18,"u64")==base+0x90ca30
                and a11y.menu_read(vt+0x100,"u64")==base+0x9113c0 then
            if found and found.window~=window.address then return nil end
            found={window=window.address,root=window.root,side=a11y.menu_read(window.address+0x98,"u32"),
                identity=tostring(window.address) .. ":" .. tostring(window.root)}
        end
    end
    return found
end

function a11y.poll_information_context()
    local context=a11y.native_information_context()
    if not context then a11y.information_announced=nil;return end
    a11y.clear_pending_tooltips()
    if context.identity==a11y.information_announced or a11y.read_context_state().kind=="dialog" then return end
    local title=a11y.ui_language=="pt" and "Informações do jogador" or "Player information"
    local before=a11y.native_speech_last
    speak(title,true,nil,"information-header:" .. context.identity)
    if a11y.native_speech_last>before then
        a11y.information_announced=context.identity
        a11y.title_pending_first_item=title
        a11y.title_pending_first_item_until_ms=tonumber(ffi.C.GetTickCount64())+2000
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].information_header=context.identity end
    end
end

function a11y.field_visualization_text(label,value,name)
    if name=="height_item" and label:find("(cm)",1,true) and tonumber(value) then
        local number=tonumber(value)/100
        local text=string.format("%.2f",number)
        if a11y.ui_language=="pt" then text=text:gsub("%.",",") end
        return label:gsub("%s*%(cm%)","") .. ": " .. text
            .. (a11y.ui_language=="pt" and " metros" or " metres")
    elseif name=="weight_item" and label:find("(kg)",1,true) and tonumber(value) then
        return label:gsub("%s*%(kg%)","") .. ": " .. value
            .. (a11y.ui_language=="pt" and " quilos" or " kilograms")
    end
    return label .. ": " .. value
end

-- A read-only presentation may share one label column across data columns.
-- Pair resource stems inside the SAME native owner/root; never pair nearby
-- writes or captions. Multiple populated columns remain ambiguous.
function a11y.visualization_player_record()
    local target=a11y.visualization_player
    local base=tonumber(process_base_u64)
    local info=a11y.native_information_context()
    if info then
        target=nil
        local data=info and base and a11y.menu_read(base+0x36f38a0,"u64")
        if data and (info.side==0 or info.side==1) and a11y.menu_read(data,"u64")==base+0x2618830 then
            -- 911650 uses variant zero for the primary displayed column;
            -- variant one is comparison. Resolve the same native descriptor.
            local offset=0xba4+info.side*0xa8
            local slot,side=a11y.menu_read(data+offset,"u32"),a11y.menu_read(data+offset+4,"u32")
            if slot and slot<40 and (side==0 or side==1) then
                target={descriptor_offset=offset,slot=slot,side=side}
            end
        end
    end
    local data=target and base and a11y.menu_read(base+0x36f38a0,"u64")
    if not data or not target.descriptor_offset or a11y.menu_read(data,"u64")~=base+0x2618830 then return nil end
    local descriptor=data+target.descriptor_offset
    if a11y.menu_read(descriptor,"u32")~=target.slot or a11y.menu_read(descriptor+4,"u32")~=target.side then return nil end
    local index=a11y.menu_read(data+target.side*0x248+0x1f8+target.slot,"u8")
    if not index or index>=40 then return nil end
    local object=a11y.menu_read(data+target.side*0x340+0x568+index*16,"u64")
    local id=object and a11y.menu_read(object+0x30,"u32")
    if not id or id==0 or (target.player_id and id~=target.player_id) then return nil end
    local name=a11y.read_native_c_string(object+0x38,64)
    if not name or #name<2 or name:find("%c") or (target.name and target.name:sub(1,#name)~=name) then return nil end
    return {object=object,player_id=id,name=target.name or name}
end

function a11y.visualization_packet()
    local snapshot=a11y.native_windows
    if not snapshot or a11y.keyboard_window or a11y.read_context_state().kind=="dialog" then return nil end
    local nodes=a11y.presented_nodes()
    local information=a11y.native_information_context()
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local detail=window.cursor_detail
        if window.enabled and (not information or information.window==window.address)
                and (information or not detail or detail.status=="no-cursor" or detail.status=="unknown-delegate") then
            for _,root in ipairs(information and {window.root} or window.owned_roots or {window.root}) do
                local members={}
                for _,node in ipairs(nodes) do
                    local member=snapshot.members[tonumber(node.address)]
                    for _,owner in ipairs(member and member.owners or {}) do
                        if owner.enabled and owner.address==window.address and owner.root==root
                                and a11y.read_native_rendered_text(node.address)==node.text then
                            members[#members+1]={node=node,parents=owner.parents or {}};break
                        end
                    end
                end
                local rows={}
                for _,item in ipairs(members) do
                    local label=item.node
                    local stem,suffix
                    if label.name then stem,suffix=label.name:match("^(.-)_item(.*)$") end
                    if stem then
                        local value,ambiguous
                        for _,peer in ipairs(members) do
                            local node=peer.node
                            if node.name==stem .. "_value" .. suffix and not a11y.empty_selection_caption(node.text) then
                                if value then ambiguous=true end
                                value=peer
                            end
                        end
                        if value and not ambiguous then
                            rows[#rows+1]={key=label.name,text=a11y.field_visualization_text(label.text,value.node.text,label.name),
                                label=label,value=value.node,parents=value.parents}
                        end
                    end
                end
                if #rows>=2 then
                    if found and (found.window~=window.address or found.root~=root) then return nil end
                    local priority={height_item=1,weight_item=2}
                    table.sort(rows,function(a,b)
                        local left,right=priority[a.key] or 3,priority[b.key] or 3
                        if left~=right then return left<right end
                        return (a.label.sequence or 0)<(b.label.sequence or 0)
                    end)
                    found={window=window.address,root=root,fields=rows,
                        identity=(a11y.native_owner_token() or "") .. ":fields:" .. window.address .. ":" .. root,
                        generation=a11y.read_context_state().generation}

                end
            end
        end
    end
    if not found and information then
        found={window=information.window,root=information.root,fields={},identity="information:" .. information.identity,
            generation=a11y.read_context_state().generation}
    end
    if found and (information or (found.fields[1] and found.fields[1].key=="height_item"
            and found.fields[2] and found.fields[2].key=="weight_item")) then
        a11y.append_visualization_attributes(found)
    end
    return found
end

function a11y.append_visualization_attributes(packet)
    local record=a11y.visualization_player_record()
    if not record then return end
    packet.identity=packet.identity .. ":player=" .. record.player_id .. ":" .. record.object
    local seen={}
    for _,field in ipairs(packet.fields) do if field.label then seen[field.label.text]=true end end
    local style=a11y.player_style_text(record)
    if style then packet.fields[#packet.fields+1]={key="style",
        text=(a11y.ui_language=="pt" and "Estilo de jogo: " or "Playing style: ") .. style} end
    if not readable(record.object,0x30) then return end
    local bytes=memory.read(record.object,0x30)
    if not bytes or #bytes~=0x30 then return end
    local attributes,plausible={},0
    for index,spec in ipairs(a11y.player_attribute_specs) do
        local value=a11y.player_record_bits(bytes,spec[3],spec[4],7)
        if value>=40 and value<=99 then plausible=plausible+1 end
        local label=a11y.ui_language=="pt" and spec[1] or spec[2]
        if not seen[label] then attributes[#attributes+1]={key="attribute:" .. index,text=label .. ": " .. value} end
    end
    if plausible>=20 then for _,field in ipairs(attributes) do packet.fields[#packet.fields+1]=field end end
end

function a11y.visualization_allowed(origin)
    local packet=a11y.visualization_packet()
    if not packet or packet.identity~=origin.identity or packet.generation~=origin.generation then return false end
    for _,field in ipairs(packet.fields) do if field.key==origin.key then return field.text==origin.text end end
    return false
end

function a11y.read_visualization(action)
    a11y.poll_native_texts(true)
    local packet=a11y.visualization_packet()
    if not packet then a11y.visualization_review=nil;return false end
    local state=a11y.visualization_review
    if not state or state.identity~=packet.identity or state.generation~=packet.generation then
        state={identity=packet.identity,generation=packet.generation,index=0,sequence=0};a11y.visualization_review=state
    end
    local count=#packet.fields
    if count==0 then
        speak(a11y.ui_language=="pt" and "Atributos ainda indisponíveis." or "Attributes unavailable.",true,true,
            "visualization:" .. packet.identity .. ":unavailable")
        return true
    end
    if action=="first" then state.index=1
    elseif action=="next" then state.index=state.index%count+1
    elseif action=="previous" then state.index=state.index==0 and count or (state.index-2)%count+1
    elseif state.index==0 or state.index>count then state.index=1 end
    state.sequence=state.sequence+1
    local field=packet.fields[state.index]
    local before=a11y.native_speech_last
    modal_focus_hold_until_ms=0;a11y.title_pending_first_item=nil;a11y.deferred_modal_announcement=nil
    speak(field.text,true,true,"visualization:" .. packet.identity .. ":" .. state.sequence,field.label and field.label.address)
    local origin={identity=packet.identity,generation=packet.generation,key=field.key,text=field.text}
    for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].visualization=origin end
    return true
end

function a11y.read_buffer(action)
    if not game_is_foreground() or overlay_visible or sider_overlay_visible or a11y.keyboard_window then return false end
    if a11y.read_context_state().kind~="dialog" then
        if a11y.read_visualization(action) then return true end
        if a11y.read_player_details(action) then return true end
    end
    local entries,review = a11y.buffer_entries()
    local context = a11y.read_context_state()
    if review and context.review_identity~=review.identity then context.cursor=0 end
    context.review_identity=review and review.identity
    if #entries > 0 then
        if context.cursor > #entries then context.cursor = 1 end
        if context.cursor==0 and action=="repeat" then context.cursor=1 end
        if action == "next" then context.cursor = context.cursor % #entries + 1 end
        if action == "previous" then context.cursor = (context.cursor - 2) % #entries + 1 end
        if action == "first" then context.cursor = 1 end
    end
    local text = entries[context.cursor] or (a11y.ui_language == "pt"
        and "Sem conteúdo confirmado neste contexto." or "No confirmed content in this context.")
    modal_focus_hold_until_ms = 0
    a11y.title_pending_first_item = nil
    a11y.deferred_modal_announcement = nil
    local node=review and review.nodes[context.cursor]
    local before=a11y.native_speech_last
    context.review_sequence=(context.review_sequence or 0)+1
    speak(text, true, true,"review:" .. tostring(context.generation) .. ":" .. tostring(context.review_sequence),node and node.address)
    if review and review.message then
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].selected_message={signature=review.message,owner=a11y.native_owner_token()}
        end
    end
    if review and review.country then
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].native_list=review.country end
    end
    if review and review.record then
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].structured_record={signature=review.record,owner=a11y.native_owner_token()}
        end
    end
    if node and review.content then
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].content_review={key=node.key,identity=node.identity,text=node.text,owner=a11y.native_owner_token()}
        end
    end
    if node and review.anchor then
        local origin={origin=a11y.capture_speech_origin(node.address),anchor=a11y.capture_speech_origin(review.anchor.address),
            generation=context.generation,identity=a11y.engine_selection_identity(node.key,node),
            list_identity=review.list_identity,selection=review.selection,parts={}}
        for _,part in ipairs(a11y.player_row_details(node)) do origin.parts[#origin.parts+1]=a11y.capture_speech_origin(part.address) end
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].roster_review=origin end
    end
    return true
end

function a11y.transition_focus_blocked(key, entry, offset, edge, now_ms)
    if not a11y.transition_old_focus_texts then return false end
    local old = a11y.transition_old_focus_nodes and a11y.transition_old_focus_nodes[key]
    local node = a11y.ui_model and a11y.ui_model.nodes[key]
    local fresh = offset == 0x104 and edge > (a11y.transition_started_frame or frame)
    if now_ms >= a11y.transition_guard_until_ms or fresh or (entry and
            (not old or old.text ~= entry.text or (node and node.identity ~= old.identity))) then
        a11y.transition_old_focus_texts, a11y.transition_old_focus_nodes = nil, nil
        return false
    end
    return true
end

function a11y.capture_pending_modal_button(key, entry, offset, edge)
    local context = a11y.read_context_state()
    local previous = context.baseline and context.baseline[key]
    local fresh = edge and edge >= context.started_frame
    local eligible = context.question and entry and offset == 0x104
        and key ~= context.message_key and is_modal_button(entry.text)
        and entry.text ~= "Sim" and entry.text ~= "Não"
        and entry.last_seen >= context.started_frame
        and (not previous or previous.text ~= entry.text or fresh)
    a11y.pending_modal_button_text = eligible and entry.text or nil
    return eligible and true or false
end

function a11y.buffer_key(vkey)
    if a11y.keyboard_window then return false end
    local actions = {[0x49]="previous", [0x4b]="next", [0x4a]="first", [0x4c]="repeat"}
    if actions[vkey] then
        local now = tonumber(ffi.C.GetTickCount64())
        if a11y.buffer_last_key == vkey and now - (a11y.buffer_last_ms or 0) < 120 then return true end
        if a11y.read_buffer(actions[vkey]) then
            a11y.buffer_last_key, a11y.buffer_last_ms = vkey, now
            return true
        end
    end
    return false
end

function a11y.review_right_stick(direction)
    if direction==0 then a11y.player_review_stick_direction=nil;return false end
    if a11y.player_review_stick_direction==direction then return true end
    if a11y.keyboard_window or (not a11y.focused_player_node() and not a11y.visualization_packet()
            and #a11y.buffer_entries()==0) then
        a11y.player_review_stick_direction=nil;return false
    end
    a11y.player_review_stick_direction=direction
    return a11y.read_buffer(direction<0 and "previous" or "next")
end

function a11y.reset_ui_model()
    a11y.reset_read_context("transition")
    local generation = a11y.ui_model and a11y.ui_model.generation or 0
    a11y.ui_model = {
        generation = generation + 1, nodes = {}, names = {}, texts = {}, count = 0,
        sequence = 0, focus_reason = nil,
    }
end

function a11y.forget_ui_widget(key)
    local model = a11y.ui_model
    local node = model and model.nodes[key]
    if node then
        local bucket=model.texts and model.texts[node.text]
        if bucket and bucket.nodes[key] then
            bucket.nodes[key]=nil;bucket.count=bucket.count-1
            if bucket.count==0 then model.texts[node.text]=nil end
        end
        local context = a11y.read_context
        if context then
            if context.answer_owners then context.answer_owners[key] = nil end
            local selected = context.selection
            local identity = selected and tostring(selected.identity or "") or ""
            if selected and (selected.widget_key == key or identity == node.identity
                    or identity:sub(1, #node.identity + 1) == node.identity .. ":") then
                context.selection, context.help = nil, nil
            end
        end
        if a11y.answer_chain then a11y.answer_chain.owners[key] = nil end
        if node.name and model.names[node.name] then
            model.names[node.name][key] = nil
            local remaining = false
            for _ in pairs(model.names[node.name]) do remaining = true; break end
            if not remaining then model.names[node.name] = nil end
        end
        model.nodes[key] = nil
        model.count = model.count - 1
    end
    if ui_focus_widgets[key] then
        ui_focus_widgets[key] = nil
        ui_focus_widget_count = ui_focus_widget_count - 1
    end
    ui_focus_state[key], ui_focus_activated[key] = nil, nil
    local row = control_rows_by_label_widget[key]
    if row then
        if controller_rows[row.label] == row then controller_rows[row.label] = nil end
        if row.value_widget_key and control_row_by_value_widget[row.value_widget_key] == row then
            control_row_by_value_widget[row.value_widget_key] = nil
        end
        if active_control_row == row then active_control_row = nil end
        if pending_control_row == row then pending_control_row = nil end
        control_rows_by_label_widget[key] = nil
    end
    local owner = control_row_by_value_widget[key]
    if owner then
        owner.value_widget, owner.value_widget_key, owner.value = nil, nil, nil
        control_row_by_value_widget[key] = nil
    end
end

function a11y.observe_ui_widget(widget, text)
    if not a11y.ui_model then a11y.reset_ui_model() end
    local model = a11y.ui_model
    local key = memory.hex(widget)
    local name = a11y.widget_internal_name(widget)
    local node = model.nodes[key]
    if node and node.name ~= name then
        a11y.forget_ui_widget(key)
        node = nil
    end
    if not node then
        if model.count >= 1024 then
            local oldest,old_rank
            local snapshot=a11y.native_windows
            for _, candidate in pairs(model.nodes) do
                local address=tonumber(candidate.address)
                local member=snapshot and snapshot.members and snapshot.members[address]
                local rank=snapshot and snapshot.selected_members and snapshot.selected_members[address] and 2
                    or member and member.active and 1 or 0
                if not oldest or rank<old_rank or (rank==old_rank and (candidate.last_seen < oldest.last_seen
                        or (candidate.last_seen == oldest.last_seen and candidate.sequence < oldest.sequence))) then
                    oldest,old_rank=candidate,rank
                end
            end
            if oldest then a11y.forget_ui_widget(oldest.key) end
        end
        model.sequence = model.sequence + 1
        node = {key=key, address=widget, name=name, generation=model.generation,
            sequence=model.sequence, identity=tostring(model.generation) .. ":" ..
                tostring(model.sequence)}
        model.nodes[key] = node
        model.count = model.count + 1
        if name then
            model.names[name] = model.names[name] or {}
            model.names[name][key] = node
        end
    end
    if a11y.component_capture and a11y.component_capture.active and node.text~=text then
        a11y.component_capture_dirty_frame=frame
    end
    if node.text~=text then
        a11y.tooltip_dirty=true
        model.texts=model.texts or {}
        local old=model.texts[node.text]
        if old and old.nodes[key] then
            old.nodes[key]=nil;old.count=old.count-1
            if old.count==0 then model.texts[node.text]=nil end
        end
        local bucket=model.texts[text] or {nodes={},count=0}
        model.texts[text]=bucket
        if not bucket.nodes[key] then bucket.count=bucket.count+1;bucket.nodes[key]=node end
    end
    node.text, node.last_seen = text, frame
    node.owner_link = a11y.ui_owner_link(widget)
    -- These are observations, not a synthetic accessibility tree.
    node.role = name and name:match("_item$") and "control-label"
        or name and name:match("_value$") and "control-value" or "unknown"
    local stem = name and (name:match("^(.-)_item$") or name:match("^(.-)_value$"))
    if stem and not a11y.unique_ui_name(name) then
        a11y.invalidate_structural_pair(stem)
    end
    return node
end

function a11y.unique_ui_name(name)
    local model = a11y.ui_model
    local bucket = model and model.names[name]
    local found
    for _, node in pairs(bucket or {}) do
        if found then return nil, "ambiguous-name" end
        found = node
    end
    return found, found and "unique-name" or "missing-name"
end

function a11y.control_for_widget(key)
    -- Localization may register every short caption as a provisional label.
    -- A value's proven native relation outranks that provisional registration.
    local value = key and control_row_by_value_widget[key]
    if value and value.native_field then return value end
    return key and (control_rows_by_label_widget[key] or value) or nil
end

function a11y.resolve_primary_focus(candidates)
    local groups, ordered = {}, {}
    for _, candidate in ipairs(candidates) do
        local row = a11y.control_for_widget(candidate.key)
        local entry = ui_focus_widgets[candidate.key]
            or (a11y.ui_model and a11y.ui_model.nodes[candidate.key])
        -- Collapse only an existing label/value relation. Equal captions and
        -- different controls remain independent selection candidates.
        local related = row and (row.is_control or (row.value and row.value ~= ""
            and not non_control_labels[row.label] and not is_modal_button(row.value))) and entry and
            ((candidate.key == row.label_widget_key and entry.text == row.label)
                or (candidate.key == row.value_widget_key and entry.text == row.value))
        local owner = related and row or candidate.key
        local group = groups[owner]
        if not group then
            group = {key=candidate.key,edge=candidate.edge or -1,row=related and row or nil}
            groups[owner], ordered[#ordered+1] = group, group
        else
            group.edge = math.max(group.edge, candidate.edge or -1)
            if row and candidate.key == row.label_widget_key then group.key = candidate.key end
        end
    end
    local best, edge, tied = nil, -1, false
    for _, candidate in ipairs(ordered) do
        if not best or candidate.edge > edge then
            best, edge, tied = candidate, candidate.edge, false
        elseif candidate.edge == edge then
            tied = true
        end
    end
    local reason = not best and "no-selection"
        or tied and "ambiguous-selection"
        or #ordered == 1 and (#candidates > 1 and "control-label-value" or "unique-selection")
        or "selection-edge"
    if a11y.ui_model then a11y.ui_model.focus_reason = reason end
    if tied then return nil, reason end
    return best, reason
end

-- Native window authority is independent of captions and the sticky cursorOver
-- field. These reads mirror WindowManager and Window getters in this EXE.
-- Unknown membership stays with the existing reader; only proven background
-- membership is rejected. No new native hooks or calls into game functions.
function a11y.menu_read(address,kind)
    -- Hooks pass uint64_t cdata; normalize before arithmetic and table keys.
    -- LuaJIT math.floor does not accept cdata, even for a valid address.
    address=tonumber(address)
    local cache=a11y.snapshot_read_work or a11y.render_read_work
    local values=cache and cache[kind]
    local cached=values and values[address]
    if cached~=nil then return cached~=false and cached or nil end
    if cache and not values then values={};cache[kind]=values end
    local size=kind=="u64" and 8 or kind=="u8" and 1 or kind=="u16" and 2 or 4
    if not address or address<0x10000 or address>0x7fffffffffff or address%1~=0
            or not readable(address,size) then
        if values and address then values[address]=false end
        return nil
    end
    local bytes
    if cache and a11y.safe_memory_read==a11y.production_memory_read then
        local block=math.floor(address/128)*128
        if address+size<=block+128 and readable(block,128) then
            cache.blocks=cache.blocks or {}
            local data=cache.blocks[block]
            if data==nil then data=a11y.safe_memory_read(block,128) or false;cache.blocks[block]=data end
            if data then bytes=data:sub(address-block+1,address-block+size) end
        end
    end
    if not bytes then bytes=a11y.safe_memory_read(address,size) end
    local value=bytes and #bytes==size and tonumber(memory.unpack(kind,bytes)) or nil
    if values then values[address]=value or false end
    return value
end

-- Immutable native schemas: shared by every traversal, never inferred from text.
a11y.native_layout = {
    holder_trees = {{8,0x30},{0x88,0x40},{0x78,0x40}},
    containers = {[0x27bae88]=true,[0x27cb508]=true,[0x27b6490]=true,
        [0x27b8d60]=true,[0x27cb298]=true},
    holders = {[0x27bae88]=true,[0x27cb508]=true,[0x27b6490]=true,
        [0x27b8d60]=true,[0x27cb298]=true,[0x27cbc08]=true,[0x27cbe98]=true},
}

-- NodeRectHolder dispatch walks three MSVC trees, not the indexed vector.
-- e4db00 visits +8; the full e4dbd0 also visits +0x88 AND +0x78.
-- Only callers with RTTI-proven holder layout may supply this address.
function a11y.menu_holder_children(holder)
    local children, seen_children = {}, {}
    for _, spec in ipairs(a11y.native_layout.holder_trees) do
        local head = a11y.menu_read(holder+spec[1], "u64")
        if head and head >= 0x10000 and a11y.menu_read(head+0x19,"u8") == 1 then
            local root = a11y.menu_read(head+8,"u64")
            local stack, visited, count = {root}, {}, 0
            while #stack > 0 and count < 256 do
                local at = table.remove(stack)
                if at and at >= 0x10000 and at ~= head and not visited[at] then
                    visited[at], count = true, count+1
                    if a11y.menu_read(at+0x19,"u8") == 0 then
                        local child = a11y.menu_read(at+spec[2],"u64")
                        if child and child >= 0x10000 and not seen_children[child] then
                            seen_children[child] = true
                            children[#children+1] = child
                        end
                        local left = a11y.menu_read(at,"u64")
                        local right = a11y.menu_read(at+0x10,"u64")
                        if left and left >= 0x10000 then stack[#stack+1] = left end
                        if right and right >= 0x10000 then stack[#stack+1] = right end
                    end
                end
            end
        end
    end
    return children
end

function a11y.has_owned_node_delegate(vtable,base)
    if not vtable then return false end
    local getter=a11y.menu_read(vtable+0x88,"u64")
    return (getter==base+0xe8ecd0 or getter==base+0xe546a0)
        and a11y.menu_read(vtable+0x28,"u64")==base+0xe8ecb0
end

function a11y.scan_menu_tree(root, base)
    local members, visited, queue, cursor, parents = {}, {}, {root}, 1, {}
    local queued,limit = {[root]=true},2048
    local truncated=false
    local function enqueue(child,parent)
        if not child or child<0x10000 or queued[child] then return end
        if #queue>=limit then truncated=true;return end
        queued[child],parents[child]=true,parent
        queue[#queue+1]=child
    end
    local frontier = {}
    -- RTTI-proven NodeBasicNodeBase and inline NodeRectHolder layouts.
    -- NodeRectText and arbitrary NodeRect subclasses do not share these.
    local containers, holders = a11y.native_layout.containers, a11y.native_layout.holders
    while cursor <= #queue do
        local node = queue[cursor]
        cursor = cursor + 1
        if not visited[node] then
            visited[node] = true
            local vtable = a11y.menu_read(node, "u64")
            if vtable then
                local rva = vtable - base
                if rva == 0x27b5260 or rva == 0x27c3a38 then members[node] = true end
                -- NodeWindow forwards native state/event calls to +0x190.
                -- NodeCursor resolves its choices from the parent at +0x88.
                -- Follow these typed links too; its flat child vector can be empty.
                local linked = rva == 0x27b6490 and a11y.menu_read(node+0x190,"u64")
                    or rva == 0x27c1ac0 and a11y.menu_read(node+0x88,"u64")
                -- PartsNormalBase forwards events/state to the NODE pointed
                -- to by +98 (e8ecd0/e8ecb0). This is not an inline holder.
                -- Verify both virtual methods before following that layout:
                -- selectors, LR switches, help boxes and player cards share it.
                if not linked then
                    -- e546a0 is an unconditional jump to e8ecd0. Headline
                    -- and slider nodes use this same +98 delegate contract.
                    if a11y.has_owned_node_delegate(vtable,base) then
                        linked=a11y.menu_read(node+0x98,"u64")
                    end
                end
                enqueue(linked,node)
                if not linked and not holders[rva] and not containers[rva]
                        and rva~=0x27b5260 and rva~=0x27c3a38 and #frontier<6 then
                    frontier[#frontier+1]={address=node,rva=rva}
                end
                if holders[rva] then
                    for _, child in ipairs(a11y.menu_holder_children(node+0x98)) do
                        enqueue(child,node)
                    end
                end
                if containers[rva] then
                    local first = a11y.menu_read(node + 0x170, "u64")
                    local last = a11y.menu_read(node + 0x178, "u64")
                    if first and last and first >= 0x10000 and last >= first
                            and (last - first) % 8 == 0 and last - first <= 2048 then
                        for at = first, last - 8, 8 do
                            local child = a11y.menu_read(at, "u64")
                            enqueue(child,node)
                        end
                    end
                end
            end
        end
    end
    return members, parents, {visited=cursor-1,queued=#queue,at_capacity=truncated,frontier=frontier}
end

-- Reuse identical traversals only within one synchronous window snapshot.
-- No object or field cache survives to another callback/frame.
function a11y.menu_tree(root,base)
    local cache=a11y.snapshot_tree_work
    local entry=cache and cache[root]
    if entry and entry.base==base then
        local parents={}
        for at,parent in pairs(entry.parents) do parents[at]=parent end
        return entry.members,parents,entry.evidence
    end
    local members,parents,evidence=a11y.scan_menu_tree(root,base)
    if not cache then return members,parents,evidence end
    if cache then
        -- Cursor readers add parent links; give each caller its own map.
        cache[root]={base=base,members=members,parents=parents,evidence=evidence}
    end
    local copy={}
    for at,parent in pairs(parents) do copy[at]=parent end
    return members,copy,evidence
end

function a11y.menu_child(container, index)
    if not container or not index or index < 0 or index >= 256 then return nil end
    local first = a11y.menu_read(container + 0x170, "u64")
    local last = a11y.menu_read(container + 0x178, "u64")
    if not first or not last or first < 0x10000 or last < first
            or (last-first)%8 ~= 0 or last-first > 2048 or index >= (last-first)/8 then return nil end
    return a11y.menu_read(first + index * 8, "u64")
end

function a11y.menu_cursor_texts(root, base)
    local cursor = a11y.menu_read(root + 0x190, "u64")
    local detail = {root=root,cursor=cursor,
        cursor_type=cursor and a11y.menu_read(cursor,"u64"),status="unknown-delegate"}
    if not cursor or detail.cursor_type ~= base + 0x27c1ac0 then return nil,detail end
    local parent = a11y.menu_read(cursor + 0x88, "u64")
    detail.parent,detail.group_index,detail.item_index = parent,
        a11y.menu_read(cursor+0x90,"u32"),a11y.menu_read(cursor+0x94,"u32")
    local group = a11y.menu_child(parent, detail.group_index)
    local selected = group and a11y.menu_child(group, detail.item_index)
    detail.group,detail.selected = group,selected
    detail.selected_type = selected and a11y.menu_read(selected,"u64")
    if not selected or selected < 0x10000 then
        detail.status = group and "missing-item" or "missing-group"
        return nil,detail
    end
    local members,parents = a11y.menu_tree(selected, base)
    parents[selected],parents[group]=group,parent
    detail.parents=parents
    detail.status = "no-text"
    for _ in pairs(members) do detail.status="resolved"; return members,detail end
    -- Some cursor groups select icons and render their current caption as a
    -- direct text child of the group (8f0366..8f03f2), outside the icon subtree.
    -- Only one live, non-decorative sibling can supply that shared caption.
    local group_members,group_parents=a11y.menu_tree(group,base)
    local caption
    for address in pairs(group_members) do
        if group_parents[address]==group and a11y.menu_node_active(address,base)==true
                and a11y.widget_internal_name(address)~="padIcon" then
            local text=a11y.read_native_rendered_text(address)
            if text and not a11y.empty_selection_caption(text) and not text:match("^%d+$")
                    and not a11y.unresolved_format(text) and not is_noninteractive_text(text) then
                if caption then return nil,detail end
                caption=address
            end
        end
    end
    if caption then
        detail.shared_caption,detail.status=caption,"shared-caption"
        detail.parents[caption]=group
        return {[caption]=true},detail
    end
    return nil,detail
end

function a11y.cursor_caption_identity(window,detail)
    if window.impl then
        local flags=a11y.menu_read(window.impl+9,"u8")
        if a11y.menu_read(window.address+0x88,"u64")~=window.impl or not flags or flags%2~=1
                or a11y.menu_read(window.impl+0x98,"u64")~=window.root then return nil end
    end
    if detail.cursor and detail.cursor>=0x10000 then
        local parent=a11y.menu_read(detail.cursor+0x88,"u64")
        local group_index=a11y.menu_read(detail.cursor+0x90,"u32")
        local item_index=a11y.menu_read(detail.cursor+0x94,"u32")
        local group=parent and group_index and a11y.menu_child(parent,group_index)
        local selected=group and item_index and a11y.menu_child(group,item_index)
        if a11y.menu_read(window.root+0x190,"u64")~=detail.cursor
                or group~=detail.group or selected~=detail.selected or item_index~=detail.item_index then return nil end
    end
    return table.concat({window.address,window.root,detail.group,detail.selected,detail.item_index or -1},":")
end

-- SelectBase and ParameterPlayerInfo share a side/Task relationship. The
-- selected card is image-only; the native parameter panel supplies its name.
-- Recognize the shared controller methods, not a translated screen title.
function a11y.parameter_caption_variant(node,owner,base)
    if not node or not owner or not owner.parents then return nil end
    local at,seen=tonumber(node.address),{}
    for _=1,12 do
        if not at or seen[at] or at==owner.root then break end
        seen[at]=true
        local name=a11y.widget_internal_name(at)
        for index=0,1 do
            local pointer=a11y.menu_read(base+0x34a2048+index*8,"u64")
            if pointer and pointer>=0x10000 and name==a11y.read_native_c_string(pointer,64) then return index end
        end
        at=owner.parents[at]
    end
end

-- The SelectBase cursor points at the actual roster card. Compare that
-- pointer to Pitch/PitchSubstitute's native card arrays, not panel order.
function a11y.cursor_player_target(window,detail,side,snapshot,base)
    local data=a11y.menu_read(base+0x36f38a0,"u64")
    if not data or a11y.menu_read(data,"u64")~=base+0x2618830 then return nil end
    local found
    for _,roster in ipairs(snapshot.windows or {}) do
        local vt=roster.enabled and a11y.menu_read(roster.address,"u64")
        local pitch,subs=vt==base+0x261eaa0,vt==base+0x261f788
        if (pitch or subs) and roster.task_parent==window.task_parent
                and a11y.menu_read(roster.address+0x98,"u32")==side then
            local scroll=pitch and 0 or a11y.menu_read(roster.address+0x4e8,"u32")
            if scroll and scroll<=29 then
                for index=0,(pitch and 10 or 11) do
                    local card=a11y.menu_read(roster.address+0xb8+index*8,"u64")
                    local selection=a11y.menu_read(roster.address+0x118+index*8,"u64")
                    -- SelectBase's native groups are pitch(0,11 entries)
                    -- and substitutes(1,12 visible entries). Its copied image
                    -- cards need not share the Pitch presentation pointers.
                    local indexed=detail.group_index==(pitch and 0 or 1) and detail.item_index==index
                    if card==detail.selected or selection==detail.selected or indexed then
                        local slot=pitch and index or index+scroll+11
                        local record=a11y.menu_read(roster.address+0x2a0+index*4,"u32")
                        local order=slot<40 and a11y.menu_read(data+side*0x248+0x1f8+slot,"u8")
                        local shown=a11y.menu_read(detail.selected+0xc,"u32")
                        if slot<40 and record and record<40 and order==record and shown and shown%8==7 then
                            local object=a11y.menu_read(data+side*0x340+0x568+record*16,"u64")
                            local id=object and object>=0x10000 and a11y.menu_read(object+0x30,"u32")
                            local name=id and id>0 and a11y.read_native_c_string(object+0x38,64)
                            if name and #name>=2 and not name:find("%c") then
                                local current={data=data,slot=slot,side=side,record=record,object=object,id=id,name=name}
                                if found and (found.slot~=slot or found.id~=id) then return nil end
                                found=current
                            end
                        end
                    end
                end
            end
        end
    end
    return found
end

function a11y.parameter_caption_matches_target(node,variant,side,target)
    if variant==nil then return false end
    local descriptor=target.data+0xba4+side*0xa8+variant*20
    local slot=a11y.menu_read(descriptor,"u32")
    local player_side=a11y.menu_read(descriptor+4,"u32")
    local name=a11y.normalized_player_name(node.text)
    return slot==target.slot and player_side==target.side and name
        and name:sub(1,#target.name)==target.name
end

function a11y.controlled_player_caption(node,snapshot,base)
    if not node or node.name~="playerName" or not snapshot or not snapshot.members then return nil end
    local member=snapshot.members[tonumber(node.address)]
    if not member or not member.active or a11y.menu_node_active(node.address,base)~=true
            or not a11y.ui_node_matches_live(node) or a11y.read_native_rendered_text(node.address)~=node.text
            or a11y.empty_selection_caption(node.text) then return nil end
    local windows={}
    for _,window in ipairs(snapshot.windows or {}) do windows[window.address]=window end
    local result
    for _,owner in ipairs(member.owners or {}) do
        local panel=windows[owner.address]
        local vt=panel and panel.enabled and a11y.menu_read(panel.address,"u64")
        if owner.enabled and vt==base+0x261e0c8 and panel.task_parent then
            local unique=0
            local variant=a11y.parameter_caption_variant(node,owner,base)
            for _,other in pairs(a11y.ui_model.names.playerName or {}) do
                local other_member=snapshot.members[tonumber(other.address)]
                if other_member and other_member.active and a11y.menu_node_active(other.address,base)==true then
                    for _,other_owner in ipairs(other_member.owners or {}) do
                        if other_owner.enabled and other_owner.address==panel.address then
                            unique=unique+1
                            break
                        end
                    end
                end
            end
            local side=a11y.menu_read(panel.address+0x98,"u32")
            if side==0 or side==1 then
                for _,window in ipairs(snapshot.windows) do
                    local d=window.cursor_detail
                    local controller=window.enabled and a11y.menu_read(window.address,"u64")
                    if controller and d and d.status=="no-text" and d.group and d.selected
                            and window.task_parent==panel.task_parent
                            and a11y.menu_read(window.address+0x98,"u32")==side
                            and a11y.menu_read(controller+0x100,"u64")==base+0x917a40
                            and a11y.menu_read(controller+0x1a0,"u64")==base+0x917ee0 then
                        local target=a11y.cursor_player_target(window,d,side,snapshot,base)
                        local matches=target and a11y.parameter_caption_matches_target(node,variant,side,target)
                        -- A single panel remains the existing normal-navigation
                        -- fallback. Multiple panels require exact cursor proof.
                        local eligible=target and matches or (not target and unique==1)
                        if eligible and target and matches and variant==0 then
                            -- Source and candidate may refer to the SAME
                            -- player when returning over the original card.
                            -- Collapse aliases only after both IDs/slots agree.
                            for _,other in pairs(a11y.ui_model.names.playerName or {}) do
                                local other_member=snapshot.members[tonumber(other.address)]
                                for _,other_owner in ipairs(other_member and other_member.owners or {}) do
                                    if other_owner.enabled and other_owner.address==panel.address
                                            and a11y.parameter_caption_variant(other,other_owner,base)==1
                                            and a11y.parameter_caption_matches_target(other,1,side,target) then eligible=false end
                                end
                            end
                        end
                        local cursor_identity=eligible and a11y.cursor_caption_identity(window,d)
                        if cursor_identity then
                            local identity=cursor_identity .. ":panel=" .. panel.address .. ":side=" .. side
                            if result and result.identity~=identity then return nil end
                            result={identity=identity,window=window.address,panel=panel.address,side=side}
                        end
                    end
                end
            end
        end
    end
    return result
end

function a11y.bind_controlled_player_captions(snapshot,base)
    for address in pairs(snapshot.controlled_selections or {}) do
        snapshot.selected_members[address],snapshot.cursor_members[address]=nil,nil
    end
    snapshot.controlled_selections={}
    for _,node in pairs(a11y.ui_model and a11y.ui_model.names.playerName or {}) do
        local binding=a11y.controlled_player_caption(node,snapshot,base)
        if binding then
            local address=tonumber(node.address)
            snapshot.selected_members[address],snapshot.cursor_members[address]=true,true
            snapshot.controlled_selections[address]=binding
            -- Other fields in this controlled panel are presentation, not
            -- additional choices created by propagated text focus events.
            for other,member in pairs(snapshot.members) do
                for _,owner in ipairs(member.owners or {}) do
                    if owner.address==binding.panel then snapshot.cursor_members[other]=true;break end
                end
            end
        end
    end
end

function a11y.native_caption_selection_identity(address)
    local snapshot=a11y.native_windows
    local binding=snapshot and snapshot.controlled_selections and snapshot.controlled_selections[tonumber(address)]
    if binding then
        local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(address)]
        local current=a11y.controlled_player_caption(node,snapshot,tonumber(process_base_u64))
        return current and current.identity
    end
    for _,window in ipairs(snapshot and snapshot.windows or {}) do
        local d=window.cursor_detail
        if window.enabled and d and d.shared_caption==tonumber(address) then return a11y.cursor_caption_identity(window,d) end
    end
end

-- Shared NodeRectText event dispatcher. Record only; speech runs next frame.
function m.on_ui_focus_event(ctx,event_id,registers)
    local base=tonumber(process_base_u64)
    if not base then return end
    local address=tonumber(read_u64(registers.rcx))
    local event=tonumber(read_u64(registers.rdx))
    local table_start=a11y.menu_read(base+0x36f9c28,"u64")
    local table_end=a11y.menu_read(base+0x36f9c30,"u64")
    if not table_start or not table_end or table_start < 0x10000
            or table_end-table_start < 16*8 or table_end-table_start > 4096 then return end
    local signature=a11y.menu_read(event,"u64")
    if not signature or signature == 0 then return end
    local entering=signature==a11y.menu_read(table_start+15*8,"u64")
    local leaving=signature==a11y.menu_read(table_start+14*8,"u64")
    if not entering and not leaving then return end
    if a11y.menu_read(address,"u64") ~= base+0x27b5260 then return end
    a11y.record_engine_focus(address,entering)
end

function a11y.record_engine_focus(address,entering)
    local owner=a11y.native_owner_token()
    local state=a11y.engine_focus
    if not entering and (not state or state.owner ~= owner) then return end
    if not state or state.owner ~= owner then
        state={owner=owner,nodes={},count=0,sequence=0}
        a11y.engine_focus=state
    end
    local key=memory.hex(address)
    if not entering then
        if state.nodes[key] then state.nodes[key]=nil; state.count=state.count-1 end
        return
    end
    if not state.nodes[key] and state.count >= 128 then return end
    if not state.nodes[key] then state.count=state.count+1 end
    local previous=state.nodes[key]
    state.sequence=state.sequence+1
    state.nodes[key]={address=address,frame=frame,
        edge=previous and previous.edge or frame,
        sequence=previous and previous.sequence or state.sequence}
    if not previous then
        log("[FLAccess] engine-focus-enter frame=" .. tostring(frame)
            .. " widget=" .. key .. " owner=" .. tostring(owner))
    end
end

function a11y.ui_node_matches_live(node)
    if not node then return false end
    local name=a11y.widget_internal_name(node.address)
    local link=a11y.ui_owner_link(node.address)
    -- A resource link is not window ownership, but a changed link/name proves
    -- that the cached caption no longer describes this same native object.
    if (name and node.name and name ~= node.name)
            or (link and node.owner_link and link ~= node.owner_link) then
        log("[FLAccess] engine-focus-recycled widget=" .. node.key)
        a11y.forget_ui_widget(node.key)
        return false
    end
    return true
end

function a11y.window_cursor_anchor(window)
    local detail=window and window.enabled and window.cursor_detail
    if not detail or not detail.group or not detail.selected then return nil end
    return {window=window.address,token=table.concat({window.address,window.root or 0,
        detail.group,detail.selected,detail.group_index or -1,detail.item_index or -1},":")}
end

function a11y.selection_cursor_anchor(key)
    local snapshot=a11y.native_windows
    local node=a11y.ui_model and a11y.ui_model.nodes[key]
    if not snapshot or not node then return nil end
    local controlled=snapshot.controlled_selections and snapshot.controlled_selections[tonumber(node.address)]
    local member=snapshot.members and snapshot.members[tonumber(node.address)]
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local detail=window.cursor_detail
        local owns=controlled and controlled.window==window.address
            or detail and detail.shared_caption==tonumber(node.address)
        if not owns and snapshot.selected_members and snapshot.selected_members[tonumber(node.address)] then
            for _,owner in ipairs(member and member.owners or {}) do
                if owner.enabled and owner.address==window.address then owns=true end
            end
        end
        local anchor=owns and a11y.window_cursor_anchor(window)
        if anchor then
            if found and found.token~=anchor.token then return nil end
            found=anchor
        end
    end
    return found
end

function a11y.release_moved_engine_selection(state)
    local previous=state and state.last_anchor
    if not previous then return end
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        if window.address==previous.window then
            local current=a11y.window_cursor_anchor(window)
            if current and current.token~=previous.token then
                local context=a11y.read_context_state()
                local result=context.selection_result
                local row=a11y.control_for_widget(state.last_key)
                if context.kind~="dialog" and result and (result.key==state.last_key or (row and result.row==row)) then
                    context.selection_result,context.selection=nil,nil
                end
                state.last_identity,state.last_anchor,state.last_key=nil,nil,nil
                a11y.reset_focus_reuse_state()
            end
            return
        end
    end
end

function a11y.engine_focus_candidates()
    local state=a11y.engine_focus
    local snapshot=a11y.native_windows
    local cursor_keys={}
    for address in pairs(snapshot and snapshot.selected_members or {}) do
        cursor_keys[#cursor_keys+1]=memory.hex(address)
    end
    table.sort(cursor_keys)
    local cursor_identity=table.concat(cursor_keys,",")
    for _,key in ipairs(cursor_keys) do
        local node=a11y.ui_model and a11y.ui_model.nodes[key]
        local binding=node and a11y.native_caption_selection_identity(node.address)
        if binding then cursor_identity=cursor_identity .. ":caption=" .. binding end
    end
    local owner=a11y.native_owner_token()
    if state and state.owner ~= owner then state=nil; a11y.engine_focus=nil end
    if not state and #cursor_keys>0 then
        state={owner=owner,nodes={},count=0,sequence=0}
        a11y.engine_focus=state
    end
    if not state then return nil end
    a11y.release_moved_engine_selection(state)
    local old_cursors=state.cursor_nodes or {}
    local current_cursors={}
    for _,key in ipairs(cursor_keys) do
        local node=a11y.ui_model and a11y.ui_model.nodes[key]
        local binding=node and a11y.native_caption_selection_identity(node.address)
        local token=(binding or key) .. ":" .. (node and node.text or "")
        current_cursors[key]={token=token,edge=old_cursors[key]
            and old_cursors[key].token==token and old_cursors[key].edge or frame}
    end
    for key in pairs(old_cursors) do
        if not current_cursors[key] and state.nodes[key] and state.nodes[key].cursor then
            state.nodes[key]=nil;state.count=state.count-1
        end
    end
    state.cursor_identity,state.cursor_nodes=cursor_identity,current_cursors
    for _,key in ipairs(cursor_keys) do
        local node=a11y.ui_model and a11y.ui_model.nodes[key]
        if node then
            if not state.nodes[key] then state.count=state.count+1 end
            state.nodes[key]={address=node.address,frame=frame,edge=current_cursors[key].edge,
                cursor=true,sequence=state.sequence}
        end
    end
    local candidates={}
    local owners=a11y.command_icon_owners()
    local pending_label=#cursor_keys>0
    for key,event in pairs(state.nodes) do
        -- Exclude recycled/background nodes; never decode captions in the hook.
        local node=a11y.ui_model and a11y.ui_model.nodes[key]
        local row=a11y.control_for_widget(key)
        -- Numeric values remain valid when linked to an observed control; bare
        -- glyph/counter nodes and controller-icon captions are not menu choices.
        local value_member=row and node and row.value_widget_key==key and row.value==node.text
        local decoration=node and (node.name=="padIcon" or node.name=="abilityNumber"
            or a11y.is_media_caption(node) or a11y.is_menu_description(node)
            or (node.name and node.name:match("_value") and not (row and row.is_control
                and (row.native_field or row.structural or row.native_slider)))
            or (node.text and (node.text:match("^%d+$") or a11y.empty_selection_caption(node.text)) and not value_member))
        local cursor_scope=snapshot and snapshot.cursor_members
        local cursor_allowed=not cursor_scope or not cursor_scope[tonumber(event.address)]
            or snapshot.selected_members[tonumber(event.address)]
        if cursor_allowed and node and node.text and node.text ~= "" and not decoration
                and a11y.ui_node_matches_live(node)
                and a11y.native_widget_allowed(event.address)
                and not is_noninteractive_text(node.text)
                and not a11y.is_command_legend(key,true,owners)
                and not looks_like_message(node.text,event.address)
                and (not a11y.is_control_help(node.text) or a11y.is_structural_answer(node.text,key))
                and not a11y.unresolved_format(node.text) then
            state.accepted=true
            if event.cursor or frame>event.edge then candidates[#candidates+1]={key=key,edge=event.edge} end
        elseif (not node or not node.text or node.text=="") and frame-event.edge <= 30 then
            pending_label=true
        end
    end
    -- A title/paragraph event alone does not establish menu-selection authority.
    if not state.accepted and not pending_label then return nil end
    -- The native dispatcher focuses a whole compound row. In the common
    -- text_item/infoText_* schema, the information slots share its resource
    -- link and event edge, but are not independent choices. Preserve model
    -- data; only collapse a proven sibling packet, never matching captions.
    local primary={}
    for _,candidate in ipairs(candidates) do
        local node=a11y.ui_model.nodes[candidate.key]
        if node.name=="text_item" and node.owner_link then
            local packet=tostring(node.owner_link) .. ":" .. tostring(candidate.edge)
            primary[packet]=(primary[packet] or 0)+1
        end
    end
    local filtered={}
    for _,candidate in ipairs(candidates) do
        local node=a11y.ui_model.nodes[candidate.key]
        local packet=node.owner_link and (tostring(node.owner_link) .. ":" .. tostring(candidate.edge))
        local detail=false
        if node.name=="noSetting" or node.name=="allOver" then
            local labels=0
            for _,other in ipairs(candidates) do
                local label=a11y.ui_model.nodes[other.key]
                if other.edge==candidate.edge and label.name=="playerName" then
                    for _,part in ipairs(a11y.player_row_details(label)) do
                        if part==node then labels=labels+1 end
                    end
                end
            end
            detail=labels==1
        end
        if node.name=="description" or (node.name and node.name:match("^description_%d+$")) then
            local labels=0
            for _,other in ipairs(candidates) do
                local label=a11y.ui_model.nodes[other.key]
                if other.edge==candidate.edge and (label.role=="control-label" or label.name=="item" or label.name=="itemName")
                        and a11y.component_peers(node.address,label.address)==true then labels=labels+1 end
            end
            detail=labels==1
        end
        if not detail and not (node.name and node.name:match("^infoText_")
                and packet and primary[packet]==1) then filtered[#filtered+1]=candidate end
    end
    candidates=filtered
    local music,artists={},{}
    for _,candidate in ipairs(candidates) do
        local packet=a11y.native_music_packet(a11y.ui_model.nodes[candidate.key])
        if packet and packet.artist then music[candidate.key]=packet;artists[packet.artist.key]=candidate end
    end
    filtered={}
    for _,candidate in ipairs(candidates) do
        local packet=music[candidate.key]
        if packet and packet.artist then
            for _,other in ipairs(candidates) do
                if other.key==packet.artist.key then candidate.edge=math.max(candidate.edge,other.edge) end
            end
        end
        if not artists[candidate.key] then filtered[#filtered+1]=candidate end
    end
    candidates=filtered
    local pause=a11y.native_pause_context()
    if pause and a11y.read_context_state().kind~="dialog" then
        local base=tonumber(process_base_u64)
        local has_navigation,navigation_members,passive=false,{},{}
        for _,candidate in ipairs(candidates) do
            local node=a11y.ui_model.nodes[candidate.key]
            local member=snapshot and snapshot.members[tonumber(node.address)]
            for _,owner in ipairs(member and member.owners or {}) do
                if owner.enabled then
                    if owner.address==pause.window and owner.root==pause.root then
                        has_navigation=true;navigation_members[candidate.key]=true
                    end
                    local vt=base and a11y.menu_read(owner.address,"u64")
                    -- MatchStatsMenuContentTeamStats owns the teamRecord
                    -- captions. Its displayed cursor is not pause navigation.
                    if vt and a11y.menu_read(vt+0x18,"u64")==base+0x4eb1c0
                            and a11y.menu_read(vt+0x100,"u64")==base+0xca1a50 then
                        passive[candidate.key]=true
                    end
                end
            end
        end
        if has_navigation then
            local scoped={}
            for _,candidate in ipairs(candidates) do
                if not passive[candidate.key] or navigation_members[candidate.key] then scoped[#scoped+1]=candidate end
            end
            candidates=scoped
        end
    end
    return candidates
end

function a11y.process_engine_focus(modal_blocked)
    if a11y.native_information_context() and not a11y.keyboard_window
            and a11y.read_context_state().kind~="dialog" then return true end
    if a11y.process_native_list_focus(modal_blocked) then return true end
    local candidates=a11y.engine_focus_candidates()
    if not candidates then return false end -- Existing adapters remain a fallback.
    if a11y.keyboard_window then return true end
    for _,candidate in ipairs(candidates) do
        if a11y.capture_reading_panel(a11y.ui_model.nodes[candidate.key]) then return true end
    end
    if a11y.process_read_dialog_focus(candidates) then return true end
    local selected,reason=a11y.resolve_primary_focus(candidates)
    if not selected then
        local keys={}
        for _,candidate in ipairs(candidates) do keys[#keys+1]=candidate.key end
        table.sort(keys)
        local unresolved=reason .. ":" .. table.concat(keys,",")
        if unresolved ~= a11y.engine_focus.unresolved then
            a11y.engine_focus.unresolved=unresolved
            log("[FLAccess] engine-focus-unresolved reason=" .. reason .. " widgets=" .. table.concat(keys,","))
            local state=a11y.engine_focus
            state.gap_count=(state.gap_count or 0)+1
            if state.gap_count<=40 then
                local events={}
                for key,event in pairs(state.nodes) do events[#events+1]={key=key,event=event} end
                table.sort(events,function(a,b)
                    if a.event.edge~=b.event.edge then return a.event.edge>b.event.edge end
                    return a.key<b.key
                end)
                local parts={}
                for index,item in ipairs(events) do
                    if index>8 then break end
                    local node=a11y.ui_model and a11y.ui_model.nodes[item.key]
                    if node then a11y.component_evidence(node,"focus-" .. reason) end
                    parts[#parts+1]=string.format("%s name=%q text=%q edge=%s flags=%s",
                        item.key,(node and node.name) or a11y.widget_internal_name(item.event.address) or "",
                        node and node.text or "",tostring(item.event.edge),
                        tostring(a11y.menu_read(item.event.address+0xc,"u32")))
                end
                log("[FLAccess] engine-focus-gap " .. table.concat(parts," | "))
            end
        end
        -- An empty/ambiguous frame is not a new selection. Keep the last
        -- committed identity through construction and propagation bursts.
        return true -- Wait for a label/settled selection, rather than old flags.
    end
    local node=a11y.ui_model.nodes[selected.key]
    a11y.engine_focus.unresolved=nil
    local event=a11y.engine_focus.nodes[selected.key]
    if not event then return true end
    -- A field keeps focus while its value changes. The value belongs in the
    -- spoken-state identity, even when no new selection event was dispatched.
    local row=a11y.control_for_widget(selected.key)
    local identity=a11y.engine_selection_identity(selected.key,node)
    if modal_blocked and event.edge <= modal_message_spoken_frame+2 then return true end
    local now=tonumber(ffi.C.GetTickCount64())
    if now < (a11y.screen_title_hold_until_ms or 0) then return true end
    a11y.track_control_focus(selected.key)
    local last_result=a11y.read_context_state().selection_result
    if a11y.engine_focus.last_identity==identity and not (last_result
            and (last_result.status=="discarded" or last_result.status=="failed")) then return true end
    local queue_before=a11y.native_speech_last
    if row and row.is_control then
        announce_control(row)
    else
        a11y.deliver_selection_result(a11y.selection_result({node=node,widget=node.address,
            identity=identity,source="engine-focus"}),{interrupt=true})
    end
    if a11y.native_speech_last==queue_before then
        -- The text-update path may already have delivered this same field.
        -- Record its current state only if control dedupe confirms delivery;
        -- a modal/presentation hold must still retry.
        if row and last_announced_control_row==row and last_controller_announcement==control_speech(row) then
            a11y.engine_focus.last_identity=identity
            a11y.engine_focus.last_key=selected.key
            a11y.engine_focus.last_anchor=a11y.selection_cursor_anchor(selected.key)
        end
        return true
    end
    a11y.engine_focus.last_identity=identity
    a11y.engine_focus.last_key=selected.key
    a11y.engine_focus.last_anchor=a11y.selection_cursor_anchor(selected.key)
    for index=queue_before+1,a11y.native_speech_last do
        a11y.native_speech_queue[index].engine_focus={owner=a11y.engine_focus.owner,
            key=selected.key,identity=identity}
    end
    if a11y.ui_model then a11y.ui_model.focus_reason="engine-event:" .. reason end
    log("[FLAccess] engine-focus-commit widget=" .. selected.key .. " identity=" .. identity
        .. " source=" .. (event.cursor and "native-cursor" or "native-event"))
    return true
end

function a11y.reading_selection_delivery_allowed(origin)
    local context=a11y.read_context
    return context and context.generation==origin.generation and context.selection
        and context.selection.identity==origin.identity
end

function a11y.engine_selection_identity(key,node)
    local row=a11y.control_for_widget(key)
    local identity=a11y.ui_focus_identity(key,node.text)
    local binding=a11y.native_caption_selection_identity(node.address)
    if binding then identity=identity .. ":caption=" .. binding end
    if row and row.is_control then identity=identity .. ":value=" .. (row.value or "") end
    for _,part in ipairs(a11y.player_row_details(node)) do
        identity=identity .. ":part=" .. part.identity .. ":" .. part.text
    end
    local roster=a11y.native_player_roster_context(node)
    local state=a11y.engine_focus
    if state and node.name=="playerName" then
        -- Availability of optional roster evidence is not another cursor move.
        -- Retain only the last identity token, never attributes or authority.
        if roster then state.roster_focus_key,state.roster_focus_token=identity,roster.identity end
        if state.roster_focus_key==identity and state.roster_focus_token then
            identity=identity .. ":panel-roster=" .. state.roster_focus_token
        end
    elseif roster then identity=identity .. ":panel-roster=" .. roster.identity end
    local page=a11y.native_page_context(node.address)
    if page then identity=identity .. ":page=" .. page.identity end
    local music=a11y.native_music_packet(node)
    if music then identity=identity .. ":music=" .. music.signature end
    local assignment=a11y.native_assignment_context(node.address)
    if assignment then identity=identity .. ":assignment=" .. assignment.identity end
    local member=a11y.native_windows and a11y.native_windows.members
        and a11y.native_windows.members[tonumber(node.address)]
    if member and member.active then
        local _,slot=a11y.native_roster_section(node,member)
        if slot then identity=identity .. ":roster=" .. slot end
    end
    return identity
end

-- Controller-assignment component: c67970 stores the selected column at +a4;
-- c68e40 resolves root[group +94][column +a4] before showing the user name.
-- c67ad0 converts column 1 to unassigned (0), 0 to side 1, 2 to side 2.
-- Follow those exact links and native methods, never discovery order/captions.
function a11y.native_assignment_context(address,unfocused)
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    if not address or not base or not snapshot or not snapshot.selected_members
            or (not unfocused and not snapshot.selected_members[tonumber(address)]) then return nil end
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local vt=window.enabled and a11y.menu_read(window.address,"u64")
        if vt and a11y.menu_read(vt+0x140,"u64")==base+0xc68fd0
                and a11y.menu_read(vt+0x148,"u64")==base+0xc67970 then
            local state=a11y.menu_read(window.address+0xa4,"u32")
            local index=a11y.menu_read(window.address+0x94,"u32")
            if state and state<=2 and index and index<32 then
                local group=a11y.menu_child(window.root,index)
                local column=group and a11y.menu_child(group,state)
                local texts=column and a11y.menu_tree(column,base)
                if texts and texts[tonumber(address)] then
                    local label
                    if state==1 then
                        label=a11y.ui_language=="pt" and "Neutro" or "Neutral"
                    else
                        local name=state==0 and "text_home" or "text_away"
                        for _,node in pairs(a11y.ui_model and a11y.ui_model.names[name] or {}) do
                            if node.name==name and a11y.native_presentation_ready(node.address) and a11y.ui_node_matches_live(node) then
                                local member=snapshot.members[tonumber(node.address)]
                                for _,owner in ipairs(member and member.owners or {}) do
                                    if owner.address==window.address or owner.address==window.task_parent then
                                        if label and label~=node.text then return nil end
                                        label=node.text;break
                                    end
                                end
                            end
                        end
                    end
                    if label and label~="" then
                        -- c68d00 passes +98 to c68e40; it selects the personal
                        -- data profile whose name is rendered in this column.
                        local profile=a11y.menu_read(window.address+0x98,"u32")
                        if profile and profile>=32 then profile=nil end
                        local result={window=window.address,root=window.root,profile=profile,state=state,text=label,focus_address=address,
                            identity=tostring(window.address) .. ":" .. tostring(group) .. ":" .. state .. ":" .. label
                                .. ":profile=" .. tostring(profile)}
                        if found and found.identity~=result.identity then return nil end
                        found=result
                    end
                end
            end
        end
    end
    return found
end

function a11y.assignment_change_allowed(change)
    local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(change.address)]
    local current=node and a11y.ui_node_matches_live(node)
        and a11y.native_assignment_context(node.address,true)
    local rendered=node and a11y.read_native_rendered_text(node.address)
    return current and current.root==change.root and current.identity==change.identity and node.text==change.text
        and (rendered==nil or rendered==change.text)
end

function a11y.poll_assignment_changes()
    if a11y.read_context_state().kind=="dialog" then a11y.assignment_monitor=nil;return end
    local owner=a11y.native_owner_token()
    local previous=a11y.assignment_monitor
    local delivered=a11y.assignment_delivered or {}
    a11y.assignment_delivered=delivered
    local current={owner=owner,items={}}
    for _,node in pairs(a11y.ui_model and a11y.ui_model.names.personalDataName or {}) do
        -- This is a profile/state announcement, not focus speech. The native
        -- column still owns its user label when focus flags change to 0x105.
        -- native_assignment_context validates the enabled typed controller,
        -- current column/side and exact subtree independently of those flags.
        if a11y.ui_node_matches_live(node) then
            local assignment=a11y.native_assignment_context(node.address,true)
            if assignment then
                -- Buttons may change an unfocused/previously blank user row
                -- without hitting the observed text setter. Refresh that exact
                -- typed column now, rather than waiting for background scanning.
                local text,raw=a11y.read_native_rendered_text(node.address)
                if text~=nil and (text~=node.text or not a11y.ui_node_matches_live(node)) then
                    a11y.on_observed_ui_text(node.address,text,raw,nil,true)
                    node=a11y.ui_model.nodes[memory.hex(node.address)]
                end
            end
            if assignment and node and node.text and not a11y.empty_selection_caption(node.text) then
                local key=tostring(assignment.window) .. ":" .. tostring(assignment.root)
                local signature=assignment.identity .. ":" .. node.text
                local item=current.items[key]
                if item and item.signature~=signature then
                    -- More than one current name in the same typed column is
                    -- ambiguous; do not pick one by discovery order.
                    current.items[key]={ambiguous=true}
                elseif not item then current.items[key]={node=node,text=node.text,assignment=assignment,signature=signature} end
            end
        end
    end
    a11y.assignment_monitor=current
    for key,item in pairs(current.items) do
        local old=previous and previous.items[key]
        if not item.ambiguous and not delivered[key] and not old then
            delivered[key]={signature=item.signature} -- initial placement is a silent baseline
        end
        local last=delivered[key]
        if not item.ambiguous and last and last.signature~=item.signature then
            local result=a11y.read_context_state().selection_result
            local already=result and result.assignment and result.assignment.identity==item.assignment.identity
                and result.label==item.node.text and result.status~="discarded" and result.status~="failed"
            if already and result.status=="delivered" then delivered[key]={signature=item.signature}
            elseif not already or result.status=="discarded" or result.status=="failed" then
                -- A native profile change may precede the rendered name. Wait
                -- for that caption to change instead of announcing the old user.
                local awaiting_name=old and old.assignment.profile~=item.assignment.profile
                    and old.text==item.text
                local queued=false
                for index=a11y.native_speech_first,a11y.native_speech_last do
                    local change=a11y.native_speech_queue[index] and a11y.native_speech_queue[index].assignment_change
                    if change and change.key==key and change.signature==item.signature then queued=true end
                end
                if awaiting_name then
                    item.awaiting_profile_name=true
                elseif old and old.awaiting_profile_name and old.text==item.text then
                    item.awaiting_profile_name=true
                elseif not queued then
                local before=a11y.native_speech_last
                a11y.assignment_attempt=(a11y.assignment_attempt or 0)+1
                speak(item.node.text .. ", " .. item.assignment.text,true,nil,
                    "assignment-change:" .. item.signature .. ":attempt=" .. a11y.assignment_attempt)
                for index=before+1,a11y.native_speech_last do
                    a11y.native_speech_queue[index].assignment_change={root=item.assignment.root,address=item.node.address,
                        text=item.node.text,identity=item.assignment.identity,key=key,signature=item.signature}
                end
                end
            end
        end
    end
    for key in pairs(delivered) do if not current.items[key] then delivered[key]=nil end end
end

-- ListMultiPageBase selects TabPageInfo from its own vector (+1d8/+1e0,
-- 40-byte records). eb1c87/eb1928 write +1d0; eb0e90/eb1090 animate
-- the exact Node at record+20 as active/inactive. No caption/index catalogue.
function a11y.native_page_context(address)
    local base=tonumber(process_base_u64)
    local snapshot=a11y.native_windows
    local member=address and snapshot and snapshot.members[tonumber(address)]
    if not base or not member or not member.active then return nil end
    local result
    for _,window in ipairs(snapshot.windows or {}) do
        local vt=a11y.menu_read(window.address,"u64")
        if (window.enabled or window.context_active) and vt and a11y.menu_read(vt+0x2e0,"u64")==base+0xeb17f0
                and a11y.menu_read(vt+0x2e8,"u64")==base+0xeb1b60 then
            local first=a11y.menu_read(window.address+0x1d8,"u64")
            local last=a11y.menu_read(window.address+0x1e0,"u64")
            local index=a11y.menu_read(window.address+0x1d0,"u32")
            if first and last and first>=0x10000 and last>=first and (last-first)%0x40==0
                    and last-first<=0x40*32 and index and index<(last-first)/0x40 then
                local record=first+index*0x40
                local child=a11y.menu_read(record+8,"u64")
                local tab=a11y.menu_read(record+0x20,"u64")
                local related=false
                for _,owner in ipairs(member.owners or {}) do
                    if owner.enabled and (owner.address==window.address or owner.address==child) then related=true end
                end
                if related and tab and tab>=0x10000 and a11y.menu_read(record,"u64")==base+0x27d6590 then
                    local texts=a11y.menu_tree(tab,base)
                    local caption,ambiguous
                    for at in pairs(texts) do
                        if a11y.widget_internal_name(at)=="tabText" and a11y.menu_node_active(at,base)
                                and a11y.native_text_presented(at) then
                            local text=a11y.read_native_rendered_text(at)
                            if text and text~="" and not a11y.unresolved_format(text) then
                                if caption then ambiguous=true end
                                caption={address=at,text=text}
                            end
                        end
                    end
                    if caption and not ambiguous then
                        caption.window,caption.index,caption.focus_address=window.address,index,address
                        caption.identity=a11y.native_owner_token() .. ":" .. tostring(window.address)
                            .. ":" .. tostring(record) .. ":" .. tostring(tab) .. ":" .. caption.text
                        if result and result.identity~=caption.identity then return nil end
                        result=caption
                    end
                end
            end
        end
    end
    return result
end

function a11y.page_focus_speech(text,address)
    local page=a11y.native_page_context(address)
    if page and page.identity~=a11y.last_page_delivery then return page.text .. ". " .. text,page end
    return text,page
end

function a11y.page_delivery_allowed(origin)
    local current=a11y.native_page_context(origin.focus_address or origin.address)
    return current and current.identity==origin.identity
end

-- A tab can change while its content has no selectable text (an icon grid or
-- empty page). Its native selected record remains presentation authority.
function a11y.poll_native_pages(blocked)
    if a11y.native_information_context() then return end
    if blocked or a11y.keyboard_window or a11y.read_context_state().kind=="dialog" then return end
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    local page
    for _,window in ipairs(snapshot and snapshot.windows or {}) do
        local vt=base and window.enabled and a11y.menu_read(window.address,"u64")
        if vt and a11y.menu_read(vt+0x2e0,"u64")==base+0xeb17f0
                and a11y.menu_read(vt+0x2e8,"u64")==base+0xeb1b60 then
            for address,member in pairs(snapshot.members or {}) do
                local belongs=false
                for _,owner in ipairs(member.owners or {}) do
                    if owner.enabled and owner.address==window.address then belongs=true;break end
                end
                if belongs and member.active then
                    local found=a11y.native_page_context(address)
                    if found then
                        if page and page.identity~=found.identity then return end
                        page=found
                    end
                    break
                end
            end
        end
    end
    if not page or page.identity==a11y.last_page_delivery then return end
    for index=a11y.native_speech_first,a11y.native_speech_last do
        local pending=a11y.native_speech_queue[index]
        if pending and pending.page_context and pending.page_context.identity==page.identity
                and a11y.speech_entry_allowed(pending) then return end
    end
    page.focus_address=page.address
    local before=a11y.native_speech_last
    speak(page.text,false,nil,"page:" .. page.identity,page.address)
    if a11y.native_speech_last>before then
        a11y.last_page_announcement=page.identity
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].page_context=page end
    end
end

function a11y.engine_focus_delivery_allowed(origin)
    local state=a11y.engine_focus
    local node=a11y.ui_model and a11y.ui_model.nodes[origin.key]
    return state and state.owner==origin.owner and state.owner==a11y.native_owner_token()
        and state.last_identity==origin.identity and state.nodes[origin.key] ~= nil
        and node and a11y.engine_selection_identity(origin.key,node)==origin.identity
end

function a11y.native_node_summary(address)
    if not address or address < 0x10000 then return "none" end
    local fields = {}
    -- Diagnostic raw candidates only: these do not establish child ownership.
    for _, offset in ipairs({0,0x38,0x98,0xa0,0x120,0x170,0x178,0x180,0x190}) do
        local value = a11y.menu_read(address+offset,"u64")
        if value then fields[#fields+1]=string.format("%x=%s",offset,memory.hex(value)) end
    end
    return table.concat(fields,",")
end

-- Bounded structural evidence for unresolved components. Never used to infer
-- speech, visibility, a button mapping or roster status from an address/name.
function a11y.component_evidence(node,reason)
    if not node then return end
    local owner=a11y.native_owner_token()
    if a11y.component_evidence_owner~=owner or not a11y.component_evidence_seen then
        a11y.component_evidence_owner,a11y.component_evidence_seen=owner,{}
        a11y.component_evidence_count=0
    end
    local key=reason .. ":" .. node.key .. ":" .. node.text
    if a11y.component_evidence_seen[key] or (a11y.component_evidence_count or 0)>=24 then return end
    a11y.component_evidence_seen[key]=true
    a11y.component_evidence_count=(a11y.component_evidence_count or 0)+1
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[tonumber(node.address)]
    local paths={}
    for index,entry in ipairs(member and member.owners or {}) do
        if index>2 then break end
        local at,visited,parts=tonumber(node.address),{},{}
        for _=1,12 do
            if not at or visited[at] then break end
            visited[at]=true
            parts[#parts+1]=string.format("%s/%s/%s",memory.hex(at),
                tostring(a11y.menu_read(at,"u64")),a11y.widget_internal_name(at) or "")
            if at==entry.root then break end
            at=entry.parents and entry.parents[at]
        end
        paths[#paths+1]=table.concat(parts,">")
    end
    local _,raw,font=a11y.read_native_rendered_text(node.address)
    log(string.format("[FLAccess] component-evidence reason=%s widget=%s name=%q text=%q flags=%s font=%s raw=%q path=%s",
        reason,node.key,node.name or "",node.text or "",tostring(a11y.menu_read(node.address+0xc,"u32")),
        tostring(font),raw or "",table.concat(paths," | ")))
end

-- Window::close (e43450) walks Impl+70/+78 in 50-byte records and
-- clears the shown state of each Node at record+40 through e4c240.
-- These owned roots include passive presentation, not just Impl+98 navigation.
function a11y.window_owned_roots(impl,primary,base)
    local roots,seen={},{}
    if primary and primary>=0x10000 then roots[1],seen[primary]=primary,true end
    -- e3d790 returns the presentation Node, e3dc90 the navigation Node.
    -- They can differ even while the same window owns both. Ownership does
    -- not grant input authority to a disabled window.
    local presentation=a11y.menu_read(impl+0x90,"u64")
    if presentation and presentation>=0x10000 and not seen[presentation] then
        local vt=a11y.menu_read(presentation,"u64")
        if vt and a11y.native_layout.holders[vt-base] then
            roots[#roots+1],seen[presentation]=presentation,true
        end
    end
    local first,last=a11y.menu_read(impl+0x70,"u64"),a11y.menu_read(impl+0x78,"u64")
    if not first or not last or first<0x10000 or last<first
            or (last-first)%0x50~=0 or last-first>0x50*64 then return roots end
    for at=first,last-0x50,0x50 do
        if #roots>=16 then break end
        local node=a11y.menu_read(at+0x40,"u64")
        if node and node>=0x10000 and not seen[node] then
            local vtable=a11y.menu_read(node,"u64")
            local rva=vtable and vtable-base
            local typed=rva and (a11y.native_layout.holders[rva] or rva==0x27b5260 or rva==0x27c3a38)
            local delegate=a11y.has_owned_node_delegate(vtable,base)
            if typed or delegate then roots[#roots+1],seen[node]=node,true end
        end
    end
    return roots
end

-- Read-only equivalent of e4d1c0: ordered holder+78 tree, value at +40,
-- filtering the Node kind at +88. Tree order, not pointer/visit order,
-- defines the index consumed by the game's presentation code.
function a11y.holder_kind_nodes(holder,kind)
    local head=a11y.menu_read(holder+0x78,"u64")
    if not head or head<0x10000 or a11y.menu_read(head+0x19,"u8")~=1 then return nil end
    local at=a11y.menu_read(head+8,"u64")
    local stack,seen,nodes,count={},{},{},0
    while (at and at~=head) or #stack>0 do
        while at and at~=head do
            if at<0x10000 or seen[at] or count>=256
                    or a11y.menu_read(at+0x19,"u8")~=0 then return nil end
            seen[at],count=true,count+1
            stack[#stack+1]=at
            at=a11y.menu_read(at,"u64")
            if not at then return nil end
        end
        at=table.remove(stack)
        local child=a11y.menu_read(at+0x40,"u64")
        if child and child>=0x10000 and a11y.menu_read(child+0x88,"u32")==kind then
            nodes[#nodes+1]=child
        end
        at=a11y.menu_read(at+0x10,"u64")
        if not at then return nil end
    end
    return nodes
end

function a11y.read_native_command_bar(base)
    -- e34b60 returns this typed singleton; e346e0 destroys +70 while hidden.
    local address=a11y.menu_read(base+0x36f98f0,"u64")
    if not address or a11y.menu_read(address,"u64")~=base+0x27b2668 then return nil end
    local root=a11y.menu_read(address+0x70,"u64")
    if not root or a11y.menu_read(root,"u64")~=base+0x27bae88
            or a11y.menu_read(address+0x1b9,"u8")~=0 then return nil end
    local flags=a11y.menu_read(root+0xc,"u32")
    -- GuideBar is presentation, not an input window. Its shown/enabled bits
    -- matter here; individual text nodes still pass the propagated-state gate.
    if not flags or flags%8~=7 then return nil end
    local pairs={}
    -- e3594d/e35969 and e35a77/e35a94 resolve the seven displayed
    -- icons at kind 19 indices 0..6 and captions at indices 7..13.
    -- The constructor's +90 arrays contain other templates/placeholders.
    local texts=a11y.holder_kind_nodes(root+0x98,0x13) or {}
    for index=0,6 do
        local icon,caption=texts[index+1],texts[index+8]
        if icon and caption and a11y.menu_read(icon,"u64")==base+0x27b5260
                and a11y.menu_read(caption,"u64")==base+0x27b5260 then
            pairs[#pairs+1]={icon=icon,caption=caption,index=index}
        end
    end
    return {address=address,root=root,pairs=pairs}
end

function a11y.component_link_capture_lines(snapshot)
    local lines,seen={},{}
    local caption_count=0
    for address in pairs(snapshot and snapshot.selected_members or {}) do
        local binding=a11y.native_caption_selection_identity(address)
        if binding and caption_count<32 then
            caption_count=caption_count+1
            lines[#lines+1]=string.format("CAPTION_SELECTION widget=%s identity=%q",tostring(address),binding)
        end
    end
    local result=a11y.read_context and a11y.read_context.selection_result
    if result then
        lines[#lines+1]=string.format("RESULT source=%q widget=%s generation=%s label=%q value=%q value_known=%s page=%q status=%q missing=%q",
            result.source,tostring(result.widget),tostring(result.generation),result.label,result.value or "",
            tostring(result.value~=nil),result.page and result.page.identity or "",result.status or "",
            table.concat(result.missing,","))
    end
    local base=tonumber(process_base_u64)
    for address in pairs(snapshot and snapshot.selected_members or {}) do
        local page=a11y.native_page_context(address)
        if page and not seen[page.identity] then
            seen[page.identity]=true
            lines[#lines+1]=string.format("PAGE window=%s index=%d caption=%s text=%q identity=%q",
                tostring(page.window),page.index,tostring(page.address),page.text,page.identity)
        end
    end
    local bar=snapshot and snapshot.command_bar
    if bar then
        for _,pair in ipairs(bar.pairs) do
            local icon,raw,font=a11y.read_native_rendered_text(pair.icon)
            local caption=a11y.read_native_rendered_text(pair.caption)
            lines[#lines+1]=string.format("COMMAND bar=%s root=%s index=%d icon=%s caption=%s icon_text=%q raw=%q font=%s text=%q",
                tostring(bar.address),tostring(bar.root),pair.index,tostring(pair.icon),tostring(pair.caption),
                icon or "",raw or "",tostring(font),caption or "")
        end
    end
    for _,window in ipairs(snapshot and snapshot.windows or {}) do
        local vt=base and a11y.menu_read(window.address,"u64")
        if vt and a11y.menu_read(vt+0x2e0,"u64")==base+0xeb17f0
                and a11y.menu_read(vt+0x2e8,"u64")==base+0xeb1b60 then
            local first=a11y.menu_read(window.address+0x1d8,"u64")
            local last=a11y.menu_read(window.address+0x1e0,"u64")
            local index=a11y.menu_read(window.address+0x1d0,"u32")
            local tab=first and last and index and last>=first and (last-first)%0x40==0
                and index<(last-first)/0x40 and a11y.menu_read(first+index*0x40+0x20,"u64")
            lines[#lines+1]=string.format("PAGE_STATE window=%s input=%s first=%s last=%s index=%s tab=%s type=%s",
                tostring(window.address),tostring(window.enabled),tostring(first),tostring(last),tostring(index),
                tostring(tab),tostring(tab and a11y.menu_read(tab,"u64")))
        end
        if vt and a11y.menu_read(vt+0x140,"u64")==base+0xc68fd0
                and a11y.menu_read(vt+0x148,"u64")==base+0xc67970 then
            lines[#lines+1]=string.format("ASSIGNMENT window=%s root=%s group=%s column=%s task_parent=%s",
                tostring(window.address),tostring(window.root),tostring(a11y.menu_read(window.address+0x94,"u32")),
                tostring(a11y.menu_read(window.address+0xa4,"u32")),tostring(window.task_parent))
        end
        if vt and (vt==base+0x261eaa0 or vt==base+0x261f788) then
            local bound=a11y.roster_limits and a11y.roster_limits[window.address]
            local presentation=a11y.roster_presentation_root(window.address)
            lines[#lines+1]=string.format("ROSTER window=%s type=%s root=%s input=%s side=%s scroll=%s boundary=%s boundary_root=%s presentation=%s",
                tostring(window.address),tostring(vt),tostring(window.root),tostring(window.enabled),
                tostring(a11y.menu_read(window.address+0x98,"u32")),
                tostring(a11y.menu_read(window.address+0x4e8,"u32")),tostring(bound and bound.limit),tostring(bound and bound.root),tostring(presentation))
            for index=0,(vt==base+0x261eaa0 and 10 or 11) do
                local data=a11y.menu_read(base+0x36f38a0,"u64")
                local side=a11y.menu_read(window.address+0x98,"u32")
                local record=a11y.menu_read(window.address+0x2a0+index*4,"u32")
                local object=data and a11y.menu_read(data,"u64")==base+0x2618830
                    and (side==0 or side==1) and record and record<40
                    and a11y.menu_read(data+side*0x340+0x568+record*16,"u64")
                local id=object and object>=0x10000 and a11y.menu_read(object+0x30,"u32")
                lines[#lines+1]=string.format("SLOT window=%s index=%d card=%s selection_card=%s record=%s player_object=%s player_id=%s",
                    tostring(window.address),index,tostring(a11y.menu_read(window.address+0xb8+index*8,"u64")),
                    tostring(a11y.menu_read(window.address+0x118+index*8,"u64")),tostring(record),tostring(object),tostring(id))
            end
        end
    end
    for address in pairs(snapshot and snapshot.members or {}) do
        local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(address)]
        local player=node and a11y.current_player_record(node)
        if player then
            local positions={}
            for _,entry in ipairs(player.secondary or {}) do positions[#positions+1]=entry.position .. ":" .. entry.level end
            lines[#lines+1]=string.format("PLAYER_DATA widget=%s object=%s player_id=%s slot=%s side=%s primary=%s secondary=%q field=%s mode=%s limit=%s identity=%q",
                tostring(address),tostring(player.object),tostring(player.player_id),tostring(player.slot),tostring(player.side),
                tostring(player.primary),table.concat(positions,","),tostring(player.field_position),
                tostring(a11y.menu_read(player.data+8,"u32")),tostring(a11y.live_roster_limit(player.data)),player.identity)
        end
        local roster=node and a11y.native_player_roster_context(node)
        if roster then
            lines[#lines+1]=string.format("PLAYER_PANEL widget=%s window=%s slot=%s side=%s player_id=%s section=%q identity=%q",
                tostring(address),tostring(roster.window),tostring(roster.slot),tostring(roster.side),
                tostring(roster.player_id),roster.section or "",roster.identity)
        end
    end
    return lines
end

-- Window instances inherit both lifecycle slots. Only this verified family
-- shares Task links (+38 parent, +40 child anchor, +50 next sibling).
-- Node objects use entirely different meanings for these offsets.
function a11y.is_native_window_task(address,base)
    local vt=address and address>=0x10000 and a11y.menu_read(address,"u64")
    return vt and a11y.menu_read(vt+0x50,"u64")==base+0xe43510
        and a11y.menu_read(vt+0x58,"u64")==base+0xe43450
end

function a11y.related_window_tasks(address,base)
    local result={}
    if not a11y.is_native_window_task(address,base) then return result end
    local parent=a11y.menu_read(address+0x38,"u64")
    if a11y.is_native_window_task(parent,base) then result[#result+1]=parent end
    local child=a11y.menu_read(address+0x40,"u64")
    local seen={}
    while child and child>=0x10000 and not seen[child] and #result<32 do
        seen[child]=true
        if not a11y.is_native_window_task(child,base)
                or a11y.menu_read(child+0x38,"u64")~=address then break end
        result[#result+1]=child
        child=a11y.menu_read(child+0x50,"u64")
    end
    return result
end

function a11y.bind_presented_window_contexts(snapshot,base)
    local windows={}
    for _,window in ipairs(snapshot.windows) do windows[window.address]=window end
    for _,window in ipairs(snapshot.windows) do
        if window.enabled then
            local current,seen=window,{}
            for depth=1,16 do
                local parent=current.task_parent and windows[current.task_parent]
                if not parent or seen[parent.address] then break end
                seen[parent.address]=true
                -- A Task relation proves ownership, not visibility. Demand the
                -- native shown state of the parent's presentation root as well.
                local flags=parent.presentation_root and a11y.menu_read(parent.presentation_root+0xc,"u32")
                if not flags or flags%8~=7 then break end
                parent.context_active=true
                current=parent
            end
        end
    end
    for _,member in pairs(snapshot.members) do
        member.presented=member.active
        for _,owner in ipairs(member.owners or {}) do
            if windows[owner.address] and windows[owner.address].context_active then member.presented=true end
        end
    end
end

function a11y.read_native_windows_snapshot(base)
    local manager = a11y.menu_read(base + 0x36f9c10, "u64")
    if not manager or a11y.menu_read(manager, "u64") ~= base + 0x27c1568 then return nil end
    local result = {manager=manager, windows={}, members={}, active={}, signature={},
        selected_members={}, cursor_members={}}
    local tree_cache = {}
    local seen = {}
    for slot = 0, 7 do
        local window = a11y.menu_read(manager + 0xc8 + slot * 16, "u64")
        local priority = a11y.menu_read(manager + 0xd0 + slot * 16, "i32")
        if not window or priority == nil then return nil end
        local registered = {}
        local first = a11y.menu_read(manager + 8 + slot * 24, "u64")
        local last = a11y.menu_read(manager + 16 + slot * 24, "u64")
        if not first or not last or last < first or (last - first) % 16 ~= 0
                or last - first > 1024 then return nil end
        if first >= 0x10000 then
            for at = first, last - 16, 16 do
                local address = a11y.menu_read(at, "u64")
                if not address then return nil end
                if address >= 0x10000 then registered[#registered + 1] = address end
            end
        elseif first ~= last then return nil end
        if window >= 0x10000 then registered[#registered + 1] = window end
        for _, address in ipairs(registered) do
          if not seen[address] then
            seen[address] = true
            for _,related in ipairs(a11y.related_window_tasks(address,base)) do
                if not seen[related] and #registered<96 then registered[#registered+1]=related end
            end
            local impl = a11y.menu_read(address + 0x88, "u64")
            if not impl then return nil end
            local flags = a11y.menu_read(impl + 9, "u8")
            local root = a11y.menu_read(impl + 0x98, "u64")
            if flags == nil or not root then return nil end
            local enabled = flags % 2 == 1
            local entry = {slot=slot, address=address, impl=impl, root=root,
                priority=priority, enabled=enabled,primary=address==window,vtable=a11y.menu_read(address,"u64")}
            entry.presentation_root=a11y.menu_read(impl+0x90,"u64")
            if a11y.is_native_window_task(address,base) then entry.task_parent=a11y.menu_read(address+0x38,"u64") end
            entry.owned_roots=a11y.window_owned_roots(impl,root,base)
            if enabled and a11y.menu_read(address,"u64") == base + 0x27c3eb0 then result.keyboard = address end
            result.windows[#result.windows + 1] = entry
            if #result.windows > 96 then return nil end
            if entry.primary or #entry.owned_roots>0 then result.signature[#result.signature + 1] = tostring(address) .. ":" ..
                tostring(root) .. ":" .. tostring(enabled) .. ":" .. tostring(priority)
                .. ":" .. table.concat(entry.owned_roots,",") end
            if enabled and (entry.primary or #entry.owned_roots>0) then
                local identity=tostring(address) .. ":" .. tostring(root)
                if #entry.owned_roots>1 or (root<0x10000 and #entry.owned_roots>0) then
                    identity=identity .. ":owned=" .. table.concat(entry.owned_roots,",")
                end
                result.active[#result.active+1]=identity
            end
            for _,root in ipairs(entry.owned_roots) do
                local cached = tree_cache[root] or (a11y.native_tree_cache and a11y.native_tree_cache[root])
                if not cached or (enabled and frame - cached.frame >= 6) then
                    local members,parents,evidence=a11y.menu_tree(root, base)
                    cached = {frame=frame, members=members, parents=parents,evidence=evidence}
                end
                tree_cache[root] = cached
                if root==entry.root then entry.tree_evidence=cached.evidence end
                for address in pairs(cached.members) do
                    -- Shared elements are eligible if ANY owner still accepts
                    -- input. Unknown branches never acquire invented ownership.
                    local member = result.members[address] or {active=false,owners={}}
                    member.owners = member.owners or {}
                    member.owners[#member.owners+1]={address=entry.address,root=root,enabled=enabled,
                        parents=cached.parents}
                    member.active = member.active or enabled
                    result.members[address] = member
                end
                if enabled and root==entry.root then
                    local selected, detail = a11y.menu_cursor_texts(root, base)
                    entry.cursor_detail = detail
                    if selected then
                        -- The window's typed cursor and its indexed child path
                        -- prove ownership even if the broad tree hit its limit.
                        for address in pairs(selected) do
                            result.selected_members[address]=true
                            result.cursor_members[address]=true
                            local member=result.members[address] or {active=false,owners={}}
                            member.active=true
                            member.owners=member.owners or {}
                            member.owners[#member.owners+1]={address=entry.address,root=root,
                                enabled=true,parents=detail.parents}
                            result.members[address]=member
                        end
                        for address in pairs(cached.members) do result.cursor_members[address]=true end
                    end
                end
            end
          end
        end
    end
    a11y.bind_presented_window_contexts(result,base)
    a11y.bind_controlled_player_captions(result,base)
    result.command_bar=a11y.read_native_command_bar(base)
    if result.command_bar then
        local bar=result.command_bar
        local cached=a11y.native_tree_cache and a11y.native_tree_cache[bar.root]
        if not cached or frame-cached.frame>=6 then
            local texts,parents=a11y.menu_tree(bar.root,base)
            cached={frame=frame,members=texts,parents=parents}
        end
        tree_cache[bar.root]=cached
        for address in pairs(cached.members) do
            local member=result.members[address] or {active=false,owners={}}
            member.active=true
            member.owners[#member.owners+1]={address=bar.address,root=bar.root,enabled=true,
                parents=cached.parents,command_bar=true}
            result.members[address]=member
        end
        result.signature[#result.signature+1]="guide:" .. tostring(bar.address) .. ":" .. tostring(bar.root)
    end
    result.signature = table.concat(result.signature, "|")
    result.active_identity = table.concat(result.active, "|")
    result.active_text_count = 0
    for _, member in pairs(result.members) do
        if member.active then result.active_text_count = result.active_text_count + 1 end
    end
    a11y.native_tree_cache = tree_cache
    local owner_parts={}
    for _,window in ipairs(result.windows) do
        if window.enabled and (window.primary or #window.owned_roots>0) then owner_parts[#owner_parts+1]=tostring(window.address) .. ":" .. tostring(window.root or 0) end
    end
    table.sort(owner_parts)
    result.owner_token=table.concat(owner_parts,",")
    return result
end

function a11y.read_native_windows(base)
    local previous=a11y.snapshot_read_work
    a11y.snapshot_tree_work={}
    a11y.snapshot_read_work=previous or a11y.render_read_work or {}
    local result=a11y.read_native_windows_snapshot(base)
    a11y.snapshot_tree_work=nil
    a11y.snapshot_read_work=previous
    return result
end

function a11y.poll_native_windows()
    if not a11y.native_windows_enabled or a11y.native_windows_frame == frame then return end
    a11y.native_windows_frame = frame
    local snapshot = a11y.read_native_windows(tonumber(process_base_u64))
    local previous = a11y.native_windows
    a11y.native_windows = snapshot
    if not snapshot then return end
    if a11y.player_detail_review and not a11y.focused_player_node() then a11y.player_detail_review=nil end
    a11y.prune_roster_limits(snapshot)
    if snapshot.keyboard ~= a11y.keyboard_window then
        a11y.keyboard_window, a11y.keyboard_text, a11y.keyboard_caret = snapshot.keyboard, nil, nil
        if not snapshot.keyboard then a11y.keyboard_input_address = nil end
        if snapshot.keyboard then speak(a11y.ui_language == "pt" and "Teclado aberto." or "Keyboard opened.") end
    end
    if not previous or previous.signature ~= snapshot.signature then
        local lines = {"[FLAccess] native-windows frame=" .. tostring(frame)
            .. " active-texts=" .. tostring(snapshot.active_text_count)}
        for _, window in ipairs(snapshot.windows) do
            lines[#lines + 1] = string.format("slot=%d window=%s root=%s slot-priority=%d input=%s window-type=%s root-type=%s cursor=%s",
                window.slot, memory.hex(window.address), memory.hex(window.root),
                window.priority, tostring(window.enabled),memory.hex(window.vtable or 0),
                memory.hex(a11y.menu_read(window.root,"u64") or 0),
                memory.hex(a11y.menu_read(window.root+0x190,"u64") or 0))
        end
        log(table.concat(lines, " "))
    end
    local selected = {}
    for address in pairs(snapshot.selected_members) do selected[#selected+1] = memory.hex(address) end
    table.sort(selected)
    local identity = table.concat(selected, ",")
    if identity ~= a11y.native_cursor_identity then
        a11y.native_cursor_identity = identity
        a11y.native_cursor_log_count = (a11y.native_cursor_log_count or 0) + 1
        if a11y.native_cursor_log_count <= 300 then
            log("[FLAccess] native-cursor frame=" .. tostring(frame) .. " text-widgets=" .. identity)
        end
    end
    -- Trace indices and each failed link, including cursors with zero labels.
    -- Bounded change-only output; no selection or caption is invented.
    local details = {}
    for _, window in ipairs(snapshot.windows) do
        local d = window.enabled and window.cursor_detail
        if d then
            details[#details+1] = string.format("window=%s delegate=%s type=%s parent=%s group-index=%s item-index=%s group=%s selected=%s selected-type=%s status=%s",
                memory.hex(window.address),memory.hex(d.cursor or 0),memory.hex(d.cursor_type or 0),
                memory.hex(d.parent or 0),tostring(d.group_index),tostring(d.item_index),
                memory.hex(d.group or 0),memory.hex(d.selected or 0),memory.hex(d.selected_type or 0),d.status)
        end
    end
    local detail_identity = table.concat(details," | ")
    if detail_identity ~= a11y.native_cursor_detail_identity then
        a11y.native_cursor_detail_identity = detail_identity
        a11y.native_cursor_detail_count = (a11y.native_cursor_detail_count or 0)+1
        if a11y.native_cursor_detail_count <= 500 then
            log("[FLAccess] native-selection frame=" .. tostring(frame) .. " " .. detail_identity)
            for _, window in ipairs(snapshot.windows) do
                local d=window.enabled and window.cursor_detail
                if d and d.status=="no-text" then
                    log("[FLAccess] native-selection-gap frame=" .. tostring(frame)
                        .. " selected={" .. a11y.native_node_summary(d.selected)
                        .. "} group={" .. a11y.native_node_summary(d.group) .. "}")
                    local evidence=window.tree_evidence
                    if evidence then
                        local parts={}
                        for _,item in ipairs(evidence.frontier) do
                            parts[#parts+1]=memory.hex(item.address) .. "/" .. memory.hex(item.rva)
                        end
                        log("[FLAccess] native-tree-gap root=" .. memory.hex(window.root)
                            .. " visited=" .. tostring(evidence.visited) .. " queued=" .. tostring(evidence.queued)
                            .. " at-capacity=" .. tostring(evidence.at_capacity)
                            .. " frontier=" .. table.concat(parts,","))
                    end
                end
            end
        end
    end
    if previous and previous.active_identity ~= snapshot.active_identity then
        a11y.engine_focus=nil
        a11y.companion_candidate,a11y.companion_spoken=nil,nil
        if a11y.pending_message_owner and a11y.pending_message_owner~=a11y.native_owner_token() then
            pending_message_text,pending_message_key,pending_message_due_ms=nil,nil,nil
            a11y.pending_message_widget_key,a11y.pending_message_owner=nil,nil
            a11y.modal_message_backlog={}
        end
        last_screen_title_key,last_announced_message_key=nil,nil
        a11y.last_page_announcement=nil;a11y.last_page_delivery=nil
        a11y.answer_chain=nil
        if not (a11y.read_context and a11y.read_context.message_key) then
            a11y.reset_read_context("native-presentation-changed")
        end
        modal_focus_hold_until_ms=0
        a11y.screen_title_hold_until_ms=0
        a11y.title_pending_first_item=nil
        a11y.deferred_modal_announcement,a11y.pending_modal_button_text=nil,nil
        a11y.clear_pending_tooltips()
        -- A real change of input ownership releases deduplication. Keep new
        -- text observations: construction can precede manager registration.
        a11y.reset_focus_reuse_state()
        -- Preserve recorded edges. Clearing them promotes every retained
        -- cursorOver=1 from the previous window to a brand-new selection.
        last_selected_ui_entry = nil
        a11y.control_focus_owner = nil
    end
    local context = a11y.read_context
    if context and context.message_key and ((context.native_owner
            and context.native_owner ~= a11y.native_owner_token())
            or not a11y.native_key_allowed(context.message_key)) then
        a11y.reset_read_context("native-window-closed")
        modal_focus_hold_until_ms = 0
        a11y.deferred_modal_announcement = nil
        a11y.modal_message_backlog = {}
        a11y.pending_modal_button_text = nil
    end
end

function a11y.native_widget_allowed(address)
    if a11y.native_windows_enabled then
        local active = a11y.menu_node_active(tonumber(address), tonumber(process_base_u64))
        if active == false then return false end
    end
    local snapshot = a11y.native_windows
    local member = snapshot and snapshot.members[tonumber(address)]
    if member then return member.active end
    return true
end

function a11y.native_text_presented(address)
    if a11y.native_widget_allowed(address) then return true end
    local member=address and a11y.native_windows and a11y.native_windows.members[tonumber(address)]
    return member and member.presented==true
        and a11y.menu_node_active(tonumber(address),tonumber(process_base_u64))==true
end

function a11y.menu_node_active(address, base)
    if not address or not base then return nil end
    local vtable = a11y.menu_read(address, "u64")
    if not vtable then return nil end
    if vtable ~= base + 0x27b5260 and vtable ~= base + 0x27c3a38 then return false end
    local flags = a11y.menu_read(address + 0xc, "u32")
    if flags == nil then return nil end
    -- Same predicate as Node::state getter at 0xe4bb70; unlike cursorOver,
    -- this includes the current propagated state of the node.
    return flags % 8 == 7 and math.floor(flags / 256) % 2 == 1
end

function a11y.native_key_allowed(key)
    local node = key and a11y.ui_model and a11y.ui_model.nodes[key]
    return not node or a11y.native_widget_allowed(node.address)
end

function a11y.native_presentation_ready(address)
    if address and not a11y.native_text_presented(address) then return false end
    if not a11y.native_windows_enabled then return true end
    local member=address and a11y.native_windows and a11y.native_windows.members[tonumber(address)]
    if member and member.presented and not member.active then return true end
    if member and member.owners and #member.owners>0 then
        for _,owner in ipairs(member.owners) do
            if owner.enabled and owner.root and owner.root>=0x10000 then return true end
        end
        return false
    end
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        if window.enabled and window.root and window.root>=0x10000 then return true end
    end
    return false
end

-- A native owner/tree, not string loading, establishes these review entries.
-- Sorting uses observation sequence; no inferred visual coordinates/categories.
function a11y.observe_control_font(data,offset,total)
    if total>4194304 or offset<0 then return end
    if offset==0 then
        a11y.control_font_scan={a=1,b=0,next=0,total=total}
        a11y.control_font_family=nil
    end
    local scan=a11y.control_font_scan
    if not scan or scan.next~=offset or scan.total~=total then return end
    local a,b=scan.a,scan.b
    for index=1,#data do a=(a+data:byte(index))%65521;b=(b+a)%65521 end
    scan.a,scan.b,scan.next=a,b,offset+#data
    if scan.next==total then
        -- Signatures of the local font assets inspected as actual glyph bitmaps.
        local known={
            ["55036:38782804"]="playstation",["760560:3728391537"]="playstation",
            ["47727:2475288431"]="xbox",["757104:3636751182"]="xbox",
            ["108565:763610868"]="xbox",["3021552:1135989911"]="xbox",
        }
        a11y.control_font_family=known[tostring(total)..":"..tostring(b*65536+a)]
        log("[FLAccess] control-font=" .. tostring(a11y.control_font_family or "unrecognized"))
        a11y.control_font_scan=nil
    end
end

-- Renderer parser e2b050 dispatches j/k to these exact callbacks. Read their
-- current mapping and symbol pointer; never call game code or infer letters.
function a11y.native_control_marker(kind,letter)
    local base=tonumber(process_base_u64)
    local index=letter:byte()-0x61
    local category=kind=="j" and 0 or kind=="k" and 1
    if not base or not category or index<0 or index>=(category==0 and 15 or 9) then return nil end
    if a11y.menu_read(base+0x36f9590+category*8,"u64")
            ~=base+(category==0 and 0xe264b0 or 0xe26960) then return nil end
    local mapped=a11y.menu_read(base+(category==0 and 0x27ae3b8 or 0x27ae3f8)+index*4,"u32")
    if not mapped or mapped>33 then return nil end
    local at=base+0x34c0660+mapped*0x10
    local pointer=a11y.menu_read(at+8,"u64")
    if pointer==0 and (mapped==32 or mapped==33) then
        mapped=a11y.menu_read(base+0x34c08c0+(mapped-32)*4,"u32")
        if not mapped or mapped>31 then return nil end
        at=base+0x34c0660+mapped*0x10
        pointer=a11y.menu_read(at+8,"u64")
    end
    if not pointer or pointer<0x10000 then return nil end
    local symbol=a11y.read_native_c_string(pointer,128)
    if not symbol or symbol=="" or symbol:find("\17",1,true) then return nil end
    return symbol
end

function a11y.control_symbol_text(text)
    local family=a11y.control_font_family
    if not (text:find("\17",1,true) or text:find("\238\128",1,true)) then return text end
    local captions=family=="playstation"
        and {[0]="Círculo",[1]="Cruz",[2]="Triângulo",[3]="Quadrado",[4]="R1",[5]="R2",[6]="L1",[7]="L2",[8]="Options",[9]="Share",[14]="R3",[15]="L3"}
        or {[0]="B",[1]="A",[2]="Y",[3]="X",[4]="RB",[5]="RT",[6]="LB",[7]="LT",[8]="Menu",[9]="Exibir",[14]="RS",[15]="LS"}
    local function caption(index)
        if not family then return nil end
        local value=captions[index]
        if not value then return nil end
        if a11y.ui_language~="pt" then
            if value=="Círculo" then value="Circle" elseif value=="Cruz" then value="Cross"
            elseif value=="Triângulo" then value="Triangle" elseif value=="Quadrado" then value="Square"
            elseif value=="Exibir" then value="View" end
        end
        return (a11y.ui_language=="pt" and "botão " or "button ") .. value
    end
    -- Markup follows the current renderer binding, including remapped confirm
    -- and cancel. Literal digits still are not physical button indices.
    text=text:gsub("\17([jk])([a-o])",function(kind,letter)
        local symbol=a11y.native_control_marker(kind,letter)
        if symbol then
            if symbol:find("\238\128",1,true) then return symbol end
            if symbol:match("^[%w%s%-_]+$") then
                return (a11y.ui_language=="pt" and "tecla " or "key ") .. symbol
            end
        end
        if kind=="k" and letter=="a" and family then return caption(1) end
        return "\17" .. kind .. letter
    end)
    return text:gsub("\238\128[\128-\143]",function(glyph)
        return caption(glyph:byte(3)-128) or glyph
    end)
end

function a11y.output_speech_text(text)
    for _,role in ipairs({"seletor","selector","campo de texto","text field",
            "ativar para editar","activate to edit","controle deslizante","slider"}) do
        text=text:gsub(", " .. role .. ",",","):gsub(", " .. role .. "$","")
    end
    for _,suffix in ipairs({"item selecionado","botão selecionado","opção selecionada",
            "selecionado","selecionada","item","selected item","selected button",
            "selected option","selected","button selected"}) do text=text:gsub(", " .. suffix .. "$","") end
    return text
end

function a11y.unresolved_format(text)
    return text and text:find("%%[%d%$%.%-%+]*[sdifucxX]")~=nil
end

function a11y.read_native_c_string(address,limit)
    address=tonumber(address)
    if not address then return nil end
    if not address or address<0x10000 then return nil end
    local parts={}
    for offset=0,(limit or 2048)-1,64 do
        local size=math.min(64,(limit or 2048)-offset)
        while size>0 and not readable(address+offset,size) do size=math.floor(size/2) end
        if size==0 then return nil end
        local bytes=a11y.safe_memory_read(address+offset,size)
        if not bytes or #bytes~=size then return nil end
        local zero=bytes:find("\0",1,true)
        parts[#parts+1]=zero and bytes:sub(1,zero-1) or bytes
        if zero then return table.concat(parts) end
        if size<64 then return nil end
    end
end

function a11y.read_native_rendered_text(address)
    address=tonumber(address)
    if not address then return nil end
    local work=a11y.render_read_work
    local previous=work and work.rendered and work.rendered[address]
    if previous then return previous[1],previous[2],previous[3] end
    local base=tonumber(process_base_u64)
    if not base or a11y.menu_read(address,"u64")~=base+0x27b5260 then return nil end
    local renderer=a11y.menu_read(address+0xa8,"u64")
    local vtable=renderer and a11y.menu_read(renderer,"u64")
    -- e29e40 copies a C string into renderer+38. Both known renderer
    -- vtables use this setter; validate its slot before reading the field.
    local setter=vtable and a11y.menu_read(vtable+0x10,"u64")
    -- Factory e2edf0 builds a proxy whose e2fa60 setter calls e29e40 on
    -- the SAME object, retaining the same text at +38. Read both contracts.
    if setter~=base+0xe29e40 and setter~=base+0xe2fa60 then return nil end
    local raw=a11y.read_native_c_string(a11y.menu_read(renderer+0x38,"u64"),2048)
    if raw==nil then return nil end
    local text,font=clean_text(raw),a11y.menu_read(renderer+8,"u32")
    if work then work.rendered=work.rendered or {};work.rendered[address]={text,raw,font} end
    return text,raw,font
end

function a11y.poll_native_texts(review)
    local snapshot=a11y.native_windows
    if not a11y.native_windows_enabled or not snapshot or not snapshot.members then return end
    local selected,others={},{}
    for address,member in pairs(snapshot.members) do
        if member.active or member.presented then
            others[#others+1]=address
            if snapshot.selected_members and snapshot.selected_members[address] then selected[#selected+1]=address end
        end
    end
    table.sort(selected);table.sort(others)
    local work,seen={},{}
    for index,address in ipairs(selected) do
        if not review and index>24 then break end
        work[#work+1],seen[address]=address,true
    end
    -- A proven field's value can live inside a delegate outside the cursor's
    -- indexed label subtree. Refresh it together with its selected label.
    for index,address in ipairs(selected) do
        if not review and index>24 then break end
        local key=memory.hex(address)
        local row=a11y.control_for_widget(key)
        local value=row and tonumber(row.value_widget)
        if value and not seen[value] and snapshot.members[value] and snapshot.members[value].active then
            work[#work+1],seen[value]=value,true
        end
    end
    local cursor=a11y.native_text_scan_cursor or 0
    for index=1,(review and #others or math.min(24,#others)) do
        local address=others[(cursor+index-1)%#others+1]
        if not seen[address] then work[#work+1]=address;seen[address]=true end
    end
    a11y.native_text_scan_cursor=#others>0 and (cursor+24)%#others or 0
    for _,address in ipairs(work) do
        if a11y.native_presentation_ready(address) then
            local text,raw,font=a11y.read_native_rendered_text(address)
            local key=memory.hex(address)
            local node=a11y.ui_model and a11y.ui_model.nodes[key]
            if text~=nil and (not node or node.text~=text or not a11y.ui_node_matches_live(node)) then
                a11y.on_observed_ui_text(address,text,raw,nil,review)
                node=a11y.ui_model and a11y.ui_model.nodes[key]
            end
            if node and raw then node.raw_text,node.native_font=raw,font end
        end
    end
end

function a11y.presented_nodes()
    local result={}
    local snapshot=a11y.native_windows
    for _,node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        local member=snapshot and snapshot.members and snapshot.members[tonumber(node.address)]
        if member and (member.active or member.presented) and node.text and node.text~="" and not a11y.unresolved_format(node.text)
                and a11y.native_presentation_ready(node.address)
                and a11y.ui_node_matches_live(node) then result[#result+1]=node end
    end
    table.sort(result,function(a,b)
        if (a.sequence or 0)~=(b.sequence or 0) then return (a.sequence or 0)<(b.sequence or 0) end
        return a.key<b.key
    end)
    return result
end

function a11y.present_companion_heading(nodes)
    local context=a11y.read_context_state()
    if context.kind=="dialog" or a11y.reading_panel_is_current() or a11y.keyboard_window then return end
    local snapshot=a11y.native_windows
    local base=tonumber(process_base_u64)
    local found
    for _,window in ipairs(snapshot and snapshot.windows or {}) do
        local detail=window.cursor_detail
        if window.enabled and detail and detail.status=="no-text" and base
                and detail.selected_type==base+0x27cb508 then
            local label,ambiguous
            for _,node in ipairs(nodes) do
                local row=control_rows_by_label_widget[node.key]
                if node.name=="text_item" and (not row or not row.value or row.value=="") then
                    local member=snapshot.members[tonumber(node.address)]
                    for _,owner in ipairs(member and member.owners or {}) do
                        if owner.enabled and owner.address==window.address then
                            if label and label~=node then ambiguous=true end
                            label=node;break
                        end
                    end
                end
            end
            if label and not ambiguous then
                if found and found~=label then return end
                found=label
            end
        end
    end
    if not found then a11y.companion_candidate=nil;return end
    local identity=(a11y.native_owner_token() or "") .. ":" .. found.identity .. ":" .. found.text
    if a11y.companion_candidate~=identity then
        a11y.companion_candidate,a11y.companion_candidate_frame=identity,frame
    elseif frame-(a11y.companion_candidate_frame or frame)>=3 and a11y.companion_spoken~=identity then
        a11y.companion_spoken=identity
        a11y.present_bound_heading(found.address,found.text)
    end
end

function a11y.poll_static_presentations(nodes)
    local snapshot=a11y.native_windows
    if not snapshot or a11y.keyboard_window or a11y.read_context_state().kind=="dialog" then return end
    for _ in pairs(snapshot.selected_members or {}) do return end
    local owner=a11y.native_owner_token()
    if a11y.static_presentation_owner~=owner then
        a11y.static_presentation_owner,a11y.static_presentation_seen=owner,{}
    end
    local seen=a11y.static_presentation_seen or {}
    a11y.static_presentation_seen=seen
    for _,node in ipairs(nodes) do
        local stem=node.name and node.name:match("^(.-)_value$")
        if stem and node.text:find("%a") and not a11y.empty_selection_caption(node.text) then
            local member=snapshot.members[tonumber(node.address)]
            local readonly=false
            for _,entry in ipairs(member and member.owners or {}) do
                for _,window in ipairs(snapshot.windows or {}) do
                    local d=window.cursor_detail
                    if entry.enabled and window.enabled and entry.address==window.address
                            and (not d or d.status=="no-cursor") then readonly=true end
                end
            end
            local label=a11y.scoped_ui_name(stem .. "_item",node.address)
            local identity=node.identity .. ":" .. node.text
            if readonly and not label and not seen[identity] then
                local before=a11y.native_speech_last
                speak(node.text,false,nil,"presentation:" .. identity,node.address)
                if a11y.native_speech_last>before then
                    seen[identity]=true
                    for index=before+1,a11y.native_speech_last do
                        a11y.native_speech_queue[index].static_presentation={address=node.address,text=node.text}
                    end
                end
            end
        end
    end
end

function a11y.poll_presented_texts()
    if a11y.keyboard_window then return end
    local owner=a11y.native_owner_token()
    if a11y.presentation_seen_owner==owner and a11y.presentation_seen
            and frame-(a11y.presentation_frame or -10000)<6 then return end
    a11y.presentation_frame=frame
    local old=a11y.presentation_seen_owner==owner and a11y.presentation_seen or {}
    local seen,titles,messages={}, {}, {}
    local nodes=a11y.presented_nodes()
    for _,node in ipairs(nodes) do
        a11y.rebind_presented_control(node)
        a11y.capture_reading_panel(node)
        local identity=tostring(node.identity or node.key) .. ":" .. node.text
        seen[node.key]=identity
        if old[node.key]~=identity then
            a11y.announce_skip_hint(node.text,node)
            if is_screen_title(node.text,node.address) then titles[#titles+1]=node
            elseif node.name=="question" or node.name=="eventMsg"
                    or a11y.text_asset_role(node.text)=="dialog" then messages[#messages+1]=node end
        end
    end
    a11y.presentation_seen,a11y.presentation_seen_owner=seen,owner
    if #titles==0 and #messages==0 then
        a11y.present_companion_heading(nodes)
        a11y.poll_static_presentations(nodes)
    end
    -- Never choose by table iteration when several independent prompts arrive.
    if #titles==1 then
        local node=titles[1]
        local role=a11y.text_asset_role(node.text)
        local member=a11y.native_windows and a11y.native_windows.members[tonumber(node.address)]
        if (not role or role=="label-or-name") and member and member.active
                and (node.name=="title" or node.name=="text_title")
                and a11y.read_context_state().kind~="dialog" then
            -- A single presented native heading needs no catalogue entry.
            -- Present it without resetting the scene or its working controls.
            a11y.present_bound_heading(node.address,node.text)
        else announce_screen_title(node.text,node.key,node.address) end
    end
    if #messages==1 then
        local node=messages[1]
        if not a11y.capture_question_panel(node) then
            remember_message_text(node.text,node.key)
            queue_recent_message()
        end
    end
end

function a11y.native_owner_token()
    local snapshot = a11y.native_windows
    if not snapshot or not snapshot.windows then return nil end
    if snapshot.owner_token then return snapshot.owner_token end
    local owners = {}
    for _, window in ipairs(snapshot.windows) do
        if window.enabled and (window.primary or window.root==nil or window.root>=0x10000 or (window.owned_roots and #window.owned_roots>0)) then
            owners[#owners+1]=tostring(window.address) .. ":" .. tostring(window.root or 0)
        end
    end
    table.sort(owners)
    return table.concat(owners,",")
end

function a11y.capture_speech_origin(address)
    if not address then return nil end
    local origin = {address=tonumber(address),owner=a11y.native_owner_token()}
    local node = a11y.ui_model and a11y.ui_model.nodes[memory.hex(address)]
    if node then origin.identity,origin.text=node.identity,node.text end
    if a11y.native_windows_enabled then origin.native_type=a11y.menu_read(origin.address,"u64") end
    return origin
end

function a11y.speech_origin_allowed(origin)
    if not origin then return true end
    if origin.owner and a11y.native_owner_token() ~= origin.owner then return false end
    if origin.native_type and a11y.menu_read(origin.address,"u64") ~= origin.native_type then return false end
    if origin.identity then
        local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(origin.address)]
        if not node or node.identity ~= origin.identity or node.text ~= origin.text then return false end
    end
    return a11y.native_presentation_ready(origin.address)
end

function a11y.apply_menu_flow(data, name)
    local metadata = data:match('"data"%s*:%s*{(.-)}')
    if not metadata or metadata:match('"type"%s*:%s*"(.-)"') ~= "menu" then return false end
    local home = metadata:match('"mark"%s*:%s*"(.-)"') == "home"
    if a11y.menu_flow_name ~= name or a11y.dashboard_review ~= home then
        a11y.menu_flow_name = name
        a11y.dashboard_review, a11y.dashboard_texts = home, {}
        log("[FLAccess] menu-flow=" .. tostring(name) .. " review=" .. tostring(home))
    end
    return true
end

function m.data_ready(ctx, filename, data, size, total_size, offset)
    local path = filename:gsub("\\", "/")
    local capture=a11y.component_capture
    if capture and capture.active and offset==0
            and (path:lower():find("common/menu/",1,true)
                or path:lower():find("common/script/flow/",1,true)) then
        local line=string.format("RESOURCE frame=%d name=%q size=%s total=%s\n",frame,path,tostring(size),tostring(total_size))
        if capture.bytes+#line<=33554432 then
            local file=io.open(capture.path,"at")
            if file then file:write(line);file:close();capture.bytes=capture.bytes+#line end
        end
    end
    if path:match("common/menu/font/ext_fnt%.bin$") and size<=4194304 and readable(data,size) then
        a11y.observe_control_font(memory.read(data,size),offset,total_size)
    end
    if path:find("common/script/flow/",1,true) and path:match("%.json$")
            and offset == 0 and size == total_size and size <= 65536
            and readable(data, size) then
        a11y.apply_menu_flow(memory.read(data, size), path)
    end
end

function a11y.record_dashboard_text(node)
    if not a11y.dashboard_review or not node or not node.text or node.text == ""
            or node.name == "padIcon" or node.name == "title"
            or node.name == "question" or node.name == "eventMsg"
            or is_noninteractive_text(node.text) or node.text:find("%%") then return end
    a11y.dashboard_texts = a11y.dashboard_texts or {}
    for _, item in ipairs(a11y.dashboard_texts) do
        if item.address == node.address then
            item.text,item.identity,item.owner=node.text,node.identity,a11y.native_owner_token()
            return
        end
    end
    if #a11y.dashboard_texts < 70 then
        a11y.dashboard_texts[#a11y.dashboard_texts+1] = {address=node.address,text=node.text,
            identity=node.identity,owner=a11y.native_owner_token()}
    end
end

function a11y.utf8_characters(text)
    local result={}
    for value in (text or ""):gmatch("[%z\1-\127\194-\244][\128-\191]*") do result[#result+1]=value end
    return result
end

function a11y.read_keyboard_text(node)
    if not a11y.keyboard_window or not node
            or (node.keyboard_owner~=a11y.keyboard_window and not a11y.native_widget_allowed(node.address))
            or (node.name~="textWord" and node.name~="inputText" and node.name~="textInput")
            or node.text==a11y.keyboard_text then return false end
    local old=a11y.keyboard_text
    a11y.keyboard_text=node.text
    if old==nil then return true end
    local before,after=a11y.utf8_characters(old),a11y.utf8_characters(node.text)
    local prefix,suffix=0,0
    while prefix<#before and prefix<#after and before[prefix+1]==after[prefix+1] do prefix=prefix+1 end
    while suffix<#before-prefix and suffix<#after-prefix
            and before[#before-suffix]==after[#after-suffix] do suffix=suffix+1 end
    local removed,inserted={},{}
    for index=prefix+1,#before-suffix do removed[#removed+1]=before[index] end
    for index=prefix+1,#after-suffix do inserted[#inserted+1]=after[index] end
    local spoken=table.concat(removed)
    if #inserted>0 and a11y.keyboard_echo_insertions then
        spoken=spoken .. (#spoken>0 and ". " or "") .. table.concat(inserted)
    end
    if spoken~="" then
        a11y.keyboard_edit_sequence=(a11y.keyboard_edit_sequence or 0)+1
        speak(spoken,true,true,"edit:" .. tostring(a11y.keyboard_edit_sequence))
    end
    return true
end

function a11y.read_native_keyboard_state()
    local window=a11y.keyboard_window
    local base=tonumber(process_base_u64)
    if not window or not base or a11y.menu_read(window,"u64")~=base+0x27c3eb0 then return nil end
    -- KeyboardPopup owns its editing state at +110. d42b90 copies the full
    -- MSVC string at state+8; e7b330 uses state+0 as the UTF-8 cursor index.
    -- The input node at popup+90 can belong to the disabled window underneath.
    local text=a11y.read_msvc_string(window+0x118)
    if text==nil then return nil end
    local caret=a11y.menu_read(window+0x110,"u32")
    local characters=a11y.utf8_characters(text)
    if not caret or caret>#characters then caret=nil end
    return {address=window,keyboard_owner=window,name="inputText",text=text,caret=caret,
        input=a11y.menu_read(window+0x90,"u64")}
end


function m.on_keyboard_input_set(ctx, event_id, registers)
    -- Observe the native input node, not the coach field behind the popup.
    -- The hook runs before the setter: read its stored string on render frames.
    local address = tonumber(read_u64(registers.rcx))
    if not address or a11y.menu_read(address,"u64") ~= tonumber(process_base_u64)+0x27c3a38 then return end
    if address ~= a11y.keyboard_input_address then
        log("[FLAccess] native-input address=" .. memory.hex(address) .. " source=NodeRectTextInput string-offset=0x118 cursor=unverified")
    end
    a11y.keyboard_input_address = address
end

function a11y.poll_keyboard_input()
    if not a11y.keyboard_window then return end
    local native=a11y.read_native_keyboard_state()
    if native then
        local previous=a11y.keyboard_text
        a11y.read_keyboard_text(native)
        if previous==native.text and native.caret~=nil and a11y.keyboard_caret~=nil
                and native.caret~=a11y.keyboard_caret then
            local characters=a11y.utf8_characters(native.text)
            speak(characters[native.caret+1] or (a11y.ui_language=="pt" and "Fim do texto." or "End of text."),
                true,true,"caret:" .. tostring(a11y.keyboard_window) .. ":" .. tostring(native.caret))
        end
        a11y.keyboard_caret=native.caret
        return
    end
    -- A recognized popup with unavailable state must wait; another input
    -- widget elsewhere cannot stand in for its edit buffer.
    if a11y.menu_read(a11y.keyboard_window,"u64")==tonumber(process_base_u64)+0x27c3eb0 then return end
    -- Compatibility fallback for a verified input without the popup layout.
    if not a11y.keyboard_input_address then return end
    local address=a11y.keyboard_input_address
    if a11y.menu_read(address,"u64")~=tonumber(process_base_u64)+0x27c3a38 then return end
    local text=a11y.read_msvc_string(address+0x118)
    if text~=nil then a11y.read_keyboard_text({address=address,name="inputText",text=text}) end
end

function a11y.main_menu_choice_current(state)
    local node=state and a11y.ui_model and a11y.ui_model.nodes[state.key]
    if not node or node.identity~=state.node_identity or node.text~=state.text
            or not a11y.ui_node_matches_live(node) then return false end
    local rendered=a11y.read_native_rendered_text(state.address)
    return rendered==nil or rendered==state.text
end

function a11y.main_menu_choice_active(state)
    if state~=a11y.main_menu_choice_state or not a11y.main_menu_choice_current(state)
            or a11y.read_context_state().kind=="dialog" or not a11y.native_presentation_ready(state.address) then return false end
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[state.address]
    if #state.scopes==0 then return state.observed_owner==a11y.native_owner_token() end
    for _,old in ipairs(state.scopes) do
        for _,owner in ipairs(member and member.owners or {}) do
            if owner.enabled and owner.address==old.address and owner.root==old.root then return true end
        end
    end
    return false
end

function a11y.queue_main_menu_choice(state)
    if not a11y.main_menu_choice_active(state) then state.status="suspended";return end
    if state.status=="delivered" or state.status=="queued" then return end
    a11y.title_pending_first_item=nil
    a11y.set_read_title(state.text)
    local before=a11y.native_speech_last
    state.attempt=(state.attempt or 0)+1
    speak(state.text,true,nil,"main-menu-choice:" .. state.key .. ":" .. state.text
        .. ":attempt=" .. state.attempt,state.address)
    if a11y.native_speech_last>before then
        state.status="queued"
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].menu_choice=state
            a11y.native_speech_queue[index].menu_choice_attempt=state.attempt
        end
    end
end

function a11y.present_main_menu_choice(widget,text)
    local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(widget)]
    if not node then return end
    local state=a11y.main_menu_choice_state
    if not state or state.key~=node.key or state.node_identity~=node.identity or state.text~=text then
        local member=a11y.native_windows and a11y.native_windows.members and a11y.native_windows.members[tonumber(widget)]
        state={key=node.key,address=tonumber(widget),node_identity=node.identity,text=text,status="pending",
            scopes={},observed_owner=a11y.native_owner_token()}
        for _,owner in ipairs(member and member.owners or {}) do state.scopes[#state.scopes+1]={address=owner.address,root=owner.root} end
        a11y.main_menu_choice_state=state
    end
    a11y.queue_main_menu_choice(state)
end

function a11y.poll_main_menu_choice()
    a11y.poll_main_menu_caption()
    local state=a11y.main_menu_choice_state
    if not state then return end
    if not a11y.main_menu_choice_current(state) then a11y.main_menu_choice_state=nil;return end
    if #state.scopes==0 then
        local member=a11y.native_windows and a11y.native_windows.members and a11y.native_windows.members[state.address]
        for _,owner in ipairs(member and member.owners or {}) do
            if owner.enabled and owner.root and owner.root>=0x10000 then
                state.scopes[#state.scopes+1]={address=owner.address,root=owner.root}
            end
        end
        if #state.scopes>0 then state.observed_owner=a11y.native_owner_token();state.status="pending" end
    end
    if not a11y.main_menu_choice_active(state) then state.status="suspended";return end
    if state.status=="suspended" then state.status="pending" end
    if state.status=="queued" then
        local queued=false
        for index=a11y.native_speech_first,a11y.native_speech_last do
            local entry=a11y.native_speech_queue[index]
            if entry and entry.menu_choice==state and a11y.speech_entry_allowed(entry) then queued=true end
        end
        if not queued then state.status="pending" end
    end
    a11y.queue_main_menu_choice(state)
end

-- Main menu presents every choice through the same text_item/text_value pair.
-- Some modded labels bypass localization; poll these exact bound nodes instead
-- of running a separate first-item publisher or scanning every observed text.
function a11y.main_menu_text_owner(node)
    if not node or (node.name~="text_item" and node.name~="text_value") then return nil end
    local base=tonumber(process_base_u64)
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        if base and window.enabled and a11y.menu_read(window.address,"u64")==base+0x266ddd8
                and a11y.record_contains(node,window,window.root) then return window end
    end
end

function a11y.poll_main_menu_caption()
    local names=a11y.ui_model and a11y.ui_model.names or {}
    local caption,owner
    for _,node in pairs(names.text_item or {}) do
        local window=a11y.main_menu_text_owner(node)
        if window and a11y.ui_node_matches_live(node) and a11y.native_presentation_ready(node.address)
                and a11y.read_native_rendered_text(node.address)==node.text and not a11y.empty_selection_caption(node.text) then
            if caption then return end
            caption,owner=node,window
        end
    end
    if not caption then return end
    main_menu_title_widget_key=caption.key
    a11y.present_main_menu_choice(caption.address,caption.text)
    local state=a11y.main_menu_choice_state
    local description
    for _,node in pairs(names.text_value or {}) do
        if a11y.record_contains(node,owner,owner.root) and a11y.native_presentation_ready(node.address)
                and a11y.ui_node_matches_live(node) and a11y.read_native_rendered_text(node.address)==node.text then
            if description then return end
            description=node.text
        end
    end
    if state and description and description~="" and state.description~=description and a11y.read_tooltips then
        state.description=description
        main_menu_tooltip,main_menu_tooltip_due_ms=description,tonumber(ffi.C.GetTickCount64())
        a11y.main_menu_tooltip_choice=state
    end
end

function a11y.loading_context()
    local base=tonumber(process_base_u64)
    local at=base and a11y.menu_read(base+0x36f9a68,"u64")
    if at and at>=0x10000 and a11y.menu_read(at,"u64")==base+0x27b55b8
            and a11y.menu_read(base+0x27b55b8+8,"u64")==base+0xe4a630 then return at end
end

function a11y.poll_loading(now)
    local at=a11y.loading_context()
    if not at then a11y.loading_notice=nil;return end
    local state=a11y.loading_notice
    if not state or state.address~=at then state={address=at,started=now};a11y.loading_notice=state end
    if not state.announced and now-state.started>=3000 then
        local before=a11y.native_speech_last
        speak(a11y.ui_language=="pt" and "Carregando tela" or "Loading screen",true,true,"loading:" .. at .. ":" .. state.started)
        for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].loading_state=state end
        if a11y.native_speech_last>before then state.announced=true end
    end
end

function a11y.main_navigation_signature(include_types)
    local parts={}
    for index,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        if index>16 then break end
        local detail=window.cursor_detail
        parts[#parts+1]=table.concat({tostring(window.address),tostring(window.root or 0),
            tostring(window.enabled),tostring(include_types and a11y.menu_read(window.address,"u64") or "not-sampled"),
            tostring(detail and detail.group_index),tostring(detail and detail.item_index),
            tostring(detail and detail.selected)},":")
    end
    return table.concat(parts,"|")
end

function a11y.poll_main_navigation_probe()
    local state=a11y.main_menu_choice_state
    if not state and not a11y.dashboard_review then a11y.main_navigation_probe,a11y.main_navigation_last=nil,nil;return end
    local probe=a11y.main_navigation_probe
    local count=a11y.main_navigation_log_count or 0
    if count>=64 then a11y.main_navigation_probe=nil;return end
    -- Idle frames reuse snapshot fields only. Native type reads are limited to
    -- the two observations following an input edge, within the log budget.
    local signature=a11y.main_navigation_signature(probe~=nil)
    if probe and count<64 then
        local phase=probe.observed and "next-render" or "input-observation"
        log(string.format("[FLAccess] main-navigation frame=%d input=%q source=%q phase=%s title=%q speech=%s overlay=%s before=%q current=%q",
            frame,probe.action,probe.source,phase,state and state.text or "main-flow",tostring(state and state.status or "unbound-title"),
            tostring(overlay_visible or sider_overlay_visible),probe.before or "unknown",signature))
        a11y.main_navigation_log_count=count+1
        if probe.observed then a11y.main_navigation_probe=nil else probe.observed=true end
    end
    a11y.main_navigation_last=signature
end

function a11y.present_bound_heading(widget,text)
    local language=a11y.native_language_context()
    if language and a11y.native_language_heading(widget)==language.label then
        a11y.poll_native_language();return
    end
    if not a11y.native_presentation_ready(widget) then a11y.defer_bound_guidance(widget,text,"heading");return end
    text=a11y.native_language_heading(widget) or text
    a11y.set_read_title(text)
    speak(text,not a11y.read_context_state().native_reading_panel,nil,nil,widget)
    a11y.title_pending_first_item=text
    a11y.title_pending_first_item_until_ms=tonumber(ffi.C.GetTickCount64())+2000
end

function a11y.defer_bound_guidance(widget,text,kind)
    if a11y.native_presentation_ready(widget) or a11y.is_control_help(text) then return end
    local title=is_screen_title(text,widget)
    local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(widget)]
    local panel=node and (node.name=="question" or node.name=="eventMsg")
    if not kind and not title and not panel and not looks_like_message(text,widget) then return end
    a11y.pending_surface_texts=a11y.pending_surface_texts or {}
    local origin=a11y.capture_speech_origin(widget)
    if origin.owner=="" or not a11y.native_presentation_ready() then origin.owner=nil end
    local member=a11y.native_windows and a11y.native_windows.members
        and a11y.native_windows.members[tonumber(widget)]
    if member and not member.active and member.owners and #member.owners>0 then
        -- A proven future owner can bind on activation. Unknown ownership
        -- must not turn an old pending caption into a new-window title.
        origin.target_windows={}
        for _,owner in ipairs(member.owners) do origin.target_windows[owner.address]=true end
        origin.owner=nil
    end
    a11y.pending_surface_texts[memory.hex(widget)]={text=text,frame=frame,
        address=tonumber(widget),kind=kind or (panel and "panel" or title and "title" or "message"),
        origin=origin}
end

function a11y.poll_surface_texts()
    for key, item in pairs(a11y.pending_surface_texts or {}) do
        local node = a11y.ui_model and a11y.ui_model.nodes[key]
        local bound=true
        if item.origin and item.origin.target_windows then
            bound=false
            local member=node and a11y.native_windows and a11y.native_windows.members
                and a11y.native_windows.members[tonumber(node.address)]
            for _,owner in ipairs(member and member.owners or {}) do
                if owner.enabled and item.origin.target_windows[owner.address] then bound=true end
            end
        end
        if not node or node.text ~= item.text or frame-item.frame > 600
                or not a11y.ui_node_matches_live(node)
                or (item.origin and item.origin.owner
                    and item.origin.owner ~= a11y.native_owner_token()) then
            a11y.pending_surface_texts[key]=nil
        elseif bound and a11y.native_presentation_ready(node.address) then
            a11y.pending_surface_texts[key]=nil
            if item.kind=="menu-choice" then a11y.present_main_menu_choice(node.address,node.text)
            elseif item.kind == "heading" then a11y.present_bound_heading(node.address,node.text)
            elseif item.kind == "panel" then a11y.capture_question_panel(node)
            elseif item.kind == "message" then remember_message_text(node.text,key); queue_recent_message()
            else announce_screen_title(node.text,key,node.address) end
        end
    end
end

function a11y.ui_owner_link(widget)
    if not readable(widget + 0x38, 8) then return nil end
    local bytes = a11y.safe_memory_read(widget+0x38,8)
    if not bytes or #bytes ~= 8 then return nil end
    local pointer = tonumber(read_u64(bytes))
    if pointer and pointer >= 0x10000 and pointer <= 0x7fffffffffff then return pointer end
end

-- nil means no structural evidence; false means known different components.
function a11y.component_peers(left,right)
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[tonumber(left)]
    local known=false
    for _,owner in ipairs(member and member.owners or {}) do
        if owner.enabled and owner.parents then
            local lp,rp=owner.parents[tonumber(left)],owner.parents[tonumber(right)]
            if lp and rp then
                known=true
                if lp==rp and lp~=owner.root then return true end
            end
        end
    end
    if known then return false end
end

function a11y.scoped_ui_name(name,address)
    local found,known
    for _,node in pairs(a11y.ui_model and a11y.ui_model.names[name] or {}) do
        local peer=a11y.component_peers(address,node.address)
        if peer~=nil then known=true end
        if peer and a11y.native_widget_allowed(node.address) and a11y.ui_node_matches_live(node) then
            if found then return nil end
            found=node
        end
    end
    if found then return found end
    if known then return nil end
    return a11y.unique_ui_name(name)
end

function a11y.command_icon_owners()
    local owners = {}
    for _, node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        if node.name == "padIcon" and node.owner_link then owners[node.owner_link] = true end
    end
    return owners
end

function a11y.is_command_legend(key, primary_focused, owners)
    local node = a11y.ui_model and a11y.ui_model.nodes[key]
    if not node then return false end
    if node.name == "padIcon" then return true end
    -- This observed layout family puts command captions and padIcon children
    -- under the same link. A caption with real primary focus remains eligible.
    return not primary_focused and node.name == "text" and node.owner_link ~= nil
        and owners[node.owner_link] == true
        and a11y.text_asset_role(node.text) == "dialog-button"
end

function a11y.ui_focus_identity(key, text)
    local node = a11y.ui_model and a11y.ui_model.nodes[key]
    -- Text is also needed for virtualized items whose data replaces a widget.
    return (node and node.identity or key) .. ":" .. text
end

local function ui_focus_speech(text)
    if is_plain_text(text) or is_splash_text(text)
            or looks_like_message(text) then
        return text
    end
    if language_options[text] then
        return text .. ", opção selecionada"
    end
    if text == "Em casa" or text == "Fora" or text == "Neutro" then
        return text .. ", opção selecionada"
    end
    if text == "Concordo." or text == "I agree." then
        return text:sub(1, -2) .. ", botão selecionado"
    end
    if text == "Sim" or text == "Não"
            or a11y.game_plan_basic_prompt_items[text] then
        return text .. ", botão selecionado"
    end
    local parenthesized_formation = text:match("%((.-)%)")
    local effective_formation = parenthesized_formation
        and parenthesized_formation:gsub("%s+", "") or nil
    if effective_formation and not effective_formation:match("^%d[%d%-]+$") then
        effective_formation = nil
    end
    if effective_formation then
        local default_suffix = (text:find("Padrão", 1, true)
                or text:find("Default", 1, true))
            and (a11y.ui_language == "pt" and ", padrão" or ", default")
            or ""
        if a11y.ui_language == "pt" then
            return effective_formation .. default_suffix
        end
        return effective_formation .. default_suffix
    elseif text:match("^%d[%d%-]+$") then
        if a11y.ui_language == "pt" then
            return text
        end
        return text
    end
    return text .. ", item selecionado"
end

function a11y.engine_focus_speech(text,node)
    local spoken=ui_focus_speech(text)
    if node and node.name and node.name:lower():find("playername",1,true) then
        spoken=a11y.output_speech_text(spoken)
        for _,detail in ipairs(a11y.player_row_details(node)) do
            spoken=spoken .. ", " .. detail.text
        end
        local section=a11y.player_component_section(node)
        local prefixes=a11y.ui_language=="pt"
            and {starter="Titular. ",reserve="Reserva. ",unselected="Não relacionado. "}
            or {starter="Starter. ",reserve="Substitute. ",unselected="Not selected. "}
        if section then spoken=(prefixes[section] or "") .. spoken end
    end
    return spoken
end

-- The indexed player row can dispatch focus to its name, rating and optional
-- caption together (real dev 21 packet 902). Only direct native siblings
-- compose a row; equal text/resource names elsewhere grant no relationship.
function a11y.player_row_details(node)
    local result={}
    if not node or node.name~="playerName" or a11y.empty_selection_caption(node.text) then return result end
    local unique=0
    local names=a11y.ui_model and a11y.ui_model.names or {}
    for _,other in pairs(names.playerName or {}) do
        if other.name=="playerName" and a11y.component_peers(node.address,other.address)
                and a11y.native_presentation_ready(other.address) and not a11y.empty_selection_caption(other.text) then unique=unique+1 end
    end
    if unique~=1 then return result end
    for _,name in ipairs({"allOver","noSetting"}) do
        local found
        for _,other in pairs(names[name] or {}) do
            if other.name==name and a11y.component_peers(node.address,other.address)
                    and a11y.native_presentation_ready(other.address) and a11y.ui_node_matches_live(other)
                    and not a11y.empty_selection_caption(other.text) and not a11y.unresolved_format(other.text) then
                if found then found=false;break end
                found=other
            end
        end
        if found and found.text~=node.text then result[#result+1]=found end
    end
    return result
end

a11y.cup_group_non_team_items = {
    ["OK"] = true,
    ["Confirmar"] = true,
    ["Voltar"] = true,
    ["Substituir"] = true,
    ["Atualizar"] = true,
    ["Aleatório"] = true,
    ["Cancelar"] = true,
    ["botão A"] = true,
}

function a11y.cup_group_team_speech(text, widget_key)
    if not a11y.cup_group_table_active
            or a11y.cup_group_non_team_items[text]
            or text:match("^Grupo [A-H]$")
            or text:match("^Group [A-H]$") then
        return nil
    end

    local cell = a11y.cup_group_cell_by_widget[widget_key]
    if not cell then
        local current = a11y.cup_group_current_cell
        local action = a11y.navigation_action
        local recent_navigation = frame - a11y.navigation_frame <= 20
            and a11y.navigation_frame ~=
                a11y.cup_group_last_navigation_frame
        if current then
            cell = {group=current.group, row=current.row}
            if recent_navigation then
                if action == "left" and cell.group % 4 ~= 1 then
                    cell.group = cell.group - 1
                elseif action == "right" and cell.group % 4 ~= 0 then
                    cell.group = cell.group + 1
                elseif action == "up" then
                    if cell.row > 1 then
                        cell.row = cell.row - 1
                    elseif cell.group > 4 then
                        cell.group = cell.group - 4
                        cell.row = 4
                    end
                elseif action == "down" then
                    if cell.row < 4 then
                        cell.row = cell.row + 1
                    elseif cell.group <= 4 then
                        cell.group = cell.group + 4
                        cell.row = 1
                    end
                end
            end
        else
            -- Group assignment opens on the first team in Group A.
            cell = {group=1, row=1}
        end
        a11y.cup_group_cell_by_widget[widget_key] = cell
    end

    if frame - a11y.navigation_frame <= 20 then
        a11y.cup_group_last_navigation_frame = a11y.navigation_frame
    end
    a11y.cup_group_current_cell = cell
    local prefix = ""
    if cell.group ~= a11y.cup_group_last_announced then
        a11y.cup_group_last_announced = cell.group
        local letter = string.char(string.byte("A") + cell.group - 1)
        prefix = (a11y.ui_language == "pt" and "Grupo " or "Group ")
            .. letter .. ". "
    end
    return prefix .. ui_focus_speech(text)
end

function a11y.ignore_cup_group_focus(text)
    -- The group-assignment grid exposes an extra OK focus cell after its
    -- final team. It is not a team and adds no useful navigation information.
    return a11y.cup_group_table_active and text == "OK"
end

-- Classify a list entry from headings in its own native component. Localized
-- words identify the section, while the tree proves the relationship. A label
-- elsewhere in the same resource file or a player's position proves nothing.
function a11y.player_component_section(node)
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[tonumber(node.address)]
    if not member or not member.active then return nil end
    local native,_,typed=a11y.native_roster_section(node,member)
    if typed then return native end
    local panel=a11y.native_player_roster_context(node)
    if panel then return panel.section end
    local headings={Titulares="starter",Reservas="reserve",["Não relacionados"]="unselected",
        ["Não relacionado"]="unselected",Starters="starter",Substitutes="reserve",
        ["Starting lineup"]="starter",["Not selected"]="unselected",["Not in squad"]="unselected"}
    local result,conflicting
    for _,owner in ipairs(member.owners or {}) do
        if owner.enabled and owner.parents then
            local parents=owner.parents
            local ancestor=parents[tonumber(node.address)]
            local visited={}
            for _=1,8 do
                if not ancestor or ancestor==owner.root or visited[ancestor] then break end
                visited[ancestor]=true
                local section,ambiguous
                for _,heading in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
                    local value=headings[heading.text]
                    local at=tonumber(heading.address)
                    local known=snapshot.members[at]
                    if value and at~=tonumber(node.address) and known and known.active
                            and a11y.native_widget_allowed(at) and a11y.ui_node_matches_live(heading) then
                        local walked={}
                        for _=1,8 do
                            at=parents[at]
                            if not at or walked[at] then break end
                            walked[at]=true
                            if at==ancestor then
                                if section and section~=value then ambiguous=true end
                                section=value;break
                            end
                        end
                    end
                end
                if ambiguous then break end
                if section then
                    if result and result~=section then conflicting=true end
                    result=section;break
                end
                ancestor=parents[ancestor]
            end
        end
    end
    if conflicting then return nil end
    if not result then a11y.component_evidence(node,"player-section-unresolved") end
    return result
end

-- The information panel is a separate sibling Window, not a descendant of
-- the pitch card. Resolve its validated player id through the same model as
-- PitchBase::getPlayer (914280), never through position or discovery order.
function a11y.focused_player_node()
    local context=a11y.read_context_state()
    if context.kind=="dialog" or context.question or a11y.keyboard_window then return nil end
    local snapshot=a11y.native_windows
    local found
    for address in pairs(snapshot and snapshot.controlled_selections or {}) do
        local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(address)]
        if node and a11y.native_caption_selection_identity(address) then
            if found and found~=node then return nil end
            found=node
        end
    end
    return found
end

-- Mirror the record used by 910490: playerInfo_0/1 selects one native
-- (slot, side) descriptor; the squad order resolves its actual player object.
-- This path does not require the old attribute-copy callbacks or name cache.
function a11y.current_player_record(node)
    local base=tonumber(process_base_u64)
    local snapshot=a11y.native_windows
    local binding=node and snapshot and snapshot.controlled_selections and snapshot.controlled_selections[tonumber(node.address)]
    if not base or not binding or not a11y.native_caption_selection_identity(node.address) then return nil end
    local data=a11y.menu_read(base+0x36f38a0,"u64")
    if not data or a11y.menu_read(data,"u64")~=base+0x2618830 then return nil end
    local member=snapshot.members[tonumber(node.address)]
    local variant
    for _,owner in ipairs(member and member.owners or {}) do
        if owner.address==binding.panel and owner.enabled and owner.parents then
            local current=a11y.parameter_caption_variant(node,owner,base)
            if current~=nil then
                if variant~=nil and variant~=current then return nil end
                variant=current
            end
        end
    end
    if variant==nil then return nil end
    local descriptor=data+0xba4+binding.side*0xa8+variant*20
    local slot,side=a11y.menu_read(descriptor,"u32"),a11y.menu_read(descriptor+4,"u32")
    if not slot or slot>=40 or (side~=0 and side~=1) then return nil end
    local record=a11y.menu_read(data+side*0x248+0x1f8+slot,"u8")
    if not record or record>=40 then return nil end
    local object=a11y.menu_read(data+side*0x340+0x568+record*16,"u64")
    if not object or object<0x10000 then return nil end
    local id=a11y.menu_read(object+0x30,"u32")
    local name=a11y.read_native_c_string(object+0x38,64)
    local heading=a11y.normalized_player_name(node.text)
    if not id or id==0 or not name or #name<2 or name:find("%c")
            or not heading or heading:sub(1,#name)~=name then return nil end
    local primary=a11y.menu_read(object+4,"u32")
    primary=primary and math.floor(primary/0x10000000)
    if primary and primary>12 then primary=nil end
    local secondary={}
    local first,last=a11y.menu_read(object+0x1c,"u32"),a11y.menu_read(object+0x20,"u32")
    if first and last then
        for position=0,12 do
            local value=position<3 and math.floor(first/2^(25+position*2))%4
                or math.floor(last/2^((position-3)*2))%4
            if value>2 then secondary=nil;break end
            if value>0 and position~=primary then secondary[#secondary+1]={position=position,level=value} end
        end
    else secondary=nil end
    local field_position
    if slot<11 then
        local tactic=a11y.menu_read(data+side*0xa8+0xb34,"u32")
        if tactic and tactic<3 then
            local phase=0
            local enabled=a11y.menu_read(data+side*0x248+tactic*0xa0+0xb4,"u8")
            if enabled and enabled~=0 then phase=a11y.menu_read(data+side*0xa8+0xb38,"u32") end
            if enabled and phase and phase<3 then
                field_position=a11y.menu_read(data+side*0x248+0x18+tactic*0xa0+phase*0x21+slot,"u8")
                if field_position and field_position>12 then field_position=nil end
            end
        end
    end
    return {data=data,object=object,player_id=id,slot=slot,side=side,record=record,descriptor_offset=descriptor-data,
        primary=primary,secondary=secondary,field_position=field_position,
        identity=table.concat({binding.identity,variant,slot,side,record,object,id},":")}
end

-- 911650 renders playStyle through 8e1f40/14c0300, property 3b.
-- Its code translation and localization-ID table are independent of position.
function a11y.load_player_style_schema()
    local base=tonumber(process_base_u64)
    if not base or base==0 then return end
    local ids={}
    for index=0,21 do
        local value=a11y.menu_read(base+0x27d3500+index*8,"u32")
        if value and value>0 then ids[value]=true end
    end
    a11y.player_style_ids=ids
end

function a11y.load_player_style_assets()
    a11y.player_style_asset_texts={pt={},en={}}
    if not a11y.use_text_assets or not a11y.sider_dir or not a11y.player_style_ids then return end
    for _,language in ipairs({"pt","en"}) do
        local path=a11y.sider_dir .. "\\livecpk\\FlAccessReader\\text\\styles-" .. language .. ".tsv"
        local file=io.open(path,"rt")
        if file then
            local labels,invalid,count={},false,0
            for line in file:lines() do
                if line:sub(1,1)~="#" then
                    local id,text=line:match("^(%d+)\t([^\t]+)$")
                    id=tonumber(id)
                    if not id or not a11y.player_style_ids[id] or not text or #text>120 or count>=64
                            or (labels[id] and labels[id]~=text) then invalid=true;break end
                    labels[id]=text;count=count+1
                end
            end
            file:close()
            if not invalid then a11y.player_style_asset_texts[language]=labels end
            log("[FLAccess] style-assets language=" .. language .. " labels=" .. tostring(invalid and 0 or count))
        end
    end
end

function a11y.remember_player_style_text(id,text)
    if a11y.player_style_ids and a11y.player_style_ids[id] then
        a11y.player_style_texts=a11y.player_style_texts or {}
        a11y.player_style_texts[a11y.ui_language]=a11y.player_style_texts[a11y.ui_language] or {}
        a11y.player_style_texts[a11y.ui_language][id]=text
    end
end

function a11y.player_style_text(record)
    local base=tonumber(process_base_u64)
    local packed=record and a11y.menu_read(record.object+0x1c,"u32")
    local index=packed and math.floor(packed/2^11)%32
    if not base or not index or index>=22 then return nil end
    local code=a11y.menu_read(base+0x2979080+index*4,"u32")
    if not code or code>=22 then return nil end
    if code==0 then return a11y.ui_language=="pt" and "Sem estilo de jogo" or "No playing style" end
    local id=a11y.menu_read(base+0x27d3500+code*8,"u32")
    local texts=a11y.player_style_texts and a11y.player_style_texts[a11y.ui_language]
    local assets=a11y.player_style_asset_texts and a11y.player_style_asset_texts[a11y.ui_language]
    return (texts and texts[id]) or (assets and assets[id])
end

function a11y.player_detail_packet()
    local node=a11y.focused_player_node()
    if not node then return nil end
    local record=a11y.current_player_record(node)
    local pt=a11y.ui_language=="pt"
    local names=a11y.player_position_names[a11y.ui_language] or a11y.player_position_names.en
    local fields={{key="name",text=node.text}}
    local style=a11y.player_style_text(record)
    fields[#fields+1]={key="style",text=style and
        ((pt and "Estilo de jogo: " or "Playing style: ") .. style)
        or (pt and "Estilo de jogo indisponível." or "Playing style unavailable.")}
    if a11y.player_secondary_verified and record and record.secondary then
        local parts={}
        for _,position in ipairs(record.secondary) do
            if position.level==2 or a11y.player_secondary_partial then
                parts[#parts+1]=names[position.position] .. (position.level==1
                    and (pt and " (adaptação parcial)" or " (partial familiarity)")
                    or (pt and " (adaptação completa)" or " (full familiarity)"))
            end
        end
        if #parts>0 then fields[#fields+1]={key="secondary",text=(pt and "Posições secundárias: " or "Secondary positions: ") .. table.concat(parts,", ")} end
    end
    local field=record and record.slot>=11 and (pt and "Não está no campo." or "Not on the pitch.")
        or record and record.field_position and ((pt and "Posição no campo: " or "Position on the pitch: ") .. names[record.field_position])
        or (pt and "Posição no campo indisponível." or "Position on the pitch unavailable.")
    fields[#fields+1]={key="field",text=field}
    return {node=node,record=record,fields=fields,generation=a11y.read_context_state().generation,
        identity=node.identity .. ":" .. node.text .. ":" .. (a11y.native_caption_selection_identity(node.address) or "")
            .. ":" .. (record and record.identity or "unknown")}
end

function a11y.player_details_allowed(origin)
    local packet=a11y.player_detail_packet()
    if not packet or packet.identity~=origin.identity or packet.generation~=origin.generation then return false end
    for _,field in ipairs(packet.fields) do
        if field.key==origin.key then return field.text==origin.text end
    end
    return false
end

function a11y.read_player_details(action)
    local packet=a11y.player_detail_packet()
    if not packet then a11y.player_detail_review=nil;return false end
    local state=a11y.player_detail_review
    if not state or state.identity~=packet.identity or state.generation~=packet.generation then
        state={identity=packet.identity,generation=packet.generation,index=0};a11y.player_detail_review=state
    end
    local count=#packet.fields
    if action=="first" then state.index=1
    elseif action=="next" then state.index=state.index%count+1
    elseif action=="previous" then state.index=state.index==0 and count or (state.index-2)%count+1
    elseif state.index==0 or state.index>count then state.index=1 end
    local field=packet.fields[state.index]
    state.sequence=(state.sequence or 0)+1
    local before=a11y.native_speech_last
    modal_focus_hold_until_ms=0;a11y.title_pending_first_item=nil;a11y.deferred_modal_announcement=nil
    speak(field.text,true,true,"player-review:" .. packet.identity .. ":" .. state.sequence,packet.node.address)
    local origin={identity=packet.identity,generation=packet.generation,key=field.key,text=field.text}
    for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].player_details=origin end
    return true
end

-- Read the same rule as 8e9210/15098a0 without calling game code. Competition
-- database lookups not resolved here remain unknown; FFFF selects the current
-- match configuration's native +33 getter (14c0d50).
function a11y.live_roster_limit(data)
    local base=tonumber(process_base_u64)
    if not base or not data then return nil end
    local mode=a11y.menu_read(data+8,"u32")
    if mode==4 then return 23 end
    if mode==nil or mode==0 or mode==1 or mode==3 or mode==8 then return nil end
    local flow=a11y.menu_read(base+0x3704e38,"u64")
    local index=flow and a11y.menu_read(flow+0xf0,"u32")
    if not index or index>=61 then return nil end
    local category=a11y.menu_read(base+0x34fc9c0+index*16,"u32")
    local manager=a11y.menu_read(base+0x3705e10,"u64")
    local config=manager and a11y.menu_read(manager+0x50,"u64")
    if not category or not config or config<0x10000 then return nil end
    local rule
    if category>=7 and category<=10 then
        return nil
    elseif index<=39 and math.floor(0xd7c0000000/2^index)%2==1 then
        rule=a11y.menu_read(config+0x35968,"u16")
    else rule=0xffff end
    if rule~=0xffff then return nil end
    local limit=a11y.menu_read(config+0x35993,"u8")
    if limit and limit>=11 and limit<=40 then return limit end
end

function a11y.native_player_roster_context(node)
    if not node or node.name~="playerName" then return nil end
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[tonumber(node.address)]
    local base=tonumber(process_base_u64)
    if not base or not member or not member.active or not a11y.native_presentation_ready(node.address)
            or not a11y.ui_node_matches_live(node) or a11y.read_native_rendered_text(node.address)~=node.text then return nil end
    local target=a11y.normalized_player_name(node.text)
    local live=a11y.current_player_record(node)
    local player=live and {player_id=live.player_id}
    for name,entry in pairs(not live and a11y.game_plan_player_cache or {}) do
        if target and (target==name or target:sub(1,#name)==name) and entry.player_id and entry.player_id>0 then
            if player and player.player_id~=entry.player_id then return nil end
            player=entry
        end
    end
    if not player then return nil end
    local data=a11y.menu_read(base+0x36f38a0,"u64") -- 8e1af0's singleton
    if not data or a11y.menu_read(data,"u64")~=base+0x2618830 then return nil end
    local windows={}
    for _,window in ipairs(snapshot.windows or {}) do windows[window.address]=window end
    local result
    for _,owned in ipairs(member.owners or {}) do
        local panel=windows[owned.address]
        if owned.enabled and panel and panel.enabled and panel.task_parent
                and a11y.menu_read(panel.address,"u64")==base+0x261e0c8 then
            local side=a11y.menu_read(panel.address+0x98,"u32")
            if side==0 or side==1 then
                for _,window in ipairs(snapshot.windows) do
                    local vt=window.enabled and a11y.menu_read(window.address,"u64")
                    local pitch=vt==base+0x261eaa0
                    local subs=vt==base+0x261f788
                    if (pitch or subs) and window.task_parent==panel.task_parent
                            and a11y.menu_read(window.address+0x98,"u32")==side then
                        local root,impl=a11y.roster_presentation_root(window.address)
                        local flags=root and a11y.menu_read(root+0xc,"u32")
                        local scroll=pitch and 0 or a11y.menu_read(window.address+0x4e8,"u32")
                        if flags and flags%8==7 and scroll and scroll<=29 then
                            for index=0,(pitch and 10 or 11) do
                                local slot=pitch and index or index+scroll+11
                                local record=a11y.menu_read(window.address+0x2a0+index*4,"u32")
                                local order=slot<40 and a11y.menu_read(data+side*0x248+0x1f8+slot,"u8")
                                local card=a11y.menu_read(window.address+0xb8+index*8,"u64")
                                local shown=card and card>=0x10000 and a11y.menu_read(card+0xc,"u32")
                                if record and record<40 and order==record and shown and shown%8==7 then
                                    local object=a11y.menu_read(data+side*0x340+0x568+record*16,"u64")
                                    local id=object and object>=0x10000 and a11y.menu_read(object+0x30,"u32")
                                    if id==player.player_id then
                                        local section,limit="starter",nil
                                        if subs then
                                            local bound=a11y.roster_limits and a11y.roster_limits[window.address]
                                            limit=a11y.live_roster_limit(data)
                                            if limit then section=slot<limit and "reserve" or "unselected"
                                            elseif bound and bound.root==root and bound.impl==impl and bound.side==side
                                                    and bound.limit>=11 and bound.limit<=40 then
                                                limit=bound.limit;section=slot<limit and "reserve" or "unselected"
                                            else section=nil end
                                        end
                                        local identity=table.concat({panel.address,window.address,root,side,slot,record,object,id,limit or -1},":")
                                        if result and result.identity~=identity then return nil end
                                        result={section=section,identity=identity,window=window.address,slot=slot,player_id=id,
                                            side=side,record=record,root=root,limit=limit}
                                    end
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    return result
end

-- A pitch/card array proves the displayed slot. Player position and names
-- cannot classify it. Substitute slot indices include the native scroll offset;
-- the match-rule boundary is recorded from the game's actual return value.
function a11y.roster_presentation_root(address)
    local base=tonumber(process_base_u64)
    local impl=a11y.menu_read(address+0x88,"u64")
    if not base or not impl or impl<0x10000 then return nil end
    -- Pitch/PitchSubstitute have no navigation root in the real dev 21
    -- capture. e3d790 uses Impl+90, including in the boundary renderer.
    local root=a11y.menu_read(impl+0x90,"u64")
    local vt=root and root>=0x10000 and a11y.menu_read(root,"u64")
    if vt and a11y.native_layout.holders[vt-base] then return root,impl end
    root=a11y.menu_read(impl+0x98,"u64")
    return root and root>=0x10000 and root or nil,impl
end

function a11y.native_roster_section(node,member)
    local base=tonumber(process_base_u64)
    if not base then return nil end
    local result,identity,matched
    for _,owner in ipairs(member.owners or {}) do
        local vt=owner.enabled and a11y.menu_read(owner.address,"u64")
        local pitch=vt==base+0x261eaa0
        local substitutes=vt==base+0x261f788
        if (pitch or substitutes) and owner.parents then
            local ancestors,at={},tonumber(node.address)
            for _=1,12 do
                if not at or ancestors[at] then break end
                ancestors[at]=true
                if at==owner.root then break end
                at=owner.parents[at]
            end
            local found,ambiguous
            for index=0,(pitch and 10 or 11) do
                for _,offset in ipairs({0xb8,0x118}) do
                    local card=a11y.menu_read(owner.address+offset+index*8,"u64")
                    if card and ancestors[card] then
                        if found and found~=index then ambiguous=true end
                        found=index
                    end
                end
            end
            if ambiguous then return nil,nil,true end
            if found and not ambiguous then
                local value,slot,limit= nil,found,nil
                matched=true
                local root,impl=a11y.roster_presentation_root(owner.address)
                if not root then return nil,nil,true end
                if pitch then value="starter" else
                    local scroll=a11y.menu_read(owner.address+0x4e8,"u32")
                    local bound=a11y.roster_limits and a11y.roster_limits[owner.address]
                    if scroll and scroll<=29 and found+scroll+11<40 and bound
                            and bound.impl==impl and bound.root==root
                            and bound.side==a11y.menu_read(owner.address+0x98,"u32")
                            and bound.limit>=11 and bound.limit<=40 then
                        value=found+scroll+11<bound.limit and "reserve" or "unselected"
                        slot,limit=found+scroll+11,bound.limit
                    end
                end
                local current=tostring(owner.address) .. ":" .. tostring(root or owner.root) .. ":" .. tostring(slot)
                    .. ":" .. tostring(limit) .. ":" .. tostring(value)
                    .. ":" .. tostring(a11y.menu_read(owner.address+0x98,"u32"))
                if identity and identity~=current then return nil,nil,true end
                identity=current
                if value and result and result~=value then return nil,nil,true end
                result=value or result
            end
        end
    end
    return result,identity,matched
end

function m.on_roster_rule_boundary(ctx,event_id,registers)
    local address=tonumber(read_u64(registers.rdi))
    local limit=tonumber(read_u64(registers.rbx))
    local base=tonumber(process_base_u64)
    if not base or not address or not limit or a11y.menu_read(address,"u64")~=base+0x261f788 then return end
    limit=limit%256
    local root,impl=a11y.roster_presentation_root(address)
    if not root or root<0x10000 then return end
    local side=a11y.menu_read(address+0x98,"u32")
    if side~=0 and side~=1 then return end
    a11y.roster_limits=a11y.roster_limits or {}
    a11y.roster_limits[address]={impl=impl,root=root,limit=limit,
        side=side,frame=frame}
    a11y.component_capture_dirty_frame=frame
end

function a11y.prune_roster_limits(snapshot)
    local registered={}
    for _,window in ipairs(snapshot.windows or {}) do registered[window.address]=window end
    for address,bound in pairs(a11y.roster_limits or {}) do
        local window=registered[address]
        -- Construction can record the rule just before manager registration.
        -- Keep that short handoff, not a cache belonging to a closed component.
        if frame-(bound.frame or -10000)>2 then
            local flags=a11y.menu_read(bound.root+0xc,"u32")
            local root,impl=a11y.roster_presentation_root(address)
            if not window or window.impl~=bound.impl or impl~=bound.impl or root~=bound.root
                    or not flags or math.floor(flags/4)%2~=1 then a11y.roster_limits[address]=nil end
        end
    end
end

function a11y.game_plan_player_section(text, heading_widget_key)
    local target=a11y.normalized_player_name(text)
    if not target then return nil end
    local heading=heading_widget_key and a11y.ui_model and a11y.ui_model.nodes[heading_widget_key]
    local panel=heading and heading.text==text and a11y.native_player_roster_context(heading)
    if panel then return panel.section end
    local section,conflicting
    for key,node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        if key~=heading_widget_key and a11y.normalized_player_name(node.text)==target
                and a11y.native_widget_allowed(node.address) and a11y.ui_node_matches_live(node) then
            local value=a11y.player_component_section(node)
            if value and section and section~=value then conflicting=true end
            if value then section=value end
        end
    end
    if conflicting then return nil end
    return section
end

function a11y.game_plan_lineup_screen_visible()
    if not a11y.game_plan_active then return false end
    local context = a11y.game_plan_context
    return context == "Escalação/Editar posição"
        or context == "Team Sheet/Edit Position"
        or context == "Plano de jogo normal"
        or context == "Normal Game Plan"
end

function a11y.read_visible_game_plan_lineup()
    if not a11y.game_plan_lineup_screen_visible() then return false end
    local generation_frame = a11y.game_plan_lineup_generation_frame
    local players = {}
    local observed_starters = 0
    for _, observed in pairs(a11y.game_plan_observed_lineup) do
        local node=a11y.ui_model and a11y.ui_model.nodes[observed.widget]
        if observed.section == "starter" and node
                and a11y.game_plan_player_section(node.text,nil)=="starter" then
            observed_starters = observed_starters + 1
        end
    end
    if observed_starters == 11 then
        for name, observed in pairs(a11y.game_plan_observed_lineup) do
            local node=a11y.ui_model and a11y.ui_model.nodes[observed.widget]
            local current=node and a11y.game_plan_player_section(node.text,nil)
            if current then players[name] = {
                name = name,
                section = current,
                number = observed.number or 999,
                widget = observed.widget,
            } end
        end
    else
        for widget_key, entry in pairs(ui_focus_widgets) do
            local name = a11y.normalized_player_name(entry.text)
            if name and entry.address and not players[name] then
                local section = a11y.game_plan_player_section(entry.text, nil)
                if section then
                    players[name] = {
                        name = name,
                        section = section,
                        number = tonumber(entry.text:match("^%s*(%d+)%s+")) or 999,
                        widget = widget_key,
                    }
                end
            end
        end
    end
    local starters, reserves, unselected = {}, {}, {}
    for _, player in pairs(players) do
        local target = player.section == "starter" and starters
            or player.section == "reserve" and reserves or unselected
        target[#target + 1] = player
    end
    local function order(left, right)
        if left.number ~= right.number then return left.number < right.number end
        return left.name < right.name
    end
    table.sort(starters, order)
    table.sort(reserves, order)
    table.sort(unselected, order)
    log(string.format(
        "[FLAccess] lineup-read generation=%d starters=%d reserves=%d",
        generation_frame, #starters, #reserves))
    -- A football starting eleven must contain exactly eleven authoritative
    -- pitch containers. Never turn an incomplete/ambiguous scan into speech.
    if #starters ~= 11 then
        speak(a11y.ui_language == "pt"
            and "A escalação ainda não foi identificada com segurança."
            or "The lineup has not been identified safely yet.")
        return false
    end
    local function names(items)
        local result = {}
        for _, item in ipairs(items) do result[#result + 1] = item.name end
        return table.concat(result, ", ")
    end
    local spoken
    if a11y.ui_language == "pt" then
        spoken = "Escalação. Titulares: " .. names(starters)
            .. ". Reservas: " .. names(reserves)
            .. (#unselected>0 and ". Não relacionados: " .. names(unselected) or "")
    else
        spoken = "Lineup. Starters: " .. names(starters)
            .. ". Reserves: " .. names(reserves)
            .. (#unselected>0 and ". Not selected: " .. names(unselected) or "")
    end
    speak(spoken)
    local now_ms = tonumber(ffi.C.GetTickCount64())
    a11y.game_plan_attribute_hold_until_ms = now_ms
        + math.min(12000, math.max(3500, #spoken * 55 + 500))
    return true
end

function a11y.game_plan_focus_speech(text, widget_key)
    local context = a11y.game_plan_context
    local node=widget_key and a11y.ui_model and a11y.ui_model.nodes[widget_key]
    local roster=node and a11y.native_player_roster_context(node)
    local roster_identity=roster and roster.identity
    if a11y.game_plan_basic_prompt_items[text]
            and not a11y.game_plan_basic_prompt_active then
        return nil
    end
    if a11y.game_plan_active
            and text == a11y.game_plan_last_focus_text
            and context == a11y.game_plan_announced_context
            and roster_identity==a11y.game_plan_last_roster_identity then
        return nil
    end
    local tactical_label, tactical_value =
        text:match("^(.+)%s+:%s+(.+)$")
    local announcement
    if tactical_label and tactical_value
            and a11y.game_plan_tactical_labels[tactical_label] then
        announcement = tactical_label .. (a11y.ui_language == "pt"
            and ", seletor, " or ", selector, ") .. tactical_value
    else
        announcement = ui_focus_speech(text)
    end
    local player = a11y.player_for_text(text)
    local player_focus = (player or text:match("^%d+%s+%S"))
        and (a11y.game_plan_edit_contexts[context]
            or text:match("^%d+%s+%S"))
    if player_focus then
        local section = a11y.game_plan_player_section(text, widget_key)
        if section then
            a11y.game_plan_last_player_section = section
            local normalized_name = a11y.normalized_player_name(text)
            if normalized_name then
                a11y.game_plan_observed_lineup[normalized_name] = {
                    section = section,
                    number = tonumber(text:match("^%s*(%d+)%s+")) or 999,
                    widget = widget_key,
                }
            end
            local section_speech
            if a11y.ui_language == "pt" then
                section_speech = section == "starter"
                    and "Titular. " or section=="reserve" and "Reserva. " or "Não relacionado. "
            else
                section_speech = section == "starter"
                    and "Starter. " or section=="reserve" and "Substitute. " or "Not selected. "
            end
            announcement = section_speech .. announcement
        else
            -- Never let an unclassified player inherit the preceding section.
            -- This was why Salah sounded like a reserve despite no match.
            a11y.game_plan_last_player_section = nil
        end
    elseif not a11y.game_plan_edit_contexts[context] then
        a11y.game_plan_last_player_section = nil
    end
    if a11y.game_plan_active then
        a11y.game_plan_last_focus_text = text
        a11y.game_plan_last_roster_identity=roster_identity
        a11y.game_plan_last_focus_widget = widget_key
        a11y.game_plan_last_focus_frame = frame
        if context and context ~= a11y.game_plan_announced_context then
            a11y.game_plan_announced_context = context
            announcement = context .. ". " .. announcement
            a11y.game_plan_pending_title = nil
        end
    end
    return announcement
end

-- Leaving a component must also cancel work scheduled by that component.
-- This shared lifecycle is used by the existing exit adapters; no caption
-- rules or inferred player-section mappings are introduced here.
function a11y.leave_game_plan()
    a11y.game_plan_active = false
    a11y.game_plan_main_surface = false
    a11y.game_plan_context = nil
    a11y.game_plan_announced_context = nil
    a11y.game_plan_last_focus_text = nil
    a11y.game_plan_last_roster_identity=nil
    a11y.game_plan_last_menu_focus = nil
    a11y.game_plan_last_player_section = nil
    a11y.game_plan_basic_prompt_active = false
    a11y.game_plan_attribute_panel_until_ms = 0
    a11y.game_plan_attribute_locked_name = nil
    a11y.game_plan_attribute_due_ms = nil
    a11y.game_plan_attribute_hold_until_ms = 0
    a11y.game_plan_active_tactical_label = nil
    a11y.game_plan_active_tactical_value = nil
    a11y.game_plan_active_tactical_widget = nil
    a11y.game_plan_active_tactical_frame = -10000
    a11y.game_plan_selected_heading_due_frame = nil
    a11y.game_plan_basic_menu_heading_due_frame = nil
    a11y.game_plan_lineup_due_ms = nil
    a11y.game_plan_lineup_input = nil
    a11y.game_plan_menu_probe_due_frame = nil
    a11y.game_plan_menu_probe_action = nil
end

function a11y.process_game_plan_selected_heading(modal_focus_blocked)
    if a11y.read_context_state().kind == "dialog" then return false end
    local due = a11y.game_plan_selected_heading_due_frame
    if not due or frame < due or modal_focus_blocked
            or a11y.game_plan_main_surface
            or tonumber(ffi.C.GetTickCount64()) <=
                a11y.game_plan_attribute_panel_until_ms then return false end
    a11y.game_plan_selected_heading_due_frame = nil
    local text = a11y.game_plan_selected_heading
    if not text or text == a11y.game_plan_last_announced_heading then
        return false
    end
    a11y.game_plan_last_announced_heading = text
    local announcement = a11y.game_plan_focus_speech(
        text, a11y.game_plan_selected_heading_widget)
    if announcement then
        a11y.commit_read_selection(announcement,
            a11y.game_plan_selected_heading_widget or text, "adapter-focus")
        speak(announcement)
        return true
    end
    return false
end

function a11y.process_game_plan_basic_menu_heading(modal_focus_blocked)
    if a11y.read_context_state().kind == "dialog" then return false end
    local due = a11y.game_plan_basic_menu_heading_due_frame
    if not due or frame < due or modal_focus_blocked
            or (a11y.game_plan_context ~= "Menu de configuração básica"
                and a11y.game_plan_context ~= "Basic Settings Menu") then
        return false
    end
    a11y.game_plan_basic_menu_heading_due_frame = nil
    local text = a11y.game_plan_basic_menu_heading_text
    if not text then return false end
    local announcement = a11y.game_plan_focus_speech(
        text, a11y.game_plan_basic_menu_heading_widget)
    if announcement then
        a11y.commit_read_selection(announcement,
            a11y.game_plan_basic_menu_heading_widget or text, "adapter-focus")
        speak(announcement)
        return true
    end
    return false
end

function a11y.game_plan_attribute_summary()
    if a11y.visualization_packet() then
        return a11y.ui_language=="pt"
            and "Informações do jogador. Use I e K ou analógico direito para cima e para baixo."
            or "Player information. Use I and K or the right stick up and down."
    end
    return a11y.ui_language=="pt"
        and "Os valores deste painel ainda não foram associados."
        or "This panel's values have not been associated yet."
end

function a11y.poll_diagnostic_keyboard()
    a11y.buffer_keyboard_state = a11y.buffer_keyboard_state or {}
    for _, vkey in ipairs({0x49, 0x4b, 0x4a, 0x4c}) do
        local down = user32.GetAsyncKeyState(vkey) < 0
        if down and not a11y.buffer_keyboard_state[vkey] then a11y.buffer_key(vkey) end
        a11y.buffer_keyboard_state[vkey] = down
    end
    local inputs = {
        {0x26, "up"}, {0x28, "down"},
        {0x25, "left"}, {0x27, "right"},
        {0x59, "Y"}, {0x0d, "A"}, {0x1b, "escape"},
    }
    for _, input_entry in ipairs(inputs) do
        local down = user32.GetAsyncKeyState(input_entry[1]) < 0
        local previous = a11y.diagnostic_keyboard_state[input_entry[1]]
        if down and not previous then
            a11y.record_game_plan_input(input_entry[2], "keyboard")
        end
        a11y.diagnostic_keyboard_state[input_entry[1]] = down
    end
end

function a11y.poll_attribute_input(now_ms)
    a11y.poll_diagnostic_keyboard()
    local o_down = user32.GetAsyncKeyState(0x4f) < 0
    local keyboard_y_down = user32.GetAsyncKeyState(0x59) < 0
    local escape_down = user32.GetAsyncKeyState(0x1b) < 0
    if escape_down and not a11y.attribute_escape_down then
        a11y.game_plan_attribute_panel_until_ms = 0
        a11y.game_plan_attribute_locked_name = nil
    end
    if o_down and not a11y.lineup_keyboard_o_down
            and a11y.game_plan_lineup_screen_visible() then
        a11y.game_plan_lineup_due_ms = now_ms + 80
        a11y.game_plan_lineup_input = "O"
    end
    if keyboard_y_down and not a11y.attribute_keyboard_y_down
            and now_ms - a11y.game_plan_attribute_opened_ms > 500 then
        a11y.game_plan_attribute_panel_until_ms = 0
        a11y.game_plan_attribute_locked_name = nil
    end
    a11y.lineup_keyboard_o_down = o_down
    a11y.attribute_keyboard_y_down = keyboard_y_down
    a11y.attribute_escape_down = escape_down

    if not a11y.xinput or now_ms < (a11y.xinput_next_poll_ms or 0) then
        return
    end
    -- Sample once per render frame. The previous 80 ms interval could miss a
    -- quick D-pad tap, leaving pre-match and Game Plan speech waiting for a
    -- later visual debounce even though the game had already moved.
    a11y.xinput_next_poll_ms = now_ms + 16
    if a11y.xinput.XInputGetState(0, a11y.xinput_state) ~= 0 then
        a11y.attribute_right_stick_y = 0
        a11y.lineup_right_stick_x = 0
        return
    end
    local raw = tonumber(a11y.xinput_state[0].Gamepad.sThumbRY)
    local buttons = tonumber(a11y.xinput_state[0].Gamepad.wButtons)
    local y_down = math.floor(buttons / 0x8000) % 2 == 1
    local b_down = math.floor(buttons / 0x2000) % 2 == 1
    local gamepad_buttons = {
        {0x0001, "up"}, {0x0002, "down"},
        {0x0004, "left"}, {0x0008, "right"},
        {0x1000, "A"}, {0x8000, "Y"}, {0x2000, "B"},
    }
    for _, input_entry in ipairs(gamepad_buttons) do
        local down = math.floor(buttons / input_entry[1]) % 2 == 1
        local previous = a11y.diagnostic_gamepad_state[input_entry[1]]
        if down and not previous then
            a11y.record_game_plan_input(input_entry[2], "gamepad-button")
        end
        a11y.diagnostic_gamepad_state[input_entry[1]] = down
    end
    local left_x = tonumber(a11y.xinput_state[0].Gamepad.sThumbLX)
    local left_y = tonumber(a11y.xinput_state[0].Gamepad.sThumbLY)
    local left_direction = left_y > 16000 and "up"
        or (left_y < -16000 and "down"
        or (left_x < -16000 and "left"
        or (left_x > 16000 and "right" or nil)))
    if left_direction and not a11y.diagnostic_left_stick_direction then
        a11y.record_game_plan_input(left_direction, "gamepad-left-stick")
    end
    a11y.diagnostic_left_stick_direction = left_direction
    local right_x = tonumber(a11y.xinput_state[0].Gamepad.sThumbRX)
    local horizontal = right_x < -16000 and -1
        or (right_x > 16000 and 1 or 0)
    a11y.lineup_right_stick_x = horizontal
    if (b_down and not a11y.attribute_b_down)
            or (y_down and not a11y.attribute_y_down
                and now_ms - a11y.game_plan_attribute_opened_ms > 500) then
        a11y.game_plan_attribute_panel_until_ms = 0
        a11y.game_plan_attribute_locked_name = nil
    end
    local vertical = raw > 16000 and 1 or (raw < -16000 and -1 or 0)
    if vertical==0 then a11y.review_right_stick(0) end
    if vertical ~= 0 and a11y.attribute_right_stick_y == 0 then
        a11y.review_right_stick(vertical > 0 and -1 or 1)
    end
    a11y.attribute_right_stick_y = vertical
    a11y.attribute_y_down = y_down
    a11y.attribute_b_down = b_down
end

local function is_focused(text_id)
    local entry = widgets[text_id]
    if not entry or not readable(entry.address + 0x104, 4) then
        return false
    end
    return memory.unpack("u32", memory.read(entry.address + 0x104, 4)) == 1
end

local function is_widget_focused(widget)
    if not widget or not readable(widget + 0x104, 4) then
        return false
    end
    return memory.unpack("u32", memory.read(widget + 0x104, 4)) == 1
end

local function register_control_label(label, widget, role, is_control)
    local label_key = memory.hex(widget)
    local node = a11y.observe_ui_widget(widget, label)
    local previous_row = control_rows_by_label_widget[label_key]
    if previous_row and previous_row.label == label then
        if not previous_row.native_slider then
            previous_row.role = role or previous_row.role
        end
        previous_row.is_control = is_control or previous_row.is_control
        previous_row.created_frame = frame
        controller_rows[label] = previous_row
        pending_control_row = previous_row
        return previous_row
    end
    if previous_row and previous_row.value_widget_key
            and control_row_by_value_widget[previous_row.value_widget_key]
                == previous_row then
        control_row_by_value_widget[previous_row.value_widget_key] = nil
    end
    if previous_row and controller_rows[previous_row.label] == previous_row then
        controller_rows[previous_row.label] = nil
    end
    local row = {
        label = label,
        label_widget = widget,
        label_widget_key = label_key,
        role = role or selector_role(label),
        is_control = is_control or false,
        created_frame = frame,
        value_variants = {},
        value_variant_count = 0,
        identity = node.identity,
        generation = node.generation,
        structural = node.role == "control-label",
    }
    control_rows_by_label_widget[label_key] = row
    controller_rows[label] = row
    pending_control_row = row
    return row
end

function a11y.valid_control_value(widget,value,structural_boolean)
    local boolean=structural_boolean and (value=="Sim" or value=="Não" or value=="Yes" or value=="No")
    if not value or value=="" or (is_modal_button(value) and not boolean)
            or non_control_labels[value] or is_noninteractive_text(value)
            or looks_like_message(value, widget) then
        return false
    end
    local name = a11y.widget_internal_name(widget)
    if name == "padIcon" or name == "listName" or name == "teamName"
            or name == "playerName" or name == "groupName"
            or name == "title" or (name and name:match("_item$")) then
        return false
    end
    return true
end

local function attach_control_value(row, widget, value)
    if not row or row.native_slider or row.external_value
            or widget == row.label_widget
            or not a11y.valid_control_value(widget,value,row.native_field) then
        return false
    end
    local label_name = a11y.widget_internal_name(row.label_widget)
    local value_name = a11y.widget_internal_name(widget)
    local structural_stem = label_name
        and label_name:match("^(.-)_item$")
    if structural_stem and value_name ~= structural_stem .. "_value" then
        -- A rules page redraws competition names alongside its selectors.
        -- Render order alone must not make a club or another field the value.
        return false
    end
    if (structural_stem or (value_name and value_name:match("_value$")))
            and a11y.structural_control_row(widget) ~= row then
        -- Duplicate field names must not pair by table iteration order.
        return false
    end
    local value_key = memory.hex(widget)
    local previous_owner = control_row_by_value_widget[value_key]
    if previous_owner and previous_owner ~= row then
        previous_owner.value_widget = nil
        previous_owner.value_widget_key = nil
        previous_owner.value = nil
        previous_owner.is_control = controller_labels[previous_owner.label] or false
    end
    if row.value_widget_key and row.value_widget_key ~= value_key
            and control_row_by_value_widget[row.value_widget_key] == row then
        control_row_by_value_widget[row.value_widget_key] = nil
    end
    row.value_widget = widget
    row.value_widget_key = value_key
    row.value = value
    row.value_frame = frame
    if not row.value_variants then
        row.value_variants = {}
        row.value_variant_count = 0
    end
    if not row.value_variants[value] then
        row.value_variants[value] = true
        row.value_variant_count = row.value_variant_count + 1
    end
    row.is_control = row.is_control
        or row.structural
        or row.native_slider
        or controller_labels[row.label]
        or (not non_control_labels[row.label]
            and row.value_variant_count >= 2)
    control_row_by_value_widget[value_key] = row
    return true
end

function a11y.rebind_presented_control(node)
    if node.role=="control-value" or node.name=="text" or node.name=="jump" or node.name=="textWord" then
        local row=a11y.structural_control_row(node.address)
        if row then attach_control_value(row,node.address,node.text) end
    end
end

-- A selector's delegated text belongs to its enclosing native choice. This
-- schema uses setName outside the selector and one current text inside it.
-- Native ancestry AND selector RTTI must agree; captions/render order do not
-- establish the relation. Multiple labels/values remain unresolved.
function a11y.native_field_label(widget)
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[tonumber(widget)]
    local model=a11y.ui_model
    local target=model and model.nodes[memory.hex(widget)]
    if not member or not member.active or not target
            or (target.name~="text" and target.name~="jump" and target.name~="textWord") then return nil end
    local base=tonumber(process_base_u64)
    if not base then return nil end
    local found
    for _,owner in ipairs(member.owners or {}) do
        if owner.enabled and owner.parents then
            local parents=owner.parents
            local at,selector,choice=tonumber(widget),nil,nil
            local direct_jump=target.name=="jump" and parents[at]
                and a11y.menu_read(parents[at],"u64")==base+0x27cb508
            if direct_jump then selector=at end
            local visited={}
            for _=1,12 do
                if not at or at==owner.root or visited[at] then break end
                visited[at]=true
                local kind=a11y.menu_read(at,"u64")
                if kind==base+0x27b84d0 or kind==base+0x27be998 or kind==base+0x27bb538
                        or kind==base+0x27bac10 or kind==base+0x27cb970
                        or kind==base+0x27c3a38 then selector=at end
                if selector and kind==base+0x27cb508 then choice=at;break end
                at=parents[at]
            end
            if selector and choice then
                local label,value,ambiguous
                for _,node in pairs(model.nodes) do
                    if node.text and node.text~="" and a11y.native_presentation_ready(node.address)
                            and a11y.ui_node_matches_live(node) then
                        local cursor,inside,seen=tonumber(node.address),false,{}
                        for _=1,12 do
                            if not cursor or seen[cursor] then break end
                            seen[cursor]=true
                            if cursor==selector then inside=true end
                            if cursor==choice then
                                if (inside or (direct_jump and parents[tonumber(node.address)]==choice and node.name=="jump"))
                                        and (node.name=="text" or node.name=="jump" or node.name=="textWord")
                                        and a11y.valid_control_value(node.address,node.text,true) then
                                    if value and value~=node then ambiguous=true end
                                    value=node
                                elseif not inside and (node.name=="setName"
                                        or (node.name=="text" and parents[tonumber(node.address)]==choice)) then
                                    if label and label~=node then ambiguous=true end
                                    label=node
                                end
                                break
                            end
                            cursor=parents[cursor]
                        end
                    end
                end
                if not ambiguous and label and value and value.key==target.key then
                    if found and found.key~=label.key then return nil end
                    found=label
                end
            end
        end
    end
    return found
end

function a11y.structural_control_row(widget)
    local name = a11y.widget_internal_name(widget)
    local stem = name and name:match("^(.-)_value$")
    if not stem then
        local label=a11y.native_field_label(widget)
        if label then
            local row=control_rows_by_label_widget[label.key]
            if not row then row=register_control_label(label.text,label.address,nil,true) end
            row.is_control=true
            row.native_field=true
            return row
        end
        return nil
    end
    local value_key = memory.hex(widget)
    local model = a11y.ui_model
    if model and model.nodes[value_key] then
        local value_node = model.nodes[value_key]
        local label_node = a11y.scoped_ui_name(stem .. "_item",widget)
        if not value_node or not label_node then return nil end
        local scoped_value=a11y.scoped_ui_name(name,label_node.address)
        if not scoped_value or scoped_value.key~=value_key then return nil end
        return control_rows_by_label_widget[label_node.key]
    end
    local found
    for _, row in pairs(control_rows_by_label_widget) do
        if a11y.widget_internal_name(row.label_widget)
                == stem .. "_item" then
            if found then return nil end
            found = row
        end
    end
    return found
end

function a11y.capture_structural_control(widget, text)
    local node = a11y.observe_ui_widget(widget, text)
    if node.role == "control-value" then
        local row = a11y.structural_control_row(widget)
        if row then attach_control_value(row, widget, text) end
        return nil
    end
    local stem = node.name and node.name:match("^(.-)_item$")
    if not stem or not text or text == "" or looks_like_message(text, widget)
            or is_noninteractive_text(text) or is_modal_button(text) then
        return nil
    end
    local row = register_control_label(text, widget,
        a11y.ui_language == "pt" and "seletor" or "selector", true)
    local value_node = a11y.scoped_ui_name(stem .. "_value",widget)
    if value_node and attach_control_value(row, value_node.address, value_node.text) then
        pending_control_row = nil
    end
    return row
end

function a11y.native_control_help(text,source_node)
    local model,snapshot=a11y.ui_model,a11y.native_windows
    if not model or not snapshot then return nil end
    local base=tonumber(process_base_u64)
    if not base then return nil end
    local bucket=model.texts and model.texts[text]
    local candidates=source_node and {[source_node.key]=source_node} or (bucket and bucket.nodes or {})
    for _,node in pairs(candidates) do
        local member=snapshot.members[tonumber(node.address)]
        if node.text==text and member and member.active
                and node.name~="question" and node.name~="eventMsg"
                and a11y.native_presentation_ready(node.address) and a11y.ui_node_matches_live(node) then
            local help_owner={}
            for _,entry in ipairs(member.owners or {}) do
                local at=tonumber(node.address)
                local visited={}
                for _=1,8 do
                    if not at or visited[at] or not entry.enabled then break end
                    visited[at]=true
                    -- RTTI-proven NodeRectHelpBox, including its delegated text.
                    if a11y.menu_read(at,"u64")==base+0x27c17a0 then help_owner[entry.address]=true;break end
                    at=entry.parents and entry.parents[at]
                end
            end
            for _,window in ipairs(snapshot.windows or {}) do
                if window.enabled and help_owner[window.address] then return node end
            end
        end
    end
end

function a11y.is_control_help(text)
    if a11y.common_tooltip and a11y.common_tooltip.text==text
            and a11y.tooltip_selection_stamp()==a11y.common_tooltip.selection then return true end
    if a11y.native_control_help(text) then return true end
    -- The lexicon calls ordinary option explanations "instruction" too.
    -- Classify them as help only in an observed control surface. Tutorials
    -- and confirmation paragraphs retain their modal path.
    local role = a11y.text_asset_role(text)
    if role ~= "tooltip-or-description" and (role ~= "instruction"
            or not (text:match("^Escolha ") or text:match("^Choose "))) then
        return false
    end
    for key, row in pairs(control_rows_by_label_widget) do
        if row.is_control and a11y.ui_model.nodes[key] then return true end
    end
    return false
end

function a11y.invalidate_structural_pair(stem)
    local model = a11y.ui_model
    for key in pairs(model and model.names[stem .. "_item"] or {}) do
        local row = control_rows_by_label_widget[key]
        -- Repeated internal names are normal in separate native components.
        -- Invalidate only a binding whose own structural proof was lost.
        if row and row.value_widget
                and a11y.structural_control_row(row.value_widget) ~= row then
            if row.value_widget_key and control_row_by_value_widget[row.value_widget_key] == row then
                control_row_by_value_widget[row.value_widget_key] = nil
            end
            row.value, row.value_widget, row.value_widget_key = nil, nil, nil
        end
    end
end

local function formatted_slider_value(row, value)
    if row.minimum == 0 and row.maximum == 15 then
        return tostring(value) .. " de 15"
    end
    return tostring(value)
end

local function bind_delayed_speed_slider(row)
    if not row or row.label ~= "Velocidade do jogo" then
        return
    end
    local best_key
    local best
    for key, candidate in pairs(unmapped_sliders) do
        if frame - (candidate.last_frame or frame) <= 60
                and (not best
                    or (candidate.last_frame or 0) > (best.last_frame or 0)) then
            best_key = key
            best = candidate
        end
    end
    if not best then
        return
    end
    row.role = "controle deslizante"
    row.native_slider = true
    row.minimum = best.minimum or -2
    row.maximum = best.maximum or 2
    row.is_control = true
    row.value = formatted_slider_value(row, best.value or 0)
    slider_rows[best_key] = {
        id = nil,
        text = row.label,
        control = row,
    }
    unmapped_sliders[best_key] = nil
    log(string.format(
        "[FLAccess] slider-map-delayed text=%q object=%s value=%d min=%d max=%d",
        row.label,
        best_key,
        best.value or 0,
        row.minimum,
        row.maximum))
end

function m.on_slider_init(ctx, event_id, registers)
    local slider = read_u64(registers.rcx)
    local maximum = tonumber(ffi.cast("int32_t", read_u64(registers.rdx)))
    local minimum = tonumber(ffi.cast("int32_t", read_u64(registers.r8)))
    local value = tonumber(ffi.cast("int32_t", read_u64(registers.r9)))
    local pending = pending_control_row
    local pending_is_fresh = pending
        and frame - (pending.created_frame or frame) <= 2
    local mapped_id = last_audio_id
    local mapped_entry = mapped_id and widgets[mapped_id] or nil
    local key = memory.hex(slider)
    if minimum >= -1000 and maximum <= 1000 and minimum < maximum then
        unmapped_sliders[key] = {
            minimum = minimum,
            maximum = maximum,
            value = value,
            last_frame = frame,
        }
    end
    if not mapped_entry and pending_is_fresh then
        mapped_entry = {
            text = pending.label,
            address = pending.label_widget,
        }
    end
    if mapped_entry and minimum >= -1000 and maximum <= 1000
            and minimum < maximum then
        local control = (not mapped_id and pending_is_fresh) and pending
            or register_control_label(
            mapped_entry.text,
            mapped_entry.address,
            "controle deslizante",
            true)
        control.role = "controle deslizante"
        control.native_slider = true
        control.minimum = minimum
        control.maximum = maximum
        control.is_control = true
        control.value = formatted_slider_value(control, value)
        slider_rows[key] = {
            id = mapped_id,
            text = mapped_entry.text,
            control = control,
        }
        unmapped_sliders[key] = nil
        if mapped_id then
            slider_values[mapped_id] = value
        end
        if a11y.game_plan_context == "Configurações táticas básicas"
                or a11y.game_plan_context == "Basic Tactical Settings" then
            active_control_row = control
            active_controller_label = control.label
            active_control_focused_ms = tonumber(ffi.C.GetTickCount64())
            a11y.game_plan_active_tactical_label = control.label
            a11y.game_plan_active_tactical_value = control.value
            a11y.game_plan_active_tactical_widget = control.label_widget_key
            a11y.game_plan_active_tactical_frame = frame
            last_spoken_controller_tooltip_key = nil
        end
        log(string.format(
            "[FLAccess] slider-map id=%s text=%q object=%s value=%d min=%d max=%d",
            mapped_id and tostring(mapped_id) or "dynamic",
            mapped_entry.text,
            key,
            value,
            minimum,
            maximum))
        a11y.record_slider(
            "init", key, value, control, minimum, maximum)
        pending_control_row = nil
        last_audio_id = nil
    end
end

function m.on_slider_set(ctx, event_id, registers)
    local slider = read_u64(registers.rcx)
    local value = tonumber(ffi.cast("int32_t", read_u64(registers.rdx)))
    local key = memory.hex(slider)
    local row = slider_rows[key]
    if not row then
        local pending = unmapped_sliders[key] or {}
        pending.value = value
        pending.last_frame = frame
        unmapped_sliders[key] = pending
    end
    if row then
        if row.id then
            slider_values[row.id] = value
        end
        local full_value = formatted_slider_value(row.control, value)
        row.control.value = full_value
        if a11y.read_context_state().kind == "dialog" then return end
        local focused = active_control_row == row.control
            or (row.id and is_focused(row.id))
            or is_widget_focused(row.control.label_widget)
        if focused then
            a11y.commit_read_selection(control_speech(row.control),
                row.control.identity or row.control.label_widget_key or key,
                "control", row.control.label)
            if active_control_row == row.control then
                -- Preserve the range for the complete focus announcement, but
                -- lateral changes should say only the newly selected value.
                local full = control_speech(row.control)
                if last_announced_control_row ~= row.control then
                    announce_control(row.control)
                elseif full ~= last_controller_announcement then
                    last_controller_announcement = full
                    speak(tostring(value))
                end
            else
                announce_control(row.control)
            end
        end
    end
    a11y.record_slider(
        "set",
        key,
        value,
        row and row.control or nil,
        row and row.control.minimum or nil,
        row and row.control.maximum or nil)
    trace_log(string.format(
        "[FLAccess] slider-set value=%d object=%s id=%s text=%q",
        value,
        key,
        row and tostring(row.id) or "none",
        row and row.text or ""))
end

local function language_value(registers)
    local controller = read_u64(registers.rcx)
    local index = tonumber(ffi.cast("uint32_t", read_u64(registers.rdx)))
    if not controller or controller < 0x10000 or index > 255
            or not readable(controller + 0x90, 8) then
        return nil, controller, index
    end
    local first = read_u64(memory.read(controller + 0x90, 8))
    return a11y.read_msvc_string(first + index * 0x20), controller, index
end

local function language_value_at(controller, index)
    if not controller or controller < 0x10000 or not index or index > 255
            or not readable(controller + 0x90, 8) then
        return nil
    end
    local first = read_u64(memory.read(controller + 0x90, 8))
    return a11y.read_msvc_string(first + index * 0x20)
end

local function speak_language(registers, label, update_ui_language)
    local value, controller, index = language_value(registers)
    log(string.format(
        "[FLAccess] language-set label=%q object=%s index=%d value=%q",
        label,
        memory.hex(controller or 0),
        index or -1,
        value or ""))
    if value and value ~= "" then
        if update_ui_language then
            a11y.set_ui_language_from_name(value)
        end
        local key = "language:" .. memory.hex(controller or 0)
        local row = language_control_by_controller[key] or {
            label = label,
            role = "seletor",
            label_widget_key = key,
            is_control = true,
            external_value = true,
        }
        row.label = label
        row.value = value
        language_control_by_controller[key] = row
        announce_control(row)
    end
end

function m.on_game_text_language_set(ctx, event_id, registers)
    speak_language(registers, "Texto do jogo", true)
end

function m.on_commentary_language_set(ctx, event_id, registers)
    speak_language(registers, "Idioma do comentário", false)
end

function a11y.language_setting_label(controller)
    local base=tonumber(process_base_u64)
    local vt=controller and a11y.menu_read(controller,"u64")
    local setter=vt and a11y.menu_read(vt+0x258,"u64")
    if not base then return nil end
    if setter==base+COMMENTARY_LANGUAGE_SET_RVA then
        return a11y.ui_language=="pt" and "Idioma do comentário" or "Commentary language"
    elseif setter==base+GAME_TEXT_LANGUAGE_SET_RVA then
        return a11y.ui_language=="pt" and "Texto do jogo" or "Game text"
    end
end

function a11y.native_language_context()
    local found
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        local label=window.enabled and window.root and window.root>=0x10000
            and a11y.language_setting_label(window.address)
        local flags=label and a11y.menu_read(window.root+0xc,"u32")
        if flags and flags%8==7 and math.floor(flags/256)%2==1 then
            if found then return nil end
            found={window=window.address,root=window.root,label=label,
                identity=tostring(window.address) .. ":" .. tostring(window.root) .. ":" .. label}
        end
    end
    return found
end

function a11y.poll_native_language()
    local context=a11y.native_language_context()
    if not context then a11y.language_announced,a11y.language_active=nil,nil;return end
    if a11y.language_active~=context.identity then
        a11y.language_active=context.identity
        a11y.language_generation=(a11y.language_generation or 0)+1
        a11y.language_announced=nil
    end
    if a11y.language_announced==context.identity or a11y.read_context_state().kind=="dialog" then return end
    local before=a11y.native_speech_last
    a11y.set_read_title(context.label)
    speak(context.label,true,nil,"language-header:" .. context.identity .. ":" .. tostring(a11y.language_generation))
    if a11y.native_speech_last>before then
        a11y.language_announced=context.identity
        a11y.title_pending_first_item=context.label
        a11y.title_pending_first_item_until_ms=tonumber(ffi.C.GetTickCount64())+2000
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].language_header=context.identity
            a11y.native_speech_queue[index].language_generation=a11y.language_generation
        end
    end
end

function a11y.native_language_heading(widget)
    local name=widget and a11y.widget_internal_name(widget)
    if name~="title" and name~="text_title" then return nil end
    local snapshot=a11y.native_windows
    local member=widget and snapshot and snapshot.members and snapshot.members[tonumber(widget)]
    local label
    for _,owner in ipairs(member and member.owners or {}) do
        if owner.enabled then
            local current=a11y.language_setting_label(owner.address)
            if current then
                if label and label~=current then return nil end
                label=current
            end
        end
    end
    return label
end

function m.on_game_text_language_nav(ctx, event_id, registers)
    local controller = read_u64(registers.rbx)
    local index = tonumber(ffi.cast("uint32_t", read_u64(registers.rax)))
    local value = language_value_at(controller, index)
    log(string.format(
        "[FLAccess] language-nav object=%s index=%d value=%q",
        memory.hex(controller or 0),
        index or -1,
        value or ""))
    if value and value ~= "" then
        local key = "language:" .. memory.hex(controller or 0)
        -- Shared navigation belongs to both language controllers. Their
        -- virtual commit method identifies the setting even before confirm.
        local label=a11y.language_setting_label(controller)
        if not label then return end
        local row = language_control_by_controller[key] or {
            label = label,
            role = "seletor",
            label_widget_key = key,
            is_control = true,
            external_value = true,
        }
        row.label=label
        language_control_by_controller[key] = row
        -- This startup screen has only one control. Repeating its label is
        -- useful context: a bare language name does not tell a screen-reader
        -- user whether it changes commentary, menus, or the game's text.
        row.value = value
        announce_control(row)
    end
end

function m.on_ui_text_set(ctx, event_id, registers)
    local widget=tonumber(read_u64(registers.rcx))
    local raw=a11y.read_msvc_string(read_u64(registers.rdx),true)
    if raw~=nil then a11y.on_observed_ui_text(widget,clean_text(raw),raw,registers) end
end

-- Existing caption-based adapters remain isolated from native component
-- discovery. Do not extend these cases to cover new screens; obtain native
-- owner/selection evidence in the common reader instead.
function a11y.observe_compatibility_context(widget_key, text)
    if a11y.native_pause_context() then return false,false end
    local normal_game_plan_marker = text == "Escalação/Editar posição"
        or text == "Team Sheet/Edit Position"
    if normal_game_plan_marker and not a11y.game_plan_active
            and (not a11y.pre_match_active
                or a11y.game_plan_entry_requested) then
        -- The normal Game Plan screen does not expose its visible "Plano de
        -- jogo" caption through the dedicated title widget used by submenus.
        -- Its Team Sheet/Edit Position command is unique to this surface and
        -- therefore provides a safe structural entry marker.
        a11y.game_plan_active = true
        a11y.game_plan_entry_requested = false
        a11y.game_plan_main_surface = true
        a11y.game_plan_context = a11y.ui_language == "pt"
            and "Plano de jogo normal" or "Normal Game Plan"
        a11y.game_plan_pending_title = a11y.game_plan_context
        a11y.game_plan_announced_context = nil
        a11y.game_plan_last_focus_text = nil
        a11y.game_plan_last_focus_widget = nil
        a11y.game_plan_last_menu_focus = text
        a11y.game_plan_selected_heading = nil
        a11y.game_plan_selected_heading_widget = nil
        a11y.game_plan_selected_heading_frame = -10000
        a11y.game_plan_selected_heading_due_frame = nil
        a11y.game_plan_last_announced_heading = nil
        a11y.game_plan_last_player_section = nil
        a11y.game_plan_attribute_panel_until_ms = 0
        a11y.game_plan_attribute_locked_name = nil
        a11y.game_plan_attribute_due_ms = nil
        a11y.game_plan_attribute_hold_until_ms = 0
        a11y.game_plan_formation_active = false
        a11y.game_plan_lineup_generation_frame = frame
        a11y.pre_match_active = false
        a11y.pre_match_entry_pending = false
        -- Control widgets are aggressively recycled between screens. Do not
        -- let the last selector on the previous screen claim a Game Plan
        -- command (for example "Agressiva, Gestão de dados") as its value.
        a11y.reset_control_tracking_state()
        focused_control_hint = nil
        a11y.reset_focus_reuse_state()
        -- This default command can exist for only one render frame before the
        -- first-use tutorial opens. Capture and announce it synchronously so
        -- a quick confirmation still enters Edit Position with the right
        -- semantic context.
        local initial_announcement = a11y.game_plan_focus_speech(
            text,
            widget_key)
        if initial_announcement then
            speak(initial_announcement)
        end
    end
    local tactical_label, tactical_value =
        text:match("^(.+)%s+:%s+(.+)$")
    if tactical_label and tactical_value then
        local short_or_long_pass = tactical_value == "Passe curto"
            or tactical_value == "Passe longo"
            or tactical_value == "Short-pass"
            or tactical_value == "Long-pass"
            or tactical_value == "Short Pass"
            or tactical_value == "Long Pass"
        if short_or_long_pass and not a11y.game_plan_tactical_labels[
                tactical_label] then
            -- The second row exposes its current advanced-instruction value
            -- (for example "Provocador") where its label should be.
            tactical_label = a11y.ui_language == "pt"
                and "Construção" or "Build Up"
        end
    end
    local tactical_heading = a11y.game_plan_active
        and tactical_label and tactical_value
        and a11y.game_plan_tactical_labels[tactical_label]
    if tactical_heading then
        local entering_tactical = a11y.game_plan_context ~=
            "Configurações táticas básicas"
            and a11y.game_plan_context ~= "Basic Tactical Settings"
        if entering_tactical then
            a11y.game_plan_basic_prompt_active = false
            a11y.game_plan_formation_active = false
            a11y.reset_focus_reuse_state()
            a11y.game_plan_last_focus_text = nil
            a11y.game_plan_announced_context = nil
        end
        a11y.game_plan_context = a11y.ui_language == "pt"
            and "Configurações táticas básicas" or "Basic Tactical Settings"
        local tactical_changed = tactical_label ~=
                a11y.game_plan_active_tactical_label
            or tactical_value ~= a11y.game_plan_active_tactical_value
        local horizontal_value_change = tactical_label ==
                a11y.game_plan_active_tactical_label
            and (a11y.diagnostic_last_input_action == "left"
                or a11y.diagnostic_last_input_action == "right")
            and frame - a11y.diagnostic_last_input_frame <= 12
        a11y.game_plan_active_tactical_label = tactical_label
        a11y.game_plan_active_tactical_value = tactical_value
        a11y.game_plan_active_tactical_widget = widget_key
        a11y.game_plan_active_tactical_frame = frame
        local row = controller_rows[tactical_label] or {
            label = tactical_label,
            role = a11y.ui_language == "pt" and "seletor" or "selector",
            label_widget_key = "game-plan-tactical:" .. tactical_label,
            is_control = true,
        }
        row.value = tactical_value
        row.is_control = true
        controller_rows[tactical_label] = row
        if tactical_changed then
            active_control_row = row
            active_controller_label = tactical_label
            active_control_focused_ms = tonumber(ffi.C.GetTickCount64())
            last_controller_announcement = control_speech(row)
            last_announced_control_row = row
            last_announced_selector_label = row.label_widget_key
            last_spoken_controller_tooltip_key = nil
            speak(horizontal_value_change
                and tactical_value or last_controller_announcement)
            if pending_controller_tooltip
                    and frame - a11y.game_plan_tactical_navigation_frame <= 30 then
                pending_controller_tooltip_label = tactical_label
                controller_tooltip_due_ms =
                    tonumber(ffi.C.GetTickCount64())
            end
        end
    end
    local numbered_player_heading = a11y.game_plan_active
        and text:match("^%d+%s+%S") ~= nil
    local game_plan_player_heading = numbered_player_heading
        and a11y.game_plan_edit_contexts[a11y.game_plan_context]
    if game_plan_player_heading then
        a11y.record_game_plan_heading(text, widget_key)
    end
    if a11y.game_plan_active or a11y.game_plan_roster_contexts[text] then
        a11y.game_plan_attribute_text_events[
            #a11y.game_plan_attribute_text_events + 1] = {
                text = text,
                frame = frame,
                widget = widget_key,
            }
        while #a11y.game_plan_attribute_text_events > 256 do
            table.remove(a11y.game_plan_attribute_text_events, 1)
        end
    end
    local root_game_plan_title = text == "Menu de configuração básica"
        or text == "Basic Settings Menu"
    if root_game_plan_title then
        -- This widget is redrawn on every real transition back to the Basic
        -- Settings menu. Refusing it because the previous context differed
        -- left Formation active and silenced the menu after returning.
        a11y.game_plan_title_widgets[widget_key] = true
    end
    local authoritative_game_plan_title =
        a11y.game_plan_roster_contexts[text]
        and a11y.game_plan_title_widgets[widget_key]
    if authoritative_game_plan_title then
        local previous_game_plan_context = a11y.game_plan_context
        local entering_basic_menu = root_game_plan_title
            and a11y.game_plan_context ~= text
        local entering_edit = a11y.game_plan_edit_contexts[text]
            and not a11y.game_plan_edit_contexts[a11y.game_plan_context]
        local entering_lineup = (a11y.game_plan_edit_contexts[text]
                or text == "Plano de jogo normal"
                or text == "Normal Game Plan")
            and a11y.game_plan_context ~= text
        if entering_basic_menu then
            a11y.game_plan_basic_menu_heading_widget = nil
            a11y.game_plan_basic_menu_heading_text = nil
            a11y.game_plan_basic_menu_heading_due_frame = nil
            a11y.game_plan_basic_prompt_active = false
        end
        a11y.game_plan_active = true
        a11y.game_plan_main_surface = text == "Plano de jogo normal"
            or text == "Normal Game Plan"
        a11y.game_plan_context = text
        a11y.game_plan_pending_title = text
        if previous_game_plan_context ~= text then
            a11y.game_plan_formation_active = false
            a11y.game_plan_last_menu_focus = nil
            a11y.reset_focus_reuse_state()
            a11y.game_plan_last_focus_text = nil
            a11y.game_plan_last_focus_widget = nil
            a11y.game_plan_announced_context = nil
            a11y.game_plan_last_announced_heading = nil
            a11y.game_plan_selected_heading_due_frame = nil
        end
        if text ~= "Configurações táticas básicas"
                and text ~= "Basic Tactical Settings" then
            a11y.game_plan_active_tactical_label = nil
            a11y.game_plan_active_tactical_value = nil
            a11y.game_plan_active_tactical_widget = nil
            a11y.game_plan_last_player_section = nil
        end
        if entering_edit then
            a11y.game_plan_last_player_section = nil
            a11y.game_plan_last_announced_heading = nil
            a11y.game_plan_observed_lineup = {}
        end
        if entering_lineup then
            a11y.game_plan_lineup_generation_frame = frame
        end
        a11y.pre_match_active = false
        a11y.pre_match_entry_pending = false
        a11y.stadium_active = false
        a11y.cup_group_table_active = false
    elseif text == "Configurações do sistema"
            or text == "System Settings" then
        if not a11y.pre_match_active then
            a11y.pre_match_entry_pending = true
            a11y.pre_match_entry_guard_until_frame = frame + 120
            a11y.pre_match_last_action = nil
        end
        a11y.pre_match_active = true
        a11y.leave_game_plan()
        a11y.stadium_active = false
        a11y.cup_group_table_active = false
    elseif text == "Altura da grama" or text == "Grass Length" then
        if not a11y.stadium_active
                or frame - a11y.stadium_last_marker_frame > 120 then
            reset_stadium_screen()
        end
        a11y.stadium_last_marker_frame = frame
        a11y.stadium_active = true
        a11y.leave_game_plan()
        a11y.pre_match_active = false
    end
    return tactical_heading, game_plan_player_heading
end

function a11y.on_observed_ui_text(widget,text,raw,registers,review)
    if not text or not widget or widget < 0x10000 then
        return
    end
    if text == "" then
        local empty_key = memory.hex(widget)
        for index = #(a11y.dashboard_texts or {}), 1, -1 do
            if a11y.dashboard_texts[index].address == widget then
                table.remove(a11y.dashboard_texts, index)
            end
        end
        a11y.forget_ui_widget(empty_key)
        ui_text_by_widget[empty_key] = nil
        if last_selected_ui_entry and last_selected_ui_entry.address == widget then
            a11y.reset_focus_reuse_state()
        end
        return
    end
    if text == "No String" or text == "/" then
        -- Construction placeholders are neither a surface change nor focus.
        -- Clearing all ownership here used to erase freshly mapped sliders.
        a11y.forget_ui_widget(memory.hex(widget))
        ui_text_by_widget[memory.hex(widget)] = nil
        return
    end

    local widget_key = memory.hex(widget)
    local observed_node = a11y.observe_ui_widget(widget, text)
    observed_node.raw_text=raw or text
    if a11y.unresolved_format(text) then return end
    a11y.poll_native_windows()
    a11y.record_dashboard_text(observed_node)
    if a11y.main_menu_text_owner(observed_node) then
        if not review and observed_node.name=="text_item" then
            main_menu_title_widget_key=observed_node.key
            a11y.present_main_menu_choice(widget,text)
        end
        return
    end
    if review then
        a11y.capture_structural_control(widget,text)
        return
    end
    -- Input feedback is owned by the actual native input node. A retained
    -- textWord from the background is not an edit event.
    if observed_node.name == "padIcon" then return end
    local structural_prompt = a11y.capture_question_panel(observed_node)
    if not structural_prompt and a11y.capture_reading_panel(observed_node) then return end
    if a11y.diagnostic_mode and registers then
        local saved_rsp = read_u64(registers.rsp)
        if saved_rsp and readable(saved_rsp + 64, 8) then
            local return_address = read_u64(memory.read(saved_rsp + 64, 8))
            local caller_number = tonumber(return_address)
            local base_number = tonumber(process_base_u64)
            if caller_number and base_number and caller_number >= base_number
                    and caller_number < base_number + 0x40000000 then
                a11y.ui_text_caller_by_widget[widget_key] =
                    caller_number - base_number
            else
                a11y.ui_text_caller_by_widget[widget_key] = nil
            end
        end
    end
    local previous = ui_text_by_widget[widget_key]
    ui_text_by_widget[widget_key] = text
    if previous ~= text then
        a11y.announce_skip_hint(text, observed_node)
    end
    if not a11y.cup_group_table_active
            and a11y.is_cup_group_header(widget, text) then
        -- Captured headers arrive before the trailing grid OK and before the
        -- explanatory paragraph. Identify the table while that OK is still
        -- a background cell, not after it has already reached speech.
        a11y.activate_cup_group_table(false)
    end
    local tactical_heading, game_plan_player_heading =
        a11y.observe_compatibility_context(widget_key, text)
    local now_ms = tonumber(ffi.C.GetTickCount64())
    if a11y.game_plan_active
            and (text == "Altura (cm)" or text == "Height (cm)") then
        local panel_was_closed = now_ms > a11y.game_plan_attribute_panel_until_ms
        a11y.game_plan_attribute_last_marker_frame = frame
        local opened_by_y = a11y.diagnostic_last_input_action == "Y"
            and frame - a11y.diagnostic_last_input_frame <= 90
            and a11y.game_plan_selected_heading ~= nil
        if panel_was_closed and opened_by_y then
            a11y.game_plan_attribute_locked_name =
                a11y.normalized_player_name(
                    a11y.game_plan_selected_heading
                        or a11y.game_plan_last_focus_text)
            a11y.game_plan_player_record = nil
            a11y.game_plan_player_name =
                a11y.game_plan_attribute_locked_name
            a11y.game_plan_player_attributes = {}
            local player = a11y.player_for_text(
                a11y.game_plan_attribute_locked_name)
            if player then
                a11y.game_plan_player_record = player.pointer
                a11y.game_plan_player_name =
                    a11y.game_plan_attribute_locked_name or player.name
                a11y.game_plan_player_attributes = player.attributes
            end
            a11y.game_plan_attribute_due_ms = now_ms + 300
            a11y.game_plan_attribute_opened_ms = now_ms
        end
        if opened_by_y then
            a11y.game_plan_attribute_panel_until_ms = now_ms + 30000
        end
    end
    local tooltip_control_label = control_label_from_tooltip(text)
    -- A pause between text writes is not a new focus. The same Informações
    -- widget can redraw after a pause while the selection never moved.
    if previous ~= text and not a11y.native_presentation_ready(widget) then
        local title = is_screen_title(text,widget)
        local role = a11y.text_asset_role(text)
        if title or ((a11y.is_instruction_message(text) or looks_like_message(text,widget))
                and not a11y.is_control_help(text)) then
            a11y.defer_bound_guidance(widget,text)
        end
    end
    if previous ~= text and a11y.native_presentation_ready(widget) then
        announce_screen_title(text, widget_key, widget)
        local tactical_tooltip = a11y.game_plan_active
            and a11y.game_plan_active_tactical_label
            and frame - a11y.game_plan_active_tactical_frame <= 90
            and looks_like_message(text, widget)
            and not a11y.is_instruction_message(text)
            and not tactical_heading
        if tactical_tooltip then
            if a11y.read_tooltips then
                pending_controller_tooltip = text
                pending_controller_tooltip_label =
                    a11y.game_plan_active_tactical_label
                active_controller_label =
                    a11y.game_plan_active_tactical_label
                controller_tooltip_due_ms = now_ms
            end
        elseif tooltip_control_label or a11y.is_control_help(text) then
            focused_control_hint = tooltip_control_label
            focused_control_hint_ms = now_ms
            latest_generic_tooltip = text
            latest_generic_tooltip_widget = widget
            latest_generic_tooltip_ms = now_ms
            a11y.set_read_help(text, tooltip_control_label)
            if a11y.read_tooltips then
                pending_controller_tooltip = text
                pending_controller_tooltip_label = tooltip_control_label
                    or active_controller_label
                controller_tooltip_due_ms = now_ms
            end
        elseif not game_plan_player_heading and not tactical_heading and not structural_prompt then
            remember_message_text(text, widget_key)
        end
        if not queue_startup_text(text, now_ms)
                and is_plain_text(text)
                and not is_noninteractive_text(text) then
            speak(text)
        end
        if #text >= 4 and #text <= 50
                and not is_modal_button(text)
                and not is_plain_text(text)
                and not is_splash_text(text)
                and not is_noninteractive_text(text)
                and not text:match("^Usuário %d+$") then
            recent_heading_text = text
            recent_heading_frame = frame
        end
    end
    if is_modal_button(text) then
        last_modal_button_frame = frame
        if text ~= "OK" or not instruction_message_locked then
            queue_recent_message()
        end
    end
    if text == "Sim" or text == "Não" then
        register_dialog_option(text, widget, widget_key)
    end
    local structural_node = a11y.ui_model and a11y.ui_model.nodes[widget_key]
    if #text >= 2 and (#text <= 50 or (#text <= 160
            and structural_node and structural_node.role == "control-label")
            or (a11y.read_context_state().kind == "dialog" and #text <= 512
                and text ~= a11y.read_context.question
                and widget_key ~= a11y.read_context.message_key
                and (a11y.is_structural_answer(text,widget_key) or
                    (a11y.text_asset_role(text) ~= "dialog" and a11y.text_asset_role(text) ~= "instruction"))))
            and not text:find("%%") and not text:match("^%d+$")
            and text ~= "-" and text:match("[%w]")
            and not is_noninteractive_text(text)
            and a11y.widget_internal_name(widget) ~= "title"
            and a11y.widget_internal_name(widget) ~= "text_title"
            and widget_key ~= main_menu_title_widget_key
            and text ~= main_menu_tooltip
            and text ~= pending_controller_tooltip then
        local previous_focus = ui_focus_widgets[widget_key]
        if a11y.focus_widget_reused(previous_focus, text) then
            a11y.reset_focus_reuse_state()
        end
        if not ui_focus_widgets[widget_key] then
            if ui_focus_widget_count >= 300 then
                local oldest_key
                local oldest_frame = frame + 1
                for candidate_key, candidate in pairs(ui_focus_widgets) do
                    if (candidate.last_seen or 0) < oldest_frame then
                        oldest_key = candidate_key
                        oldest_frame = candidate.last_seen or 0
                    end
                end
                if oldest_key then
                    a11y.forget_ui_widget(oldest_key)
                end
            end
            ui_focus_widget_count = ui_focus_widget_count + 1
        end
        ui_focus_widgets[widget_key] = {
            address = widget,
            text = text,
            last_seen = frame,
            identity = a11y.observe_ui_widget(widget, text).identity,
        }
    end

    local label_row = control_rows_by_label_widget[widget_key]
    if label_row and text ~= label_row.label then
        if label_row.value_widget_key
                and control_row_by_value_widget[label_row.value_widget_key]
                    == label_row then
            control_row_by_value_widget[label_row.value_widget_key] = nil
        end
        if controller_rows[label_row.label] == label_row then
            controller_rows[label_row.label] = nil
        end
        control_rows_by_label_widget[widget_key] = nil
        if active_control_row == label_row then
            active_control_row = nil
        end
        label_row = nil
    end

    -- A field pair needs no localization ID, known caption, or screen name.
    label_row = a11y.capture_structural_control(widget, text) or label_row
    local value_row
    local structural_row = a11y.structural_control_row(widget)
    if structural_row and attach_control_value(
            structural_row, widget, text) then
        value_row = structural_row
        pending_control_row = nil
    elseif label_row and text == label_row.label then
        pending_control_row = label_row
    elseif active_control_row
            and not active_control_row.native_slider
            and not active_control_row.external_value
            and not a11y.game_plan_active
            and now_ms - active_control_focused_ms <= 500
            and widget ~= active_control_row.label_widget
            and not label_row
            and is_widget_focused(widget) then
        if attach_control_value(active_control_row, widget, text) then
            value_row = active_control_row
        end
        pending_control_row = nil
    elseif pending_control_row and not a11y.game_plan_active
            and frame - (pending_control_row.created_frame or frame) <= 2
            and widget ~= pending_control_row.label_widget then
        if attach_control_value(pending_control_row, widget, text) then
            value_row = pending_control_row
        end
        pending_control_row = nil
    else
        value_row = control_row_by_value_widget[widget_key]
        if value_row and not value_row.native_slider then
            if not attach_control_value(value_row, widget, text) then
                value_row = nil
            end
        elseif value_row and value_row.native_slider then
            value_row = nil
        end
    end
    local tactical_context = a11y.game_plan_context ==
            "Configurações táticas básicas"
        or a11y.game_plan_context == "Basic Tactical Settings"
    if value_row and active_control_row == value_row and previous ~= text
            and not tactical_context then
        announce_control_value(value_row, text)
    end

    local seen_key = widget_key .. "\0" .. text
    if not ui_text_seen[seen_key] and ui_text_unique_count < 6000 then
        ui_text_seen[seen_key] = true
        ui_text_unique_count = ui_text_unique_count + 1
        trace_log(string.format(
            "[FLAccess] ui-text widget=%s previous=%q text=%q",
            widget_key,
            previous or "",
            text))
    end

end

function a11y.empty_selection_caption(text)
    local value=(text or ""):gsub("%s","")
    return value=="" or value=="-" or value=="–" or value=="—"
end

function a11y.observe_native_list_selection(text,identity,widget)
    if a11y.empty_selection_caption(text) or not widget or widget<0x10000 then return end
    local previous=a11y.native_list_selection
    local name,link=a11y.widget_internal_name(widget),a11y.ui_owner_link(widget)
    if previous and previous.identity==identity and previous.text==text and previous.widget==widget
            and previous.name==name and previous.link==link then
        previous.observed=frame
        return
    end
    a11y.native_list_selection={text=text,identity=identity,widget=widget,observed=frame,
        name=name,link=link}
end

-- The base carousel exposes 0x50 caption records. NationalitySelect instead
-- overrides its country renderer with filtered IDs; keep both layouts separate.
-- Its outer cursor selects the carousel, not an individual country caption.
-- C9D900/C9D860 select country IDs from the continent's filtered uint16 vector.
-- This override does not populate the generic carousel's 0x50 caption records.
function a11y.filtered_country_id(window,parent)
    local key=a11y.menu_read(parent,"u32")
    local offset,index=a11y.menu_read(parent+0x64,"u32"),a11y.menu_read(parent+0x68,"u32")
    local head=a11y.menu_read(window+0x170,"u64")
    if not key or key>4 or not offset or not index or not head or head<0x10000 then return nil end
    local at=a11y.menu_read(head+8,"u64")
    local seen={}
    for _=1,64 do
        if not at or at<0x10000 or at==head or seen[at] or a11y.menu_read(at+0x19,"u8")~=0 then return nil end
        seen[at]=true
        local current=a11y.menu_read(at+0x20,"u32")
        if current==nil then return nil end
        if current==key then
            local first,last=a11y.menu_read(at+0x28,"u64"),a11y.menu_read(at+0x30,"u64")
            if not first or first<0x10000 or not last or last<first or (last-first)%2~=0
                    or last-first>1024 or offset+index>=(last-first)/2 then return nil end
            local id=a11y.menu_read(first+(offset+index)*2,"u16")
            if not id or id>=0x1ff then return nil end
            return id,first+(offset+index)*2
        end
        at=a11y.menu_read(at+(current<key and 0x10 or 0),"u64")
    end
end

-- Read-only equivalent of CBBA20 -> 14BB0B0 -> 14B8060. Require an exact
-- native ID match; the game's missing-ID fallback to its first record is unsafe
-- for speech. Names come from the current database, not a hardcoded country map.
function a11y.country_name(id)
    local base=tonumber(process_base_u64)
    local manager=base and a11y.menu_read(base+0x3705e10,"u64")
    local database=manager and a11y.menu_read(manager+0x48,"u64")
    local count=database and a11y.menu_read(database+0x184b5e0,"u32")
    if not count or count<1 or count>512 then return nil end
    local low,high=0,count
    local first=database+0x1843f20
    while low<high do
        local mid=math.floor((low+high)/2)
        local packed=a11y.menu_read(first+mid*0x4c+0x48,"u32")
        if not packed then return nil end
        if packed%512<id then low=mid+1 else high=mid end
    end
    if low>=count then return nil end
    local record=first+low*0x4c
    local packed=a11y.menu_read(record+0x48,"u32")
    if not packed or packed%512~=id then return nil end
    local text=a11y.read_native_c_string(record,0x48)
    return text and text~="" and clean_text(text) or nil
end

function a11y.native_country_selection()
    local base=tonumber(process_base_u64)
    local snapshot=a11y.native_windows
    if not base or not snapshot then return nil end
    local work=a11y.render_read_work
    if work and work.country_selection~=nil then return work.country_selection or nil end
    local found
    for _,window in ipairs(snapshot.windows or {}) do
        local at=window.address
        local vt=window.enabled and a11y.menu_read(at,"u64")
        if vt==base+0x271f4d0 and a11y.menu_read(vt+0xd8,"u64")==base+0xc9d990
                and a11y.menu_read(vt+0x268,"u64")==base+0xc97190
                and a11y.menu_read(at+0x9b,"u8")==1 then
            local first,last=a11y.menu_read(at+0x100,"u64"),a11y.menu_read(at+0x108,"u64")
            local scroll,index=a11y.menu_read(at+0x118,"u32"),a11y.menu_read(at+0x11c,"u32")
            if first and first>=0x10000 and last and last>=first and (last-first)%0x70==0
                    and last-first<=512*0x70 and scroll and index and scroll+index<(last-first)/0x70 then
                local parent=first+(scroll+index)*0x70
                local special=a11y.menu_read(at+0x180,"u8")
                local category=a11y.menu_read(parent,"u32")
                local text,record
                if special==0 and category and category<=4 then
                    local id,cell=a11y.filtered_country_id(at,parent)
                    text,record=id and a11y.country_name(id),cell
                elseif special~=nil then
                    local children,finish=a11y.menu_read(parent+8,"u64"),a11y.menu_read(parent+0x10,"u64")
                    local offset,selected=a11y.menu_read(parent+0x64,"u32"),a11y.menu_read(parent+0x68,"u32")
                    if children and children>=0x10000 and finish and finish>=children and (finish-children)%0x50==0
                            and finish-children<=512*0x50 and offset and selected and offset+selected<(finish-children)/0x50 then
                        record=children+(offset+selected)*0x50
                        text=a11y.read_msvc_string(record+0x28)
                    end
                end
                if text and not a11y.empty_selection_caption(text) then
                    if found then return nil end
                    found={text=text,native_only=true,
                        identity="country:" .. at .. ":" .. window.root .. ":" .. parent .. ":" .. record}
                end
            end
        end
    end
    if work then work.country_selection=found or false end
    return found
end

function a11y.poll_native_country_selection()
    local context=a11y.read_context_state()
    if context.kind=="dialog" and (context.structural_question or context.structural_event or not a11y.native_country_active()) then return end
    local item=a11y.native_list_selection
    local current=a11y.native_country_selection()
    if current then
        if current.native_only then
            if not item or item.identity~=current.identity or item.text~=current.text then
                a11y.native_list_selection={text=current.text,identity=current.identity,native_only=true,observed=frame}
            end
        else a11y.observe_native_list_selection(current.text,current.identity,current.widget) end
        a11y.native_list_selection.country=true
    elseif a11y.native_list_selection and a11y.native_list_selection.country then
        a11y.native_list_selection=nil
    end
end

function a11y.native_list_delivery_allowed(origin)
    local item=a11y.native_list_selection
    if item and item.country then
        local current=a11y.native_country_selection()
        if not current or current.identity~=item.identity or current.text~=item.text then return false end
        if item.native_only then
            return item.identity==origin.identity and item.text==origin.text and a11y.native_owner_token()==origin.owner
        end
    end
    return item and item.identity==origin.identity and item.text==origin.text
        and item.widget==origin.widget and a11y.native_owner_token()==origin.owner
end

function a11y.native_country_active()
    local base=tonumber(process_base_u64)
    if not base then return false end
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        if window.enabled and (window.vtable or a11y.menu_read(window.address,"u64"))==base+0x271f4d0
                and a11y.menu_read(window.address,"u64")==base+0x271f4d0
                and a11y.menu_read(window.address+0x9b,"u8")==1 then return true end
    end
    return false
end

function a11y.process_native_list_focus(modal_blocked)
    local item=a11y.native_list_selection
    local context=a11y.read_context_state()
    if item and (item.nested or item.country) and context.kind=="dialog" and not context.structural_question and not context.structural_event
            and a11y.native_country_active() then
        a11y.reset_read_context("native-nested-selection")
        modal_focus_hold_until_ms=0;modal_blocked=false
        a11y.screen_title_hold_until_ms=0
    end
    if not item or (not item.committed and frame-(item.observed or -10000)>120) or modal_blocked or a11y.keyboard_window
            or a11y.read_context_state().kind=="dialog" then return false end
    if item.country and item.native_only then
        local current=a11y.native_country_selection()
        if not current or current.identity~=item.identity or current.text~=item.text then return false end
        local identity=(a11y.native_owner_token() or "") .. ":" .. item.identity .. ":" .. item.text
        if item.committed~=identity and item.speech_status~="failed-content" then
            a11y.commit_read_selection(item.text,identity,"native-list")
            local before=a11y.native_speech_last
            item.attempt=(item.attempt or 0)+1
            speak(item.text,true,true,"native-country:" .. identity .. ":" .. item.attempt)
            for index=before+1,a11y.native_speech_last do
                a11y.native_speech_queue[index].native_list={identity=item.identity,text=item.text,owner=a11y.native_owner_token(),state=item}
                item.committed=identity
            end
        end
        return true
    end
    local snapshot=a11y.native_windows
    local member=snapshot and snapshot.members and snapshot.members[item.widget]
    if not member or not member.active or not a11y.native_presentation_ready(item.widget) then return false end
    if snapshot.cursor_members and snapshot.cursor_members[item.widget]
            and not snapshot.selected_members[item.widget] then return false end
    if (item.name and a11y.widget_internal_name(item.widget)~=item.name)
            or (item.link and a11y.ui_owner_link(item.widget)~=item.link) then
        a11y.native_list_selection=nil;return false
    end
    -- Callbacks capture data before setters finish. Verify the actual rendered
    -- caption in the frame, then let this native component own its selection.
    local text=a11y.read_native_rendered_text(item.widget)
    if text~=item.text then
        if frame-item.observed>120 then a11y.native_list_selection=nil;return false end
        return true -- wait; a cached old caption cannot take over
    end
    local owner=a11y.native_owner_token()
    if not owner then return false end
    local identity=owner .. ":" .. item.identity .. ":" .. text
    if tonumber(ffi.C.GetTickCount64())<(a11y.screen_title_hold_until_ms or 0) then return true end
    local node=a11y.ui_model and a11y.ui_model.nodes[memory.hex(item.widget)]
    if not node or node.text~=text then a11y.on_observed_ui_text(item.widget,text,text,nil,true) end
    local before=a11y.native_speech_last
    a11y.deliver_selection_result(a11y.selection_result({text=text,widget=item.widget,
        identity=identity,source="native-list"}),{interrupt=true})
    if a11y.native_speech_last>before then
        item.committed=identity
        for index=before+1,a11y.native_speech_last do
            a11y.native_speech_queue[index].native_list={identity=item.identity,text=text,widget=item.widget,owner=owner,state=item}
        end
        log(string.format("[FLAccess] native-list-commit text=%q widget=%s",text,memory.hex(item.widget)))
    end
    return true
end

-- The league/team carousel renders nine records around its selection. At this
-- call site r13 is the visible-cell index (0..8) and r15 is the corresponding
-- data record. Cell 4 is the real selected record, independent of scroll
-- direction and of the widget addresses recycled by the UI.
function m.on_list_item_render(ctx, event_id, registers)
    if a11y.read_context_state().kind == "dialog" then return end
    local visible_index = tonumber(read_u64(registers.r13))
    if visible_index ~= 4 then
        return
    end

    local record = tonumber(read_u64(registers.r15))
    if not record or record < 0x10000 or not readable(record + 0x20, 0x20) then
        return
    end

    local text = a11y.read_msvc_string(record + 0x20)
    if not text or text == "" or is_noninteractive_text(text) then
        return
    end
    if a11y.game_plan_context == "Configurações táticas básicas"
            or a11y.game_plan_context == "Basic Tactical Settings"
            or a11y.game_plan_edit_contexts[a11y.game_plan_context] then
        -- This renderer is shared by carousels and game-plan background
        -- lists. Tactical headings and player headings are authoritative.
        return
    end
    local formation_context = a11y.game_plan_context == "Alterar formação"
        or a11y.game_plan_context == "Change Formation"
    local formation_inside = text:match("%((.-)%)")
    local compact_formation = formation_inside
        and formation_inside:gsub("%s+", "") or nil
    local formation_value = (compact_formation
            and compact_formation:match("^%d[%d%-]+$"))
        or text:match("^%d[%d%-]+$")
    if a11y.game_plan_active and formation_context and formation_value then
        a11y.game_plan_formation_active = true
    elseif a11y.game_plan_active then
        -- Both teams' formations are permanently rendered on the normal Game
        -- Plan pitch. They are display data, not the focused bottom command.
        return
    end

    -- r12 is the exact text node assigned immediately before c97408.
    a11y.observe_native_list_selection(text,"list:" .. memory.hex(record),tonumber(read_u64(registers.r12)))
end

-- Shared nested-carousel caption setter. Here RSI is the selected 0x50 child
-- record and RDI is its actual kind-19 text node. Capture before the setter;
-- process_native_list_focus verifies the rendered copy after it completes.
function m.on_nested_list_caption(ctx,event_id,registers)
    local context=a11y.read_context_state()
    if context.kind=="dialog" and (context.structural_question or context.structural_event or not a11y.native_country_active()) then return end
    local record=tonumber(read_u64(registers.rsi))
    local widget=tonumber(read_u64(registers.rdi))
    if not record or record<0x10000 or not widget or widget<0x10000 then return end
    local text=a11y.read_msvc_string(record+0x28)
    if text and not a11y.empty_selection_caption(text) then
        a11y.observe_native_list_selection(text,"nested-list:" .. memory.hex(record),widget)
        a11y.native_list_selection.nested=true
    end
end

-- Club selection uses a separate nine-cell renderer. r14 is its visible-cell
-- index and the game itself treats cell 4 as selected. Both native and
-- alternate/modded club-name branches build the displayed MSVC string in the
-- same stack slot immediately before assigning it to the UI widget.
function m.on_team_item_text(ctx, event_id, registers)
    if a11y.read_context_state().kind == "dialog" then return end
    local visible_index = tonumber(read_u64(registers.r14))
    if visible_index ~= 4 then
        return
    end

    local saved_rbp = tonumber(read_u64(registers.rbp))
    if not saved_rbp or saved_rbp < 0x10000 then
        return
    end
    local text = a11y.read_msvc_string(saved_rbp - 0x19)
    if not text or text == "" or is_noninteractive_text(text) then
        return
    end
    if a11y.game_plan_active then
        return
    end

    -- Both string branches pass this rdi node to e48bf0 after the hook.
    a11y.observe_native_list_selection(text,"team:" .. text,tonumber(read_u64(registers.rdi)))
end

function m.on_player_record_copy(ctx, event_id, registers)
    local operation = tonumber(ffi.cast("uint32_t", read_u64(registers.rax)))
    if operation == 2 then
        a11y.capture_player_record(read_u64(registers.rdx), "copy")
    end
end

function m.on_player_record_lookup(ctx, event_id, registers)
    a11y.capture_player_record(read_u64(registers.rax), "lookup")
end

function m.on_resolved_text(ctx, event_id, registers)
    local source = read_u64(registers.rax)
    local length = tonumber(read_u64(registers.r8))
    if not source or not length or length < 1 or length > 512 then
        return
    end

    local text=a11y.safe_memory_read(source,length)
    if not text then return end
    local zero = text:find("\0", 1, true)
    if zero then
        text = text:sub(1, zero - 1)
    end

    -- At this hook location, Sider's saved RSP is 64 bytes below the
    -- localization resolver caller's return address.
    local saved_rsp = read_u64(registers.rsp)
    local return_address=saved_rsp and read_u64(a11y.safe_memory_read(saved_rsp+64,8))
    if not return_address then return end
    local caller_rva = tonumber(return_address - process_base_u64)
    local text_id = tonumber(ffi.cast("uint32_t", read_u64(registers.rdi)))
    local resolved_text = clean_text(text)
    if resolved_text == "No String" or resolved_text == "/" then return end
    a11y.remember_player_style_text(text_id,resolved_text)
    a11y.detect_ui_language(resolved_text)
    -- Localization resolves words for hidden and future screens as well.
    -- Resolution alone must not open a dialog or announce a skip command.
    if caller_rva == 0xb22537 and resolved_text ~= "" then
        language_options[resolved_text] = true
    end
    local is_football_life_tooltip_part = text_id==13107593 or text_id==13107596
    -- The project description is passive information. Do not enqueue it as
    -- an automatic main-menu choice or make it hold navigation speech.
    if controller_labels[resolved_text] then
        local label = resolved_text
        local row = controller_rows[label] or {}
        controller_rows[label] = row
    end
    local controller_label = controller_tooltip_labels[text_id]
    if text_id == 13238441 then
        if active_controller_label == "Condição: Em casa" then
            controller_label = "Condição: Fora"
        else
            controller_label = "Condição: Em casa"
        end
    end
    if controller_label then
        active_controller_label = controller_label
        local row = controller_rows[controller_label]
        local value = controller_tooltip_values[text_id]
        if not value and row then
            value = row.value
        end
        announce_controller_row(controller_label, value)
        if a11y.read_tooltips then
            pending_controller_tooltip = clean_text(text)
            pending_controller_tooltip_label = controller_label
            controller_tooltip_due_ms = tonumber(ffi.C.GetTickCount64())
        end
    end
    if caller_rva == 0xe4901d then
        local widget=read_u64(a11y.safe_memory_read(saved_rsp+72,8))
        local spoken = clean_text(text)
        if widget >= 0x10000 and spoken ~= "" then
            local widget_key = memory.hex(widget)
            a11y.observe_ui_widget(widget,spoken)
            local previous_widget_text = standard_text_by_widget[widget_key]
            standard_text_by_widget[widget_key] = spoken
            local now_ms = tonumber(ffi.C.GetTickCount64())
            local is_game_plan_tactical_tooltip =
                a11y.game_plan_active
                and a11y.game_plan_active_tactical_label
                and frame - a11y.game_plan_active_tactical_frame <= 90
                and #spoken >= 35
                and not a11y.is_instruction_message(spoken)
                and not is_noninteractive_text(spoken)
            local is_active_tooltip = a11y.is_control_help(spoken)
                or is_game_plan_tactical_tooltip
                or (not a11y.is_instruction_message(spoken)
                    and active_control_row
                    and active_control_row.label_widget
                    and widget ~= active_control_row.label_widget
                    and now_ms - active_control_focused_ms <= 5000
                    and #spoken >= 35
                    and not is_noninteractive_text(spoken))
            if previous_widget_text ~= spoken then
                -- This localization call has a verified widget argument.
                -- Defer bound messages written before their window activates,
                -- just as the direct UI setter does.
                a11y.defer_bound_guidance(widget,spoken)
                announce_screen_title(spoken, widget_key, widget)
                -- Help for the focused control is a tooltip, not a modal
                -- message. Keep it out of the message queue so disabling
                -- tooltip reading suppresses every route to speech.
                if not is_active_tooltip then
                    remember_message_text(spoken, widget_key)
                end
                if not queue_startup_text(spoken, now_ms)
                        and is_plain_text(spoken)
                        and not is_noninteractive_text(spoken) then
                    speak(spoken,nil,nil,nil,widget)
                end
            end
            if is_modal_button(spoken) then
                last_modal_button_frame = frame
                register_dialog_option(spoken, widget, widget_key)
                if spoken ~= "OK" or not instruction_message_locked then
                    queue_recent_message()
                end
            end
            if a11y.read_tooltips and #spoken >= 35 and not is_noninteractive_text(spoken) then
                latest_generic_tooltip = spoken
                latest_generic_tooltip_widget = widget
                latest_generic_tooltip_ms = now_ms
            end
            if a11y.read_tooltips and is_active_tooltip then
                pending_controller_tooltip = spoken
                pending_controller_tooltip_label =
                    is_game_plan_tactical_tooltip
                        and a11y.game_plan_active_tactical_label
                        or (active_control_row and active_control_row.label)
                a11y.set_read_help(spoken, pending_controller_tooltip_label)
                active_controller_label = pending_controller_tooltip_label
                controller_tooltip_due_ms =
                    now_ms
            end
            if #spoken <= 60 and not audio_ids[text_id]
                    and not (a11y.widget_internal_name(widget) or ""):match("_value$")
                    and not non_control_labels[spoken]
                    and (controller_labels[spoken]
                        or not spoken:match("[%.%!%?]$"))
                    and not is_noninteractive_text(spoken)
                    and not is_splash_text(spoken)
                    and not looks_like_message(spoken, widget)
                    and not is_active_tooltip then
                local candidate_row = register_control_label(
                    spoken,
                    widget,
                    selector_role(spoken),
                    controller_labels[spoken] or false)
                bind_delayed_speed_slider(candidate_row)
            end
            if featured_initial_ids[text_id] or text_id==13107593 then
                main_menu_title_widget_key = widget_key
            end
            local is_main_menu_title = main_menu_title_widget_key == widget_key
                and ((text_id >= 60948000 and text_id <= 60949000) or text_id==13107593)
            if is_main_menu_title and (previous_widget_text ~= spoken
                    or featured_initial_ids[text_id]) then
                local is_initial_featured = featured_initial_ids[text_id]
                    and previous_widget_text == nil
                reset_navigation_generation()
                a11y.observe_ui_widget(widget,spoken)
                startup_complete = true
                startup_completed_frame = frame
                main_menu_focus_guard_until = frame + 4
                current_main_menu_title = spoken
                a11y.set_read_title(spoken)
                -- Speak now for navigation and retain a short fallback for the
                -- first main-menu frame, which can arrive just before Windows
                -- reports the game as foreground. Duplicate suppression keeps
                -- this from speaking twice during ordinary navigation.
                local title_needs_retry = not a11y.game_is_foreground()
                dynamic_text_candidate = title_needs_retry
                    and spoken .. ", item" or nil
                a11y.dynamic_text_origin=title_needs_retry and a11y.capture_speech_origin(widget) or nil
                dynamic_text_due_ms = title_needs_retry
                    and tonumber(ffi.C.GetTickCount64()) + 250 or nil
                main_menu_tooltip = nil
                main_menu_tooltip_due_ms = nil
                log(string.format(
                    "[FLAccess] main-menu-title widget=%s previous=%q text=%q",
                    widget_key,
                    previous_widget_text or "",
                    spoken))
                if not title_needs_retry then a11y.present_main_menu_choice(widget,spoken) end
            elseif main_menu_title_widget_key and not is_football_life_tooltip_part
                    and text_id >= 13107000 and text_id <= 13108000 then
                if a11y.read_tooltips then
                    main_menu_tooltip = spoken
                    a11y.main_menu_tooltip_choice=a11y.main_menu_choice_state
                    main_menu_tooltip_due_ms =
                        tonumber(ffi.C.GetTickCount64())
                end
            end
            if frame - last_widget_frame > 12 and widget_count > 0 then
                trace_log(string.format(
                    "[FLAccess] widget-generation-gap gap=%d",
                    frame - last_widget_frame))
            end
            last_widget_frame = frame
            local previous = widgets[text_id]
            if not previous then
                widget_count = widget_count + 1
            end
            widgets[text_id] = {
                address = widget,
                text = spoken,
                last_seen = frame,
            }
            if audio_ids[text_id] then
                last_audio_id = text_id
            end
            if not previous or previous.address ~= widget then
                trace_log(string.format(
                    "[FLAccess] widget id=%u text=%q address=%s",
                    text_id,
                    spoken,
                    memory.hex(widget)))
            end
        end
    end

    local key = tostring(text_id) .. "\0" .. text
    if seen[key] then
        return
    end
    seen[key] = true
    unique_count = unique_count + 1
    if unique_count > 4000 then
        return
    end
    trace_log(string.format(
        "[FLAccess] resolved id=%u text=%q length=%d caller_rva=%s",
        text_id,
        text,
        length,
        memory.hex(caller_rva)))
end

local function scan_dialog_focus()
    local yes = dialog_options["Sim"]
    local no = dialog_options["Não"]
    if not a11y.dialog_option_allowed(yes) or not a11y.dialog_option_allowed(no) then return nil,nil end
    if not yes or not no or yes.key == no.key
            or math.abs(yes.last_seen - no.last_seen) > 3
            or frame - math.max(yes.last_seen, no.last_seen) > 900 then
        return nil, nil
    end
    local function selected_at(offset)
        if not readable(yes.address + offset, 4)
                or not readable(no.address + offset, 4) then
            return nil
        end
        local yes_value = memory.unpack(
            "u32", memory.read(yes.address + offset, 4))
        local no_value = memory.unpack(
            "u32", memory.read(no.address + offset, 4))
        if yes_value == 1 and no_value ~= 1 then
            return "Sim"
        elseif no_value == 1 and yes_value ~= 1 then
            return "Não"
        end
        return nil
    end
    if dialog_preferred_offset then
        local selected = selected_at(dialog_preferred_offset)
        if selected then
            return selected, dialog_preferred_offset
        end
    end
    for _, offset in ipairs(dialog_focus_offsets) do
        local selected = selected_at(offset)
        if selected then
            return selected, offset
        end
    end
    return nil, nil
end

function a11y.dialog_option_allowed(option)
    return option and (not option.native_owner or option.native_owner==""
        or option.native_owner==a11y.native_owner_token())
        and a11y.native_presentation_ready(option.address)
end

local function dialog_is_active()
    local yes = dialog_options["Sim"]
    local no = dialog_options["Não"]
    return yes and no and yes.key ~= no.key
        and a11y.dialog_option_allowed(yes) and a11y.dialog_option_allowed(no)
        and math.abs(yes.last_seen - no.last_seen) <= 3
        and frame - math.max(yes.last_seen, no.last_seen) <= 900
end

function a11y.dismiss_dialog_for_focus(
        dialog_active, modal_focus_blocked, selected_entry, selected_activity)
    if not dialog_active or not selected_entry
            or is_modal_button(selected_entry.text) then
        return dialog_active, modal_focus_blocked, false
    end
    local yes = dialog_options["Sim"]
    local no = dialog_options["Não"]
    local last_button_seen = math.max(
        yes and yes.last_seen or -1,
        no and no.last_seen or -1)
    if not selected_activity or selected_activity <= last_button_seen + 3 then
        return dialog_active, modal_focus_blocked, false
    end

    -- Football Life leaves the old Sim/Não objects and their focus bits alive
    -- after closing this confirmation. A freshly activated non-button belongs
    -- to the destination screen and is the reliable dismissal signal.
    dialog_options = {}
    dialog_signature = nil
    dialog_preferred_offset = nil
    dialog_focus_candidate = nil
    dialog_focus_candidate_since = 0
    last_dialog_announcement = nil
    a11y.confirmation_dialog_until_frame = 0
    a11y.dialog_button_queued_for_message = false
    modal_focus_hold_until_ms = 0
    log(string.format(
        "[FLAccess] dialog-dismissed destination=%q",
        selected_entry.text))
    return false, false, true
end

local function process_dialog_focus(modal_focus_blocked, queue_after_message)
    if frame % 2 ~= 0
            or (modal_focus_blocked and not queue_after_message) then
        return
    end
    local dialog_selected, dialog_offset = scan_dialog_focus()
    local candidate = dialog_selected and
        (dialog_signature .. ":" .. dialog_selected) or nil
    if candidate ~= dialog_focus_candidate then
        dialog_focus_candidate = candidate
        dialog_focus_candidate_since = frame
    elseif candidate and frame - dialog_focus_candidate_since >= 4
            and candidate ~= last_dialog_announcement then
        last_dialog_announcement = candidate
        dialog_preferred_offset = dialog_offset
        log(string.format(
            "[FLAccess] dialog-focus offset=0x%x text=%q",
            dialog_offset,
            dialog_selected))
        local should_queue = queue_after_message
            and not a11y.dialog_button_queued_for_message
        a11y.commit_read_selection(dialog_selected .. ", botão selecionado",
            candidate, "dialog-answer")
        speak(dialog_selected .. ", botão selecionado", not should_queue)
        if should_queue then
            a11y.dialog_button_queued_for_message = true
        end
    end
end

local function process_delayed_speech(now_ms, modal_focus_blocked)
    if a11y.read_context_state().kind == "dialog" then
        a11y.clear_pending_tooltips()
        dynamic_text_candidate, dynamic_text_due_ms = nil, nil
        return
    end
    if a11y.read_tooltips and not modal_focus_blocked and controller_tooltip_due_ms
            and now_ms >= controller_tooltip_due_ms then
        local tooltip_key = (pending_controller_tooltip_label or "") .. "\0" ..
            (pending_controller_tooltip or "")
        if active_controller_label == pending_controller_tooltip_label
                and pending_controller_tooltip
                and pending_controller_tooltip ~= ""
                and tooltip_key ~= last_spoken_controller_tooltip_key then
            last_spoken_controller_tooltip_key = tooltip_key
            speak(pending_controller_tooltip, false)
        end
        controller_tooltip_due_ms = nil
    end
    if not modal_focus_blocked and dynamic_text_due_ms
            and now_ms >= dynamic_text_due_ms then
        if dynamic_text_candidate and dynamic_text_candidate ~= ""
                and (not a11y.dynamic_text_origin or a11y.speech_origin_allowed(a11y.dynamic_text_origin)) then
            speak(dynamic_text_candidate, false,nil,nil,a11y.dynamic_text_origin and a11y.dynamic_text_origin.address)
        end
        a11y.dynamic_text_origin=nil
        dynamic_text_candidate = nil
        dynamic_text_due_ms = nil
    end
    if a11y.read_tooltips and not modal_focus_blocked and main_menu_tooltip_due_ms
            and now_ms >= main_menu_tooltip_due_ms then
        local state=a11y.main_menu_tooltip_choice
        if state and state==a11y.main_menu_choice_state and a11y.main_menu_choice_active(state)
                and state.status~="delivered" then return end
        if state and state.status=="delivered" and a11y.main_menu_choice_active(state)
                and main_menu_tooltip and main_menu_tooltip~="" then
            local before=a11y.native_speech_last
            speak(main_menu_tooltip,false,nil,"main-tooltip:" .. state.key .. ":" .. state.text)
            for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].menu_tooltip=state end
        end
        main_menu_tooltip,main_menu_tooltip_due_ms,a11y.main_menu_tooltip_choice=nil,nil,nil
    end
end

local function log_focus_snapshot(counts, selected, selected_seen)
    local parts = {}
    for index, count in ipairs(counts) do
        if count > 0 and selected[index] then
            local entry = ui_focus_widgets[selected[index]]
            if entry then
                parts[#parts + 1] = string.format(
                    "0x%x=%q(age=%d,candidates=%d)",
                    ui_focus_offsets[index],
                    entry.text,
                    frame - (selected_seen[index] or frame),
                    count)
            end
        end
    end
    log("[FLAccess] focus-snapshot " .. table.concat(parts, " "))
end

function a11y.diagnostic_role(widget_key, entry)
    local row = control_rows_by_label_widget[widget_key]
        or control_row_by_value_widget[widget_key]
    if row then
        if row.native_slider then
            return "slider", row
        end
        return row.role or "control", row
    end
    if is_modal_button(entry.text) then
        return "dialog-button", nil
    end
    if a11y.game_plan_title_widgets[widget_key]
            and a11y.game_plan_screen_titles[entry.text] then
        return "screen-title", nil
    end
    if widget_key == a11y.game_plan_active_tactical_widget then
        return "tactical-control-heading", nil
    end
    if widget_key == a11y.game_plan_selected_heading_widget then
        return "selected-player-heading", nil
    end
    if a11y.game_plan_menu_items[entry.text] then
        return "menu-item", nil
    end
    if a11y.pre_match_actions[entry.text] then
        return "pre-match-action", nil
    end
    local asset_role = a11y.text_asset_role(entry.text)
    if asset_role and asset_role ~= "text" then
        return asset_role, nil
    end
    if a11y.is_instruction_message(entry.text) then
        return "instruction-dialog-text", nil
    end
    if looks_like_message(entry.text) then
        return "message-or-tooltip", nil
    end
    if is_noninteractive_text(entry.text) then
        return "noninteractive-text", nil
    end
    return "unknown-focusable", nil
end

function a11y.record_focus(kind, widget_key, entry, selected_offset,
        counts, selected, selected_seen, dense_virtual_list)
    if not a11y.diagnostic_mode or not entry then
        return
    end
    a11y.diagnostic_sequence = a11y.diagnostic_sequence + 1
    local role, row = a11y.diagnostic_role(widget_key, entry)
    local lines = {
        string.format(
            "EVENT %d frame=%d kind=%s widget=%s offset=0x%x age=%d dense_list=%s role=%s",
            a11y.diagnostic_sequence,
            frame,
            tostring(kind or "stable-focus"),
            widget_key,
            selected_offset or 0,
            frame - (entry.last_seen or frame),
            dense_virtual_list and "true" or "false",
            a11y.diagnostic_text(role)),
        string.format("text=%q", a11y.diagnostic_text(entry.text)),
    }
    local caller_rva = a11y.ui_text_caller_by_widget[widget_key]
    lines[#lines + 1] = "text_set_caller_rva=" ..
        (caller_rva and string.format("0x%x", caller_rva) or "unknown")
    lines[#lines + 1] = string.format(
        "screen_context heading=%q main_menu=%q recent_message=%q",
        a11y.diagnostic_text(recent_heading_text),
        a11y.diagnostic_text(current_main_menu_title),
        a11y.diagnostic_text(recent_message_text))
    if row then
        lines[#lines + 1] = string.format(
            "control label=%q value=%q type=%q label_widget=%s value_widget=%s native_slider=%s min=%s max=%s",
            a11y.diagnostic_text(row.label),
            a11y.diagnostic_text(row.value),
            a11y.diagnostic_text(row.role),
            tostring(row.label_widget_key or "nil"),
            tostring(row.value_widget_key or "nil"),
            row.native_slider and "true" or "false",
            tostring(row.minimum or "nil"),
            tostring(row.maximum or "nil"))
    end

    local address = entry.address
    lines[#lines + 1] = string.format(
        "widget_internal_name=%q source=msvc-string@+0x18",
        a11y.diagnostic_text(a11y.widget_internal_name(address)))
    if address and readable(address + 0x38, 8) then
        lines[#lines + 1] = "widget_relation_candidate=" ..
            a11y.diagnostic_hex(read_u64(memory.read(address + 0x38, 8))) ..
            " source=pointer@+0x38"
    end
    local raw = {}
    if address and readable(address, 0x40) then
        for offset = 0, 0x38, 8 do
            local value = read_u64(memory.read(address + offset, 8))
            raw[#raw + 1] = string.format(
                "+0x%02x=%s", offset, a11y.diagnostic_hex(value))
        end
        local vtable = read_u64(memory.read(address, 8))
        local vtable_key = a11y.diagnostic_hex(vtable)
        local class_id = a11y.diagnostic_class_ids[vtable_key]
        if not class_id then
            a11y.diagnostic_class_count = a11y.diagnostic_class_count + 1
            class_id = string.format(
                "class-%03d", a11y.diagnostic_class_count)
            a11y.diagnostic_class_ids[vtable_key] = class_id
        end
        local vtable_number = tonumber(vtable)
        local base_number = tonumber(process_base_u64)
        local rva = "outside-main-module"
        if vtable_number and base_number and vtable_number >= base_number
                and vtable_number < base_number + 0x40000000 then
            rva = string.format("0x%x", vtable_number - base_number)
        end
        lines[#lines + 1] = string.format(
            "object class=%s vtable=%s vtable_rva=%s raw_qwords={%s}",
            class_id,
            vtable_key,
            rva,
            table.concat(raw, ","))
    else
        lines[#lines + 1] = "object unreadable"
    end

    local focus_fields = {}
    for _, offset in ipairs(ui_focus_offsets) do
        local value = "unreadable"
        if address and readable(address + offset, 4) then
            value = tostring(memory.unpack(
                "u32", memory.read(address + offset, 4)))
        end
        focus_fields[#focus_fields + 1] = string.format(
            "+0x%x=%s", offset, value)
    end
    lines[#lines + 1] = "focus_fields={" ..
        table.concat(focus_fields, ",") .. "}"

    local banks = {}
    for index, count in ipairs(counts) do
        if count > 0 then
            local key = selected[index]
            local candidate = key and ui_focus_widgets[key] or nil
            banks[#banks + 1] = string.format(
                "+0x%x count=%d selected=%s text=%q age=%d",
                ui_focus_offsets[index],
                count,
                tostring(key or "nil"),
                a11y.diagnostic_text(candidate and candidate.text or ""),
                candidate and frame - (selected_seen[index] or frame) or -1)
        end
    end
    lines[#lines + 1] = "candidate_banks={" ..
        table.concat(banks, "; ") .. "}"

    local links = {}
    if address and readable(address, 0xf0) then
        for offset = 0, 0xe8, 8 do
            local pointer = read_u64(memory.read(address + offset, 8))
            local key = a11y.diagnostic_hex(pointer)
            local linked_text = ui_text_by_widget[key]
            if linked_text then
                links[#links + 1] = string.format(
                    "+0x%x=%s %q",
                    offset,
                    key,
                    a11y.diagnostic_text(linked_text))
                if #links >= 16 then
                    break
                end
            end
        end
    end
    lines[#lines + 1] = "known_widget_links={" ..
        table.concat(links, "; ") .. "}"

    local recent = {}
    for key, candidate in pairs(ui_focus_widgets) do
        local age = frame - (candidate.last_seen or frame)
        if age <= 120 then
            recent[#recent + 1] = {
                key = key,
                text = candidate.text,
                age = age,
            }
        end
    end
    table.sort(recent, function(left, right)
        if left.age == right.age then
            return left.key < right.key
        end
        return left.age < right.age
    end)
    local inventory = {}
    for index = 1, math.min(#recent, 40) do
        local candidate = recent[index]
        local observed = ui_focus_widgets[candidate.key]
        local candidate_address = observed and observed.address
        local relation = "unreadable"
        if candidate_address and readable(candidate_address + 0x38, 8) then
            relation = a11y.diagnostic_hex(read_u64(
                memory.read(candidate_address + 0x38, 8)))
        end
        inventory[#inventory + 1] = string.format(
            "%s %q age=%d name=%q relation=%s",
            candidate.key,
            a11y.diagnostic_text(candidate.text),
            candidate.age,
            a11y.diagnostic_text(a11y.widget_internal_name(candidate_address)),
            relation)
    end
    lines[#lines + 1] = string.format(
        "recent_screen_inventory count=%d shown=%d {%s}",
        #recent,
        #inventory,
        table.concat(inventory, "; "))

    local controls = {}
    for label, control in pairs(controller_rows) do
        controls[#controls + 1] = string.format(
            "%q type=%q value=%q label_widget=%s value_widget=%s created=%s value_frame=%s",
            a11y.diagnostic_text(label),
            a11y.diagnostic_text(control.role),
            a11y.diagnostic_text(control.value),
            tostring(control.label_widget_key or "nil"),
            tostring(control.value_widget_key or "nil"),
            tostring(control.created_frame or "nil"),
            tostring(control.value_frame or "nil"))
    end
    table.sort(controls)
    while #controls > 50 do
        table.remove(controls)
    end
    lines[#lines + 1] = "known_control_inventory={" ..
        table.concat(controls, "; ") .. "}"
    lines[#lines + 1] = ""
    a11y.diagnostic_write(lines)
end

function a11y.safe_record_focus(kind, selected_key, selected_entry,
        selected_offset, counts, selected, selected_seen, dense_virtual_list)
    -- Every memory access inside record_focus is guarded by readable().
    a11y.record_focus(
        kind,
        selected_key or "nil",
        selected_entry,
        selected_offset,
        counts,
        selected,
        selected_seen,
        dense_virtual_list)
end

function a11y.observe_diagnostic_focus(candidate_key, selected_key, selected_entry,
        selected_offset, counts, selected, selected_seen, dense_virtual_list)
    if not a11y.diagnostic_mode or not candidate_key or not selected_entry then
        return
    end
    local diagnostic_key = candidate_key .. ":" ..
        string.format("0x%x", selected_offset or 0)
    if diagnostic_key ~= a11y.diagnostic_candidate_key then
        a11y.diagnostic_candidate_key = diagnostic_key
        a11y.diagnostic_candidate_since = frame
        if frame - a11y.diagnostic_last_snapshot_frame >= 90 then
            a11y.diagnostic_last_snapshot_frame = frame
            a11y.safe_record_focus(
                "focus-snapshot",
                selected_key,
                selected_entry,
                selected_offset,
                counts,
                selected,
                selected_seen,
                dense_virtual_list)
        end
        return
    end
    if frame - a11y.diagnostic_candidate_since < 4
            or diagnostic_key == a11y.diagnostic_last_key then
        return
    end
    a11y.diagnostic_last_key = diagnostic_key
    a11y.safe_record_focus(
        "stable-focus",
        selected_key,
        selected_entry,
        selected_offset,
        counts,
        selected,
        selected_seen,
        dense_virtual_list)
end

-- Resolve one native reading authority before entering the compatibility scan.
-- Unknown components retain the compatibility path; no route guesses a label.
function a11y.dispatch_native_selection(modal_blocked,dialog_active)
    local route,handled="compatibility",false
    if a11y.selected_message_packet() then
        a11y.poll_selected_message();route,handled="selected-message",true
    elseif not dialog_active and a11y.poll_structured_record(modal_blocked) then
        route,handled="structured-record",true
    elseif a11y.process_engine_focus(modal_blocked) then
        route,handled="native-focus",true
    end
    local identity=tostring(a11y.native_owner_token()) .. ":" .. route
    if identity~=a11y.last_native_route then
        a11y.last_native_route=identity
        log("[FLAccess] reader-route kind=" .. route .. " owner=" .. tostring(a11y.native_owner_token()))
    end
    return handled
end

local function scan_current_ui_focus(modal_focus_blocked, dialog_active)
    if a11y.keyboard_window then return false end
    if a11y.native_windows_enabled and not a11y.native_presentation_ready() then return false end
    if a11y.dispatch_native_selection(modal_focus_blocked,dialog_active) then return true end
    if ui_focus_widget_count <= 0 then
        a11y.reset_focus_reuse_state()
        last_selected_ui_entry = nil
        return false
    end
    if frame < main_menu_focus_guard_until then
        return false
    end
    local counts = {}
    local selected = {}
    local selected_seen = {}
    local primary_candidates = {}
    for index = 1, #ui_focus_offsets do
        counts[index] = 0
        selected_seen[index] = -1
    end
    local command_owners = a11y.command_icon_owners()
    local game_plan_menu_bank_active = false
    local game_plan_menu_best_key
    local game_plan_menu_best_index
    local game_plan_menu_best_activation = -1
    for widget_key, entry in pairs(ui_focus_widgets) do
        if a11y.native_widget_allowed(entry.address) and not is_noninteractive_text(entry.text)
                and not (entry.text == "OK" and a11y.game_plan_active
                    and (a11y.game_plan_context ==
                            "Configurações táticas básicas"
                        or a11y.game_plan_context ==
                            "Basic Tactical Settings"))
                and readable(entry.address + 0xf0, 0x30) then
            local bytes = memory.read(entry.address + 0xf0, 0x30)
            local state = ui_focus_state[widget_key] or {}
            local activated = ui_focus_activated[widget_key] or {}
            ui_focus_state[widget_key] = state
            ui_focus_activated[widget_key] = activated
            for index, offset in ipairs(ui_focus_offsets) do
                local relative = offset - 0xf0
                local value = memory.unpack(
                    "u32", bytes:sub(relative + 1, relative + 4))
                local native = a11y.native_windows
                if index == 1 and native and native.cursor_members
                        and native.cursor_members[tonumber(entry.address)] then
                    value = native.selected_members[tonumber(entry.address)] and 1 or 0
                end
                if value == 1 and state[index] ~= 1 then
                    activated[index] = frame
                end
                state[index] = value
                local primary_flag = memory.unpack("u32", bytes:sub(0x15, 0x18)) == 1
                if native and native.cursor_members and native.cursor_members[tonumber(entry.address)] then
                    primary_flag = native.selected_members[tonumber(entry.address)] or false
                end
                if value == 1 and not a11y.is_command_legend(widget_key, primary_flag, command_owners) then
                    if index == 1 then
                        if a11y.ui_model then
                            a11y.ui_model.last_primary_edge = math.max(a11y.ui_model.last_primary_edge or -1,
                                activated[index] or -1)
                        end
                        primary_candidates[#primary_candidates + 1] = {
                            key=widget_key, edge=activated[index] or -1,
                        }
                    end
                    if a11y.game_plan_main_surface
                            and a11y.game_plan_menu_items[entry.text]
                            and (activated[index] or -1)
                                > game_plan_menu_best_activation then
                        game_plan_menu_best_activation = activated[index]
                        game_plan_menu_best_key = widget_key
                        game_plan_menu_best_index = index
                    end
                    if index == 5 and a11y.game_plan_active
                            and a11y.game_plan_menu_items[entry.text] then
                        game_plan_menu_bank_active = true
                    end
                    counts[index] = counts[index] + 1
                    local activity = math.max(
                        activated[index] or -1,
                        entry.last_seen or -1)
                    if activity > selected_seen[index] then
                        selected_seen[index] = activity
                        selected[index] = widget_key
                    end
                end
            end
        end
    end
    local selected_key
    local selected_offset
    local selected_offset_index
    local freshest_offset_index
    local freshest_seen = -1
    for index = 1, #ui_focus_offsets do
        if counts[index] > 0 and selected_seen[index] > freshest_seen then
            freshest_seen = selected_seen[index]
            freshest_offset_index = index
        end
    end
    -- League/club grids refresh several visible rows at 0x104 and 0x100.
    -- Prefer the freshest 0x100 row only while both banks belong to the same
    -- update cycle. Never lock a widget: recycled addresses caused stale
    -- leagues, players and pre-match items to leak into later screens.
    if not dialog_active and a11y.process_read_dialog_focus(primary_candidates) then return true end
    local dense_virtual_list = counts[1] >= 3 and counts[5] >= 3
    local game_plan_roster_offset_index = 10 -- 0xfc
    local primary_entry = selected[1] and ui_focus_widgets[selected[1]] or nil
    local context_entry = selected[5] and ui_focus_widgets[selected[5]] or nil
    local game_plan_roster_context = a11y.game_plan_active
        and a11y.game_plan_context
        and a11y.game_plan_edit_contexts[a11y.game_plan_context]
    local game_plan_settings_context = a11y.game_plan_active
        and game_plan_menu_bank_active
    local basic_settings_menu = a11y.game_plan_active
        and (a11y.game_plan_context == "Menu de configuração básica"
            or a11y.game_plan_context == "Basic Settings Menu")
    local edit_position_active = a11y.game_plan_active
        and (a11y.game_plan_context == "Escalação/Editar posição"
            or a11y.game_plan_context == "Team Sheet/Edit Position"
            or (frame - recent_heading_frame <= 120
                and (recent_heading_text == "Trocar ícone de jog."
                    or recent_heading_text == "Change Player Icon")))
    local recent_game_plan_player = edit_position_active
        and counts[game_plan_roster_offset_index] > 0
        and frame - selected_seen[game_plan_roster_offset_index] <= 30
    local game_plan_setting_offset_index
    local game_plan_setting_activation = -1
    local basic_menu_offset_index
    local basic_menu_activation = -1
    local game_plan_player_header_offset_index
    local game_plan_player_header_seen = -1
    if edit_position_active then
        for index = 1, #ui_focus_offsets do
            local entry = selected[index] and ui_focus_widgets[selected[index]] or nil
            if entry and entry.text:match("^%d+%s+%S")
                    and selected_seen[index] > game_plan_player_header_seen then
                game_plan_player_header_seen = selected_seen[index]
                game_plan_player_header_offset_index = index
            end
        end
    end
    if game_plan_settings_context then
        for index = 1, #ui_focus_offsets do
            local entry = selected[index] and ui_focus_widgets[selected[index]] or nil
            local activation = selected[index]
                and ui_focus_activated[selected[index]]
                and ui_focus_activated[selected[index]][index] or -1
            if entry and (a11y.game_plan_menu_items[entry.text]
                    or controller_labels[entry.text])
                    and activation > game_plan_setting_activation then
                game_plan_setting_activation = activation
                game_plan_setting_offset_index = index
            end
        end
    end
    if basic_settings_menu then
        for index = 1, #ui_focus_offsets do
            local entry = selected[index]
                and ui_focus_widgets[selected[index]] or nil
            local activation = selected[index]
                and ui_focus_activated[selected[index]]
                and ui_focus_activated[selected[index]][index] or -1
            if entry and not a11y.game_plan_title_widgets[selected[index]]
                    and (a11y.game_plan_menu_items[entry.text]
                    or (a11y.game_plan_basic_prompt_active
                        and a11y.game_plan_basic_prompt_items[entry.text]))
                    and (activation > basic_menu_activation
                        or (activation == basic_menu_activation
                            and selected_seen[index] >
                                (basic_menu_offset_index
                                    and selected_seen[basic_menu_offset_index]
                                    or -1))) then
                basic_menu_activation = activation
                basic_menu_offset_index = index
            end
        end
    end
    local primary_is_game_plan_control = primary_entry
        and (a11y.game_plan_menu_items[primary_entry.text]
            or a11y.game_plan_basic_prompt_items[primary_entry.text]
            or primary_entry.text:match("%(%s*[%d%-]+%s*%)")
            or primary_entry.text:match("^%d[%d%-]+$"))
    if a11y.game_plan_main_surface and game_plan_menu_best_key
            and frame - game_plan_menu_best_activation <= 120 then
        -- Player cards can refresh after the focused command and replace the
        -- per-bank freshest entry. Select the command by its focus edge.
        selected[game_plan_menu_best_index] = game_plan_menu_best_key
        selected_seen[game_plan_menu_best_index] =
            game_plan_menu_best_activation
        selected_offset_index = game_plan_menu_best_index
    elseif basic_settings_menu then
        -- Team and player cards keep their focus flags behind this menu.
        -- Only its actual commands and an open Use/Do not use dialog are
        -- eligible. Text can update without a 0->1 focus edge, so a stale
        -- activation alone cannot make the whole menu permanently silent.
        if basic_menu_offset_index
                and (frame - basic_menu_activation <= 120
                    or (selected[basic_menu_offset_index]
                        and frame - (ui_focus_widgets[
                            selected[basic_menu_offset_index]].last_seen
                            or frame) <= 12)) then
            selected_offset_index = basic_menu_offset_index
        else
            if a11y.diagnostic_mode and frame - a11y.navigation_frame <= 2
                    and selected[1] then
                a11y.record_focus("unresolved-game-plan",
                    selected[1], ui_focus_widgets[selected[1]],
                    ui_focus_offsets[1], counts, selected, selected_seen,
                    dense_virtual_list)
            end
            return false
        end
    elseif a11y.game_plan_active and primary_is_game_plan_control then
        -- Menus and formation lists expose the real selection at 0x104.
        -- Player cards at 0xfc keep animating behind them.
        selected_offset_index = 1
    elseif edit_position_active and game_plan_player_header_offset_index then
        -- The numbered heading is the only object tied to the selected
        -- footballer. The 0xfc bank contains every card being redrawn.
        selected_offset_index = game_plan_player_header_offset_index
    elseif edit_position_active then
        -- Silence is preferable to announcing a random background player
        -- while the selected-player heading is temporarily unavailable.
        return false
    elseif game_plan_settings_context then
        -- While this menu opens, 0x100 contains every visible entry and old
        -- players. A submenu may use a different bank, so prefer the control
        -- whose focus bit was most recently activated; fall back to 0x104.
        if game_plan_setting_offset_index
                and frame - game_plan_setting_activation <= 90 then
            selected_offset_index = game_plan_setting_offset_index
        elseif counts[1] > 0 then
            selected_offset_index = 1
        end
    elseif recent_game_plan_player then
        selected_offset_index = game_plan_roster_offset_index
    elseif dense_virtual_list then
        -- 0x104 is the actual selected row. 0x100 is the previous row: for
        -- example, while the game selects LaLiga 2 it still exposes LaLiga at
        -- 0x100. This applies to clubs and also avoids stale "Confirmar" rows.
        selected_offset_index = 1
    elseif counts[1] > 0 then
        -- Ordinary menus, pre-match actions and settings consistently expose
        -- their real selection at 0x104. Player names and hidden selectors on
        -- nearby offsets are refreshed continuously and otherwise steal the
        -- "freshest" heuristic even while their focus bits are stale.
        selected_offset_index = 1
    elseif ui_focus_preferred_offset_index
            and counts[ui_focus_preferred_offset_index] > 0 then
        selected_offset_index = ui_focus_preferred_offset_index
    elseif freshest_offset_index then
        selected_offset_index = freshest_offset_index
    end
    local now_ms = tonumber(ffi.C.GetTickCount64())
    if modal_focus_blocked or now_ms < modal_focus_hold_until_ms + 1500 then
        local freshest_button_seen = -1
        for index = 1, #ui_focus_offsets do
            local button_entry = selected[index]
                and ui_focus_widgets[selected[index]] or nil
            if button_entry and is_modal_button(button_entry.text)
                    and selected_seen[index] >= freshest_seen - 3
                    and selected_seen[index] > freshest_button_seen then
                freshest_button_seen = selected_seen[index]
                selected_offset_index = index
            end
        end
    end
    if selected_offset_index then
        local selection_reason = "legacy-adapter"
        if selected_offset_index == 1 and not a11y.game_plan_active
                and not a11y.pre_match_active and not a11y.cup_group_table_active
                and not modal_focus_blocked and not dialog_active then
            local resolved, reason = a11y.resolve_primary_focus(primary_candidates)
            selection_reason = reason
            if not resolved then
                if a11y.diagnostic_mode
                        and frame - a11y.diagnostic_last_snapshot_frame >= 60 then
                    a11y.safe_record_focus("unresolved-structural",
                        selected[1], ui_focus_widgets[selected[1]],
                        0x104, counts, selected, selected_seen, dense_virtual_list)
                end
                last_selected_ui_entry = nil
                a11y.reset_focus_reuse_state()
                return false
            end
            selected[1] = resolved.key
        end
        if a11y.ui_model then a11y.ui_model.focus_reason = selection_reason end
        selected_key = selected[selected_offset_index]
        selected_offset = ui_focus_offsets[selected_offset_index]
    end
    local selected_entry = selected_key and ui_focus_widgets[selected_key] or nil
    if selected_entry and selected_offset ~= 0x104
            and not a11y.game_plan_active and not a11y.pre_match_active
            and not a11y.stadium_active and not a11y.cup_group_table_active
            and not is_modal_button(selected_entry.text)
            and not (control_rows_by_label_widget[selected_key]
                and control_rows_by_label_widget[selected_key].is_control)
            and not (control_row_by_value_widget[selected_key]
                and control_row_by_value_widget[selected_key].is_control) then
        -- Other state banks also belong to noninteractive overlays (the
        -- captured music artist was at 0x114/0x100). Only mapped controls or
        -- a verified adapter can grant those banks focus authority.
        a11y.reset_focus_reuse_state()
        last_selected_ui_entry = nil
        return false
    end
    if selected_entry and selected_offset ~= 0x104
            and not a11y.game_plan_active and not a11y.pre_match_active
            and not a11y.stadium_active and not a11y.cup_group_table_active
            and not dialog_active and not modal_focus_blocked
            and not a11y.secondary_focus_is_current(selected_key, selected_offset_index) then
        if a11y.ui_model then a11y.ui_model.focus_reason = "stale-secondary-focus" end
        a11y.reset_focus_reuse_state()
        last_selected_ui_entry = nil
        return false
    end
    a11y.track_control_focus(selected_key)
    last_selected_ui_entry = selected_entry
    local preserved_pre_match_row = selected_key
        and control_rows_by_label_widget[selected_key] or nil
    if not (a11y.pre_match_active and preserved_pre_match_row
            and a11y.pre_match_actions[preserved_pre_match_row.label]) then
        preserved_pre_match_row = nil
    end
    local inferred_pre_match_text
    local selected_activity = selected_offset_index
        and selected_seen[selected_offset_index] or nil
    local recent_navigation = frame - a11y.navigation_frame <= 20
    if a11y.pre_match_active and not preserved_pre_match_row
            and selected_entry
            and not a11y.pre_match_actions[selected_entry.text]
            and selected_activity
            and ((recent_navigation
                    and ((a11y.navigation_action == "left"
                            and (a11y.pre_match_last_action == "Início"
                                or a11y.pre_match_last_action == "Kick Off"))
                        or (a11y.navigation_action == "right"
                            and (a11y.pre_match_last_action == "Uniforme"
                                or a11y.pre_match_last_action == "Uniform"))))
                or (frame - selected_activity > 30
                    and (a11y.pre_match_last_action == "Uniforme"
                        or a11y.pre_match_last_action == "Uniform"
                        or a11y.pre_match_last_action == "Início"
                        or a11y.pre_match_last_action == "Kick Off"
                        or a11y.pre_match_last_action == "Plano de jogo"
                        or a11y.pre_match_last_action == "Game Plan"))) then
        inferred_pre_match_text = a11y.ui_language == "pt"
            and "Estádio" or "Stadium"
    end
    local selected_focus_text = preserved_pre_match_row
        and preserved_pre_match_row.label
        or inferred_pre_match_text
        or (selected_entry and selected_entry.text or nil)
    local primary_edge = selected_key and ui_focus_activated[selected_key]
        and ui_focus_activated[selected_key][1] or -1
    if a11y.transition_focus_blocked(selected_key, selected_entry, selected_offset, primary_edge, now_ms) then
        return false
    end
    local selected_formation_inside = selected_focus_text
        and selected_focus_text:match("%((.-)%)") or nil
    local selected_compact_formation = selected_formation_inside
        and selected_formation_inside:gsub("%s+", "") or nil
    local selected_is_formation = selected_focus_text and
        ((selected_compact_formation
                and selected_compact_formation:match("^%d[%d%-]+$"))
            or selected_focus_text:match("^%d[%d%-]+$"))
    if a11y.game_plan_active and selected_focus_text
            and a11y.game_plan_menu_items[selected_focus_text]
            and selected_activity and frame - selected_activity <= 12
            and not a11y.game_plan_edit_contexts[a11y.game_plan_context]
            and a11y.game_plan_context ~= "Configurações táticas básicas"
            and a11y.game_plan_context ~= "Basic Tactical Settings" then
        a11y.game_plan_last_menu_focus = selected_focus_text
    end
    if a11y.pre_match_active and selected_focus_text
            and not a11y.pre_match_actions[selected_focus_text]
            and not inferred_pre_match_text
            and not is_modal_button(selected_focus_text) then
        -- Game Plan widgets continue toggling focus bits behind pre-match.
        -- Ignore them without replacing the current candidate; otherwise the
        -- real horizontal action never survives the debounce interval.
        return false
    end
    if a11y.game_plan_main_surface and selected_focus_text
            and not a11y.game_plan_menu_items[selected_focus_text]
            and not is_modal_button(selected_focus_text) then
        -- Player names and both teams' formations are display-only on the
        -- overview. The five bottom commands are the only actionable focus.
        return false
    end
    if selected_focus_text
            and a11y.game_plan_basic_prompt_items[selected_focus_text]
            and not a11y.game_plan_basic_prompt_active then
        -- A closed Basic Settings prompt survives in the widget pool. Its
        -- stale focus flag used to say "Usar, selecionado" between players.
        return false
    end
    if a11y.ignore_cup_group_focus(selected_focus_text) then
        return false
    end
    if selected_focus_text == "OK" and last_screen_title_key
            and not pending_message_text
            and now_ms < a11y.screen_title_hold_until_ms + 2000 then
        -- Title and lone OK commonly precede a notice whose paragraph is
        -- created later. Give that text hook time to claim speech priority.
        return false
    end
    local candidate_key = selected_entry and
        a11y.ui_focus_identity(selected_key, selected_focus_text) or nil
    if not candidate_key and not modal_focus_blocked and not dialog_active then
        if a11y.ui_model then a11y.ui_model.focus_reason = "no-selection" end
        a11y.reset_focus_reuse_state()
    end
    if pending_message_text ~= nil then
        -- The game's focus widget may be ready before its dialog text hook.
        -- Let the paragraph enter Prism first, then queue its button.
        a11y.capture_pending_modal_button(selected_key, selected_entry, selected_offset,
            selected_key and ui_focus_activated[selected_key] and ui_focus_activated[selected_key][1])
        ui_focus_candidate_key = candidate_key
        ui_focus_candidate_since = frame
        return selected_entry ~= nil
    end
    local pre_match_action = selected_focus_text and a11y.pre_match_active
        and a11y.pre_match_actions[selected_focus_text] or false
    local dialog_dismissed
    dialog_active, modal_focus_blocked, dialog_dismissed =
        a11y.dismiss_dialog_for_focus(
            dialog_active,
            modal_focus_blocked,
            selected_entry,
            selected_activity)
    -- Let fresh destination focus expire a closed dialog, but leave an
    -- active dialog exclusively to its own reader (including Sim/Não).
    if dialog_active then return selected_entry ~= nil end
    local fast_known_focus = selected_key
        and (control_rows_by_label_widget[selected_key]
            or control_row_by_value_widget[selected_key]
            or controller_labels[selected_focus_text]
            or a11y.fast_focus_items[selected_focus_text])
    local focus_debounce_frames = (selected_focus_text
            and is_modal_button(selected_focus_text) and 10)
        or pre_match_action and 4
        or (game_plan_roster_context and selected_offset == 0xfc and 18)
        or (recent_navigation and selected_offset == 0x104
            and selected_activity and frame - selected_activity <= 2
            and 0)
        -- 0x104 is the verified active-focus bank on ordinary PES menus.
        -- Hidden widgets may retain bits elsewhere, but cannot enter this
        -- fast path unless the selection resolver chose this exact bank.
        or (selected_offset == 0x104 and 4)
        or (fast_known_focus and 4)
        or 12
    a11y.observe_diagnostic_focus(
        candidate_key,
        selected_key,
        selected_entry,
        selected_offset,
        counts,
        selected,
        selected_seen,
        dense_virtual_list)
    if edit_position_active and selected_focus_text
            and selected_focus_text:match("^%d+%s+%S") then
        -- Player headings are updated in place. Their dedicated delayed
        -- reader follows that update directly; the generic focus debounce
        -- would otherwise miss fast navigation or repeat the same player.
        return selected_entry ~= nil
    end
    local selected_is_modal_button = selected_entry
        and is_modal_button(selected_entry.text)
    local selected_is_known_control = selected_key
        and (control_rows_by_label_widget[selected_key]
            or control_row_by_value_widget[selected_key])
    local selected_is_startup_item = selected_is_modal_button
        or selected_is_known_control
        or (selected_entry and language_options[selected_entry.text])
    local changed_after_message = modal_focus_blocked
        and selected_offset_index
        and selected_seen[selected_offset_index] > modal_message_spoken_frame + 2
    -- Keep the initial item silent after an instructional paragraph. There is
    -- no reliable NVDA completion callback here. A real arrow movement changes
    -- the focus after the paragraph began and is announced immediately.
    -- A focus seen while a title/dialog speaks has not been announced yet.
    -- Do not mark it as read: the same row must still be available afterward.
    local startup_focus_allowed = selected_entry and (
        (startup_complete and frame - startup_completed_frame >= 12)
        or selected_is_startup_item)
    if dialog_dismissed and pre_match_action and startup_focus_allowed then
        a11y.pre_match_entry_pending = false
        a11y.pre_match_last_action = selected_focus_text
        last_ui_focus_announcement = candidate_key
        ui_focus_candidate_key = candidate_key
        ui_focus_candidate_since = frame
        a11y.commit_read_selection(ui_focus_speech(selected_focus_text), candidate_key, "adapter-focus")
        if a11y.pre_match_notice_text then
            speak(a11y.pre_match_notice_text)
            a11y.offer_adapter_selection(ui_focus_speech(selected_focus_text),candidate_key,selected_entry.address,false)
        else
            a11y.offer_adapter_selection(ui_focus_speech(selected_focus_text),candidate_key,selected_entry.address)
        end
        return true
    end
    if a11y.pre_match_entry_pending and pre_match_action
            and startup_focus_allowed then
        if frame > a11y.pre_match_entry_guard_until_frame then
            a11y.pre_match_entry_pending = false
        elseif modal_message_spoken_frame == frame
                and pending_message_text == nil then
            a11y.pre_match_entry_pending = false
            a11y.pre_match_last_action = selected_focus_text
            last_ui_focus_announcement = candidate_key
            ui_focus_candidate_key = candidate_key
            ui_focus_candidate_since = frame
            a11y.commit_read_selection(ui_focus_speech(selected_focus_text), candidate_key, "adapter-focus")
            a11y.offer_adapter_selection(ui_focus_speech(selected_focus_text),candidate_key,selected_entry.address,false)
            return true
        else
            ui_focus_candidate_key = candidate_key
            ui_focus_candidate_since = frame
            return true
        end
    end
    if candidate_key ~= ui_focus_candidate_key then
        log_focus_snapshot(counts, selected, selected_seen)
        ui_focus_candidate_key = candidate_key
        ui_focus_candidate_since = frame
        local game_plan_menu_navigation = recent_navigation
            and a11y.game_plan_active
            and ((a11y.game_plan_basic_prompt_active
                    and a11y.game_plan_basic_prompt_items[selected_focus_text])
                or ((a11y.navigation_action == "up"
                        or a11y.navigation_action == "down")
                    and selected_is_formation
                    and (a11y.game_plan_context == "Alterar formação"
                        or a11y.game_plan_context == "Change Formation"))
                or (a11y.game_plan_menu_items[selected_focus_text]
                    and not a11y.game_plan_edit_contexts[
                        a11y.game_plan_context]
                    and a11y.game_plan_context ~=
                        "Configurações táticas básicas"
                    and a11y.game_plan_context ~=
                        "Basic Tactical Settings"
                    and not a11y.game_plan_formation_active))
        if game_plan_menu_navigation and startup_focus_allowed
                and candidate_key ~= last_ui_focus_announcement then
            -- Known Game Plan rows are authoritative and often exist for only
            -- one render frame between animated player-card refreshes.
            last_ui_focus_announcement = candidate_key
            ui_focus_preferred_offset_index = selected_offset_index
            local announcement = a11y.game_plan_focus_speech(
                selected_focus_text, selected_key)
            if announcement then
                a11y.commit_read_selection(announcement, candidate_key, "adapter-focus")
                a11y.offer_adapter_selection(announcement,candidate_key,selected_entry.address)
            end
        elseif pre_match_action and startup_focus_allowed
                and (not dialog_active or selected_is_modal_button)
                and candidate_key ~= last_ui_focus_announcement then
            -- Pre-match recreates unrelated widgets continuously, resetting
            -- the generic debounce before it can finish. Its six known action
            -- strings already identify the selected command reliably.
            last_ui_focus_announcement = candidate_key
            ui_focus_preferred_offset_index = selected_offset_index
            a11y.pre_match_last_action = selected_focus_text
            a11y.commit_read_selection(ui_focus_speech(selected_focus_text), candidate_key, "adapter-focus")
            a11y.offer_adapter_selection(ui_focus_speech(selected_focus_text),candidate_key,selected_entry.address)
        end
    elseif candidate_key
            and frame - ui_focus_candidate_since >= focus_debounce_frames
            and (not modal_focus_blocked or changed_after_message
                or pre_match_action)
            and startup_focus_allowed
            and (not dense_virtual_list or a11y.game_plan_active
                or a11y.cup_group_table_active
                or selected_is_startup_item)
            and (not dialog_active or selected_is_modal_button)
            and candidate_key ~= last_ui_focus_announcement then
        last_ui_focus_announcement = candidate_key
        if selected_key ~= main_menu_title_widget_key then
            dynamic_text_candidate = nil
            dynamic_text_due_ms = nil
            main_menu_tooltip = nil
            main_menu_tooltip_due_ms = nil
        end
        log(string.format(
            "[FLAccess] ui-focus offset=0x%x widget=%s text=%q reason=%s identity=%s",
            selected_offset,
            selected_key,
            selected_entry.text,
            a11y.ui_model and a11y.ui_model.focus_reason or "legacy-adapter",
            candidate_key))
        ui_focus_preferred_offset_index = selected_offset_index
        a11y.commit_read_selection(ui_focus_speech(selected_focus_text), candidate_key,
            selected_offset == 0x104 and "primary-focus" or "adapter-focus")
        local selected_control = control_rows_by_label_widget[selected_key]
            or (controller_labels[selected_entry.text]
                and controller_rows[selected_entry.text])
        if preserved_pre_match_row then
            selected_control = nil
        end
        if selected_control
                and selected_control.label ~= selected_entry.text then
            selected_control = nil
        end
        local selected_value_control =
            control_row_by_value_widget[selected_key]
        local stadium_control = selected_offset == 0x104
            and stadium_control_for_entry(selected_key, selected_entry) or nil
        local handled_control = false
        local now_ms = tonumber(ffi.C.GetTickCount64())
        local tactical_row
        if a11y.game_plan_active
                and (a11y.game_plan_context ==
                        "Configurações táticas básicas"
                    or a11y.game_plan_context ==
                        "Basic Tactical Settings")
                and a11y.game_plan_active_tactical_label
                and frame - a11y.game_plan_active_tactical_frame <= 90 then
            tactical_row = controller_rows[
                a11y.game_plan_active_tactical_label]
        end
        local formation_inside = selected_focus_text:match("%((.-)%)")
        local compact_formation = formation_inside
            and formation_inside:gsub("%s+", "") or nil
        local formation_context = a11y.game_plan_context == "Alterar formação"
            or a11y.game_plan_context == "Change Formation"
        local formation_text = a11y.game_plan_active and formation_context
            and ((compact_formation
                    and compact_formation:match("^%d[%d%-]+$"))
                or selected_focus_text:match("^%d[%d%-]+$"))
        if formation_text then
            a11y.game_plan_formation_active = true
        end
        if selected_control and selected_control.native_slider then
            active_control_row = selected_control
            active_controller_label = selected_control.label
            a11y.game_plan_active_tactical_label = selected_control.label
            a11y.game_plan_active_tactical_value = selected_control.value
            a11y.game_plan_active_tactical_frame = frame
            announce_control(selected_control)
            handled_control = true
        elseif tactical_row then
            -- A single live heading contains authoritative label and value.
            -- Ignore stale focus bits belonging to the other rendered rows.
            announce_control(tactical_row)
            handled_control = true
        elseif formation_text then
            local announcement = a11y.game_plan_focus_speech(
                selected_focus_text,
                selected_key)
            if announcement then
                a11y.offer_adapter_selection(announcement,candidate_key,selected_entry.address)
            end
            handled_control = true
        elseif a11y.game_plan_formation_active then
            -- Formation lists redraw player names and old tactical values in
            -- the same focus banks. Only the formation row is interactive.
            handled_control = true
        elseif a11y.game_plan_active
                and not a11y.game_plan_edit_contexts[a11y.game_plan_context]
                and a11y.game_plan_context ~= "Configurações táticas básicas"
                and a11y.game_plan_context ~= "Basic Tactical Settings"
                and a11y.game_plan_menu_items[selected_focus_text] then
            local announcement = a11y.game_plan_focus_speech(
                selected_focus_text,
                selected_key)
            if announcement then
                a11y.offer_adapter_selection(announcement,candidate_key,selected_entry.address)
            end
            handled_control = true
        elseif stadium_control then
            if active_control_row == stadium_control then
                announce_control_value(stadium_control, selected_entry.text)
            else
                announce_control(stadium_control)
            end
            handled_control = true
        elseif focused_control_hint
                and now_ms - focused_control_hint_ms <= 1500
                and selected_entry.text ~= focused_control_hint
                and a11y.valid_control_value(
                    selected_entry.address, selected_entry.text) then
            local hinted_row = controller_rows[focused_control_hint] or {
                label = focused_control_hint,
                role = "seletor",
                label_widget_key = "hint:" .. focused_control_hint,
                is_control = true,
            }
            hinted_row.value = selected_entry.text
            controller_rows[focused_control_hint] = hinted_row
            announce_control(hinted_row)
            focused_control_hint = nil
            handled_control = true
        elseif selected_control and (selected_control.is_control
                or (selected_control.value
                    and selected_control.value ~= ""
                    and not is_modal_button(selected_control.value)
                    and not non_control_labels[selected_control.label])) then
            announce_control(selected_control)
            handled_control = true
        elseif selected_value_control and (selected_value_control.is_control
                or (selected_value_control.value
                    and selected_value_control.value ~= ""
                    and not is_modal_button(selected_value_control.value)
                    and not non_control_labels[selected_value_control.label]))
                and a11y.valid_control_value(
                    selected_entry.address, selected_entry.text) then
            announce_control_value(
                selected_value_control,
                selected_entry.text)
            handled_control = true
        elseif active_control_row
                and not active_control_row.native_slider
                and not active_control_row.external_value
                and not a11y.game_plan_active
                and now_ms - active_control_focused_ms <= 500
                and selected_entry.address ~= active_control_row.label_widget
                and not control_rows_by_label_widget[selected_key]
                and a11y.valid_control_value(
                    selected_entry.address, selected_entry.text) then
            local attached = attach_control_value(
                active_control_row,
                selected_entry.address,
                selected_entry.text)
            if attached then
                announce_control_value(active_control_row, selected_entry.text)
                handled_control = true
            end
        end
        if not handled_control then
                if pre_match_action then
                    a11y.pre_match_last_action = selected_focus_text
                end
                local announcement = a11y.cup_group_team_speech(
                    selected_focus_text,
                    selected_key) or a11y.game_plan_focus_speech(
                        selected_focus_text,
                        selected_key)
                if announcement then
                    a11y.commit_read_selection(announcement, candidate_key, "adapter-focus")
                    a11y.offer_adapter_selection(announcement,candidate_key,selected_entry.address)
                end
                -- Modal scheduling belongs to the common speech boundary.
        end
    end
    return selected_entry ~= nil
end

function a11y.tooltip_selection_stamp()
    local parts={}
    for _,window in ipairs(a11y.native_windows and a11y.native_windows.windows or {}) do
        local d=window.enabled and window.cursor_detail
        if d and d.selected then
            parts[#parts+1]=table.concat({window.address,window.root or 0,d.group_index or -1,d.item_index or -1,d.selected},":")
        end
    end
    if #parts==0 then return nil end
    table.sort(parts);return table.concat(parts,"|")
end

function a11y.common_tooltip_allowed(stamp)
    if a11y.tooltip_selection_stamp()~=stamp.selection then return false end
    for _,part in ipairs(stamp.parts) do if not a11y.content_review_allowed(part) then return false end end
    return true
end

function a11y.poll_common_tooltip()
    local context=a11y.read_context_state()
    if not a11y.read_tooltips or context.structural_question or context.structural_event
            or a11y.keyboard_window or a11y.selected_message_packet() then return end
    local selection=a11y.tooltip_selection_stamp()
    if not selection then a11y.common_tooltip=nil;return end
    if not a11y.tooltip_dirty and a11y.tooltip_last_selection==selection then return end
    a11y.tooltip_dirty=false;a11y.tooltip_last_selection=selection
    local snapshot=a11y.native_windows
    local candidates,rank={},-1
    local input_owners={}
    local result=context.selection_result
    local member=result and snapshot.members and snapshot.members[tonumber(result.widget)]
    for _,owner in ipairs(member and member.owners or {}) do if owner.enabled then input_owners[owner.address]=true end end
    if not member then
        for _,window in ipairs(snapshot.windows or {}) do
            if window.enabled and window.cursor_detail and window.cursor_detail.selected then input_owners[window.address]=true end
        end
    end
    for _,node in pairs(a11y.ui_model and a11y.ui_model.nodes or {}) do
        local name=(node.name or ""):lower()
        local member=snapshot.members and snapshot.members[tonumber(node.address)]
        local owned=false
        for _,owner in ipairs(member and member.owners or {}) do if owner.enabled and input_owners[owner.address] then owned=true;break end end
        local body=name=="text_contents" or name=="question" or name=="eventmsg" or name=="messagebody" or name=="bodytext" or name=="padicon"
        if not body and owned and node.text and node.text~="" then
            local structural=name:find("tooltip",1,true) or name:find("description",1,true) or name:find("explanation",1,true)
            local native_help=a11y.native_control_help(node.text,node)
            local current_rank=native_help and 2 or structural and 1 or a11y.text_asset_role(node.text)=="tooltip-or-description" and 0 or -1
            if current_rank>=0 and current_rank>=rank and a11y.native_presentation_ready(node.address)
                    and a11y.ui_node_matches_live(node) and a11y.read_native_rendered_text(node.address)==node.text then
                if current_rank>rank then candidates={};rank=current_rank end
                candidates[#candidates+1]=node
            end
        end
    end
    if #candidates==0 then return end
    table.sort(candidates,function(a,b) return a.sequence<b.sequence end)
    local parts,texts,seen={}, {}, {}
    local owner=a11y.native_owner_token()
    for _,node in ipairs(candidates) do
        if not seen[node.text] then
            seen[node.text]=true;texts[#texts+1]=node.text
            parts[#parts+1]={key=node.key,text=node.text,identity=node.identity,owner=owner}
        end
    end
    local text=table.concat(texts," ")
    local previous=a11y.common_tooltip
    if previous and previous.selection==selection and previous.text==text and previous.status~="pending" then return end
    local stamp={selection=selection,text=text,parts=parts,status="pending",attempt=(previous and previous.attempt or 0)+1}
    a11y.common_tooltip=stamp
    pending_controller_tooltip,controller_tooltip_due_ms=nil,nil
    local before=a11y.native_speech_last
    speak(text,false,true,"tooltip:" .. selection .. ":" .. text .. ":" .. stamp.attempt)
    for index=before+1,a11y.native_speech_last do a11y.native_speech_queue[index].common_tooltip=stamp;stamp.status="queued" end
end

function a11y.finish_render_work()
    a11y.render_read_work=nil
    local metric=a11y.render_metric
    if not metric then return end
    if prism_started and a11y.render_speech_allowed then
        a11y.stop_nvda_if_requested()
        a11y.flush_native_speech(tonumber(ffi.C.GetTickCount64()))
    end
    a11y.render_speech_allowed=false
    a11y.render_metric,a11y.render_read_work=nil,nil
    local elapsed=tonumber(ffi.C.GetTickCount64())-metric.started
    local stats=a11y.render_stats or {frames=0,ms=0,max_ms=0,reads=0,speech_ms=0,speech_calls=0,focus_ms=0}
    stats.frames,stats.ms,stats.reads=stats.frames+1,stats.ms+elapsed,stats.reads+metric.reads
    stats.max_ms=math.max(stats.max_ms,elapsed)
    stats.focus_ms=stats.focus_ms+(metric.focus_ms or 0)
    stats.speech_ms=stats.speech_ms+(metric.speech_ms or 0)
    stats.speech_calls=stats.speech_calls+(metric.speech_calls or 0)
    a11y.render_stats=stats
    if stats.frames>=600 then
        log(string.format("[FLAccess] reader-work frames=%d mean-ms=%.3f max-ms=%d memory-copies-per-frame=%.1f speech-ms=%.3f speech-calls=%d focus-ms=%.3f",
            stats.frames,stats.ms/stats.frames,stats.max_ms,stats.reads/stats.frames,stats.speech_ms/stats.frames,stats.speech_calls,stats.focus_ms/stats.frames))
        a11y.render_stats=nil
    end
end

function m.display_frame(ctx)
    a11y.render_read_work={}
    a11y.render_speech_allowed=false
    a11y.render_metric={started=tonumber(ffi.C.GetTickCount64()),reads=0}
    frame = frame + 1
    a11y.current_frame = frame
    a11y.poll_direct_message_update()
    if not prism_started and frame >= 120 then
        prism_started = true
        start_native_prism(ctx)
    end
    if not game_is_foreground() then
        game_was_foreground = false
        a11y.nvda_stop_requested = false
        a11y.clear_speech_queue()
        a11y.finish_render_work()
        return
    end
    a11y.render_speech_allowed=true
    a11y.poll_native_windows()
    a11y.poll_native_texts()
    a11y.poll_native_country_selection()
    a11y.poll_keyboard_input()
    a11y.poll_information_context()
    a11y.poll_native_pause()
    a11y.poll_native_language()
    a11y.poll_presented_texts()
    a11y.poll_notice_actions()
    a11y.poll_surface_texts()
    a11y.poll_main_menu_choice()
    a11y.poll_loading(tonumber(ffi.C.GetTickCount64()))
    a11y.poll_skip_hint()
    a11y.poll_component_capture()
    if not game_was_foreground then
        game_was_foreground = true
        foreground_resume_frame = frame + 4
        ui_focus_candidate_key = nil
        last_ui_focus_announcement = nil
        a11y.finish_render_work()
        return
    end
    if frame < foreground_resume_frame then
        a11y.finish_render_work()
        return
    end
    if overlay_visible or sider_overlay_visible then
        a11y.finish_render_work()
        return
    end
    local now_ms = tonumber(ffi.C.GetTickCount64())
    a11y.poll_attribute_input(now_ms)
    a11y.poll_focus_trace()
    a11y.record_game_plan_menu_probe()
    if a11y.game_plan_lineup_due_ms
            and now_ms >= a11y.game_plan_lineup_due_ms then
        a11y.read_visible_game_plan_lineup()
        a11y.game_plan_lineup_due_ms = nil
        a11y.game_plan_lineup_input = nil
    end
    local startup_busy = process_startup_speech(now_ms)
    if pending_message_text and not a11y.native_key_allowed(a11y.pending_message_widget_key) then
        pending_message_text, pending_message_key, pending_message_due_ms = nil, nil, nil
        a11y.pending_message_widget_key = nil
    end
    if not startup_busy and pending_message_due_ms
            and now_ms >= pending_message_due_ms then
        if pending_message_text and pending_message_text ~= ""
                and pending_message_key ~= last_announced_message_key then
            local context = a11y.read_context_state()
            local spoken_prompt = context.structural_question and context.question == pending_message_text
                and ((a11y.ui_language == "pt" and "Pergunta: " or "Question: ") .. pending_message_text)
                or pending_message_text
            local prompt_node=a11y.ui_model and a11y.ui_model.nodes[a11y.pending_message_widget_key]
            speak(spoken_prompt, nil, true, nil, prompt_node and prompt_node.address)
            a11y.dialog_button_queued_for_message = false
            modal_message_spoken_frame = frame
            last_announced_message_key = pending_message_key
            a11y.last_modal_message_text = pending_message_text
            local reading_time = #pending_message_text * 65 + 500
            if reading_time < 1800 then reading_time = 1800 end
            if reading_time > 10000 then reading_time = 10000 end
            -- Consecutive dialog pages are queued in Prism. Keep focus
            -- blocked until the entire queued reading finishes, not only
            -- until the most recently detected page would finish alone.
            modal_focus_hold_until_ms =
                math.max(now_ms, modal_focus_hold_until_ms) + reading_time
            if #a11y.modal_message_backlog == 0
                    and a11y.pending_modal_button_text
                    and not a11y.ignore_cup_group_focus(
                        a11y.pending_modal_button_text) then
                if a11y.deferred_modal_announcement
                        and a11y.deferred_modal_announcement:sub(
                            1, #a11y.pending_modal_button_text)
                                == a11y.pending_modal_button_text then
                    a11y.deferred_modal_announcement = nil
                end
                local button = a11y.pending_modal_button_text
                speak(button ..
                    ", botão selecionado", false, true)
                a11y.dialog_button_queued_for_message = true
            end
            if #a11y.modal_message_backlog == 0 then
                a11y.pending_modal_button_text = nil
            end
        end
        pending_message_text = nil
        pending_message_key = nil
        a11y.pending_message_widget_key = nil
        pending_message_due_ms = nil
        if #a11y.modal_message_backlog > 0 then
            local next_message = table.remove(a11y.modal_message_backlog, 1)
            pending_message_text = next_message.text
            pending_message_key = next_message.key
            a11y.pending_message_widget_key =
                next_message.key:match("^(.-)%z")
            pending_message_due_ms = now_ms + 40
        end
    end
    -- Startup and dialog work above can enqueue speech before later guards
    -- return early. Deliver it now instead of paying another render frame.
    if a11y.game_plan_attribute_due_ms then
        if not startup_busy and pending_message_text == nil
                and now_ms >= a11y.game_plan_attribute_due_ms then
            local attribute_summary = a11y.game_plan_attribute_summary()
            speak(attribute_summary)
            a11y.game_plan_attribute_due_ms = nil
            local attribute_reading_time = #attribute_summary * 55 + 500
            if attribute_reading_time < 2500 then
                attribute_reading_time = 2500
            end
            if attribute_reading_time > 9000 then
                attribute_reading_time = 9000
            end
            a11y.game_plan_attribute_hold_until_ms =
                now_ms + attribute_reading_time
        end
        a11y.finish_render_work()
        return
    end
    if now_ms < a11y.game_plan_attribute_hold_until_ms then
        a11y.finish_render_work()
        return
    end
    if now_ms <= a11y.game_plan_attribute_panel_until_ms then
        -- The game renders every player card while the attribute overlay is
        -- open. None of those background names represents a focus change.
        a11y.finish_render_work()
        return
    end
    local modal_focus_blocked = startup_busy
        or pending_message_text ~= nil
        or now_ms < modal_focus_hold_until_ms
        or now_ms < a11y.screen_title_hold_until_ms
    local dialog_active = frame <= a11y.confirmation_dialog_until_frame
        and dialog_is_active()
        and math.min(dialog_options.Sim.last_seen,
            dialog_options["Não"].last_seen)
                >= a11y.modal_dialog_start_frame - 5 or false
    a11y.process_game_plan_selected_heading(
        modal_focus_blocked or dialog_active)
    a11y.process_game_plan_basic_menu_heading(
        modal_focus_blocked or dialog_active)
    -- The specialized reader is enabled only by the current destructive-back
    -- confirmation. This reads its Sim/Não focus without allowing old dialog
    -- widgets to compete with later screens.
    if dialog_active then
        process_dialog_focus(
            modal_focus_blocked,
            now_ms < modal_focus_hold_until_ms)
    end
    -- Do not mix the current UI-state reader with the legacy localization
    -- fallback. Hidden widgets retain their old focus bit after a transition,
    -- so the fallback can overwrite a correct announcement with an item from
    -- the previous screen (for example "Partida local" on the league list).
    a11y.poll_native_pages(modal_focus_blocked or dialog_active)
    local focus_started=tonumber(ffi.C.GetTickCount64())
    scan_current_ui_focus(modal_focus_blocked, dialog_active)
    a11y.render_metric.focus_ms=tonumber(ffi.C.GetTickCount64())-focus_started
    a11y.poll_assignment_changes()
    a11y.poll_common_tooltip()
    a11y.poll_main_navigation_probe()

    -- Delayed speech is evaluated after focus. A newly focused item can then
    -- cancel an obsolete tooltip before it reaches the screen reader.
    process_delayed_speech(now_ms, modal_focus_blocked)
    if not modal_focus_blocked and a11y.deferred_modal_announcement then
        a11y.drain_deferred_speech()
    end
    -- Hooks and focus scanning enqueue only. Flush again after processing so
    -- confirmed navigation reaches Prism in this render frame rather than the
    -- next one. Prism calls remain serialized on display_frame.
    a11y.finish_render_work()
end

function a11y.overlay_text()
    local s = a11y.strings()
    local tooltip = string.format(
        s.tooltip_option,
        a11y.read_tooltips and s.yes or s.no)
    local diagnostic = string.format(
        s.diagnostic_option,
        a11y.diagnostic_mode and s.yes or s.no)
    if a11y.selected_option == 1 then
        tooltip = "---> " .. tooltip .. " <---"
    else
        diagnostic = "---> " .. diagnostic .. " <---"
    end
    return table.concat({
        string.format(s.title, a11y.runtime_version),
        s.menu_reading,
        s.speech_output,
        tooltip,
        diagnostic,
        "",
        s.navigate_options,
        s.change_option,
        s.restore_defaults,
        s.close_sider,
        s.next_module,
        s.previous_module,
    }, "\n")
end

function a11y.selected_option_text()
    local s = a11y.strings()
    if a11y.selected_option == 2 then
        return string.format(
            s.diagnostic_option,
            a11y.diagnostic_mode and s.yes or s.no)
    end
    return string.format(
        s.tooltip_option,
        a11y.read_tooltips and s.yes or s.no)
end

